window.LANTERN_VIDEOS = [{"id":"voa-people-watching","type":"video","category":"fun","title":"I Love People-Watching!","creator":"VOA Learning English","year":2021,"level":"A2","durationSeconds":300,"genre":"comedy","summaryTr":"Anna, arkadaşlarıyla parkta insanları gözlemlerken işe dönme saatini unutuyor. Patronu görünce başlayan saklanma çabası, küçük bir sürprizle bitiyor.","levelNoteTr":"Seviye, altyazı ve kelime desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Ana skeçteki ekran altyazıları dokunulabilir olarak hazırlanmıştır. VOA’nın Dinle/Konuş tekrarları ve ara açıklamaları özgün hâliyle korunur; bu bölümlerde her cümle için dokunulabilir altyazı bulunmaz.","videoUrl":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b0/b07eac5a-cc3a-4f3e-821c-ecae337b5415_720p.mp4","qualities":[{"label":"240p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b0/b07eac5a-cc3a-4f3e-821c-ecae337b5415_240p.mp4","sizeMB":13},{"label":"360p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b0/b07eac5a-cc3a-4f3e-821c-ecae337b5415.mp4","sizeMB":22},{"label":"480p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b0/b07eac5a-cc3a-4f3e-821c-ecae337b5415_480p.mp4","sizeMB":44},{"label":"720p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b0/b07eac5a-cc3a-4f3e-821c-ecae337b5415_720p.mp4","sizeMB":66}],"source":{"name":"VOA Learning English — I Love People-Watching!","url":"https://learningenglish.voanews.com/a/lets-learn-english-lesson-15-i-love-people-watching/3343720.html","watchUrl":"https://learningenglish.voanews.com/a/lets-learn-english-lesson-15-i-love-people-watching/3343720.html","license":"VOA özgün üretimi · Kamu malı","licenseUrl":"https://learningenglish.voanews.com/p/6021.html","credit":"Voice of America / VOA Learning English. Özgün video bütünüyle ve değiştirilmeden oynatılır."},"subtitleSource":{"name":"VOA’nın video üzerindeki İngilizce ekran altyazıları","url":"https://learningenglish.voanews.com/a/lets-learn-english-lesson-15-i-love-people-watching/3343720.html","license":"VOA özgün metni · Kamu malı","licenseUrl":"https://learningenglish.voanews.com/p/6021.html","credit":"Voice of America; metin çıkarımı ve zaman eşlemesi: Lantern English","changeNoteTr":"Ana skeçteki ekran yazıları aktarılmış, OCR yazım hataları düzeltilmiş ve yaklaşık 0,5 saniye çözünürlükle zamanlanmıştır. Dinle/Konuş alıştırmalarındaki boşluklar korunmuştur."},"glossary":{"people-watch":"insanları gözlemlemek; gelip geçenleri izlemek","keyana":"Keyana (karakter adı)","weaver":"Weaver (karakterin soyadı)","curly":"kıvırcık; saç için","straight":"saç için: düz","bench":"bank; oturmak için kullanılan uzun sıra"},"captions":[{"start":25,"end":31,"text":"Hello! People from all over the world come to Washington, D.C."},{"start":31,"end":34.5,"text":"When I'm at work, I love eating lunch outside."},{"start":34.5,"end":39.5,"text":"I like to watch people walking by. They all look very different."},{"start":39.5,"end":42.5,"text":"Today, my friend Ashley is eating lunch with me."},{"start":42.5,"end":47,"text":"Ashley, today the weather is beautiful, isn't it?"},{"start":47,"end":53.5,"text":"Yes, it is. Ahh. Ooh, we have to return to work!"},{"start":53.5,"end":59,"text":"No, we have time! Let's people-watch a little more."},{"start":59,"end":61.5,"text":"Okay."},{"start":100,"end":104.5,"text":"Oh, I know her. She works in my office! Keyana, hi!"},{"start":104.5,"end":106,"text":"Come and join us!"},{"start":106,"end":107.5,"text":"Hi Anna, how are you?"},{"start":107.5,"end":110.5,"text":"I'm doing great! Keyana, this is my friend Ashley."},{"start":110.5,"end":111.5,"text":"Hi, Ashley!"},{"start":111.5,"end":114,"text":"We need to return to work."},{"start":114,"end":118,"text":"But the weather is beautiful and people-watching is fun!"},{"start":118,"end":120,"text":"I love people-watching too!"},{"start":120,"end":123.5,"text":"Well, have a seat!"},{"start":123.5,"end":128,"text":"It is fun to see how people are different or the same."},{"start":128,"end":134.5,"text":"It is. For example, Anna, you are tall. But Ashley and I are short."},{"start":140,"end":145.5,"text":"And Keyana, you and Ashley have brown eyes; I have blue eyes."},{"start":145.5,"end":149.5,"text":"You two have light skin and I have dark skin."},{"start":149.5,"end":154,"text":"Ashley, you have straight hair. Keyana and I have curly hair."},{"start":154,"end":157,"text":"You have very curly hair, Anna."},{"start":157,"end":162,"text":"I need to return to work. See you, Anna! Nice to meet you Ashley!"},{"start":162,"end":163.5,"text":"Bye, Keyana!"},{"start":166,"end":170.5,"text":"Anna, I have to go, too. Are you returning to work?"},{"start":170.5,"end":175.5,"text":"I still have time. And this sun feels so good!"},{"start":179,"end":184,"text":"Um, Anna, what does your boss look like?"},{"start":184,"end":188,"text":"She is short. She has straight, light hair."},{"start":188,"end":190,"text":"Does she wear glasses?"},{"start":190,"end":192,"text":"Yes. Yes, she does."},{"start":192,"end":195,"text":"Is she wearing a blue sweater today?"},{"start":232.5,"end":234,"text":"How do you know that?"},{"start":234,"end":236.5,"text":"She's coming this way."},{"start":236.5,"end":238,"text":"Oh no! Hide me!"},{"start":240.5,"end":245,"text":"Um, bye Anna. Call me later."},{"start":245,"end":247,"text":"Bye, Ashley! Talk to you later!"},{"start":250,"end":253.5,"text":"Anna? Is that you?"},{"start":253.5,"end":256.5,"text":"Ms. Weaver! Hi!"},{"start":256.5,"end":259,"text":"What are you doing behind that bench?"},{"start":259,"end":264,"text":"I am looking for my, my ... stick. Here it is."},{"start":264,"end":269,"text":"I am people-watching. Oh! But it's time to return to work!"},{"start":269,"end":274.5,"text":"No need to hurry. I love people-watching too! Let's sit!"},{"start":274.5,"end":276.5,"text":"Sure!"},{"start":279.5,"end":281.5,"text":"Ahh."},{"start":284,"end":286,"text":"It's a beautiful day, isn't it?"},{"start":286,"end":288.5,"text":"Yes. Yes, it is, Ms. Weaver."},{"start":288.5,"end":294.5,"text":"People-watching in D.C. is fun. It makes me forget the time!"},{"start":294.5,"end":297.5,"text":"Until next time! Ahh."}],"categoryTr":"Komedi skeçi","captionCoverage":"main-dialogue"},{"id":"pepper-and-carrot-potion-contest","type":"video","title":"Pepper & Carrot: The Potion Contest","creator":"Morevna Project","year":2017,"level":"A2","category":"fun","durationSeconds":454,"genre":"comedy","summaryTr":"Genç cadı Pepper ve turuncu kedisi Carrot, kasabanın büyük iksir yarışmasına katılır. Rakipler göz kamaştırıcı iksirler sunarken Pepper'ın elindeki şişe herkesi şaşırtacaktır. David Revoy'un çizgi romanından uyarlanmış neşeli bir animasyon.","levelNoteTr":"A2, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Cümleler kısa ve günlük; iksir, büyü ve sunucu konuşmalarındaki süslü sözcükler kelime desteği gerektirebilir.","advisoryTr":"Çizgi film tarzı hafif aksiyon ve zararsız bir \"kedi çişi\" esprisi içerir; tüm yaşlara uygundur.","videoUrl":"https://peertube.touhoppai.moe/static/streaming-playlists/hls/79ff0983-3f55-4111-9f7d-f3d3feeefb69/4cac02ca-6045-4cab-880d-5dd13ecb4f4e-720-fragmented.mp4","qualities":[{"label":"360p","url":"https://peertube.touhoppai.moe/static/streaming-playlists/hls/79ff0983-3f55-4111-9f7d-f3d3feeefb69/1f75c515-0db6-46f6-8ced-eaa52249021e-360-fragmented.mp4","sizeMB":30},{"label":"720p","url":"https://peertube.touhoppai.moe/static/streaming-playlists/hls/79ff0983-3f55-4111-9f7d-f3d3feeefb69/4cac02ca-6045-4cab-880d-5dd13ecb4f4e-720-fragmented.mp4","sizeMB":62},{"label":"1080p","url":"https://peertube.touhoppai.moe/static/streaming-playlists/hls/79ff0983-3f55-4111-9f7d-f3d3feeefb69/d88f7b11-878e-4694-8f20-c9f63b4e4f60-1080-fragmented.mp4","sizeMB":98}],"source":{"name":"Morevna Project — Pepper & Carrot Motion Comic, Episode 6","url":"https://morevnaproject.org/pepper-and-carrot/episode-6","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Morevna Project · Yönetmen ve animasyon: Nikolai Mamashev · David Revoy'un Pepper & Carrot çizgi romanına dayanır","watchUrl":"https://peertube.touhoppai.moe/videos/watch/79ff0983-3f55-4111-9f7d-f3d3feeefb69"},"subtitleSource":{"name":"Morevna Project — İngilizce SRT altyazısı","url":"https://raw.githubusercontent.com/morevnaproject/subtitles-translation/master/output/pepper-and-carrot-ep6/pepper-and-carrot-ep6-eng.srt","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changeNoteTr":"Altyazı sözleri korunmuş; [yawns] gibi ses notları ve biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"captions":[{"start":1.03,"end":3.53,"text":"Morevna Project..."},{"start":4.37,"end":6.78,"text":"...in association with \"Ethic Cinema\"..."},{"start":7.24,"end":8.51,"text":"...presents."},{"start":24.24,"end":28.24,"text":"Oh, I fell asleep with the window open again..."},{"start":29.96,"end":32.76,"text":"Ufff... it's so windy..."},{"start":33.62,"end":36.91,"text":"...and why can I see Komona through the window?"},{"start":37.24,"end":38.24,"text":"Komona?!"},{"start":39.2,"end":39.99,"text":"THE CONTEST!!!"},{"start":41.7,"end":43.28,"text":"In previous episodes:"},{"start":43.45,"end":45.49,"text":"Pepper spent a lot of effort..."},{"start":45.87,"end":49.49,"text":"...preparing for the potion contest."},{"start":50.04,"end":50.87,"text":"I must've..."},{"start":51.21,"end":54,"text":"...must've accidentally fallen asleep..."},{"start":54.47,"end":55.1,"text":"But..."},{"start":56.18,"end":57.32,"text":"But...where am I?"},{"start":58.22,"end":59.16,"text":"Oh!!!"},{"start":64.88,"end":68.58,"text":"Carrot! It's so cute that you took care of everything!"},{"start":69.64,"end":70.64,"text":"Meow!"},{"start":71.62,"end":76.04,"text":"You even thought to bring a potion, my clothes, and my hat!"},{"start":77.12,"end":80.67,"text":"Well, let's see which potion you brought."},{"start":81.17,"end":83.04,"text":"So, what do we have here?"},{"start":83.87,"end":85.87,"text":"Whaaaat?!"},{"start":88.74,"end":92.84,"text":"Caaaaaaarrrrrooooooot!!!!!!!"},{"start":93.64,"end":97.4,"text":"Pepper & Carrot. Episode 6: The Potion Contest"},{"start":98.33,"end":103.12,"text":"As Mayor of Komona, I declare the potion contest..."},{"start":103.42,"end":105.08,"text":"...open!"},{"start":106.87,"end":110.87,"text":"Four young witches are participating in this contest!"},{"start":111.92,"end":114.54,"text":"Please give a huge round of applause!"},{"start":120.62,"end":124.62,"text":"It is an honor to welcome the ravishing and ingenious witch..."},{"start":125.21,"end":127.67,"text":"...from the great Technologist's Union!!!.."},{"start":128.04,"end":131.78,"text":"Coriander!"},{"start":133.04,"end":137.71,"text":"And don't forget about our local girl, Komona's very own witch..."},{"start":138.08,"end":140.96,"text":"Saffron!"},{"start":146.66,"end":148.92,"text":"Our third participant..."},{"start":149.14,"end":152.58,"text":"...comes to us from the lands of the setting moons..."},{"start":153.04,"end":154.92,"text":"...the mysterious..."},{"start":155.9,"end":158.34,"text":"...Shichimi!"},{"start":160.12,"end":164.52,"text":"And finally our last participant, from the forest of Squirrel's End..."},{"start":164.82,"end":166.3,"text":"...Pepper."},{"start":169.34,"end":170.78,"text":"Ladies and gentlemen!"},{"start":170.87,"end":176.46,"text":"The winner of the grand prize will be determined by applaud-o-meter!"},{"start":176.58,"end":180.42,"text":"Let the games begin!"},{"start":182.58,"end":187.37,"text":"Well! First up Coriander's demonstration."},{"start":189.83,"end":191.5,"text":"Ladies & gentlemen..."},{"start":191.96,"end":195.04,"text":"...fear death no more, thanks to my..."},{"start":195.67,"end":197.37,"text":"...Potion of Zombification!"},{"start":207.98,"end":209.7,"text":"Amazing!"},{"start":210.56,"end":217.18,"text":"With this mi-ra-cu-lous potion, Coriander defies death itself!"},{"start":218.54,"end":220.62,"text":"Yes-yes-yes..."},{"start":221.46,"end":223.52,"text":"A potion of Zombification.."},{"start":223.92,"end":225.2,"text":"that's nothing!"},{"start":225.21,"end":227.33,"text":"It's time to rate MY potion."},{"start":227.83,"end":231.83,"text":"The real potion you've all been waiting for..."},{"start":236.48,"end":238.38,"text":"...The Potion of Poshness!"},{"start":241.12,"end":243.71,"text":"Fantastic!"},{"start":243.96,"end":245.75,"text":"Incredible!"},{"start":246.29,"end":250.8,"text":"This potion could make all of Komona rich!"},{"start":250.96,"end":253.58,"text":"It seems, Coriander has already been eliminated!"},{"start":253.87,"end":257.87,"text":"Will Shichimi be able to beat that last demonstration?"},{"start":258.83,"end":262.7,"text":"I... I did not know we had to give a demonstration."},{"start":263.04,"end":264.37,"text":"Come on Shichimi!"},{"start":264.42,"end":265.79,"text":"Everyone's waiting for you!"},{"start":266.33,"end":267.17,"text":"No!.."},{"start":267.58,"end":268.12,"text":"I cannot!.."},{"start":268.46,"end":270.2,"text":"It is too dangerous!.."},{"start":270.4,"end":271.64,"text":"S-sorry!.."},{"start":272.37,"end":273.75,"text":"Ladies and gentlemen..."},{"start":274,"end":275.5,"text":"...it seems that Shichimi forfeits..."},{"start":275.54,"end":276.42,"text":"Give me that!"},{"start":276.58,"end":277.37,"text":"CAREFUL!!!"},{"start":277.66,"end":279.48,"text":"What could be so dangerous?"},{"start":279.68,"end":283.46,"text":"You're just scared because your potion isn't as fantastic as mine!"},{"start":284.58,"end":286.9,"text":"No-no, it is a potion of..."},{"start":287.96,"end":290.84,"text":"...GIANT MONSTERS!!!"},{"start":298.1,"end":299.94,"text":"Mr. Mayor, Mr. Mayor!"},{"start":300.1,"end":301.26,"text":"Is it my turn now???"},{"start":301.28,"end":302.34,"text":"Run!"},{"start":307.52,"end":311.26,"text":"You're lucky, Carrot; It seems nobody will see your wondrous potion..."},{"start":311.5,"end":313.6,"text":"She will destroy our town!!!"},{"start":314.72,"end":317.76,"text":"Wait, I think I have an idea!"},{"start":326.06,"end":326.96,"text":"Hey!"},{"start":327.44,"end":330.06,"text":"You oversized-posh-zombie-canary!"},{"start":330.12,"end":332.37,"text":"Wanna try one last \"potion\"?"},{"start":333.42,"end":334.71,"text":"But first..."},{"start":334.79,"end":337,"text":"...read the label!"},{"start":337.92,"end":339.48,"text":"Read it carefully!"},{"start":344.36,"end":349.92,"text":"If you don't get out of Komona right away, trust me: I'll pour it all over you!"},{"start":350.58,"end":351.25,"text":"Understood?!"},{"start":375.71,"end":380.74,"text":"Because she saved our town we award first place to..."},{"start":380.79,"end":383.04,"text":"...Miss Pepper!"},{"start":383.24,"end":385.28,"text":"For her wonderful potion!"},{"start":386.02,"end":387.33,"text":"Huh, in fact..."},{"start":387.58,"end":389.29,"text":"...it's not really a potion..."},{"start":389.42,"end":392.58,"text":"...it's just my cat's pee sample from his last trip to the vet!"},{"start":393.17,"end":394.17,"text":"Isn't it, Carrot?"},{"start":395.71,"end":396.42,"text":"Meow!"}],"glossary":{"morevna":"Morevna Project (animasyon stüdyosu)","ethic":"Ethic Cinema (yapım ortağının adı)","ufff":"of! (yorgunluk, sıkıntı sesi)","komona":"Komona (şehrin adı)","komona's":"Komona'nın (şehrin adı)","whaaaat":"neee?! (what, şaşkınlıkla uzatılmış)","caaaaaaarrrrrooooooot":"Caaarrot! (Carrot'a öfkeyle bağırış)","technologist's":"Technologist's Union: Teknologlar Birliği","coriander":"Coriander (yarışmacı cadının adı)","coriander's":"Coriander'ın (yarışmacı cadının adı)","saffron":"Saffron (yarışmacı cadının adı)","shichimi":"Shichimi (yarışmacı cadının adı)","o":"applaud-o-meter: alkışölçer","mi":"mi-ra-cu-lous: mucizevi (heceleyerek)","ra":"mi-ra-cu-lous: mucizevi (heceleyerek)","cu":"mi-ra-cu-lous: mucizevi (heceleyerek)","lous":"mi-ra-cu-lous: mucizevi (heceleyerek)","s":"S-sorry: Ö-özür dilerim (kekeleme)"}},{"id":"voa-game-is-fun","type":"video","category":"fun","title":"This Game Is Fun!","creator":"VOA Learning English","year":2021,"level":"A2","durationSeconds":300,"genre":"comedy","summaryTr":"Anna, telefonundaki oyunda sanal simgeleri kovalarken Dan ile yarışa tutuşuyor. Puan toplamak kolay; önündeki ağacı fark etmek biraz daha zor!","levelNoteTr":"Seviye, altyazı ve kelime desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Ana skeçteki ekran altyazıları dokunulabilir olarak hazırlanmıştır. VOA’nın Dinle/Konuş tekrarları ve ara açıklamaları özgün hâliyle korunur; bu bölümlerde her cümle için dokunulabilir altyazı bulunmaz.","videoUrl":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b9/b9ddf673-07ec-4557-b33d-37cf6315e3e3_720p.mp4","qualities":[{"label":"240p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b9/b9ddf673-07ec-4557-b33d-37cf6315e3e3_240p.mp4","sizeMB":12},{"label":"360p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b9/b9ddf673-07ec-4557-b33d-37cf6315e3e3.mp4","sizeMB":21},{"label":"480p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b9/b9ddf673-07ec-4557-b33d-37cf6315e3e3_480p.mp4","sizeMB":38},{"label":"720p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b9/b9ddf673-07ec-4557-b33d-37cf6315e3e3_720p.mp4","sizeMB":64}],"source":{"name":"VOA Learning English — This Game Is Fun!","url":"https://learningenglish.voanews.com/a/lets-learn-english-lesson-26-this-game-is-fun/3457248.html","watchUrl":"https://learningenglish.voanews.com/a/lets-learn-english-lesson-26-this-game-is-fun/3457248.html","license":"VOA özgün üretimi · Kamu malı","licenseUrl":"https://learningenglish.voanews.com/p/6021.html","credit":"Voice of America / VOA Learning English. Özgün video bütünüyle ve değiştirilmeden oynatılır."},"subtitleSource":{"name":"VOA’nın video üzerindeki İngilizce ekran altyazıları","url":"https://learningenglish.voanews.com/a/lets-learn-english-lesson-26-this-game-is-fun/3457248.html","license":"VOA özgün metni · Kamu malı","licenseUrl":"https://learningenglish.voanews.com/p/6021.html","credit":"Voice of America; metin çıkarımı ve zaman eşlemesi: Lantern English","changeNoteTr":"Ana skeçteki ekran yazıları aktarılmış, OCR yazım hataları düzeltilmiş ve yaklaşık 0,5 saniye çözünürlükle zamanlanmıştır. Dinle/Konuş alıştırmalarındaki boşluklar korunmuştur."},"glossary":{"memorial":"bir kişiyi veya olayı anmak için yapılan anıt","roosevelt":"Roosevelt (ABD başkanının soyadı)","lincoln":"Lincoln (ABD başkanının soyadı)","americana":"Amerikan kültürüne ait şeyler; burada Anna adıyla kelime oyunu","wrestler":"güreşçi","bald":"bald eagle: kel kartal; ABD simgesi olan kuş","liberty":"özgürlük; Statue of Liberty: Özgürlük Heykeli"},"captions":[{"start":30.5,"end":35,"text":"This is the Roosevelt Memorial. Where is the symbol?"},{"start":35.5,"end":38,"text":"But this game is really fun."},{"start":38,"end":41.5,"text":"You have to find things that aren't really there."},{"start":41.5,"end":46,"text":"When you find an American symbol, you win points and"},{"start":46,"end":49.5,"text":"a Fun Fact about a U.S. president."},{"start":51.5,"end":57,"text":"Yay! I found Uncle Sam and I won 40 points!"},{"start":57,"end":60.5,"text":"What is the Fun Fact?"},{"start":60.5,"end":65.5,"text":"Franklin Roosevelt was the first to fly in a plane as president!"},{"start":65.5,"end":71.5,"text":"I didn't know that. This is a really beautiful memorial."},{"start":142.5,"end":149.5,"text":"I found it! The Statue of Liberty! Please give me my Fun Fact."},{"start":149.5,"end":152,"text":"Abraham Lincoln was a great wrestler!"},{"start":152,"end":156.5,"text":"I didn't know that. Lincoln wanted freedom for all people."},{"start":156.5,"end":159.5,"text":"So, the Statue of Liberty works well."},{"start":159.5,"end":166.5,"text":"And I won 20 points! Time to find the next symbol."},{"start":189.5,"end":191.5,"text":"Hey! Look out!"},{"start":191.5,"end":196.5,"text":"Sorry. Hey, it's you! Now, I should be more careful."},{"start":196.5,"end":197.5,"text":"That's okay."},{"start":197.5,"end":201.5,"text":"This game is a lot of fun. What's your name?"},{"start":201.5,"end":204,"text":"Dan. What's yours?"},{"start":204,"end":205.5,"text":"Anna."},{"start":205.5,"end":207.5,"text":"Like Americana!"},{"start":207.5,"end":210,"text":"Yeah, I guess so."},{"start":255,"end":256.5,"text":"Did you find any symbols?"},{"start":256.5,"end":264,"text":"Yes, I found three and I won 120 points!"},{"start":264,"end":268.5,"text":"Me too. But, did you find the bald eagle?"},{"start":268.5,"end":271,"text":"No. Did you?"},{"start":271,"end":273.5,"text":"No."},{"start":273.5,"end":276.5,"text":"First one to find it wins?"},{"start":277,"end":280,"text":"Hey Anna, look out for that tree!"},{"start":282,"end":284.5,"text":"I learned a lot about presidents with this game."},{"start":284.5,"end":287.5,"text":"But I ought to be more careful."},{"start":287.5,"end":292,"text":"Until next time!"}],"categoryTr":"Komedi skeçi","captionCoverage":"main-dialogue"},{"id":"astronauts-reading-fan-mail","type":"video","title":"Astronauts Reading Fan Mail","creator":"NASA Johnson Space Center","year":2022,"level":"B1","category":"real","durationSeconds":410,"genre":"documentary","summaryTr":"NASA astronotları çocukların gönderdiği mektupları ve çizimleri okuyor: Uzayda peynir var mı? Tavuk nugget nasıl yenir? Astronotlar uzaylılara inanır mı? Samimi, esprili ve gerçek İngilizce konuşmalar.","levelNoteTr":"B1, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Yedi farklı astronot doğal ve hızlı konuşur; günlük ifadeler ve roket, yörünge gibi uzay kelimeleri vardır.","advisoryTr":"Tüm yaşlara uygundur.","videoUrl":"https://images-assets.nasa.gov/video/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL~medium.mp4","qualities":[{"label":"Standart","url":"https://images-assets.nasa.gov/video/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL~medium.mp4","sizeMB":117},{"label":"Yüksek","url":"https://images-assets.nasa.gov/video/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL~large.mp4","sizeMB":253}],"source":{"name":"NASA — Astronauts Reading Fan Mail #3","url":"https://images.nasa.gov/details/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL","license":"Kamu malı (NASA yapımı, ABD'de telife tabi değil)","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","credit":"NASA Johnson Space Center · Jeanette Epps, Kayla Barron, Kjell Lindgren, Megan McArthur, Zena Cardman, Reid Wiseman, Anil Menon"},"subtitleSource":{"name":"NASA — resmî İngilizce SRT altyazısı","url":"https://images-assets.nasa.gov/video/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL.srt","license":"Kamu malı (NASA)","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","changeNoteTr":"NASA'nın tamamı büyük harfli altyazısı okunurluk için normal yazıma çevrildi, kısa parçalar cümle olarak birleştirildi ve bozuk kesme işaretleri düzeltildi; sözler korunmuştur."},"captions":[{"start":0,"end":1.701,"text":"Hi, my name is Jeanette Epps."},{"start":1.701,"end":3.57,"text":"Hi, I'm NASA astronaut, Kayla Barron."},{"start":3.57,"end":7.107,"text":"I am NASA astronaut Kjell Lindgren, and I just got back from the International"},{"start":7.107,"end":8.408,"text":"Space Station a few weeks ago."},{"start":8.408,"end":12.112,"text":"It's awesome to be back with my family and friends, to be back here on the Earth."},{"start":12.112,"end":16.182,"text":"I do love to get real letters, whether it's at home or at work or even in space"},{"start":16.182,"end":19.986,"text":"we get cards and letters delivered from family from time to time, which is so exciting."},{"start":19.986,"end":24.29,"text":"And this year we'd like to thank all the students who sent in letters and notes to us."},{"start":24.29,"end":27.527,"text":"And this is one of my favorite things to do is to read your letters."},{"start":27.527,"end":29.329,"text":"So let's get to it."},{"start":36.202,"end":38.438,"text":"The first time you went into space, how did it feel?"},{"start":38.438,"end":40.173,"text":"Were you scared or happy?"},{"start":40.173,"end":43.309,"text":"My first space launch was incredible."},{"start":43.309,"end":46.913,"text":"We were super well prepared, so I think for the most part we were just"},{"start":46.913,"end":50.75,"text":"executing the procedures, doing the job we had practiced doing."},{"start":50.75,"end":55.455,"text":"But as we counted down, you know, the famous countdown from ten, nine, eight up to that"},{"start":55.455,"end":58.691,"text":"moment of launch, the rocket engines light underneath us."},{"start":58.691,"end":63.029,"text":"And there's kind of this magic moment where you hang in the air, you're just off"},{"start":63.029,"end":66.332,"text":"the launch pad, and you can feel that you're starting to travel to space, but you haven't"},{"start":66.332,"end":68.134,"text":"really started accelerating yet."},{"start":68.134,"end":72.005,"text":"And in that moment, I was just flooded with pure joy."},{"start":72.005,"end":76.843,"text":"I was just so excited that my journey was finally starting and so excited to do it"},{"start":76.843,"end":79.679,"text":"with my teammates, my crew and our team around the world."},{"start":79.679,"end":85.051,"text":"And so, yeah, it was I was happy more than anything else."},{"start":85.051,"end":87.42,"text":"What do we have in here?"},{"start":87.62,"end":91.091,"text":"Look at this."},{"start":91.091,"end":92.692,"text":"That's so good."},{"start":92.692,"end":94.06,"text":"I'm going to put that on my refrigerator."},{"start":94.06,"end":95.462,"text":"Oh, look at this."},{"start":95.462,"end":97.097,"text":"This makes my day."},{"start":97.097,"end":97.73,"text":"How great is that?"},{"start":97.73,"end":99.866,"text":"That's going up on the wall for sure."},{"start":99.866,"end":102.035,"text":"I love those colors. Love it."},{"start":102.469,"end":105.905,"text":"I had a bowl of cereal and milk for breakfast and chili for lunch."},{"start":105.905,"end":108.508,"text":"And every now and then you open these up and you learn what, like,"},{"start":108.508,"end":109.542,"text":"somebody's favorite food is."},{"start":109.542,"end":111.644,"text":"Is there cheese to eat in your spaceship?"},{"start":111.644,"end":112.479,"text":"I love cheese."},{"start":112.479,"end":113.646,"text":"Oh, my gosh. Me too."},{"start":113.646,"end":118.084,"text":"Actually, it's really hard to send cheese to space because it goes bad pretty quickly."},{"start":118.084,"end":121.187,"text":"But you can send some hard cheeses to space, so I really hope that"},{"start":121.187,"end":122.555,"text":"that's there in my spaceship."},{"start":122.555,"end":124.457,"text":"Sara says."},{"start":124.457,"end":129.462,"text":"I think space is very cool, but I think space ice cream would be the best part."},{"start":129.462,"end":134.634,"text":"Sara, you know all that there is to know because you're absolutely right, space"},{"start":134.634,"end":136.536,"text":"ice cream is very cool and cold."},{"start":136.536,"end":138.338,"text":"Do you like chicken nuggets?"},{"start":138.338,"end":139.706,"text":"I love all chicken nuggets."},{"start":139.706,"end":142.242,"text":"I'm sure there's somebody out there that does not like chicken nuggets,"},{"start":142.242,"end":143.176,"text":"but that is not me."},{"start":143.176,"end":147.147,"text":"So I think the bigger chicken nugget question is, how do you eat your chicken nuggets?"},{"start":147.147,"end":149.215,"text":"With a fork, and knife, dip them in ketchup?"},{"start":149.215,"end":151.651,"text":"Are you kind of a mayonnaise or a mustard person?"},{"start":151.651,"end":154.854,"text":"Or is it just straight up, I've got 18 chicken nuggets in front of me"},{"start":154.854,"end":157.223,"text":"and I'm getting after it all right now?"},{"start":157.223,"end":160.593,"text":"So I don't care how you eat yours, but I'll tell you how I eat mine."},{"start":160.593,"end":161.895,"text":"I definitely like chicken nuggets."},{"start":161.895,"end":164.364,"text":"I like a little bit of ketchup and I definitely use my fingers."},{"start":164.364,"end":169.702,"text":"It's a great question and I hope you have a wonderful holiday season, Charlie."},{"start":169.702,"end":172.071,"text":"So what type of rocket ship did you go on?"},{"start":172.071,"end":176.509,"text":"Well, this most recent mission, I flew in a Crew Dragon capsule"},{"start":176.509,"end":178.578,"text":"on top of a Falcon-9 rocket."},{"start":178.578,"end":179.746,"text":"It was absolutely amazing."},{"start":179.746,"end":183.116,"text":"We launched from Kennedy Space Center and we were in low Earth orbit"},{"start":183.116,"end":184.417,"text":"in less than nine minutes."},{"start":184.417,"end":188.221,"text":"Now, my first mission about seven years ago, I launched in a Soyuz capsule"},{"start":188.221,"end":192.225,"text":"on a Soyuz rocket out of baikonur cosmodrome in Kazakhstan."},{"start":192.225,"end":196.496,"text":"I launched with our Russian partners and, and that was my first flight."},{"start":196.496,"end":201.034,"text":"And so it was really cool to have that experience of flying into space"},{"start":201.034,"end":202.936,"text":"on two different types of rockets."},{"start":202.936,"end":204.671,"text":"What's your favorite thing about your job?"},{"start":204.671,"end":209.842,"text":"Well, Piper, one of my favorite things about my job is that I continue to learn new things"},{"start":209.842,"end":210.81,"text":"just about every day."},{"start":210.81,"end":215.081,"text":"Flying in the T-38, doing robotics, just about everything that we do here."},{"start":215.081,"end":216.549,"text":"There's always something new going on."},{"start":216.549,"end":217.283,"text":"And I like to learn."},{"start":217.283,"end":217.784,"text":"This is cool."},{"start":217.784,"end":219.452,"text":"This is a launch pad."},{"start":219.452,"end":220.954,"text":"Look at that."},{"start":220.987,"end":222.956,"text":"Very detailed from Gabe."},{"start":222.956,"end":224.49,"text":"Gabe, that's awesome."},{"start":224.49,"end":224.857,"text":"I see."},{"start":224.857,"end":226.259,"text":"We got the, we got the pad here."},{"start":226.259,"end":230.93,"text":"We got the gantry that we walk across into the capsule there with the astronauts inside."},{"start":230.93,"end":233.166,"text":"That is a great drawing, Gabe. Good job."},{"start":233.166,"end":235.101,"text":"Can you feel heat in the spaceship?"},{"start":235.101,"end":236.703,"text":"Especially when we're coming home?"},{"start":236.703,"end":238.738,"text":"The- our spacecraft gets really hot."},{"start":238.738,"end":242.842,"text":"That's why we have a heat shield that protects us as our spacecraft starts to travel"},{"start":242.842,"end":243.643,"text":"through the atmosphere."},{"start":243.643,"end":247.914,"text":"Because all of that resistance of the gases in the atmosphere really cause the,"},{"start":247.914,"end":249.249,"text":"the craft to heat up."},{"start":249.249,"end":253.086,"text":"But we're in suits that give us cooling, so they keep our bodies cool."},{"start":253.086,"end":255.121,"text":"And it's kind of like you have air conditioning."},{"start":255.121,"end":258.791,"text":"So even though the vehicle gets really hot, the spaceship gets really hot, we stay at a"},{"start":258.791,"end":259.792,"text":"comfortable temperature."},{"start":259.792,"end":261.861,"text":"What types of things do we do in outer space?"},{"start":261.861,"end":267.133,"text":"Right now we're in low-Earth orbit, so that's where the space station is."},{"start":267.133,"end":268.901,"text":"We do two main things there."},{"start":268.901,"end":274.641,"text":"One is to keep it functioning and keep it working because it's a complex machine there"},{"start":274.641,"end":275.908,"text":"in low-Earth orbit."},{"start":275.908,"end":279.479,"text":"The other thing we do is we do research there and a lot of our time"},{"start":279.479,"end":284.684,"text":"is trying to understand the human body, understand different things that we need to take"},{"start":284.684,"end":290.089,"text":"the next step to the Moon to stay and after that to Mars."},{"start":290.089,"end":293.826,"text":"And so to keep exploring, we have to keep learning."},{"start":293.826,"end":297.33,"text":"I love not knowing what is inside each of these letters."},{"start":297.33,"end":299.299,"text":"And this one from Evan is really cool."},{"start":299.299,"end":301.034,"text":"The drawings are always my favorite."},{"start":301.034,"end":308.141,"text":"From Abigail in Saint George, Utah used a really awesome cat astronaut sticker here"},{"start":308.141,"end":310.61,"text":"who doesn't love a cat on a flying saucer?"},{"start":310.61,"end":312.445,"text":"Do astronauts believe in aliens?"},{"start":312.445,"end":313.613,"text":"Well, that's a good question."},{"start":313.613,"end":314.18,"text":"I don't know."},{"start":314.18,"end":316.716,"text":"Some maybe do and some maybe don't."},{"start":316.716,"end":320.286,"text":"I think it would be amazing to discover aliens in our lifetime."},{"start":320.286,"end":323.456,"text":"From my perspective, aliens probably don't look like little green men,"},{"start":323.456,"end":327.86,"text":"but they might be like tiny microorganisms that live or used to live on a planet"},{"start":327.86,"end":328.561,"text":"like Mars."},{"start":328.561,"end":331.898,"text":"Unequivocally, 100%, I believe in aliens."},{"start":331.898,"end":335.702,"text":"There is no way that you can be on the space station going around the Earth"},{"start":335.702,"end":340.54,"text":"and look out at night and see millions of stars and not think for certain."},{"start":340.54,"end":343.576,"text":"There are aliens out there and people ask me if I've ever seen an alien."},{"start":343.576,"end":345.378,"text":"And I say absolutely. 100%."},{"start":345.378,"end":347.88,"text":"I've seen aliens because you're looking at them every night."},{"start":347.88,"end":353.152,"text":"When you look out in the night sky, somewhere out there, there is some crazy civilization"},{"start":353.152,"end":355.588,"text":"doing some crazy work that we haven't discovered yet."},{"start":355.588,"end":356.656,"text":"I know it is out there."},{"start":356.656,"end":359.359,"text":"Thank you all so much for the letters that you write to us."},{"start":359.359,"end":363.262,"text":"It means so much to receive them and I love reading every single one."},{"start":363.262,"end":364.43,"text":"Thank you."},{"start":364.43,"end":367.6,"text":"These letters are the rocket fuel that we use."},{"start":367.6,"end":369.135,"text":"This is what keeps us going."},{"start":369.135,"end":373.573,"text":"So please don't stop sending them, please keep sending them and help us push this"},{"start":373.573,"end":374.34,"text":"mission forward."},{"start":374.34,"end":376.342,"text":"Because it's super important."},{"start":376.342,"end":377.143,"text":"Thank you."},{"start":377.143,"end":380.847,"text":"Thanks, everybody, for all your letters and your awesome questions."},{"start":380.847,"end":386.486,"text":"The curiosity is awesome and I hope you stay engaged and thinking about how the world"},{"start":386.486,"end":387.787,"text":"and the universe works."},{"start":387.787,"end":388.821,"text":"Thank you for your letters."},{"start":388.821,"end":389.856,"text":"Keep them coming."},{"start":389.856,"end":391.224,"text":"Have a great holiday."},{"start":391.224,"end":395.161,"text":"I am so thankful to be back here on Earth with my family and friends"},{"start":395.161,"end":399.866,"text":"and I wish you all the best this holiday season as you spend time with your family,"},{"start":399.866,"end":403.136,"text":"with your friends on our incredible planet, our home, the Earth."}],"glossary":{"jeanette":"Jeanette Epps (NASA astronotu)","epps":"Jeanette Epps (NASA astronotu)","nasa":"NASA (ABD Ulusal Havacılık ve Uzay Dairesi)","kayla":"Kayla Barron (NASA astronotu)","barron":"Kayla Barron (NASA astronotu)","kjell":"Kjell Lindgren (NASA astronotu)","lindgren":"Kjell Lindgren (NASA astronotu)","sara":"Sara (mektup yazan çocuğun adı)","charlie":"Charlie (mektup yazan çocuğun adı)","gabe":"Gabe (mektup yazan çocuğun adı)","evan":"Evan (mektup yazan çocuğun adı)","abigail":"Abigail (mektup yazan çocuğun adı)","kennedy":"Kennedy Uzay Merkezi (Florida'daki fırlatma üssü)","soyuz":"Soyuz (Rus uzay kapsülü ve roketi)","baikonur":"Baykonur (Kazakistan'daki uzay üssü)","cosmodrome":"kozmodrom, uzay üssü","kazakhstan":"Kazakistan","utah":"Utah (ABD'de bir eyalet)","t":"T-38 (astronotların eğitim uçağı)"}},{"id":"elephants-dream","type":"video","title":"Elephants Dream","creator":"Blender Foundation","year":2006,"level":"B1","category":"scifi","durationSeconds":654,"genre":"scifi","summaryTr":"Emo ve Proog, tuhaf makinelerle dolu bir dünyada yol alırken gördükleri şeyler konusunda anlaşamaz. Kısa sorular, yön tarifleri ve tekrarlanan günlük ifadelerle dinleme pratiği yap.","levelNoteTr":"B1, İngilizce altyazı ve kelime desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Konuşmalar çoğunlukla kısa, yavaş ve tekrarlıdır. Soyut olay örgüsünü yorumlamak ve birkaç mecazı anlamak daha ileri düzeyde olabilir; uzun sessiz sahneler vardır.","advisoryTr":"Karanlık ve gerçeküstü görüntüler, tehdit ve fiziksel şiddet içerir; küçük çocuklar için uygun olmayabilir.","videoUrl":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-240.mp4","sizeMB":31},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-360.mp4","sizeMB":50},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-480.mp4","sizeMB":70},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-720.mp4","sizeMB":117}],"source":{"name":"Blender Foundation — Elephants Dream","url":"https://orange.blender.org/","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5/","credit":"(CC) Blender Foundation / Netherlands Media Art Institute | orange.blender.org","licenseSourceUrl":"https://orange.blender.org/blog/creative-commons-license-2/","watchUrl":"https://video.blender.org/videos/watch/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText:Elephants_Dream.ogv.en.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar kaynak sayfasının geçmişinde)","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür. Üç küçük zaman çakışmasının bitişleri en fazla 0,009 saniye kısaltılmıştır."},"glossary":{"emo":"Emo (karakter adı)","proog":"Proog (karakter adı)","snarlers":"hırlayan şeyler; filmde hayalî makine adı","pulp":"posa; burada ezilmiş bir kütle","ground":"ezilmiş, öğütülmüş","sick":"hasta; burada rahatsız, dengesiz","babylon":"Babil","colossus":"dev heykel","rhodes":"Rodos","clockwork":"saat mekanizması; kusursuz işleyiş","hah":"hah! (ünlem)","b":"but kelimesinde kekeleme (ama)","n":"no kelimesinde kekeleme (hayır)"},"captions":[{"start":15,"end":18.13,"text":"At the left we can see…"},{"start":18.13,"end":20.5,"text":"At the right we can see the—"},{"start":20.5,"end":21.98,"text":"…the head-snarlers."},{"start":21.98,"end":24.55,"text":"Everything is safe… Perfectly safe."},{"start":24.55,"end":25.77,"text":"Emo?"},{"start":26.12,"end":27.22,"text":"Emo?"},{"start":28.62,"end":30.104,"text":"Watch out!"},{"start":46.56,"end":48.26,"text":"Are you hurt?"},{"start":51.99,"end":54.2,"text":"I don’t think so. You?"},{"start":55.52,"end":57.09,"text":"I’m OK."},{"start":57.09,"end":61.11,"text":"Get up, Emo! It’s not safe here."},{"start":62.03,"end":63.22,"text":"Let’s go."},{"start":63.22,"end":65.19,"text":"What’s next?"},{"start":65.19,"end":66.96,"text":"You’ll see!"},{"start":67.68,"end":68.84,"text":"You’ll see!"},{"start":76.03,"end":78.48,"text":"Emo! This way."},{"start":94.22999999999999,"end":95.47999999999999,"text":"Follow me!"},{"start":131.1,"end":132.52100000000002,"text":"Hurry, Emo!"},{"start":168.438,"end":170.063,"text":"You’re not paying attention!"},{"start":170.063,"end":174.31,"text":"I–I just want to answer the phone."},{"start":174.31,"end":177.04,"text":"Emo, look… I mean, listen."},{"start":179.14,"end":182,"text":"You have to learn to listen."},{"start":183.14,"end":185.04,"text":"This is not some game."},{"start":185.04,"end":189.18,"text":"You… I mean, we. We could easily die out here."},{"start":190.01,"end":194.39600000000002,"text":"Listen… Listen to the sounds of the machine."},{"start":198.05,"end":200,"text":"Listen to your breathing."},{"start":266.646,"end":269.313,"text":"Well, don’t you ever get tired of this?"},{"start":269.313,"end":271.09,"text":"Tired?!"},{"start":271.09,"end":273.31,"text":"Emo, the machine is like…"},{"start":273.31,"end":275.26,"text":"Like clockwork!"},{"start":275.26,"end":277.063,"text":"One move out of place…"},{"start":277.063,"end":279.12,"text":"…and you’re ground to a pulp."},{"start":280.95,"end":282.104,"text":"But isn’t it—"},{"start":282.104,"end":286.03,"text":"Pulp, Emo! Is that what you want? Pulp?"},{"start":287.104,"end":290.42,"text":"Emo, your goal in life…"},{"start":290.44,"end":291.95,"text":"…pulp?!"},{"start":341.31,"end":343.42,"text":"Emo, close your eyes."},{"start":344.15,"end":345.396,"text":"–Why?\n–Now!"},{"start":351.15,"end":351.97,"text":"OK."},{"start":353.11,"end":354.68,"text":"Good."},{"start":359.42,"end":362.1,"text":"What do you see at your left side, Emo?"},{"start":364.02,"end":366,"text":"–Nothing.\n–Really?"},{"start":366,"end":367.58,"text":"No, nothing at all."},{"start":367.58,"end":371.98,"text":"Really? A–And at your right? What do you see at your right side, Emo?"},{"start":373.31,"end":376.84,"text":"The same, Proog. Exactly the same…"},{"start":376.84,"end":379.896,"text":"–…nothing!\n–Great."},{"start":399.97,"end":402.72,"text":"Listen, Proog! Do you hear that?"},{"start":403.44,"end":404.56,"text":"Can we go here?"},{"start":405.063,"end":406.56,"text":"–There?\n–Yeah!"},{"start":406.58,"end":408.188,"text":"It isn’t safe, Emo."},{"start":409.14,"end":412.01,"text":"–B–But…\n–Trust me, it’s not."},{"start":413.02,"end":414.17,"text":"Well, maybe I could…"},{"start":414.17,"end":415.146,"text":"No."},{"start":417.1,"end":418.82,"text":"–But…\n–No!"},{"start":418.82,"end":420.24,"text":"No!"},{"start":420.771,"end":423.05,"text":"Any further questions, Emo?"},{"start":423.97,"end":425.09,"text":"N–No."},{"start":429.05,"end":430.08,"text":"Emo?"},{"start":431.14,"end":433.08,"text":"Emo, why?!"},{"start":433.08,"end":435.36,"text":"Emo, why…?"},{"start":435.36,"end":438.84,"text":"Why can’t you see the beauty of this place?"},{"start":438.84,"end":440.646,"text":"The way it works."},{"start":440.646,"end":443.92,"text":"How… How perfect it is."},{"start":443.92,"end":447.04,"text":"No, Proog, I don’t see."},{"start":447.04,"end":449.97,"text":"I don’t see because there’s nothing there."},{"start":451.05,"end":455.24,"text":"And why should I trust my life to something that isn’t there?"},{"start":455.24,"end":456.6,"text":"Well, can you tell me that?"},{"start":456.6,"end":457.38,"text":"Emo…"},{"start":457.38,"end":458.92,"text":"Answer me!"},{"start":462.97,"end":464,"text":"Proog…"},{"start":465.05,"end":466.854,"text":"…you’re a sick man!"},{"start":466.854,"end":468.90999999999997,"text":"Stay away from me!"},{"start":472.188,"end":474.854,"text":"No! Emo! It’s a trap!"},{"start":475.42,"end":476.979,"text":"Hah, “it’s a trap!”"},{"start":476.979,"end":481.229,"text":"At the left side you can see the Hanging Gardens of Babylon!"},{"start":481.96,"end":483.95,"text":"How’s that for a trap?"},{"start":485.72,"end":486.92,"text":"No, Emo."},{"start":489,"end":492.64,"text":"At the right side you can see—well guess what…"},{"start":492.64,"end":494.66,"text":"…the Colossus of Rhodes!"},{"start":495.32,"end":496.39,"text":"No!"},{"start":496.396,"end":500.16,"text":"The Colossus of Rhodes! And it is here just for you, Proog."},{"start":500.16,"end":501.688,"text":"Just for you!"},{"start":531,"end":533.021,"text":"It is there…"},{"start":533.021,"end":536.04,"text":"I’m telling you, Emo…"},{"start":537,"end":539.86,"text":"…it is… there…"}]},{"id":"how-big-is-space","type":"video","title":"How Big Is Space? We Asked a NASA Expert","creator":"NASA","year":2025,"level":"B1","category":"real","durationSeconds":96,"genre":"education","summaryTr":"Bir NASA bilim insanı tek bir soruyu cevaplıyor: Uzay ne kadar büyük? Işık yılı, galaksiler ve evrenin sınırı hakkında bir buçuk dakikalık, hızlı ve anlaşılır bir açıklama.","levelNoteTr":"B1, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Konuşma açık ve tempolu; light-year, galaxy, observable gibi bilim kelimeleri vardır.","advisoryTr":"Tüm yaşlara uygundur.","videoUrl":"https://images-assets.nasa.gov/video/How%20Big%20is%20Space/How%20Big%20is%20Space~medium.mp4","qualities":[{"label":"Standart","url":"https://images-assets.nasa.gov/video/How%20Big%20is%20Space/How%20Big%20is%20Space~medium.mp4","sizeMB":25},{"label":"Yüksek","url":"https://images-assets.nasa.gov/video/How%20Big%20is%20Space/How%20Big%20is%20Space~large.mp4","sizeMB":55}],"source":{"name":"NASA — How Big is Space? We Asked a NASA Expert","url":"https://images.nasa.gov/details/How%20Big%20is%20Space","license":"Kamu malı (NASA yapımı, ABD'de telife tabi değil)","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","credit":"NASA · A NASA 360 Production"},"subtitleSource":{"name":"NASA — resmî İngilizce SRT altyazısı","url":"https://images-assets.nasa.gov/video/How%20Big%20is%20Space/How%20Big%20is%20Space.srt","license":"Kamu malı (NASA)","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","changeNoteTr":"Altyazı sözleri korunmuş; zamanlar saniyeye dönüştürülmüştür."},"captions":[{"start":0,"end":3.136,"text":"How big is space?"},{"start":3.67,"end":5.171,"text":"We Asked a NASA Scientist."},{"start":5.171,"end":7.474,"text":"Space is really big."},{"start":7.474,"end":10.844,"text":"Thinking about our solar system, let's imagine you could get in a car"},{"start":10.844,"end":13.146,"text":"and drive to Pluto at highway speeds."},{"start":13.146,"end":15.782,"text":"It would take you about 6,000 years to get there."},{"start":15.782,"end":19.252,"text":"When we start to think about other stars outside of our solar system,"},{"start":19.252,"end":22.022,"text":"we need to think about another unit of distance."},{"start":22.022,"end":24.958,"text":"This is why astronomers use the unit light-years."},{"start":24.958,"end":28.228,"text":"Light travels at 186,000 miles per second."},{"start":28.528,"end":31.531,"text":"One light year is about 6 trillion miles."},{"start":31.664,"end":35.101,"text":"The closest star to our Sun is about four light years away."},{"start":35.869,"end":40.373,"text":"Our own Milky Way galaxy is about 100,000 light-years across."},{"start":40.44,"end":43.576,"text":"We know from deep field images of the universe that there are hundreds"},{"start":43.576,"end":46.579,"text":"of billions, perhaps a trillion other galaxies."},{"start":46.713,"end":49.482,"text":"Using some of the deepest images yet from JWST,"},{"start":49.516,"end":51.017,"text":"we've been able to see galaxies"},{"start":51.017,"end":54.02,"text":"that emitted their light about 13 and a half billion years ago."},{"start":54.354,"end":58.158,"text":"Now, here's a really important thing. Because the universe is expanding,"},{"start":58.191,"end":59.859,"text":"those most distant galaxies"},{"start":59.859,"end":63.696,"text":"are actually much further away than 13 and a half billion light years."},{"start":64.23,"end":67.934,"text":"I'm glossing over some math here, but we can estimate that the observable"},{"start":67.934,"end":71.704,"text":"universe is about 92 billion light-years across."},{"start":72.105,"end":75.742,"text":"But we're pretty sure that the universe is even bigger than what we can see."},{"start":76.309,"end":78.511,"text":"And here's where things get really weird,"},{"start":78.511,"end":82.248,"text":"we don't actually know if the universe is finite or infinite."},{"start":82.649,"end":86.252,"text":"As much as we've learned about the universe, science has no reliable"},{"start":86.252,"end":89.322,"text":"estimate of the actual size of the entire universe."},{"start":89.889,"end":91.925,"text":"We Asked a NASA Scientist."},{"start":91.925,"end":96.029,"text":"NASA. A NASA 360 Production."}],"glossary":{"nasa":"NASA (ABD Ulusal Havacılık ve Uzay Dairesi)","pluto":"Plüton (cüce gezegen)","milky":"Milky Way: Samanyolu galaksisi","jwst":"JWST: James Webb Uzay Teleskobu"}},{"id":"morevna-episode-3","type":"video","title":"Morevna: Episode 3 — Underground","creator":"Morevna Project","year":2018,"level":"B1","category":"adventure","durationSeconds":617,"genre":"fantasy","summaryTr":"Rus masalı Marya Morevna'nın bilim kurgu dünyasında geçen anime tarzı uyarlaması. Marya malikânesinden çıkarken tamirci Ivan'a tüm anahtarları bırakır ve tek bir kapıyı açmamasını tembihler. Ivan merakına yenik düşer.","levelNoteTr":"B1, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Konuşmalar kısa ama hızlıdır; telsiz konuşmaları, emir cümleleri ve teknik kelimeler vardır.","advisoryTr":"Çizgi film tarzı dövüş ve silah sahneleri, hafif argo (\"damn\") içerir. Dizinin 3. bölümüdür ve merak uyandıran açık bir sonla biter.","videoUrl":"https://peertube.touhoppai.moe/static/streaming-playlists/hls/4adb3a75-6784-4e99-8a5d-66d13578ba9d/1c5c2052-b4eb-4fd2-9819-d62aa67d5403-720-fragmented.mp4","qualities":[{"label":"360p","url":"https://peertube.touhoppai.moe/static/streaming-playlists/hls/4adb3a75-6784-4e99-8a5d-66d13578ba9d/c0727f91-890b-48e4-a4dd-2dc750b3b42e-360-fragmented.mp4","sizeMB":28},{"label":"720p","url":"https://peertube.touhoppai.moe/static/streaming-playlists/hls/4adb3a75-6784-4e99-8a5d-66d13578ba9d/1c5c2052-b4eb-4fd2-9819-d62aa67d5403-720-fragmented.mp4","sizeMB":56},{"label":"1080p","url":"https://peertube.touhoppai.moe/static/streaming-playlists/hls/4adb3a75-6784-4e99-8a5d-66d13578ba9d/3dbfc20c-9e3e-447c-a529-0298d87d3780-1080-fragmented.mp4","sizeMB":96}],"source":{"name":"Morevna Project — Morevna Episode 3 (English)","url":"https://morevnaproject.org/","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Morevna Project · Adamant Art School of Gorno-Altaisk ile birlikte","watchUrl":"https://peertube.touhoppai.moe/videos/watch/4adb3a75-6784-4e99-8a5d-66d13578ba9d"},"subtitleSource":{"name":"Morevna Project — İngilizce SRT altyazısı","url":"https://raw.githubusercontent.com/morevnaproject/subtitles-translation/master/output/morevna-ep3/morevna-ep3-eng.srt","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"captions":[{"start":0.36,"end":2.4,"text":"Morevna Project..."},{"start":2.88,"end":7,"text":"...in association with \"Adamant\" Art School of Gorno-Altaisk..."},{"start":7.44,"end":9.24,"text":"presents"},{"start":26.4,"end":30.4,"text":"\"Falcon\", \"Falcon\", respond. This is \"Hawk\". What's your status?"},{"start":55,"end":57.68,"text":"Hey officer, can I help you somehow?"},{"start":59.92,"end":61.56,"text":"Stay away, stay away!"},{"start":61.72,"end":63.6,"text":"I am a government agent!"},{"start":64.56,"end":67.12,"text":"I know, I know..."},{"start":67.84,"end":70.56,"text":"And I am the owner of this mansion."},{"start":72.96,"end":78.96,"text":"Episode 3: Underground"},{"start":99.48,"end":105.04,"text":"Ah, Marya Morevna, I just don't get it. We aren't that rich..."},{"start":105.8,"end":109.56,"text":"...but they are coming here like bees to a..."},{"start":109.8,"end":111.36,"text":"...honeypot!"},{"start":111.8,"end":113.56,"text":"I am not a bee, I am a \"Hawk\"."},{"start":113.84,"end":115.6,"text":"Spread your wings, Hawk."},{"start":118.36,"end":120.36,"text":"But it seems like you're having fun."},{"start":120.64,"end":122.2,"text":"Of course I am!"},{"start":122.64,"end":125.16,"text":"But still, why did you drop my favorite toolbox on him?"},{"start":141.16,"end":144.72,"text":"I just can't figure out what you did to them if they're after you so much..."},{"start":145.16,"end":147.16,"text":"I have no idea."},{"start":147.72,"end":149.28,"text":"Going somewhere?"},{"start":149.6,"end":152.24,"text":"I am going to a biker party, and I won't be back until tomorrow."},{"start":152.44,"end":155.16,"text":"Dinner on plate, firewood in shed, dog food under sink..."},{"start":155.44,"end":156.68,"text":"Do we have dogs here?"},{"start":156.92,"end":161.68,"text":"...in case of a power outage, turn on the electric generator and don't forget to restart the air defense system."},{"start":161.88,"end":164.12,"text":"Here are the keys to all of the doors in the mansion."},{"start":164.24,"end":168.56,"text":"Feel free to go anywhere, but don't touch this key and don't unlock the door."},{"start":168.84,"end":169.6,"text":"But why?"},{"start":169.84,"end":172.16,"text":"Just don't!"},{"start":173.36,"end":175.12,"text":"Well, bye..."},{"start":191.2,"end":195.76,"text":"So dear, now I can have some fun with you then."},{"start":233,"end":235.44,"text":"Hm, it seems this lovely evening is in danger."},{"start":242.36,"end":246.68,"text":"Stay here, I'll be right back."},{"start":248.68,"end":251.24,"text":"Caption on the door: \"Cellar\""},{"start":277.2,"end":279.4,"text":"Aha, here it is!"},{"start":285.84,"end":287.2,"text":"What?"},{"start":297.72,"end":299.84,"text":"Could it be..."},{"start":303.12,"end":307.08,"text":"...feel free to go anywhere, but don't touch this key..."},{"start":353.32,"end":355.68,"text":"Hey, is anybody here?"},{"start":358.04,"end":360.92,"text":"There is something wrong with your engine here."},{"start":364.32,"end":366.8,"text":"Damn you…"},{"start":367.52,"end":370.36,"text":"Ah? Who is it?"},{"start":374.28,"end":377.32,"text":"Come on..."},{"start":381.52,"end":386.28,"text":"My name is Ivan Tsarevich... and I am very good at fixing things."},{"start":390.04,"end":391.64,"text":"Inside..."},{"start":398.96,"end":401.16,"text":"There..."},{"start":405.12,"end":410.4,"text":"The framework is quite unusual. It will be a challenge to get inside."},{"start":411.8,"end":414.12,"text":"So, let's start!"},{"start":418.24,"end":420.84,"text":"Yes..."},{"start":423.92,"end":426.4,"text":"Excellent..."},{"start":428.96,"end":431.12,"text":"Well done."},{"start":434.4,"end":437.6,"text":"Certainly, you've got talent..."},{"start":439.16,"end":442.24,"text":"This is not the hardest one..."},{"start":442.48,"end":446.08,"text":"Still, it's quite strange that it's so tricky to open this thing..."},{"start":452.56,"end":453.72,"text":"Well, that's all."},{"start":454.6,"end":457.24,"text":"Open Sesame!"},{"start":480.72,"end":485.48,"text":"What's up? You are almost there!"},{"start":486.16,"end":494.52,"text":"I don't know... there seems to be some piece of paper here... I'm going to remove it now."},{"start":574.88,"end":576.04,"text":"Oh, no..."}],"glossary":{"morevna":"Morevna (Marya Morevna, Rus masal kahramanı)","marya":"Marya Morevna (Rus masal kahramanı)","adamant":"Adamant (sanat okulunun adı)","gorno":"Gorno-Altaysk (Rusya'da bir şehir)","altaisk":"Gorno-Altaysk (Rusya'da bir şehir)","ivan":"Ivan Tsarevich (masaldaki prens)","tsarevich":"Tsarevich: çar oğlu, prens","hm":"hımm (düşünme sesi)","sesame":"Open Sesame: Açıl susam açıl!"}},{"id":"voa-movie-night","type":"video","category":"fun","title":"Movie Night","creator":"VOA Learning English","year":2021,"level":"B1","durationSeconds":300,"genre":"comedy","summaryTr":"Anna ve Pete sinemaya gider. Patlamış mısır, milkshake ve telefon derken sessiz kalma işi beklenmedik şekilde tersine döner. Komik bir skeçle kibar rica kalıplarını dinle.","levelNoteTr":"Seviye, altyazı ve kelime desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Ana skeçteki ekran altyazıları dokunulabilir olarak hazırlanmıştır. VOA’nın Dinle/Konuş tekrarları ve ara açıklamaları özgün hâliyle korunur; bu bölümlerde her cümle için dokunulabilir altyazı bulunmaz.","videoUrl":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/72/72d73c46-9f5a-47ba-96dc-4a2e460ce714_720p.mp4","qualities":[{"label":"240p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/72/72d73c46-9f5a-47ba-96dc-4a2e460ce714_240p.mp4","sizeMB":13},{"label":"360p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/72/72d73c46-9f5a-47ba-96dc-4a2e460ce714.mp4","sizeMB":18},{"label":"480p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/72/72d73c46-9f5a-47ba-96dc-4a2e460ce714_480p.mp4","sizeMB":27},{"label":"720p","url":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/72/72d73c46-9f5a-47ba-96dc-4a2e460ce714_720p.mp4","sizeMB":65}],"source":{"name":"VOA Learning English — Movie Night","url":"https://learningenglish.voanews.com/a/lets-learn-english-level-2-lesson-19/4242927.html","watchUrl":"https://learningenglish.voanews.com/a/lets-learn-english-level-2-lesson-19/4242927.html","license":"VOA özgün üretimi · Kamu malı","licenseUrl":"https://learningenglish.voanews.com/p/6021.html","credit":"Voice of America / VOA Learning English. Özgün video bütünüyle ve değiştirilmeden oynatılır."},"subtitleSource":{"name":"VOA’nın video üzerindeki İngilizce ekran altyazıları","url":"https://learningenglish.voanews.com/a/lets-learn-english-level-2-lesson-19/4242927.html","license":"VOA özgün metni · Kamu malı","licenseUrl":"https://learningenglish.voanews.com/p/6021.html","credit":"Voice of America; metin çıkarımı ve zaman eşlemesi: Lantern English","changeNoteTr":"Ana skeçteki ekran yazıları aktarılmış, OCR yazım hataları düzeltilmiş ve yaklaşık 0,5 saniye çözünürlükle zamanlanmıştır. Dinle/Konuş alıştırmalarındaki boşluklar korunmuştur."},"glossary":{"plot":"film veya hikâyenin olay örgüsü","preview":"fragman; yakında gösterilecek filmin tanıtımı","rock":"burada: koltuğun ileri geri sallanması","thick":"milkshake için: koyu kıvamlı","shush":"birine sessiz olmasını söylemek","mind":"would you mind: ... yapar mısın / sakıncası var mı?"},"captions":[{"start":6.5,"end":10,"text":"Hi, can you tell me how to get to your movie theater?"},{"start":12,"end":15,"text":"Oh, that's easy. Okay, thank you. Bye."},{"start":15.5,"end":19,"text":"Hi, Pete! Thanks for the movie invitation."},{"start":19,"end":20,"text":"Yeah, sure Anna."},{"start":20,"end":23.5,"text":"I love movies. I love the plot! I love the set design!"},{"start":23.5,"end":26,"text":"I love the costumes! I love -"},{"start":26,"end":31,"text":"Anna, I take movies very seriously. You're not one of"},{"start":31,"end":35,"text":"those people who talks during a movie, are you?"},{"start":35,"end":37.5,"text":"No."},{"start":37.5,"end":38.5,"text":"Good."},{"start":39.5,"end":44.5,"text":"Anna loves movies. And she loves talking about movies."},{"start":45,"end":47.5,"text":"And Pete doesn't sound happy about that."},{"start":47.5,"end":50,"text":"But he's trying to be polite."},{"start":98.5,"end":104,"text":"I love the smell of popcorn."},{"start":104,"end":107.5,"text":"I love seats that rock."},{"start":107.5,"end":110.5,"text":"I love when people are quiet."},{"start":117.5,"end":119.5,"text":"Ooh look, the previews are starting!"},{"start":119.5,"end":121.5,"text":"I love to see what movies are coming out."},{"start":121.5,"end":123.5,"text":"Oh, this one looks good!"},{"start":123.5,"end":129,"text":"Anna, the previews are part of the movie experience."},{"start":129,"end":130.5,"text":"So, would you mind not talking?"},{"start":130.5,"end":132.5,"text":"Oh, sure, sure."},{"start":144,"end":148,"text":"Anna, I was wondering: are you almost finished with that?"},{"start":148,"end":154.5,"text":"No. There's still a lot of milkshake at the bottom."},{"start":154.5,"end":157,"text":"Anna, do you mind not drinking so loudly?"},{"start":157,"end":160,"text":"I'll try. But it's really thick."},{"start":163,"end":164.5,"text":"Anna, what are you doing?!"},{"start":164.5,"end":166.5,"text":"Shh!"},{"start":166.5,"end":170,"text":"I'm not the one making all the noise."},{"start":172,"end":173.5,"text":"I'm done now."},{"start":184.5,"end":189.5,"text":"Anna, would you mind opening that a little bit more quietly?"},{"start":189.5,"end":191.5,"text":"I'll try."},{"start":197,"end":199,"text":"Anna, just give it to me!"},{"start":200.5,"end":202,"text":"Shhh!"},{"start":202,"end":205.5,"text":"It's not mine. I'm opening it for her."},{"start":205.5,"end":207,"text":"Shhhhhh!!"},{"start":207,"end":208.5,"text":"Here!"},{"start":208.5,"end":211,"text":"Thanks, Pete."},{"start":211,"end":214.5,"text":"Now, would you mind being more quiet?"},{"start":223,"end":229.5,"text":"Excuse me, would you mind turning down your phone light?"},{"start":230.5,"end":233.5,"text":"Oh, sorry! I forgot to turn my phone off."},{"start":233.5,"end":239,"text":"Oh no! I dropped it. Where is it?"},{"start":239,"end":242.5,"text":"Anna, can you please turn your phone off?"},{"start":242.5,"end":247,"text":"Excuse me, would you mind lending me your phone light for a minute?"},{"start":247,"end":250,"text":"No! I'll get it!"},{"start":250,"end":252.5,"text":"Shhhhh!"},{"start":252.5,"end":255.5,"text":"Look, people, I'm not the noisy one here!"},{"start":255.5,"end":258,"text":"So, you need to shush the right person."},{"start":258,"end":262.5,"text":"And I should know about shushing! I shush people all the time!"},{"start":262.5,"end":266.5,"text":"Excuse me, sir. You can't yell in a movie theater."},{"start":266.5,"end":268.5,"text":"Would you mind coming with me?"},{"start":268.5,"end":275.5,"text":"You're kicking me out? Me? But I'm always the quiet one in the movie!"},{"start":275.5,"end":280.5,"text":"Pete should know better. You have to be quiet in a movie theater."},{"start":281,"end":283,"text":"Shh! The movie's starting!"},{"start":284,"end":288,"text":"That's a surprise. I thought Anna would be the noisy one."},{"start":288,"end":293,"text":"Well, she was ... with her food. But Pete did all of the talking."},{"start":293,"end":298,"text":"At least he tried to be polite by using indirect questions."}],"categoryTr":"Komedi skeçi","captionCoverage":"main-dialogue"},{"id":"nps-my-trip-to-the-beach","type":"video","category":"real","title":"My Trip to the Beach","creator":"National Park Service · Ranger Scott","year":2020,"level":"B1","durationSeconds":206.32,"genre":"adventure","summaryTr":"Ranger Scott ile göl kıyısında hayalî bir geziye çık: soğuk su, martılar, kumdan kaleler ve piknik vakti! Duyularla anlatılan sakin ve neşeli bir kısa hikâye.","levelNoteTr":"B1, İngilizce altyazı ve kelime desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Anlatım yavaş ve nettir; duyuları anlatan sıfatlar ve birkaç doğa kelimesi içerir.","videoUrl":"https://www.nps.gov/nps-audiovideo/legacy/piro/128F745D-C3B4-DDE0-EB19452A0DCDE0DF/piro-StoryTimewithaRanger-MyTriptotheBeach_854x480.mp4","qualities":[{"label":"240p","url":"https://www.nps.gov/nps-audiovideo/legacy/piro/128F745D-C3B4-DDE0-EB19452A0DCDE0DF/piro-StoryTimewithaRanger-MyTriptotheBeach_426x240.mp4"},{"label":"360p","url":"https://www.nps.gov/nps-audiovideo/legacy/piro/128F745D-C3B4-DDE0-EB19452A0DCDE0DF/piro-StoryTimewithaRanger-MyTriptotheBeach_640x360.mp4"},{"label":"480p","url":"https://www.nps.gov/nps-audiovideo/legacy/piro/128F745D-C3B4-DDE0-EB19452A0DCDE0DF/piro-StoryTimewithaRanger-MyTriptotheBeach_854x480.mp4"},{"label":"720p","url":"https://www.nps.gov/nps-audiovideo/legacy/piro/128F745D-C3B4-DDE0-EB19452A0DCDE0DF/piro-StoryTimewithaRanger-MyTriptotheBeach_1280x720.mp4"}],"source":{"name":"National Park Service — Story Time with a Ranger","url":"https://www.nps.gov/media/video/view.htm?id=128F745D-C3B4-DDE0-EB19452A0DCDE0DF","watchUrl":"https://www.nps.gov/media/video/view.htm?id=128F745D-C3B4-DDE0-EB19452A0DCDE0DF","license":"NPS özgün üretimi · ABD kamu malı","licenseUrl":"https://www.nps.gov/aboutus/disclaimer.htm","credit":"National Park Service / Pictured Rocks National Lakeshore; Taylor Mace (Ranger Taylor), Ranger Scott. Özgün video değiştirilmeden oynatılır."},"subtitleSource":{"name":"National Park Service — Resmî İngilizce altyazı","url":"https://www.nps.gov/nps-audiovideo/legacy/closed-caption/mwr/avElement/piro-StoryTimewithaRanger-MyTriptotheBeach-captions.vtt","license":"NPS özgün metni · ABD kamu malı","licenseUrl":"https://www.nps.gov/aboutus/disclaimer.htm","credit":"National Park Service","changeNoteTr":"Resmî WebVTT altyazısı sözleri ve zamanları korunarak uygulama biçimine dönüştürülmüş, satır sonları boşlukla birleştirilmiştir."},"glossary":{"aqua":"açık mavi-yeşil; su rengi","driftwood":"suya düşüp kıyıya vurmuş ağaç parçası","lakeshore":"göl kıyısı","rippling":"küçük dalgalarla kıpırdayan","bark":"ağacın kabuğu","rumble":"guruldama; burada karnın guruldaması","superior":"Lake Superior: Superior Gölü (yer adı)","twelvemile":"Twelvemile Beach (plaj adı)","scott":"Scott (anlatıcının adı)"},"captions":[{"start":0.22,"end":4.56,"text":"[WAVES]"},{"start":4.56,"end":8.2,"text":"Welcome to Story Time with a Ranger. I'm Ranger Scott and I work for"},{"start":8.2,"end":11.6,"text":"Pictured Rocks National Lakeshore. I'll be reading you a story about a family"},{"start":11.6,"end":14.78,"text":"visiting one of our beaches  found here in the park."},{"start":14.78,"end":19.24,"text":"So, if you're ready, I'll begin! [WAVES]"},{"start":19.24,"end":26.16,"text":"\"My Trip to the Beach'\" written by Ranger Taylor and read by Ranger Scott. [WAVES]"},{"start":26.16,"end":29.28,"text":"It is a warm summer day,  the sun shines bright,"},{"start":29.28,"end":32.48,"text":"and you are with your family  visiting Pictured Rocks."},{"start":32.48,"end":36.719,"text":"You are walking on a sandy path towards the biggest of the Great Lakes -"},{"start":36.719,"end":41.04,"text":"Lake Superior. What do you hear in the distance?  [QUIET WAVES]"},{"start":41.04,"end":44.78,"text":"Can you hear the waves up ahead? [WAVES]"},{"start":44.78,"end":50.3,"text":"As you come to the edge of the trees, the wide  beach lies before you. It's called Twelvemile Beach."},{"start":50.3,"end":56.16,"text":"And do you know why? Because this beach  stretches for 12 long miles along the shore."},{"start":56.16,"end":59.88,"text":"You see that Lake Superior  is a brilliant aqua blue"},{"start":59.88,"end":65.22,"text":"and the moving waves have white  watery caps on top of them. [WAVES]"},{"start":65.22,"end":70.7,"text":"You step onto the beach and take off your shoes.  How does the sand feel between your toes?"},{"start":70.7,"end":75.58,"text":"Perhaps its feels soft and firm  all at the same time."},{"start":75.58,"end":81.94,"text":"Walking through the warm sand, you and your  family head to the water's edge. [WAVES]"},{"start":81.94,"end":86.5,"text":"You watch the rhythm of the waves washing up  onto the sand and flowing back out to the lake."},{"start":86.5,"end":91.6,"text":"Washing up...flowing back... washing up...flowing back"},{"start":91.6,"end":96.1,"text":"The sun is really warm on your body now.  So, it's time to put your toes in the water."},{"start":96.1,"end":100.96000000000001,"text":"What do you think it'll feel like? [WAVES]"},{"start":100.96000000000001,"end":105.34,"text":"It's quite a change to walk from the warm sand into the cold water, isn't it?"},{"start":105.34,"end":108.96000000000001,"text":"You can see the sunlight  sparkling on the rippling surface."},{"start":108.96000000000001,"end":111.64,"text":"Looking down through the  clear water of Lake Superior,"},{"start":111.64,"end":114.8,"text":"you can see the tan  sandy bottom below."},{"start":114.8,"end":119.58,"text":"[BIRD CALL] What's that?!"},{"start":119.58,"end":125.22,"text":"Something is alive nearby. You look up  into the blue sky. What do you see?"},{"start":125.22,"end":130.7,"text":"There it is. You spot a seagull flying high in the sky. [BIRD CALL]"},{"start":130.7,"end":137.86,"text":"You're finally cooled off now. So, you walk out of the  water and continue down the beach. [WAVES]"},{"start":137.86,"end":143.44,"text":"You can see the wet wavy lines in the sand where  the last big waves washed up onto the shore."},{"start":143.44,"end":147.2,"text":"You spot something up ahead that the  waves have brought in from the lake."},{"start":147.2,"end":152.3,"text":"What is that? You walk closer  to investigate. [WAVES]"},{"start":152.3,"end":158.06,"text":"It's a piece of a tree that fell into the lake  a long time ago and it's called driftwood."},{"start":158.06,"end":162.86,"text":"The water has rubbed off the bark and polished it smooth and cool."},{"start":162.86,"end":169.14,"text":"Wanting our park visitors to see this treasure,  you put it back where you found it. [WAVES]"},{"start":169.14,"end":173.2,"text":"You hear a rumble but there  isn't a rain cloud in sight."},{"start":173.2,"end":177.84,"text":"It's your belly and that means it's time for a picnic with your family."},{"start":177.84,"end":182,"text":"Afterwards maybe you'll find colorful rocks to make patterns in the sand,"},{"start":182,"end":186.7,"text":"or gently toss them into the lake. Or maybe you'll build giant castles,"},{"start":186.7,"end":191.68,"text":"or whole kingdoms in the sand. Whatever your adventure you choose,"},{"start":191.68,"end":194.48,"text":"the beach awaits.  [WAVES]"},{"start":194.48,"end":199.2,"text":"\"The End.\" Thanks for joining me  today for Story Time with a Ranger."},{"start":199.2,"end":201.4,"text":"I hope you come again soon."},{"start":201.4,"end":206.32,"text":"[WAVES]"}],"categoryTr":"Doğa hikâyesi"},{"id":"sintel","type":"video","title":"Sintel","creator":"Blender Foundation","year":2010,"level":"B1","category":"adventure","durationSeconds":888,"genre":"fantasy","summaryTr":"Sintel, yaralı bir yavru ejderhayla dost olur. Dostunu aramak için çıktığı yolculuk, onu uzak ve tehlikeli topraklara götürür.","levelNoteTr":"B1, Lantern English'in İngilizce altyazı desteğiyle izleme için yaptığı tahmini değerlendirmedir; resmî bir CEFR derecesi değildir. Kısa diyaloglar ve görsel anlatım takibi kolaylaştırır. Bazı fantastik kelimeler ve mecazlar sözlük desteği gerektirebilir.","advisoryTr":"Fantastik çatışma, yaralanma ve ölüm içeren üzücü sahneler bulunur.","videoUrl":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-240.mp4","sizeMB":49},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-360.mp4","sizeMB":84},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-480.mp4","sizeMB":120},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-720.mp4","sizeMB":200},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-818.mp4","sizeMB":239}],"source":{"name":"Blender Foundation — Sintel / Durian Open Movie Project","url":"https://durian.blender.org/download/","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","credit":"© copyright Blender Foundation | durian.blender.org","licenseSourceUrl":"https://durian.blender.org/sharing/","watchUrl":"https://video.blender.org/w/2PcJe5aZqozRvH7MJ8BTmC","creditNoteTr":"Film, sonundaki tam jenerik korunarak resmî Blender kaynağından oynatılır. Film ve İngilizce altyazı metni değiştirilmemiştir; altyazı zamanları site için sayısal biçime dönüştürülmüştür. Türkçe öğrenme açıklamaları Lantern English tarafından hazırlanmıştır."},"subtitleSource":{"name":"Sintel — resmî İngilizce SRT altyazısı","url":"https://durian.blender.org/wp-content/content/subtitles/sintel_en.srt","license":"CC BY 3.0"},"glossary":{"unprepared":"hazırlıksız","scales":"Scales: Sintel'in ejderha dostunun adı (kelime anlamı: pullar)","sintel":"Sintel: filmin ana karakterinin adı","kindred":"benzer duygu ve düşünceleri paylaşan, yakın","spirit":"ruh; burada kindred spirit: ruh ikizi, yakın hissettiğin kişi","gatekeepers":"geçitlerin veya kapıların bekçileri","blade":"bıçak veya kılıcın keskin kısmı","shed":"dökmek; shed blood: kan dökmek","dear":"çok sevilen, değerli","quest":"uzun ve zorlu arayış","shhh":"şşşt, sessiz ol"},"captions":[{"start":107.25,"end":110.5,"text":"This blade has a dark past."},{"start":111.8,"end":115.8,"text":"It has shed much innocent blood."},{"start":118,"end":121.45,"text":"You're a fool for traveling alone,\nso completely unprepared."},{"start":121.75,"end":124.8,"text":"You're lucky your blood's still flowing."},{"start":125.25,"end":126.3,"text":"Thank you."},{"start":127.5,"end":129,"text":"So..."},{"start":129.4,"end":133.8,"text":"What brings you to\nthe land of the gatekeepers?"},{"start":135,"end":137.5,"text":"I'm searching for someone."},{"start":138,"end":142.2,"text":"Someone very dear?\nA kindred spirit?"},{"start":143.4,"end":145,"text":"A dragon."},{"start":148.85,"end":151.75,"text":"A dangerous quest for a lone hunter."},{"start":152.95,"end":155.87,"text":"I've been alone for\nas long as I can remember."},{"start":207.25,"end":210.5,"text":"We're almost done. Shhh..."},{"start":210.75,"end":213.5,"text":"Hey, sit still."},{"start":228.25,"end":232.25,"text":"Good night, Scales."},{"start":250.35,"end":253.85,"text":"Get him, Scales! Come on!"},{"start":265.25,"end":268.25,"text":"Scales?"},{"start":304,"end":307.5,"text":"Yeah! Come on!"},{"start":338.75,"end":342,"text":"Scales!"},{"start":445.85,"end":447.5,"text":"I have failed."},{"start":452.8,"end":456.5,"text":"You've only failed to see..."},{"start":457.8,"end":460.5,"text":"These are dragon lands, Sintel."},{"start":460.85,"end":464,"text":"You are closer than you know."},{"start":557.6,"end":559.5,"text":"Scales!"},{"start":621.6,"end":624,"text":"Scales?"},{"start":626.2,"end":629.8,"text":"Scales..."}]},{"id":"tears-of-steel","type":"video","title":"Tears of Steel","creator":"Blender Foundation","year":2012,"level":"B1","category":"scifi","durationSeconds":734,"genre":"scifi","summaryTr":"Bir bilim kurgu çekim platosunda eski bir aşkın hesaplaşması, robotlar ve zamana karşı yarış iç içe geçer. Konuşmalar günlük dilde ve sahne sahne ilerler.","levelNoteTr":"B1, Lantern English'in İngilizce altyazı desteğiyle izleme için yaptığı tahmini değerlendirmedir; resmî bir CEFR derecesi değildir. Konuşmalar günlük dildedir; birkaç argo ve sinema terimi (ad-lib, abort, cut) sözlük desteği gerektirebilir. Sintel'e göre konuşma daha yoğundur ve daha uzun diyaloglar içerir.","advisoryTr":"Bilim kurgu aksiyonu ve robot saldırısı sahneleri vardır. Konuşmalarda hafif argo ve küfür geçer.","videoUrl":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-240.mp4","sizeMB":50},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-360.mp4","sizeMB":86},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-480.mp4","sizeMB":122},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-720.mp4","sizeMB":225},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-800.mp4","sizeMB":248}],"source":{"name":"Blender Foundation — Tears of Steel / Mango Open Movie Project","url":"https://mango.blender.org/","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","credit":"(CC) Blender Foundation | mango.blender.org","licenseSourceUrl":"https://mango.blender.org/sharing/","watchUrl":"https://video.blender.org/videos/watch/8533ea43-4271-4a57-9694-e9d0b35e1aa1","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından oynatılır. Film ve İngilizce altyazı metni değiştirilmemiştir; altyazı zamanları site için sayısal biçime dönüştürülmüştür. Türkçe öğrenme açıklamaları Lantern English tarafından hazırlanmıştır."},"subtitleSource":{"name":"Tears of Steel — resmî İngilizce SRT altyazısı (TOS-en.srt)","url":"https://download.blender.org/demo/movies/ToS/subtitles/TOS-en.srt","license":"CC BY 3.0"},"glossary":{"jerk":"aşağılık herif, hıyar","passions":"tutkular","robotics":"robot bilimi, robotik","freaked":"korkmuş, tedirgin olmuş (freak out)","freaky":"ürkütücü, tuhaf","claws":"pençeler","synced":"senkronize edildi","overwrite":"üzerine yazma","abort":"iptal etmek, yarıda kesmek","tender":"nazik, şefkatli","crush":"ezmek, ezip geçmek","rockstar":"rock yıldızı; çok başarılı kişi","vivacissimo":"müzik terimi: çok canlı ve hızlı","captain":"kaptan"},"captions":[{"start":23,"end":24.5,"text":"You're a jerk, Thom."},{"start":25,"end":27,"text":"Look Celia, we have to follow our passions;"},{"start":27,"end":30.5,"text":"...you have your robotics, and I\njust want to be awesome in space."},{"start":30.8,"end":34,"text":"Why don't you just admit that\nyou're freaked out by my robot hand?"},{"start":34.5,"end":36,"text":"I'm not freaked out by- it's..."},{"start":37,"end":38,"text":"...alright! Fine!"},{"start":38,"end":41,"text":"I'm freaked out! I have nightmares\nthat I'm being chased..."},{"start":41,"end":42,"text":"...by these giant robotic claws of death..."},{"start":42.2,"end":45,"text":"\"Fourty years later\"\nWhatever, Thom. We're done."},{"start":50,"end":53.5,"text":"Robot's memory synced and locked!"},{"start":61,"end":63,"text":"This is pretty freaky."},{"start":117,"end":119,"text":"Shouldn't you be down there?"},{"start":131,"end":133,"text":"I heard you guys talking last night."},{"start":136,"end":138,"text":"It's not my fault, you know."},{"start":191,"end":192,"text":"Are you ready?"},{"start":193,"end":195,"text":"Of course you're ready, you're a rockstar."},{"start":197,"end":198,"text":"How's it looking, Barley?"},{"start":199,"end":201,"text":"We should have about ten minutes..."},{"start":201.5,"end":203,"text":"Well that's perfect."},{"start":203.5,"end":206.5,"text":"We're on in one! All systems go!\nYeah you, go!"},{"start":208,"end":212,"text":"Go! Move your asses! Go go go!"},{"start":213,"end":217,"text":"I love it! Come on, go!"},{"start":223,"end":224,"text":"That's nice."},{"start":224.5,"end":225.7,"text":"Nothing to worry about."},{"start":226,"end":227,"text":"Thom."},{"start":231,"end":233,"text":"There she is."},{"start":233.5,"end":234.5,"text":"Now."},{"start":235,"end":236,"text":"You love her."},{"start":237,"end":238.5,"text":"She is your passion!"},{"start":240,"end":241,"text":"Be tender to her."},{"start":241.5,"end":244.5,"text":"Be honest! Eh- be tender."},{"start":245,"end":248,"text":"Remind her what love is."},{"start":292,"end":295,"text":"...and, action!"},{"start":296.5,"end":298,"text":"Memory overwrite in progress!"},{"start":299,"end":301,"text":"You're a jerk, Thom!"},{"start":302.5,"end":305,"text":"Ohp- Sorry! Sorry."},{"start":316,"end":317,"text":"Look Celia."},{"start":318,"end":320,"text":"We have to follow our passions."},{"start":321,"end":323,"text":"You have your robotics..."},{"start":325,"end":328,"text":"...and I just want to be awesome in space."},{"start":339,"end":341,"text":"Okay, they're coming. Two minutes left!"},{"start":343,"end":344,"text":"Speed it up, Thom!"},{"start":345,"end":346,"text":"Vivacissimo!"},{"start":347,"end":350,"text":"Why don't you just admit that you're\nfreaked out by my robot hand?"},{"start":356,"end":359,"text":"Listen Celia, I was young..."},{"start":359.5,"end":361,"text":"...and a dick."},{"start":361,"end":363,"text":"But that's no reason to\ndestroy the world."},{"start":365,"end":366,"text":"Why does he do this?"},{"start":366.5,"end":368.5,"text":"We already tried that one!"},{"start":371.5,"end":372.5,"text":"Abort!"},{"start":373,"end":374,"text":"Cut!"},{"start":374,"end":375,"text":"Whoaaa!"},{"start":379,"end":380,"text":"Whoaaa!"},{"start":381,"end":383,"text":"Nooooo!"},{"start":383,"end":385,"text":"You broke my heart."},{"start":386,"end":387,"text":"I know."},{"start":387,"end":389,"text":"You forgot me on earth."},{"start":389,"end":390,"text":"I know."},{"start":390.5,"end":393,"text":"I should just crush you."},{"start":396,"end":397,"text":"I'm-"},{"start":407,"end":408,"text":"I'm sorry."},{"start":410,"end":411,"text":"Good ad-lib."},{"start":419,"end":420.5,"text":"Not my fault!"},{"start":422,"end":423,"text":"This time."},{"start":428,"end":429.5,"text":"Quiet on set!"},{"start":430,"end":431,"text":"We're out of time!"},{"start":493,"end":494,"text":"Come on!"},{"start":502,"end":504,"text":"RAAAAAAAAH!"},{"start":504,"end":505,"text":"Memory overwrite, 90%."},{"start":506,"end":508,"text":"Captain! We have to abort!"},{"start":518,"end":520,"text":"The world's changed, Celia..."},{"start":534,"end":536,"text":"...maybe we can too."},{"start":538,"end":539,"text":"Memory overwrite complete!"},{"start":559,"end":560,"text":"You know."},{"start":562,"end":564,"text":"There's a lesson to be learned from this."},{"start":566,"end":567,"text":"Could'a gone worse."}]},{"id":"alternative-math","type":"video","provider":"youtube","youtubeId":"Zh3Yz3PiXZw","title":"Alternative Math","creator":"David Maddox · Ideaman","year":2017,"level":"B2","category":"fun","genre":"comedy","durationSeconds":547,"summaryTr":"Basit bir matematik sorusu, öğretmen ile aileler arasında giderek büyüyen bir tartışmaya dönüşür. Okul, otorite ve tartışma dili üzerinden ilerleyen bir hiciv.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Gündelik okul konuşmaları, anlaşılır tartışmalar ve tekrarlanan savunmalar B2 seviyesine uygundur; alay ve toplumsal hicvi fark etmek gerekir.","advisoryTr":"Bağırışlar, tehditkâr davranışlar ve siyasi hiciv içerir.","downloadable":false,"source":{"name":"Ideaman — Alternative Math","url":"https://www.youtube.com/watch?v=Zh3Yz3PiXZw","watchUrl":"https://www.youtube.com/watch?v=Zh3Yz3PiXZw","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"David Maddox · Ideaman · Yayıncı: Ideaman"},"glossary":{"evidence":"kanıt","opinion":"görüş","principal":"okul müdürü","suspend":"görevden veya okuldan geçici uzaklaştırmak","correct":"doğru; düzeltmek","alternative":"alternatif; başka bir seçenek"},"captions":[]},{"id":"carnival-of-souls","type":"video","title":"Carnival of Souls","creator":"Herk Harvey","year":1962,"level":"B2","category":"horror","genre":"horror","durationSeconds":4663,"summaryTr":"Bir kazadan sağ çıkan genç kadın yeni bir şehirde işe başlar. Terk edilmiş bir eğlence alanı ve sürekli gördüğü bir yabancı, gerçeklikle ilişkisini sarsar. Atmosferik bir hayalet hikâyesi.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Gündelik diyaloglar ve meslekle ilgili konuşmalar çoğunlukla açık ilerler; eski kayıt, ima ve bilinçli olarak belirsiz bırakılan sahneler ek dikkat ister.","advisoryTr":"Ölüm, kaza, tacizkâr davranışlar ve rahatsız edici hayalet görüntüleri içerir.","videoUrl":"https://upload.wikimedia.org/wikipedia/commons/transcoded/6/69/Carnival_of_Souls_%281962%29_by_Herk_Harvey.webm/Carnival_of_Souls_%281962%29_by_Herk_Harvey.webm.480p.vp9.webm","qualities":[{"label":"240p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/6/69/Carnival_of_Souls_%281962%29_by_Herk_Harvey.webm/Carnival_of_Souls_%281962%29_by_Herk_Harvey.webm.240p.vp9.webm","sizeMB":140},{"label":"480p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/6/69/Carnival_of_Souls_%281962%29_by_Herk_Harvey.webm/Carnival_of_Souls_%281962%29_by_Herk_Harvey.webm.480p.vp9.webm","sizeMB":424}],"source":{"name":"Wikimedia Commons — Carnival of Souls","url":"https://commons.wikimedia.org/wiki/File:Carnival_of_Souls_(1962)_by_Herk_Harvey.webm","watchUrl":"https://commons.wikimedia.org/wiki/File:Carnival_of_Souls_(1962)_by_Herk_Harvey.webm","license":"Kamu malı (ABD)","licenseUrl":"https://commons.wikimedia.org/wiki/File:Carnival_of_Souls_(1962)_by_Herk_Harvey.webm","credit":"Herk Harvey · Özgün film; Wikimedia Commons aktarımı","creditNoteTr":"Video, kaynak sürümüyle ve jeneriğiyle birlikte değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText%3ACarnival%20of%20Souls%20(1962)%20by%20Herk%20Harvey.webm.en.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar altyazı sayfasının geçmişinde)","changeNoteTr":"Sözler ve zamanlar korunmuştur; biçim etiketleri kaldırılıp satırlar birleştirilerek zamanlar saniyeye dönüştürülmüştür."},"glossary":{"boarding":"boarding house: pansiyon","organist":"org çalan müzisyen","pavilion":"pavyon; eğlence veya sergi yapısı"},"captions":[{"start":10.8,"end":14.04,"text":"Stop it, Joe! Look at this !"},{"start":14.36,"end":17.12,"text":"- Shall we go for a walk? - OK."},{"start":18.76,"end":20.04,"text":"Come on man, here we go!"},{"start":38.72,"end":41.44,"text":"I will show them what I can do..."},{"start":58.84,"end":61.08,"text":"Road under construction"},{"start":107.12,"end":112.08,"text":"THE CARNIVAL OF SOULS"},{"start":197.84,"end":200.28,"text":"The river carries so much mud and sand"},{"start":200.4,"end":203.44,"text":"that we will have trouble to find the car."},{"start":214.2,"end":215.44,"text":"- This way. - Good."},{"start":215.68,"end":219.6,"text":"- What happened ? - We can't help it, sir."},{"start":220.28,"end":222.8,"text":"- Oh no ? - We were already on deck,"},{"start":223.12,"end":225.24,"text":"when the car came behind us."},{"start":225.44,"end":230.07999999999998,"text":"She wanted to double us and she had to swerve."},{"start":230.28,"end":232.68,"text":"You wouldn't have it a bit pushed?"},{"start":243.6,"end":245.28,"text":"It's been three hours."},{"start":245.76,"end":248.28,"text":"Oh yes ? It's not sure let's find her."},{"start":248.92,"end":251.44,"text":"There is too much current and too much sand."},{"start":252.04,"end":253.96,"text":"We can always try..."},{"start":259.4,"end":261.04,"text":"What's going on ?"},{"start":282.36,"end":283.88,"text":"Come on, let's go down!"},{"start":304.08,"end":308.04,"text":"- So that ! It's Mary Henry... - How are you ?"},{"start":308.44,"end":310.52,"text":"How did you get out of there?"},{"start":310.92,"end":314.04,"text":"Put that, we'll take you back to town."},{"start":317.4,"end":319.24,"text":"And the other girls?"},{"start":323,"end":324.48,"text":"I do not remember."},{"start":480.28,"end":482,"text":"It will be the same organ in Utah?"},{"start":482.4,"end":486.4,"text":"Practically. It's me who installed it there."},{"start":487.08,"end":489.08,"text":"The crash won't delay your leaving ?"},{"start":489.4,"end":493.32,"text":"No, I'm leaving this morning. Nothing keeps me here."},{"start":493.64,"end":494.84,"text":"It's true."},{"start":495.16,"end":498.12,"text":"Alright Mary. This church is going to have an excellent organist!"},{"start":498.44,"end":502.08,"text":"- You'll like it. - This job or another..."},{"start":502.4,"end":506.24,"text":"You are going to work in a church, anyway..."},{"start":506.56,"end":508.72,"text":"To hold the organ, that's all."},{"start":509.04,"end":511.04,"text":"Let's go!"},{"start":511.36,"end":515.56,"text":"It's not very well paid, sure, but it's a start."},{"start":516.6,"end":518.68,"text":"Are you going to your parents?"},{"start":519.76,"end":522.08,"text":"No, I'm in a hurry."},{"start":522.4,"end":525.68,"text":"I will not have time to stop on the way."},{"start":526.08,"end":530.32,"text":"Mary, music, we don't do it only with his head."},{"start":531.04,"end":533.88,"text":"Put a little of your soul into it, Okay ?"},{"start":541.08,"end":543.04,"text":"Good luck, Mary!"},{"start":543.44,"end":545.6,"text":"Come see us sometime."},{"start":545.92,"end":549.12,"text":"Thanks, but I'm leaving for all time."},{"start":789.44,"end":791.6,"text":"- Can I help you ? - Full."},{"start":791.76,"end":793.08,"text":"OK."},{"start":818.36,"end":820.68,"text":"Would you like anything else, ma'am?"},{"start":821.28,"end":825.12,"text":"What is this big building a few miles near the lake?"},{"start":825.8,"end":828.04,"text":"Ah, you want to talk of the old public bath."},{"start":828.36,"end":831.28,"text":"It used to be a nice luxurious place."},{"start":831.48,"end":834.76,"text":"The lake has dried up and they turned it into a ballroom."},{"start":834.92,"end":837.16,"text":"And then they built these buildings"},{"start":837.28,"end":839.76,"text":"and for a time they performed there a kind of carnival."},{"start":840.08,"end":843.44,"text":"But, that was years ago. Now there is nothing."},{"start":843.88,"end":845.16,"text":"I see."},{"start":848.8,"end":853.28,"text":"I have the address of a pension, could you tell me how to get there?"},{"start":853.84,"end":857,"text":"Sure. It's very close to here."},{"start":865.36,"end":868.28,"text":"I reserved it for you as soon as I got your letter."},{"start":871.6,"end":873.44,"text":"I could have rented it yesterday..."},{"start":873.76,"end":877.56,"text":"It is very good, thats what i was looking for."},{"start":877.88,"end":880.04,"text":"I was sure of it."},{"start":880.6,"end":883.04,"text":"It is not really a boarding house here."},{"start":883.36,"end":887.44,"text":"It's just you and Mr. Linden, across the hall."},{"start":893.2,"end":896.6,"text":"You each have your bathroom."},{"start":899.6,"end":901.52,"text":"And for the baths,"},{"start":901.84,"end":904.48,"text":"take as many that you want."},{"start":904.8,"end":907.24,"text":"Thanks. I will like it here."},{"start":907.56,"end":910,"text":"I hope you will stay one moment."},{"start":910.8,"end":914.2,"text":"I live on the ground floor, ON the other side."},{"start":914.52,"end":918.4,"text":"If you are missing something, it will wait until tomorrow."},{"start":922.72,"end":925.8,"text":"- Good night. - Good night, Mrs. Thomas."},{"start":982.76,"end":986.48,"text":"And here is our little gem, MissHenry."},{"start":987,"end":989.48,"text":"We come from the same city, he and I."},{"start":989.8,"end":992.84,"text":"I say. It is over there that we have been told about you."},{"start":993.16,"end":995.28,"text":"Have you found accommodation?"},{"start":995.52,"end":997.76,"text":"- Yes, I took a room. - Good."},{"start":998.08,"end":1000.52,"text":"I hope that you will like it here."},{"start":1000.84,"end":1003.76,"text":"Of course the church is not big"},{"start":1004.16,"end":1007.08,"text":"but our parishioners are charming."},{"start":1007.52,"end":1010.6,"text":"We're gonna throw a little party in your honor."},{"start":1011.08,"end":1014.08,"text":"- I'd rather not. - Oh good ?"},{"start":1014.52,"end":1017.32,"text":"Of course it's not an obligation,"},{"start":1017.76,"end":1020.36,"text":"but these ladies will be disappointed."},{"start":1020.76,"end":1023.76,"text":"The important thing is that they like my way of playing!"},{"start":1024.2,"end":1026.52,"text":"Definitely..."},{"start":1026.92,"end":1029.84,"text":"Let's stop talking about it. We'll see later."},{"start":1030.28,"end":1032.48,"text":"But my dear,"},{"start":1033,"end":1036.88,"text":"you can not live like a hermit!"},{"start":1038.08,"end":1040.92,"text":"- Can I try it? - I was going to ask you."},{"start":1062.48,"end":1063.36,"text":"I leave you."},{"start":1064.28,"end":1067.04,"text":"I'm right next to it If you need me."},{"start":1082.72,"end":1086.8,"text":"We have an organist who knows how to touch souls."},{"start":1143.16,"end":1146.96,"text":"- What did you see ? - Nothing."},{"start":1147.4,"end":1150.52,"text":"I played too long. I feel weird."},{"start":1150.64,"end":1152.12,"text":"You need air."},{"start":1152.8,"end":1156.88,"text":"I have a visit to make, near the lake. I am taking you ?"},{"start":1157.6,"end":1159.8,"text":"Near the old pavilion?"},{"start":1160.88,"end":1162.72,"text":"- Are you going there? - Very close."},{"start":1163.08,"end":1165.88,"text":"- Do you want to see it? - With you, yes!"},{"start":1166.12,"end":1167.52,"text":"Good."},{"start":1203.48,"end":1205.04,"text":"It was great before."},{"start":1205.6,"end":1207.76,"text":"It's been closed for a long time."},{"start":1208.16,"end":1210.76,"text":"- Can we come in? - Certainly not !"},{"start":1211.12,"end":1215.08,"text":"It's dangerous, that's why they put up a fence."},{"start":1215.52,"end":1218,"text":"We could sneak..."},{"start":1218.76,"end":1222.2,"text":"What attracts you so much?"},{"start":1222.52,"end":1223.56,"text":"I do not know."},{"start":1224.12,"end":1226.64,"text":"I'm pretty reasonable usually."},{"start":1226.96,"end":1231.92,"text":"I may want to see if he is hiding something."},{"start":1232.68,"end":1234.68,"text":"- Are you coming with me? - Nope."},{"start":1235.04,"end":1236.92,"text":"It is prohibited by law."},{"start":1237.24,"end":1240.68,"text":"A pastor cannot break the law !"},{"start":1241,"end":1244.76,"text":"It's true. I'll be back maybe another time."},{"start":1246.2,"end":1248.72,"text":"We're leaving ?"},{"start":1275.08,"end":1278.32,"text":"- Oh, it's you! - Good evening."},{"start":1279,"end":1282.68,"text":"You played the organ all day ?"},{"start":1283.32,"end":1286.8,"text":"I took a drive with my boss."},{"start":1287.28,"end":1289.08,"text":"An old pastor."},{"start":1291.52,"end":1294,"text":"You have some pay you a portion."},{"start":1295.32,"end":1298.48,"text":"as Mr. Linden would say, the other tenant."},{"start":1299.16,"end":1302.88,"text":"- Have you had dinner? - I forgot !"},{"start":1303.4,"end":1306.2,"text":"It's not a boarding house but what do i have"},{"start":1306.64,"end":1308.88,"text":"make you a coffee and a sandwich."},{"start":1309.04,"end":1311.44,"text":"I show you this in a moment."},{"start":1311.88,"end":1315.12,"text":"Good. I will have a bath, as you suggested."},{"start":1315.32,"end":1320.28,"text":"As much as you want, this is not a problem."},{"start":1367.44,"end":1369.04,"text":"Come in, Mrs. Thomas."},{"start":1370.92,"end":1372.92,"text":"One minute."},{"start":1393.6,"end":1395.84,"text":"I thought it was Madame Thomas!"},{"start":1396.16,"end":1398.88,"text":"I suspected a little..."},{"start":1399.2,"end":1401.4,"text":"I am John Linden, your neighbour."},{"start":1401.72,"end":1404.36,"text":"- Nice to meet you. Excuse me. - Say..."},{"start":1404.64,"end":1407.6,"text":"One moment, stay out!"},{"start":1433.84,"end":1436.2,"text":"My name is Mary Henry."},{"start":1436.32,"end":1438.92,"text":"I say..."},{"start":1439.24,"end":1442.2,"text":"I heard you say to Mrs. Thomas that you had not had dinner."},{"start":1442.52,"end":1444.84,"text":"Since we are neighbors..."},{"start":1445.16,"end":1446.8,"text":"I haven't eaten either."},{"start":1447.12,"end":1449.36,"text":"so I invite you to dinner?"},{"start":1449.68,"end":1451.6,"text":"That's nice, but no thanks."},{"start":1451.92,"end":1454.04,"text":"I know we don't know each other..."},{"start":1454.36,"end":1456.8,"text":"I'm sorry, I can't."},{"start":1457.12,"end":1461.08,"text":"There is a small restaurant very nice, close..."},{"start":1461.6,"end":1464.2,"text":"And I don't like eat alone!"},{"start":1464.52,"end":1466.92,"text":"I dine in my room, tonight."},{"start":1467.88,"end":1471.28,"text":"Good. If you change your mind, call me !"},{"start":1474.8,"end":1476.68,"text":"We feel lonely here sometimes."},{"start":1477.32,"end":1479.28,"text":"Good night, Mr. Linden."},{"start":1562.16,"end":1565.72,"text":"Miss Henry? It's Mrs. Thomas."},{"start":1584.76,"end":1586.76,"text":"Who is that man in the corridor ?"},{"start":1588.72,"end":1590.24,"text":"A man ?"},{"start":1592.52,"end":1594.52,"text":"You must have seen Mr. Linden."},{"start":1594.72,"end":1597.16,"text":"He has his room opposite."},{"start":1597.4,"end":1600.56,"text":"No, the other!"},{"start":1601.08,"end":1603.72,"text":"There is no one else!"},{"start":1604.56,"end":1607.24,"text":"There's me, you and Mr. Linden."},{"start":1607.52,"end":1609.88,"text":"The three of us, that's all."},{"start":1610.12,"end":1612.6,"text":"But you must have seen it, out !"},{"start":1613.36,"end":1615.64,"text":"You have to eat."},{"start":1616.04,"end":1619.76,"text":"When you have an empty stomach, sometimes we have funny ideas."},{"start":1620.12,"end":1622.92,"text":"You must have heard crack the floor."},{"start":1623.24,"end":1625.48,"text":"Old houses creak!"},{"start":1625.8,"end":1629.52,"text":"I saw it, I tell you, not heard !"},{"start":1632.4,"end":1634.48,"text":"Do not tell such things!"},{"start":1635.8,"end":1638.2,"text":"Even without that, I have trouble sleeping!"},{"start":1639.32,"end":1641.76,"text":"It's these old houses..."},{"start":1642.08,"end":1646,"text":"These are too big. They have too many corners."},{"start":1648.96,"end":1652.08,"text":"You must not leave roam his imagination."},{"start":1652.4,"end":1655.04,"text":"- You're going out ? - Obviously !"},{"start":1675.84,"end":1678.32,"text":"There is nobody."},{"start":1680.48,"end":1684.16,"text":"eat the sandwich what I did to you."},{"start":1685.96,"end":1689.24,"text":"Leave the coffee, if it keeps you awake."},{"start":1689.6,"end":1691.52,"text":"No risk."},{"start":1694.32,"end":1696.8,"text":"Coffee never keeps me awake."},{"start":1779.04,"end":1781.68,"text":"Good morning !"},{"start":1782,"end":1783.8,"text":"I heard your alarm clock!"},{"start":1784.12,"end":1786.32,"text":"- Guess what I have. - No idea."},{"start":1786.64,"end":1789.44,"text":"What's needed to start the day off right."},{"start":1789.76,"end":1793,"text":"I do it in my room to drink it out of bed."},{"start":1793.32,"end":1796.2,"text":"But to come and see you, I had to dress well!"},{"start":1796.68,"end":1798.64,"text":"Exactly what I need!"},{"start":1798.96,"end":1802.64,"text":"Two coffees, it works!"},{"start":1808.56,"end":1812.2,"text":"You were less happy from my visit last night..."},{"start":1812.6,"end":1815.28,"text":"I am not someone very sociable."},{"start":1815.72,"end":1819.4,"text":"You lead me into temptation!"},{"start":1819.88,"end":1821.64,"text":"What ? It's too complicated for me!"},{"start":1821.96,"end":1824.64,"text":"I am not than a mere storekeeper."},{"start":1825.08,"end":1827.56,"text":"But I make a good living."},{"start":1828.2,"end":1831.2,"text":"I have a small drop left. You want some ?"},{"start":1831.52,"end":1835.52,"text":"No thanks. It is not indicated for an organist."},{"start":1836.04,"end":1837.48,"text":"Is that your job?"},{"start":1837.96,"end":1840.12,"text":"We pay you to play the organ?"},{"start":1840.72,"end":1842.4,"text":"Some churches do."},{"start":1843.32,"end":1847,"text":"You are a churchwoman... I couldn't know!"},{"start":1847.56,"end":1850,"text":"This is where I earn my living, that's all."},{"start":1850.6,"end":1853.36,"text":"- Funny way to see! - Why ?"},{"start":1853.88,"end":1856.8,"text":"What's shocking? I work"},{"start":1857,"end":1858.96,"text":"in a church, that's all."},{"start":1859.44,"end":1862.08,"text":"I am an organist and I get paid to play."},{"start":1863.48,"end":1866,"text":"And it doesn't give you nightmares ?"},{"start":1867.96,"end":1870,"text":"It's funny you say that."},{"start":1870.72,"end":1873.52,"text":"In fact, it has nothing to do with it, but..."},{"start":1873.84,"end":1877.4,"text":"Last night, I had a weird feeling."},{"start":1877.92,"end":1880.8,"text":"I too had a difficult night."},{"start":1882,"end":1883.12,"text":"It's strange..."},{"start":1884.28,"end":1886.96,"text":"Everything is different during the day."},{"start":1887.96,"end":1891.32,"text":"At night, our imagination plays tricks on us."},{"start":1892.52,"end":1895.6,"text":"And as soon as it's day, everything is in order."},{"start":1898,"end":1899.76,"text":"Nights should be removed."},{"start":1900.28,"end":1903.84,"text":"Or return them more interesting?"},{"start":1906.88,"end":1910.32,"text":"- Where did you learn the organ? - At University."},{"start":1910.56,"end":1912.52,"text":"I could have gone there!"},{"start":1913.24,"end":1917.52,"text":"But I preferred football. All these courses to learn..."},{"start":1917.8,"end":1921.56,"text":"- Eh yes ! - I'm not stupid,"},{"start":1922.28,"end":1925.4,"text":"but I didn't like the methods of the time."},{"start":1925.96,"end":1928.72,"text":"I hated raw materials."},{"start":1929.32,"end":1931.8,"text":"- Like what ? - You know..."},{"start":1932.32,"end":1934.92,"text":"Like raw materials from Brazil."},{"start":1938.28,"end":1941.16,"text":"coffee, sugar, stuff like that!"},{"start":1942,"end":1945.92,"text":"I didn't care about school, I preferred girls."},{"start":1946.52,"end":1948.68,"text":"Was it your favorite subject?"},{"start":1949.32,"end":1951.64,"text":"Yes, the only one where I passed my exams."},{"start":1953.48,"end":1955.92,"text":"A problem ? Does it still taste like coffee?"},{"start":1956.84,"end":1959.28,"text":"don't take me for an alcoholic!"},{"start":1959.52,"end":1962.32,"text":"It's to be happy in the morning, that's all."},{"start":1962.52,"end":1964.48,"text":"At noon, you must be hilarious!"},{"start":1964.8,"end":1967.04,"text":"That's why I'm appreciated."},{"start":1967.36,"end":1969.64,"text":"I work in good spirits."},{"start":1969.96,"end":1972.88,"text":"I didn't make you laugh this morning ?"},{"start":1973.2,"end":1975.68,"text":"Yes, this morning you have fulfilled me."},{"start":1976,"end":1979.04,"text":"I can fill you too in the evening if you want."},{"start":1980.52,"end":1982.84,"text":"- I'll rinse the cups. - Nope !"},{"start":1983.16,"end":1985.6,"text":"Especially not, it would be less good tomorrow!"},{"start":1985.92,"end":1987.28,"text":"Thanks for the coffee."},{"start":1988.12,"end":1989.92,"text":"Unhygienic but delicious."},{"start":1990.04,"end":1994.32,"text":"You should have put some disinfectant!"},{"start":1995.72,"end":1998.2,"text":"We really need am I leaving already?"},{"start":1998.76,"end":2000,"text":"You will arrive to walk through the door?"},{"start":2001.44,"end":2003.4,"text":"Who do you take me for?"},{"start":2003.52,"end":2006.48,"text":"I just want to say that you are well charged."},{"start":2008.08,"end":2010.08,"text":"Let's stay there..."},{"start":2010.4,"end":2013.76,"text":"You must probably go to work Mr. Linden, right?"},{"start":2014.12,"end":2017.8,"text":"- Not you ? - No, shopping day."},{"start":2030.12,"end":2031.88,"text":"Does the hem hang well?"},{"start":2032.2,"end":2034.16,"text":"We're going to do a little editing."},{"start":2034.48,"end":2037.92,"text":"Aside from that, the drape is perfect."},{"start":2038.24,"end":2042.16,"text":"This is not reasonnable, but I'll take both."},{"start":2042.48,"end":2045.64,"text":"We're going to edit a little the rounding here."},{"start":2046.48,"end":2048.92,"text":"I accompany you to your cabin?"},{"start":2130.08,"end":2130.8,"text":"I love it !"},{"start":2131.12,"end":2133.88,"text":"Can you have it delivered to me?"},{"start":2135.36,"end":2137.8,"text":"I said I took it!"},{"start":2153.2,"end":2155.24,"text":"But what does she have?"},{"start":2158.52,"end":2160.8,"text":"What do they all have?"},{"start":2164.04,"end":2166.12,"text":"Why am I not being answered?"},{"start":2268.32,"end":2270.56,"text":"- What is it ? - It's that man!"},{"start":2272.04,"end":2275.16,"text":"I meant him no harm. I was thirsty."},{"start":2275.56,"end":2280.16,"text":"No, not that man!"},{"start":2282,"end":2283.88,"text":"It was the other!"},{"start":2285.84,"end":2289.16,"text":"There was someone else a strange man."},{"start":2289.64,"end":2291.32,"text":"You were scared, that's all."},{"start":2291.72,"end":2294.84,"text":"nervous breakdowns, It's no use. Calm down!"},{"start":2295.28,"end":2300.08,"text":"The am Dr. Samuels. My office is just across the street."},{"start":2300.84,"end":2302.76,"text":"You are in shock."},{"start":2303.32,"end":2305.44,"text":"Can I help you if you desire it."},{"start":2306.12,"end":2308.52,"text":"Thanks. I can come right away ?"},{"start":2308.72,"end":2311.2,"text":"Sure. I take him to my office."},{"start":2311.64,"end":2313.72,"text":"I will take care of her."},{"start":2328.36,"end":2331.92,"text":"I heard nothing more, but that wasn't the worst."},{"start":2332.76,"end":2335.08,"text":"Nobody saw me."},{"start":2335.4,"end":2336.84,"text":"It was like..."},{"start":2338.96,"end":2341.48,"text":"As if I had ceased to exist,"},{"start":2343.32,"end":2346,"text":"and that I didn't have no place in this world,"},{"start":2347,"end":2349.2,"text":"no life around me."},{"start":2350.36,"end":2354.16,"text":"That's where you saw that man ?"},{"start":2354.88,"end":2356.12,"text":"Yes."},{"start":2358.72,"end":2362.32,"text":"Excuse me for having my back turned, I took notes."},{"start":2362.64,"end":2364.72,"text":"I must have spoken for an hour."},{"start":2365.04,"end":2368.2,"text":"Did you tell me everything? Did you forget anything?"},{"start":2368.96,"end":2372.12,"text":"No, I told you all the story."},{"start":2372.44,"end":2374.6,"text":"He follows me, that's all."},{"start":2374.92,"end":2378.76,"text":"- It is not so simple. - What do you mean ?"},{"start":2379.36,"end":2382.96,"text":"If he had been in the park, someone would have seen him."},{"start":2383.28,"end":2386.64,"text":"And that man on the landing that you are alone"},{"start":2386.96,"end":2390.84,"text":"- to have seen. - Where are you coming from?"},{"start":2391.16,"end":2394.88,"text":"Your car fell in the water a few days ago."},{"start":2395.2,"end":2397.48,"text":"You survived by miracle."},{"start":2397.8,"end":2400.72,"text":"The emotional shock must have been terrible."},{"start":2401.16,"end":2403.88,"text":"You take me for a fool that's it ?"},{"start":2404.04,"end":2406.16,"text":"No way."},{"start":2406.48,"end":2408.12,"text":"I'm a sensible person"},{"start":2408.44,"end":2411.36,"text":"rational, I don't imagine nonsense."},{"start":2411.68,"end":2415.88,"text":"Let's go! It may happen to anyone!"},{"start":2416.36,"end":2420.76,"text":"You have never interpreted a crooked conversation?"},{"start":2422.12,"end":2424.48,"text":"You never took a person"},{"start":2424.64,"end":2428.28,"text":"- for another? - I do not see the link."},{"start":2428.76,"end":2432.24,"text":"Our imagination plays tricks on us."},{"start":2432.56,"end":2435.96,"text":"She distorts what they say our senses. OK ?"},{"start":2436.6,"end":2438.16,"text":"It's possible."},{"start":2438.48,"end":2442,"text":"These are things that happen every day."},{"start":2442.32,"end":2446.32,"text":"So during a high fever or after a shock."},{"start":2446.64,"end":2450.08,"text":"I can not believe that I imagined all this."},{"start":2450.56,"end":2454.16,"text":"This man makes you think about someone ?"},{"start":2454.32,"end":2456.68,"text":"- To a friend, to your father? - Nope."},{"start":2456.84,"end":2460.32,"text":"- Do you have a boyfriend? - No, I don't want to."},{"start":2460.64,"end":2463.12,"text":"- Never ? - Nope."},{"start":2464.64,"end":2468.6,"text":"I find myself telling you this, but it's true."},{"start":2468.96,"end":2472.24,"text":"I don't wanna feel close to someone."},{"start":2472.56,"end":2475.04,"text":"You have always been like that ?"},{"start":2476.84,"end":2478.32,"text":"No I do not know."},{"start":2478.64,"end":2482.92,"text":"You don't like to mingle to others, to their lives?"},{"start":2483.24,"end":2486.24,"text":"I find it difficult to approach them."},{"start":2486.56,"end":2490.72,"text":"I feel like I'm looking for something else."},{"start":2490.88,"end":2493.44,"text":"Do you feel guilty?"},{"start":2494.12,"end":2495.92,"text":"I don't understand."},{"start":2496.32,"end":2499.84,"text":"I am not a psychiatrist I may be clumsy."},{"start":2500.2,"end":2503.68,"text":"anything can come of a feeling of guilt."},{"start":2503.84,"end":2505.72,"text":"It's ridiculous !"},{"start":2506.04,"end":2508.8,"text":"It's possible. Frankly I do not know."},{"start":2510.16,"end":2511.88,"text":"One thing is certain."},{"start":2512.52,"end":2516.16,"text":"If my imagination is in question, I can put it in order."},{"start":2516.84,"end":2519.32,"text":"You are a very strong-willed person."},{"start":2519.76,"end":2521.4,"text":"I want to survive anyway."},{"start":2522.52,"end":2525.2,"text":"This old pavilion, near the lake,"},{"start":2525.76,"end":2528.04,"text":"is related to all this according to you."},{"start":2529.48,"end":2533.2,"text":"I could go to get to the bottom of it."},{"start":2534.44,"end":2537.08,"text":"- If I went... - No rush !"},{"start":2537.96,"end":2541.8,"text":"If it's my imagination It has to stop."},{"start":2542.28,"end":2544.88,"text":"Get accompanied, at least."},{"start":2545,"end":2547.8,"text":"You said that I have the will!"},{"start":2548.84,"end":2551.04,"text":"It is now that I have to go."},{"start":2551.52,"end":2554.72,"text":"If necessary, I will go alone."},{"start":2834.2,"end":2838.12,"text":"I hope you're not going yet send me for a ride,"},{"start":2839.04,"end":2841.48,"text":"but I would like invite you to dinner."},{"start":2841.72,"end":2845.56,"text":"I ate in town. And I must rehearse in church tonight."},{"start":2845.92,"end":2850.24,"text":"If I came take you out?"},{"start":2850.56,"end":2853.12,"text":"We could go dancing If you want."},{"start":2853.44,"end":2856.56,"text":"Dance, it's not my forte."},{"start":2860.92,"end":2863.08,"text":"Can I ask you something?"},{"start":2863.4,"end":2867,"text":"- Always ask. - Are you afraid of men?"},{"start":2867.32,"end":2869.84,"text":"No way."},{"start":2871.68,"end":2874.28,"text":"You are quite distant."},{"start":2874.64,"end":2877.88,"text":"You were nicer this morning when we had coffee."},{"start":2878.12,"end":2880.76,"text":"I needed company."},{"start":2881.28,"end":2884.04,"text":"You may be happy tonight."},{"start":2884.92,"end":2887.12,"text":"It's not funny to go home alone."},{"start":2889.92,"end":2891.12,"text":"It's true."},{"start":2892.16,"end":2895,"text":"I will be finished around 9 o'clock, will it be ok?"},{"start":2895.32,"end":2897.52,"text":"Very well."},{"start":2898.6,"end":2902.24,"text":"See you at church."},{"start":3107.68,"end":3110.32,"text":"It is a profanation, sacrilege!"},{"start":3110.72,"end":3113.16,"text":"what are you playing there in a church?"},{"start":3113.6,"end":3117.16,"text":"So you have no respect?"},{"start":3118.92,"end":3122.48,"text":"I pity you to miss of soul at this point."},{"start":3123.32,"end":3125.84,"text":"This organ and the music we play here"},{"start":3126,"end":3129.12,"text":"have for us great meaning."},{"start":3129.6,"end":3132.16,"text":"I thought it was same for you."},{"start":3132.68,"end":3134.6,"text":"But if not,"},{"start":3135,"end":3138.24,"text":"you can't stay our organist."},{"start":3138.8,"end":3142.12,"text":"I must, in all conscience, ask you to leave."},{"start":3166.6,"end":3168.84,"text":"I don't give up on you however."},{"start":3169.4,"end":3171.32,"text":"Don't turn your back to the Church!"},{"start":3171.56,"end":3174.56,"text":"You will find help here, accept it."},{"start":3204.72,"end":3207.72,"text":"Hi ! I wait for a long time."},{"start":3207.96,"end":3209.76,"text":"My car is here, let's go."},{"start":3236.6,"end":3238.36,"text":"So what ? You don't drink?"},{"start":3238.72,"end":3241.36,"text":"- Not really. - Not really !"},{"start":3241.68,"end":3244.92,"text":"What's left, can you tell me?"},{"start":3245.76,"end":3249.28,"text":"Me, I drink..."},{"start":3249.44,"end":3251.76,"text":"Ah, really, I drink!"},{"start":3257.36,"end":3259.48,"text":"You don't like either the music ?"},{"start":3259.88,"end":3262.04,"text":"- If it's okay. - But no !"},{"start":3262.36,"end":3264.12,"text":"You don't like dancing"},{"start":3264.44,"end":3266.8,"text":"nor drink,"},{"start":3267.12,"end":3270.08,"text":"nor that a man approaches you. I am wrong ?"},{"start":3270.72,"end":3274.44,"text":"- I did not say that. - You do not pick up a word!"},{"start":3277.32,"end":3280.68,"text":"I will put back the song you love so much."},{"start":3286.44,"end":3290.32,"text":"- Hey Johnny, who's the girl? - You don't know her, kid."},{"start":3290.68,"end":3293,"text":"You're hiding things from me."},{"start":3293.4,"end":3296.48,"text":"It's not the kind of sausage that you usually go out!"},{"start":3296.8,"end":3299.88,"text":"stop drooling, she's too good for you!"},{"start":3300.32,"end":3302.16,"text":"We bet ?"},{"start":3302.84,"end":3306.96,"text":"Drop it. I'm on a roll."},{"start":3307.08,"end":3308.52,"text":"I could help you..."},{"start":3308.84,"end":3312.28,"text":"I don't want her to see me with a sucker like you!"},{"start":3313.96,"end":3315.92,"text":"Good luck !"},{"start":3319.52,"end":3321.4,"text":"Have you met a friend?"},{"start":3321.72,"end":3326.52,"text":"Yes... A classmate."},{"start":3328.28,"end":3331.8,"text":"He told me that a girl wanted to talk to me."},{"start":3333.16,"end":3336.28,"text":"- He asked me to go. - What did you answer?"},{"start":3336.72,"end":3340.04,"text":"I refused, of course. I'm going out with you tonight."},{"start":3344.8,"end":3348.8,"text":"He said you looked to bore you with me."},{"start":3349.36,"end":3350.96,"text":"It's not true!"},{"start":3351.36,"end":3354.36,"text":"I enjoyed this evening in your company."},{"start":3354.84,"end":3357.36,"text":"She would have been sinister, without you."},{"start":3359.16,"end":3361.88,"text":"So have fun! Finish your drink!"},{"start":3368.24,"end":3370.92,"text":"It's not poison at whatever cost!"},{"start":3371.4,"end":3374.04,"text":"I'm sorry to be disagreeable to you."},{"start":3375.48,"end":3376.68,"text":"I do not understand anything."},{"start":3377.52,"end":3380.92,"text":"First, you're ignoring me. Well, that's class!"},{"start":3381.36,"end":3383.84,"text":"You have to be prayed for, what..."},{"start":3384.16,"end":3387.12,"text":"And there you spin soft, a real mess!"},{"start":3388.12,"end":3392.92,"text":"Yesterday I was not interested. Tonight I want to be with you."},{"start":3393.64,"end":3397.04,"text":"- With anyone ? - No, with you!"},{"start":3403.48,"end":3406.16,"text":"Come on, let yourself go..."},{"start":3409.24,"end":3413,"text":"Do you prefer to be alone? I'm leaving, if you want."},{"start":3413.8,"end":3416.12,"text":"I like your company, I assure you !"},{"start":3417.44,"end":3421.48,"text":"Don't leave me alone tonight. I want to stay close to you."},{"start":3430.12,"end":3433.24,"text":"- It is serious ? - Yes."},{"start":3444.04,"end":3446,"text":"If we were leaving, both ?"},{"start":3446.88,"end":3450.04,"text":"You know my room is next to yours."},{"start":3450.92,"end":3453.76,"text":"So you don't have just one word to say..."},{"start":3472.8,"end":3476.76,"text":"- Oh dear ! - We're going to wake Mrs. Thomas!"},{"start":3477.08,"end":3480.32,"text":"She sleeps on the other side, she won't hear anything."},{"start":3489.76,"end":3491.72,"text":"Sweetheart..."},{"start":3492.88,"end":3495.88,"text":"Won't you leave me there?"},{"start":3497.84,"end":3500.28,"text":"It's dark in there"},{"start":3502.08,"end":3504,"text":"Are you going to be alone tonight?"},{"start":3504.56,"end":3507.88,"text":"Let me pass a moment with you."},{"start":3509.24,"end":3511.12,"text":"You don't want to be alone!"},{"start":3511.44,"end":3513.4,"text":"No."},{"start":3524.08,"end":3526.84,"text":"- Sorry, I can not... - Lets go !"},{"start":3527.4,"end":3531.2,"text":"I must please you a little since you let me in."},{"start":3560.24,"end":3561.92,"text":"But what do you have ?"},{"start":3565.6,"end":3567.52,"text":"What is happening here ?"},{"start":3568.96,"end":3572.24,"text":"- What do you have ? - A man is chasing me."},{"start":3572.88,"end":3574.68,"text":"Do something !"},{"start":3574.92,"end":3576.64,"text":"- I am leaving. - No, stay!"},{"start":3577.64,"end":3580.4,"text":"Oh no, my dear! That's all me!"},{"start":3580.56,"end":3583.12,"text":"I ran into a weirdo!"},{"start":3583.2,"end":3585.6,"text":"Don't leave me alone!"},{"start":3638.56,"end":3640.2,"text":"What have you discovered, doctor?"},{"start":3641.64,"end":3643.84,"text":"Not much, I'm afraid."},{"start":3644.12,"end":3647.36,"text":"I'm glad you're here."},{"start":3648.04,"end":3651.84,"text":"I was going to call someone, but I would not have liked to pay."},{"start":3652.12,"end":3654.16,"text":"I came on purpose."},{"start":3654.56,"end":3658.04,"text":"I keep thinking about her since she left my office yesterday."},{"start":3658.36,"end":3660.56,"text":"What is she making?"},{"start":3661,"end":3663.52,"text":"The Devil alone knows."},{"start":3664.12,"end":3668.84,"text":"I heard her move objects all night."},{"start":3669.08,"end":3671.52,"text":"It's the first time I hear that."},{"start":3671.64,"end":3674.16,"text":"And this morning she didn't want let me in."},{"start":3674.36,"end":3676.48,"text":"She is strange."},{"start":3676.68,"end":3679.32,"text":"She absolutely refuses my help."},{"start":3679.8,"end":3684.36,"text":"I don't criticize her. Something about her baffles me."},{"start":3684.92,"end":3688.84,"text":"I insisted that she call me when she needs help."},{"start":3689.84,"end":3691.84,"text":"I can't let her stay in this house."},{"start":3692.2,"end":3693.68,"text":"Don't worry about that."},{"start":3694.04,"end":3697.84,"text":"She wants to leave town as soon as possible."},{"start":3698.64,"end":3700.6,"text":"I hope she leaves."},{"start":3703.28,"end":3705.08,"text":"I hope she can."},{"start":3746.52,"end":3748.96,"text":"You go ?"},{"start":3749.24,"end":3751.28,"text":"Where are you going ?"},{"start":3755.48,"end":3759.4,"text":"I won't pay you back the rest of the week !"},{"start":3816.04,"end":3819.2,"text":"It's the gearbox. Shall we put her on the bridge?"},{"start":3832.48,"end":3834.2,"text":"Its good."},{"start":3835,"end":3837.36,"text":"- Will it be long? - Must see."},{"start":3837.68,"end":3839.64,"text":"Want to come down?"},{"start":3840.12,"end":3843.72,"text":"- Can I stay here? - If you want."},{"start":3986.32,"end":3988.84,"text":"when leave the next bus going east?"},{"start":3990.32,"end":3992.8,"text":"I must take it!"},{"start":4009.24,"end":4014.32,"text":"I want to get out of here! I have to go !"},{"start":4028.04,"end":4032.92,"text":"The next bus heading from the east will leave"},{"start":4034.4,"end":4036,"text":"from gate 9.\""},{"start":4100.44,"end":4103.24,"text":"Do not close the gate! Wait !"},{"start":4103.56,"end":4106.2,"text":"Let me take this train!"},{"start":4106.52,"end":4110.36,"text":"I must leave at any cost, You're welcome !"},{"start":4115.32,"end":4118.96,"text":"Listen to me ! You hear me ?"},{"start":4131.32,"end":4133.64,"text":"Why can't I hear anything?"},{"start":4137.96,"end":4140.88,"text":"You can help me ?"},{"start":4144.92,"end":4147.36,"text":"One moment please !"},{"start":4164.68,"end":4167.92,"text":"Why can't anyone hear me?"},{"start":4221.24,"end":4226.36,"text":"Doctor, I came to see you because you are my only hope."},{"start":4227.56,"end":4232.2,"text":"Without your help, I should go back there."},{"start":4234.16,"end":4236.52,"text":"He tries to attract me somewhere, to remember."},{"start":4238.32,"end":4242.72,"text":"Tell me what to do, Doctor!"},{"start":4578.68,"end":4580.2,"text":"The car is over there."},{"start":4580.96,"end":4583.4,"text":"And the footsteps lead here."},{"start":4593.8,"end":4595.72,"text":"And then, nothing."},{"start":4621.88,"end":4625.64,"text":"It's okay, Will, she's here."},{"start":4625.96,"end":4627.92,"text":"Bring it up!"},{"start":4658.48,"end":4662.4,"text":"© Bach Films"}]},{"id":"cosmos-laundromat","type":"video","title":"Cosmos Laundromat: First Cycle","creator":"Blender Foundation","year":2015,"level":"B2","category":"scifi","durationSeconds":730,"genre":"fantasy","summaryTr":"Issız bir adada yaşayan Franck, hayatını değiştirebileceğini söyleyen sıra dışı bir satıcıyla karşılaşır. İmalı konuşmaları, ikna dilini ve günlük deyimleri takip et.","levelNoteTr":"B2, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Günlük ifadelerin yanında ima, alay, mecaz ve satış konuşması vardır. Aksanlar, eksiltili cümleler ve birkaç teknik ifade dinlemeyi zorlaştırır; ilk konuşma yaklaşık 2:20’de başlar.","advisoryTr":"İntihar düşüncesi ve girişimi, ağır küfür ve karanlık temalar içerir. Hassas izleyiciler için uygun olmayabilir; yapımcı hedef kitleyi 13+ olarak belirtir.","videoUrl":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-240.mp4","sizeMB":43},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-360.mp4","sizeMB":76},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-480.mp4","sizeMB":110},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-720.mp4","sizeMB":201},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-804.mp4","sizeMB":230}],"source":{"name":"Blender Foundation — Cosmos Laundromat: First Cycle","url":"https://gooseberry.blender.org/","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","credit":"(CC) Blender Foundation | gooseberry.blender.org","licenseSourceUrl":"https://gooseberry.blender.org/license/","watchUrl":"https://video.blender.org/videos/watch/f507dfdc-e73e-45a4-9778-d758cbe1ce96","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText:Cosmos_Laundromat_-_First_Cycle_-_Official_Blender_Foundation_release.webm.en-gb.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar kaynak sayfasının geçmişinde)","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"glossary":{"franck":"Franck (karakter adı)","victor":"Victor (karakter adı)","hector":"Hector (yanlış söylenen ad)","casper":"Casper (yanlış söylenen ad)","hooves":"toynaklar","sheepy":"koyuna ait; burada koyunluk işleri","fucking":"lanet olası (ağır küfür)","tumble":"tamburda döndürme","spin":"sıkma, dönme","variable":"değişken, ayarlanabilir","squeaky":"gıcırdayan; squeaky clean: tertemiz","hehehe":"he he he (gülme sesi)","eh":"ee, hey (ünlem)","ho":"hop, hey (ünlem)","err":"ee, şey (duraksama)"},"captions":[{"start":140,"end":141.3,"text":"Excuse me?"},{"start":141.8,"end":143,"text":"Excuse me, sir?"},{"start":144,"end":145.5,"text":"Excuse me?"},{"start":147,"end":149,"text":"Oh, come on."},{"start":150,"end":152,"text":"Do you have a moment, sir?"},{"start":152,"end":157.05,"text":"I'm kind of in the middle of something here."},{"start":157.05,"end":158.95,"text":"I've come a long way for you, Franck."},{"start":169,"end":171,"text":"My name is Victor."},{"start":172,"end":174,"text":"Hi."},{"start":174,"end":176,"text":"And you are...."},{"start":178,"end":179.5,"text":"You are Franck."},{"start":180.5,"end":184,"text":"You are so much more than just a sheep, aren't you?"},{"start":185,"end":188,"text":"Oh yeah? How would you know?"},{"start":190,"end":192.9,"text":"Look at you. You're an adventurer, Franck."},{"start":192.9,"end":197,"text":"Just like me, you're... a lone wolf."},{"start":198,"end":202,"text":"Tell me, does one choose to be alone?"},{"start":203,"end":205,"text":"No, one doesn't."},{"start":205,"end":207.6,"text":"One doesn’t even choose to be a wolf."},{"start":210,"end":212,"text":"Or does one?"},{"start":215,"end":218.8,"text":"Well, mister... err... Hector."},{"start":218.8,"end":220,"text":"Victor. Victor."},{"start":220,"end":226,"text":"I don’t know what you’re on about but I'm just"},{"start":226,"end":228.6,"text":"And I suggest you do the same."},{"start":228.6,"end":232,"text":"No. No no no, Franck. Wait wait wait."},{"start":232,"end":235,"text":"No. This is not... the way."},{"start":235,"end":238.5,"text":"Just give me one minute of your precious time."},{"start":238.5,"end":241.5,"text":"Precious time? Hehehe."},{"start":241.5,"end":243.5,"text":"Yeah just give me one minute."},{"start":243.5,"end":246.5,"text":"You would have one more minute, wouldn't you?"},{"start":248,"end":251,"text":"Okay half. Half a minute."},{"start":265.1,"end":269.3,"text":"I knew it."},{"start":269.3,"end":272,"text":"You will not regret this."},{"start":272,"end":275,"text":"The adventures you will have."},{"start":275,"end":278.5,"text":"All the lives you've ever wanted."},{"start":278.5,"end":281.7,"text":"All you’ve been missing."},{"start":281.7,"end":286,"text":"Here. This is... the best product we have... in store."},{"start":286,"end":290,"text":"Variable spin speed, excellent tumble performance..."},{"start":290,"end":294,"text":"...in one... handy... device. Squeaky clean."},{"start":297,"end":301,"text":"Well this... this better be good."},{"start":301,"end":304,"text":"Took me ages to tie that rope."},{"start":305,"end":307,"text":"With my fucking hooves."},{"start":307,"end":309,"text":"No more need for hooves."},{"start":309,"end":311,"text":"No more sheepy business."},{"start":312,"end":314.5,"text":"Ho! Time flies."},{"start":314.5,"end":316.7,"text":"Wait wait wait wait wait wait."},{"start":316.7,"end":318.5,"text":"How does this thing work?"},{"start":318.5,"end":321,"text":"I mean, how do I make it work?"},{"start":321,"end":322.5,"text":"No you don't."},{"start":322.5,"end":324,"text":"I just turned it on for you."},{"start":326,"end":327,"text":"When can I go?"},{"start":329,"end":330,"text":"Where can I go?"},{"start":330,"end":333,"text":"We will pick you up. Don't worry, just stay here."},{"start":333,"end":335,"text":"In this exact place."},{"start":335,"end":337,"text":"Don't move. Just wait."},{"start":338,"end":340,"text":"That's it?"},{"start":341,"end":342,"text":"Hey!"},{"start":342.5,"end":344,"text":"Hey!"},{"start":344,"end":345.5,"text":"Wait, mister!"},{"start":345.5,"end":348.9,"text":"Eh, Casper!"},{"start":348.9,"end":351,"text":"Hector whatever!"}]},{"id":"night-of-the-living-dead","type":"video","title":"Night of the Living Dead","creator":"George A. Romero","year":1968,"level":"B2","category":"horror","genre":"horror","durationSeconds":5753,"summaryTr":"Zombilerle çevrili bir çiftlik evinde hayatta kalmaya çalışan bir grup, dışarıdaki tehlike kadar kendi anlaşmazlıklarıyla da mücadele eder. Klasik zombi korkusunda acil durum konuşmalarını ve tartışmaları takip et.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Radyo haberleri, emirler ve tartışmalar çoğunlukla açık anlatılır; bağırışlar, eski ses kaydı ve üst üste konuşmalar dinlemeyi zorlaştırır.","advisoryTr":"Ölüm, kan, zombi saldırıları, aile içi çatışma ve rahatsız edici görüntüler içerir.","videoUrl":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/24/Night_of_the_Living_Dead_%281968%29.webm/Night_of_the_Living_Dead_%281968%29.webm.480p.vp9.webm","qualities":[{"label":"240p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/24/Night_of_the_Living_Dead_%281968%29.webm/Night_of_the_Living_Dead_%281968%29.webm.240p.vp9.webm","sizeMB":184},{"label":"480p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/24/Night_of_the_Living_Dead_%281968%29.webm/Night_of_the_Living_Dead_%281968%29.webm.480p.vp9.webm","sizeMB":529}],"source":{"name":"Wikimedia Commons — Night of the Living Dead","url":"https://commons.wikimedia.org/wiki/File:Night_of_the_Living_Dead_(1968).webm","watchUrl":"https://commons.wikimedia.org/wiki/File:Night_of_the_Living_Dead_(1968).webm","license":"Kamu malı (ABD)","licenseUrl":"https://commons.wikimedia.org/wiki/File:Night_of_the_Living_Dead_(1968).webm","credit":"George A. Romero · Özgün film; Wikimedia Commons aktarımı","creditNoteTr":"Video, kaynak sürümüyle ve jeneriğiyle birlikte değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText%3ANight%20of%20the%20Living%20Dead%20(1968).webm.en.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar altyazı sayfasının geçmişinde)","changeNoteTr":"Sözler ve zamanlar korunmuştur; biçim etiketleri kaldırılıp satırlar birleştirilerek zamanlar saniyeye dönüştürülmüştür."},"glossary":{"cemetery":"mezarlık","ghoul":"hortlak","morgue":"morg","shelter":"sığınak; sığınmak","cellar":"mahzen","broadcast":"radyo veya televizyon yayını","flesh":"et; vücudun yumuşak dokusu","rescue":"kurtarmak; kurtarma","refuge":"sığınak","homicide":"cinayet","feed":"beslemek","newsroom":"haber merkezi","reporter":"muhabir","sheriff":"şerif","governor":"vali","racket":"burada: iş; gürültü; yasa dışı düzen","barbra":"Barbra (karakter adı)"},"captions":[{"start":139.451,"end":142.715,"text":"They ought to make the day the time changes the first day of summer."},{"start":142.8,"end":144.055,"text":"What?"},{"start":144.223,"end":146.316,"text":"Well, it's eight o'clock and it's still light."},{"start":146.441,"end":149.162,"text":"A lot of good the extra daylight does us."},{"start":149.204,"end":150.92000000000002,"text":"Now we've still got a three-hour drive back."},{"start":151.129,"end":152.93,"text":"We're not going to be home until after midnight."},{"start":152.971,"end":155.692,"text":"Well, if it really bugged you, Johnny, you wouldn't do it."},{"start":155.81799999999998,"end":158.58100000000002,"text":"You think I wanna blow Sunday on a scene like this?"},{"start":158.665,"end":160.758,"text":"You know, I figure we're either gonna have to move mother out here,"},{"start":160.883,"end":163.395,"text":"or move the grave into Pittsburgh."},{"start":163.47899999999998,"end":165.488,"text":"She can't make a trip like this."},{"start":165.572,"end":167.748,"text":"I don't know that she can't."},{"start":168.041,"end":171.809,"text":"- Is there any candy left? - No."},{"start":172.185,"end":174.571,"text":"Look at this thing. \"We still remember. \""},{"start":174.697,"end":177.167,"text":"I don't. You know, I don't even remember what the man looks like."},{"start":177.292,"end":178.96699999999998,"text":"Johnny, it takes you five minutes."},{"start":179.09199999999998,"end":184.073,"text":"5 minutes to put the wreath on the grave and 6 hours to drive back and forth."},{"start":184.115,"end":186.376,"text":"Mother wants to remember, so we trot 200 miles into the country"},{"start":186.459,"end":188.469,"text":"and she stays at home."},{"start":188.636,"end":190.436,"text":"Well, we're here, John, all right?"},{"start":197.845,"end":200.65,"text":"Radio: Testing... back on... Ah, ladies and... We're coming back"},{"start":200.776,"end":203.162,"text":"on the air after an interruption due to technical problem..."},{"start":215.594,"end":218.692,"text":"There's nothing wrong with the radio. Must've been the station."},{"start":218.817,"end":221.036,"text":"Which row is it in?"},{"start":241.338,"end":243.347,"text":"There's no one around."},{"start":243.598,"end":246.235,"text":"Well, it's late. If you'd gotten up earlier..."},{"start":246.277,"end":249.165,"text":"Oh, look, I already lost an hour's sleep in the time change."},{"start":249.249,"end":252.305,"text":"I think you complain just to hear yourself talk."},{"start":252.34,"end":254.022,"text":"There it is."},{"start":269.719,"end":272.60699999999997,"text":"I wonder what happened to the one from last year."},{"start":273.025,"end":275.997,"text":"Each year we spend good money on these things."},{"start":276.081,"end":278.677,"text":"We come out here, and the one from last year is gone."},{"start":278.761,"end":280.644,"text":"Well, the flowers die,"},{"start":280.77,"end":283.449,"text":"And the caretaker or somebody takes them away."},{"start":283.951,"end":287.006,"text":"Yeah, a little spit and polish,"},{"start":287.09000000000003,"end":288.304,"text":"he can clean this up sell it next year."},{"start":289.016,"end":291.611,"text":"Wonder how many times we bought the same one?"},{"start":308.899,"end":311.704,"text":"Hey, come on, Barb, church was this morning, huh?"},{"start":330.625,"end":334.978,"text":"Hey, I mean, praying's for church, huh? Come on."},{"start":335.229,"end":338.034,"text":"I haven't seen you in church lately."},{"start":339.959,"end":342.178,"text":"Well, there's not much sense in my going to church."},{"start":342.889,"end":346.448,"text":"Do you remember one time when we were small, we were out here?"},{"start":346.573,"end":348.457,"text":"It was from right over there."},{"start":348.582,"end":350.466,"text":"I jumped out at you from behind the tree"},{"start":350.55,"end":353.229,"text":"And Grandpa got all excited, and he shook his fist at me, and he said,"},{"start":353.313,"end":355.615,"text":"\"Boy, you'll be damned to hell!\""},{"start":356.159,"end":358.461,"text":"[chuckles] Remember that? Right over there."},{"start":359.09000000000003,"end":360.303,"text":"Boy, you used to really be scared here."},{"start":361.936,"end":363.276,"text":"Johnny."},{"start":363.694,"end":367.168,"text":"- Hey, you're still afraid. - Stop it now. I mean it."},{"start":370.852,"end":374.117,"text":"[imitating Boris Karloff] They're coming to get you, Barbra."},{"start":374.41,"end":377.054,"text":"Stop it. You're ignorant."},{"start":377.089,"end":379.35,"text":"They're coming for you, Barbra."},{"start":380.103,"end":382.405,"text":"Stop it. You're acting like a child."},{"start":382.74,"end":384.289,"text":"They're coming for you."},{"start":384.875,"end":387.596,"text":"Look! There comes one of them now."},{"start":388.433,"end":391.279,"text":"- He'll hear you. - Here he comes now. I'm getting out of here!"},{"start":391.447,"end":392.536,"text":"Johnny!"},{"start":403.336,"end":404.507,"text":"Johnny!"},{"start":404.591,"end":406.349,"text":"Help me!"},{"start":834.659,"end":836.5,"text":"It's all right."},{"start":839.598,"end":841.733,"text":"Don't worry about him. I can handle him."},{"start":841.817,"end":844.831,"text":"Probably be a lot more of them as soon as they find out about us."},{"start":848.222,"end":849.602,"text":"Truck is outta gas."},{"start":849.686,"end":851.696,"text":"This pump out here is locked. Is there a key?"},{"start":853.621,"end":856.635,"text":"We can try to get out of here if we can get some gas. Is there a key?"},{"start":866.723,"end":868.691,"text":"I suppose you've tried this."},{"start":878.193,"end":879.784,"text":"Do you live here?"},{"start":902.932,"end":904.858,"text":"We've gotta get out of here."},{"start":904.983,"end":907.16,"text":"We have to get where there are some other people."},{"start":910.802,"end":913.021,"text":"Maybe we better take some food."},{"start":913.397,"end":917.249,"text":"I'll see if I can find some food."},{"start":959.778,"end":963.797,"text":"- What's happening? - I'll be just a second."},{"start":964.048,"end":965.261,"text":"What's happening?"},{"start":978.865,"end":980.289,"text":"Two of them."},{"start":985.521,"end":988.578,"text":"There are two of them out there. Have you seen any more around here?"},{"start":988.613,"end":990.754,"text":"I can take care of those two."},{"start":990.796,"end":993.349,"text":"- I know you're afraid, but we have to... - I don't know! I don't know!"},{"start":993.384,"end":995.443,"text":"What's happening?"},{"start":1136.342,"end":1137.766,"text":"They know we're in here now."},{"start":1153.129,"end":1154.426,"text":"Don't look at it."},{"start":1227.597,"end":1229.941,"text":"Get some more lights on in this house."},{"start":1267.698,"end":1271.006,"text":"Why don't you see if you can find some wood, some boards,"},{"start":1271.048,"end":1273.099,"text":"something there by the fireplace, Something we can nail this place up?"},{"start":1277.871,"end":1279.126,"text":"Well, goddamn..."},{"start":1281.848,"end":1286.369,"text":"Look. I know you're afraid. I'm afraid too."},{"start":1286.452,"end":1289.891,"text":"But we have to try to board the house up together."},{"start":1289.926,"end":1292.521,"text":"Now, I'm going to board up the windows and the doors. Do you understand?"},{"start":1292.556,"end":1295.208,"text":"We'll be all right here."},{"start":1295.243,"end":1298.8,"text":"We'll be all right till someone comes to rescue us. But we have to work together."},{"start":1298.835,"end":1299.931,"text":"You'll have to help me."},{"start":1299.973,"end":1303.237,"text":"Now I want you to go in and get some wood so I can board the place up."},{"start":1304.117,"end":1305.121,"text":"Ok?"},{"start":1306.294,"end":1307.424,"text":"Ok?"},{"start":1467.035,"end":1468.249,"text":"They're not that strong."},{"start":1468.543,"end":1471.765,"text":"Here, I want you to pick out some nails. Pick out the biggest ones you can find."},{"start":1477.417,"end":1479.9279999999999,"text":"There, this room looks pretty secure."},{"start":1481.77,"end":1484.909,"text":"If we have to, we can run in here and board up the doors."},{"start":1487.839,"end":1491.23,"text":"Won't be long before those things'll be back, pounding their way in here."},{"start":1491.272,"end":1494.788,"text":"They're afraid now."},{"start":1496.295,"end":1499.351,"text":"They're afraid of fire. I found that out."},{"start":1511.532,"end":1515.551,"text":"You know a place back down the road called Beekman's? Beekman's diner?"},{"start":1522.332,"end":1525.346,"text":"Anyhow, that's where I found that truck I have out there."},{"start":1527.481,"end":1529.406,"text":"There's a radio in the truck."},{"start":1530.788,"end":1532.797,"text":"I had jumped in to listen to it,"},{"start":1533.3,"end":1537.402,"text":"When a big gasoline truck came screaming right across the road."},{"start":1537.444,"end":1541.462,"text":"Well, there must have been 10-15 of those things chasing after it."},{"start":1542.718,"end":1544.644,"text":"Grabbing and holding on."},{"start":1548.159,"end":1550.001,"text":"Now, I didn't see them at first."},{"start":1551.676,"end":1554.773,"text":"I could just see that the truck was moving in a funny way."},{"start":1555.611,"end":1558.122,"text":"And those things were catching up to it."},{"start":1560.592,"end":1563.647,"text":"Truck went right across the road."},{"start":1564.485,"end":1567.624,"text":"Slammed on my brakes to keep from hitting it myself."},{"start":1567.917,"end":1570.052,"text":"It went right through the guard rail."},{"start":1576.289,"end":1580.224,"text":"I guess... I guess the driver must have cut off the road,"},{"start":1580.434,"end":1583.573,"text":"into that gas station by Beekman's diner."},{"start":1583.992,"end":1587.675,"text":"It went right through the billboard. Ripped over a gas pump,"},{"start":1587.717,"end":1588.645,"text":"and never stopped moving."},{"start":1588.68,"end":1591.485,"text":"By now it's like a moving bonfire."},{"start":1594.707,"end":1598.35,"text":"Didn't know if the truck was going to explode or what."},{"start":1601.196,"end":1605.089,"text":"I can still hear the man, screaming."},{"start":1609.066,"end":1612.833,"text":"This thing is just backing away from it."},{"start":1614.465,"end":1617.731,"text":"I look back at the diner to see"},{"start":1617.773,"end":1620.075,"text":"If there was anyone there who could help me."},{"start":1622.586,"end":1624.728,"text":"That was when I noticed that"},{"start":1624.763,"end":1627.191,"text":"The entire place had been encircled."},{"start":1629.368,"end":1632.13,"text":"Wasn't a sign of life left, except..."},{"start":1636.023,"end":1638.2,"text":"by now, there were no more screams."},{"start":1640.126,"end":1642.261,"text":"I realized that..."},{"start":1643.558,"end":1645.281,"text":"I was alone."},{"start":1645.316,"end":1646.531,"text":"With 50 or 60 of those things."},{"start":1648.414,"end":1650.926,"text":"Just standing there,"},{"start":1651.804,"end":1653.688,"text":"staring at me."},{"start":1655.196,"end":1657.288,"text":"I started to drive. I..."},{"start":1658.753,"end":1660.888,"text":"Just plowed right through them."},{"start":1660.972,"end":1662.73,"text":"They didn't move."},{"start":1662.814,"end":1668.507,"text":"They didn't run, or... just stood there, staring at me."},{"start":1670.684,"end":1672.944,"text":"Just wanted to crush them."},{"start":1677.004,"end":1681.357,"text":"They... scattered through the air, like bugs."},{"start":1683.952,"end":1686.758,"text":"We were riding in the cemetery."},{"start":1687.636,"end":1689.185,"text":"Johnny and me."},{"start":1690.232,"end":1691.613,"text":"Johnny."},{"start":1697.851,"end":1702.037,"text":"We... we came to put a wreath on my father's grave."},{"start":1704.088,"end":1707.855,"text":"Johnny and... and he said,"},{"start":1709.027,"end":1711.999,"text":"\"Can I have some candy, Barbra?\""},{"start":1715.012,"end":1717.357,"text":"And we didn't have any."},{"start":1719.743,"end":1721.417,"text":"And..."},{"start":1726.147,"end":1727.445,"text":"Oh, it's hot in here."},{"start":1728.115,"end":1729.203,"text":"Hot..."},{"start":1736.152,"end":1738.726,"text":"And he said, \"Oh, it's late. \""},{"start":1738.761,"end":1741.301,"text":"\"Why did we start so late?\""},{"start":1741.845,"end":1744.113,"text":"And I said, \"Johnny,"},{"start":1744.148,"end":1746.868,"text":"\"if you'd gotten up earlier,"},{"start":1746.903,"end":1748.71,"text":"\"we wouldn't be late. \""},{"start":1749.715,"end":1752.854,"text":"Johnny asked me if I were afraid."},{"start":1753.064,"end":1756.287,"text":"And I said, \"I'm not afraid, Johnny. \""},{"start":1758.463,"end":1761.98,"text":"And then this man started walking up the road."},{"start":1763.612,"end":1767.631,"text":"He came slowly, and Johnny kept teasing me and saying,"},{"start":1767.798,"end":1770.896,"text":"\"He's coming to get you, Barbra. \""},{"start":1770.938,"end":1773.993,"text":"And I laughed at him, and said, \"Johnny, stop it. \""},{"start":1776.003,"end":1778.556,"text":"And then Johnny ran away."},{"start":1778.64,"end":1780.942,"text":"And I went up to this man,"},{"start":1780.977,"end":1783.244,"text":"and I was going to apologize,"},{"start":1784.584,"end":1786.594,"text":"Why don't you just keep calm?"},{"start":1786.635,"end":1790.486,"text":"And I looked up, and I said, \"Good eve... \""},{"start":1791.993,"end":1793.458,"text":"And he grabbed me!"},{"start":1794.714,"end":1798.481,"text":"He grabbed me! And he ripped at me!"},{"start":1798.774,"end":1802.082,"text":"He held me and he ripped at my clothes!"},{"start":1802.207,"end":1804.468,"text":"I think you should just calm down."},{"start":1805.053,"end":1809.114,"text":"Oh, I screamed, \"Johnny! Johnny, help me! Oh, help me!\""},{"start":1809.149,"end":1812.504,"text":"And he wouldn't let me go. He ripped..."},{"start":1816.397,"end":1818.281,"text":"And then Johnny came and he ran"},{"start":1819.411,"end":1821.671,"text":"And he... he fought this man,"},{"start":1822.509,"end":1825.397,"text":"And I got so afraid I ran."},{"start":1825.481,"end":1827.197,"text":"I ran... I ran..."},{"start":1831.467,"end":1833.937,"text":"And Johnny didn't come."},{"start":1835.066,"end":1838.458,"text":"We've got... we have to wait for Johnny."},{"start":1844.276,"end":1846.746,"text":"Maybe... we'd better go out and get him."},{"start":1847.876,"end":1850.345,"text":"We have to go out and get Johnny."},{"start":1850.387,"end":1851.894,"text":"He's out there."},{"start":1853.025,"end":1856.959,"text":"Please, don't you hear me? We've got to go out and get him."},{"start":1858.718,"end":1862.109,"text":"Please! We have got to go get Johnny!"},{"start":1862.569,"end":1864.536,"text":"Please help me!"},{"start":1866.839,"end":1869.894,"text":"Look, don't you know what's going on out there? This is no Sunday school picnic."},{"start":1869.929,"end":1872.287,"text":"Don't you understand? My brother is alone."},{"start":1872.322,"end":1876.466,"text":"- Your brother is dead. - No! My brother is not dead!"},{"start":1930.549,"end":1932.977,"text":"Radio: Because of the obvious threat to untold numbers of citizens,"},{"start":1933.103,"end":1936.2,"text":"and because of the crisis which is even now developing,"},{"start":1936.242,"end":1939.214,"text":"this radio station will remain on the air, day and night."},{"start":1939.507,"end":1941.767,"text":"This station and hundreds of other radio and TV stations"},{"start":1941.809,"end":1943.86,"text":"throughout this part of the country are pooling their resources"},{"start":1943.986,"end":1949.051,"text":"Through an emergency network hookup to keep you informed of all developments."},{"start":1949.428,"end":1952.776,"text":"At this hour, we repeat, these are the facts as we know them."},{"start":1952.818,"end":1954.576,"text":"There is an epidemic of mass murder"},{"start":1954.618,"end":1957.675,"text":"being committed by a virtual army of unidentified assassins."},{"start":1957.842,"end":1960.27,"text":"The murders are taking place in villages, cities,"},{"start":1960.437,"end":1965.376,"text":"Rural homes and suburbs with no apparent pattern or reason for the slayings."},{"start":1965.411,"end":1968.557,"text":"It seems to be a sudden, general explosion of mass homicide."},{"start":1968.726,"end":1971.411,"text":"We have some descriptions of the assassins."},{"start":1971.446,"end":1974.271,"text":"Eyewitnesses say they are ordinary looking people."},{"start":1974.306,"end":1977.097,"text":"Some say they appear to be in a kind of trance."},{"start":1977.139,"end":1978.604,"text":"Others describe them as being..."},{"start":1988.693,"end":1994.594,"text":"So, at this point there is no really authentic way for us"},{"start":1995.6,"end":1996.604,"text":"to say who or what to look for and guard yourself against."},{"start":1996.646,"end":2000.539,"text":"...reaction of law enforcement officials"},{"start":2000.581,"end":2004.641,"text":"is one of complete bewilderment at this hour."},{"start":2006.651,"end":2010.752,"text":"Police, sheriffs' deputies, and emergency ambulances"},{"start":2010.787,"end":2012.8029999999999,"text":"are literally deluged with calls for help"},{"start":2012.845,"end":2015.273,"text":"The scene can best be described as mayhem."},{"start":2015.308,"end":2017.702,"text":"Mayors of Pittsburgh, Philadelphia, and Miami,"},{"start":2017.744,"end":2020.506,"text":"Along with the governors of several eastern and midwestern states"},{"start":2020.841,"end":2024.022,"text":"have indicated the national guard may be mobilized at any moment,"},{"start":2024.105,"end":2025.278,"text":"but that has not happened as yet."},{"start":2025.445,"end":2029.799,"text":"The only advice our reporters have been able to get from official sources"},{"start":2029.834,"end":2033.817,"text":"is for private citizens to stay in their homes behind locked doors."},{"start":2033.985,"end":2036.461,"text":"Do not venture outside, for any reason,"},{"start":2036.496,"end":2038.296,"text":"until the nature of this crisis has been determined"},{"start":2038.464,"end":2041.519,"text":"and until we can advise what course of action to take."},{"start":2041.554,"end":2044.283,"text":"Keep listening to radio and TV"},{"start":2044.366,"end":2047.589,"text":"for any special instructions as this crisis develops further."},{"start":2047.624,"end":2050.812,"text":"Thousands of office and factory workers are being urged"},{"start":2050.896,"end":2052.696,"text":"to stay at their places of employment,"},{"start":2052.738,"end":2055.291,"text":"not to make any attempt to get to their homes."},{"start":2055.459,"end":2058.354,"text":"However, in spite of this urging and warning,"},{"start":2058.389,"end":2060.691,"text":"streets and highways are packed with frantic people"},{"start":2060.733,"end":2064.375,"text":"trying to reach their families, or apparently to flee just anywhere."},{"start":2064.919,"end":2070.068,"text":"Repeat: The safest course of action at this time is simply to stay where you..."},{"start":2088.653,"end":2090.586,"text":"Ladies and gentlemen, we've just received word"},{"start":2090.621,"end":2092.839,"text":"that the president has called a meeting of his cabinet"},{"start":2093.007,"end":2095.442,"text":"to deal with the sudden epidemic of murder"},{"start":2095.477,"end":2097.988,"text":"which has seized the eastern third of this nation."},{"start":2098.023,"end":2100.5,"text":"The meeting is scheduled to convene within the hour."},{"start":2100.542,"end":2102.97,"text":"Members of the presidential cabinet will be joined"},{"start":2103.054,"end":2106.863,"text":"by officials of the FBI and the joint chiefs behind closed doors."},{"start":2107.532,"end":2109.667,"text":"A White House spokesman, in announcing this conference,"},{"start":2109.709,"end":2111.719,"text":"says there will be an official announcement"},{"start":2111.76,"end":2113.77,"text":"as soon as possible following that meeting."},{"start":2113.812,"end":2116.239,"text":"This is the latest dispatch just received in our newsroom."},{"start":2116.867,"end":2121.388,"text":"Latest word also from national press services in Washington, D.C.,"},{"start":2121.472,"end":2125.909,"text":"that the emergency presidential conference which we've just mentioned"},{"start":2125.951,"end":2129.593,"text":"Will include high-ranking scientists from NASA."},{"start":2140.518,"end":2143.49,"text":"Radio and TV stations across the eastern part of the country"},{"start":2143.574,"end":2145.499,"text":"including the one to which you are listening"},{"start":2145.625,"end":2148.638,"text":"have joined their facilities in an emergency network"},{"start":2148.68,"end":2150.69,"text":"to bring you this news as it develops."},{"start":2150.857,"end":2153.369,"text":"We urge you to stay tuned to radio and TV"},{"start":2153.453,"end":2155.336,"text":"and to stay indoors at all costs."},{"start":2156.927,"end":2159.104,"text":"Late reports reaching this newsroom"},{"start":2159.145,"end":2161.155,"text":"tell of frightened people seeking refuge"},{"start":2161.197,"end":2163.206,"text":"in churches, schools and government buildings."},{"start":2163.248,"end":2164.971,"text":"Demanding shelter and protection"},{"start":2165.006,"end":2166.597,"text":"from the wholesale murder which apparently"},{"start":2166.632,"end":2168.438,"text":"is engulfing much of the nation."},{"start":2168.941,"end":2171.787,"text":"Law enforcement officials are at a loss to explain or,"},{"start":2171.871,"end":2173.755,"text":"even at this hour, even to theorize"},{"start":2173.797,"end":2175.974,"text":"about the reasons for this wave of murder..."},{"start":2177.732,"end":2183.09,"text":"Chief T.K. Dunmore of Camden, North Carolina, is quoted as saying, quote,"},{"start":2183.125,"end":2187.736,"text":"\"Tell the people, for God's sake, to get off the streets. \""},{"start":2187.82,"end":2191.134,"text":"\"Tell 'em to go home and lock their doors and windows up tight. \""},{"start":2191.169,"end":2194.684,"text":"\"We don't know what kind of murder-happy characters we have here. \" End quote."},{"start":2196.108,"end":2198.787,"text":"That's Chief Dunmore of Camden, North Carolina."},{"start":2199.498,"end":2202.262,"text":"So far the only descriptions, the only clues,"},{"start":2202.345,"end":2206.447,"text":"anyone has of the killers come from frightened witnesses."},{"start":2206.53,"end":2208.665,"text":"These eyewitness accounts variously describe"},{"start":2208.749,"end":2210.8,"text":"the murderers as \"ordinary looking people,\""},{"start":2210.842,"end":2212.475,"text":"\"Misshapen monsters. \""},{"start":2212.559,"end":2214.575,"text":"\"People who look like they're in a trance. \""},{"start":2214.61,"end":2218.294,"text":"And \"things that look like people but act like animals. \""},{"start":2218.336,"end":2220.931,"text":"Some eyewitnesses tell of seeing victims"},{"start":2220.966,"end":2223.526,"text":"who look as though they had been torn apart."},{"start":2223.861,"end":2228.047,"text":"This whole ghastly story began developing two days ago"},{"start":2228.089,"end":2232.149,"text":"with the report of the slaying of a family of seven..."},{"start":2232.191,"end":2234.326,"text":"Since then, reports of some senseless killings"},{"start":2234.368,"end":2236.377,"text":"began snowballing in a reign of terror"},{"start":2236.412,"end":2237.256,"text":"which has hopscotched..."},{"start":2241.651,"end":2243.66,"text":"...keep track of the murder reports"},{"start":2243.695,"end":2245.67,"text":"by the placing of markers on a map"},{"start":2245.795,"end":2247.554,"text":"seem to indicate a general spreading"},{"start":2247.637,"end":2251.154,"text":"from the extreme southeastern and states north and west."},{"start":2251.656,"end":2253.414,"text":"Our newsmen, who have been on the telephone"},{"start":2253.449,"end":2255.388,"text":"talking with officials of other cities"},{"start":2255.423,"end":2258.395,"text":"have determined that none of this kind of mass murder"},{"start":2258.688,"end":2261.744,"text":"has yet been reported west of the Mississippi river,"},{"start":2261.786,"end":2264.926,"text":"except in the extreme southeastern portion of Texas."},{"start":2265.302,"end":2266.935,"text":"Similar killings have been reported"},{"start":2266.977,"end":2268.734,"text":"around the Houston and Galveston areas"},{"start":2268.769,"end":2269.83,"text":"but nothing like the..."},{"start":2269.865,"end":2271.372,"text":"I found a gun and some bullets out there."},{"start":2274.344,"end":2275.432,"text":"Oh, and these."},{"start":2283.553,"end":2285.52,"text":"This place is boarded up pretty solid now."},{"start":2286.819,"end":2288.534,"text":"We ought to be all right here for a while."},{"start":2290.209,"end":2292.176,"text":"We have a gun and bullets,"},{"start":2292.72,"end":2294.227,"text":"Food and the radio,"},{"start":2296.739,"end":2300.046,"text":"Sooner or later, someone's bound to come and get us out."},{"start":2301.594,"end":2304.609,"text":"So again, we join with law enforcement agencies"},{"start":2304.902,"end":2306.828,"text":"in urging you to seek shelter in a building."},{"start":2306.911,"end":2308.689,"text":"Lock the doors and windows securely."},{"start":2308.724,"end":2310.469,"text":"Hey, that's us. We're doing all right."},{"start":2310.511,"end":2312.478,"text":"Be cautious of any suspicious strangers,"},{"start":2312.52,"end":2314.529,"text":"and keep tuned to your radio and television"},{"start":2314.571,"end":2315.75,"text":"for survival instructions"},{"start":2315.785,"end":2318.046,"text":"and further details of this continuing story."},{"start":2318.13,"end":2319.929,"text":"Look, I don't know if you're hearing me."},{"start":2320.767,"end":2322.609,"text":"But I'm going upstairs now."},{"start":2324.953,"end":2327.422,"text":"If anything should try to break in, I can hear it from up there."},{"start":2327.457,"end":2329.222,"text":"I'll be down to take care of it."},{"start":2331.399,"end":2332.829,"text":"Everything is all right for now."},{"start":2332.864,"end":2336.129,"text":"I'll be back to reinforce the windows and doors later."},{"start":2336.631,"end":2338.683,"text":"But you'll be alright for now, ok?"},{"start":2341.194,"end":2342.283,"text":"Ok?"},{"start":2345.338,"end":2347.599,"text":"Radio: Civil defense officials in Cumberland"},{"start":2347.634,"end":2348.854,"text":"have told newsmen that murder victims"},{"start":2348.896,"end":2353.878,"text":"show evidence of having been partially devoured by their murderers."},{"start":2393.184,"end":2395.653,"text":"Consistent reports from witnesses to the effect that people"},{"start":2395.689,"end":2398.542,"text":"who acted as though they were in a kind of trance"},{"start":2398.584,"end":2400.307,"text":"were killing and eating their victims"},{"start":2400.342,"end":2403.983,"text":"prompted authorities to examine the bodies of some of the victims."},{"start":2404.018,"end":2407.626,"text":"Medical authorities in Cumberland, Maryland have concluded that in all cases"},{"start":2407.661,"end":2411.937,"text":"the killers are eating the flesh of the people they murdered."},{"start":2412.272,"end":2415.998,"text":"Repeating this latest bulletin just received moments ago from Cumberland."},{"start":2416.033,"end":2418.384,"text":"Civil defense authorities have told newsmen"},{"start":2418.467,"end":2420.435,"text":"that murder victims show evidence"},{"start":2420.519,"end":2423.365,"text":"of having been partially devoured by their murderers."},{"start":2423.407,"end":2427.174,"text":"Medical examination of victims' bodies shows conclusively that"},{"start":2427.209,"end":2430.23,"text":"the killers are eating the flesh of the people they kill."},{"start":2431.15,"end":2435.714,"text":"And so this incredible story becomes more ghastly with each report."},{"start":2435.749,"end":2437.939,"text":"It's difficult to imagine such a thing actually happening"},{"start":2437.974,"end":2441.657,"text":"but these are the reports we have been receiving and passing on to you,"},{"start":2441.692,"end":2444.965,"text":"Reports which have been verified as completely as is possible"},{"start":2445,"end":2446.597,"text":"in this confused situation."},{"start":2460.075,"end":2462.588,"text":"- Hold it! - Don't shoot. We're from town."},{"start":2462.63,"end":2463.676,"text":"A radio!"},{"start":2464.681,"end":2467.701,"text":"Radio: The Butler county sheriff has verified that reports"},{"start":2467.736,"end":2471.881,"text":"of murder victims being partially eaten by their slayers is true."},{"start":2474.057,"end":2477.071,"text":"How long you guys been down there? I could've used some help up here."},{"start":2477.113,"end":2478.501,"text":"That's the cellar. It's the safest place."},{"start":2478.536,"end":2480.88,"text":"You mean you didn't hear the racket we were making up here?"},{"start":2480.915,"end":2482.932,"text":"How were we supposed to know what was going on?"},{"start":2482.973,"end":2484.941,"text":"Could've been those things for all we knew."},{"start":2484.983,"end":2486.078,"text":"That girl was screaming."},{"start":2486.113,"end":2488.373,"text":"Surely you must know what a girl screaming sounds like."},{"start":2488.408,"end":2489.462,"text":"Those things don't make any noise."},{"start":2489.797,"end":2492.022,"text":"Anybody would know somebody needed help."},{"start":2492.057,"end":2494.61,"text":"Look, it's kind of hard to hear what's going on from down there."},{"start":2494.736,"end":2496.954,"text":"We thought we could hear screams, but for all we knew,"},{"start":2496.996,"end":2499.801,"text":"that could have meant those things were in the house after her."},{"start":2500.052,"end":2503.024,"text":"- And you wouldn't come up and help? - Well, if there were more..."},{"start":2503.059,"end":2505.285,"text":"The racket sounded like the place was being ripped apart."},{"start":2505.368,"end":2507.001,"text":"How were we supposed to know what was going on?"},{"start":2507.461,"end":2508.549,"text":"Now wait a minute."},{"start":2508.591,"end":2511.186,"text":"You just got finished saying you couldn't hear it from down there."},{"start":2511.221,"end":2513.573,"text":"Now you say it sounded like the place was being ripped apart."},{"start":2513.615,"end":2515.917,"text":"It would be nice if you'd get your story straight, man."},{"start":2516.001,"end":2518.22,"text":"All right, now you tell me."},{"start":2519.015,"end":2522.154,"text":"I'm not going to take that kind of a chance when we've got a safe place."},{"start":2522.448,"end":2524.833,"text":"We luck into a safe place, and you're telling us"},{"start":2524.875,"end":2528.098,"text":"we've gotta risk our lives just because somebody might need help, huh?"},{"start":2528.133,"end":2531.322,"text":"- Yeah. Something like that. - All right, why don't we settle this..."},{"start":2531.364,"end":2532.368,"text":"Look, mister!"},{"start":2532.41,"end":2534.084,"text":"We came up, ok? We're here."},{"start":2534.879,"end":2536.896,"text":"Now I suggest we all go back downstairs"},{"start":2536.931,"end":2538.94,"text":"before any of those things find out we're in here."},{"start":2538.975,"end":2540.28,"text":"They can't get in here."},{"start":2540.531,"end":2542.163,"text":"You got the whole place boarded up?"},{"start":2542.246,"end":2543,"text":"Yeah, most of it."},{"start":2543.168,"end":2546.223,"text":"All but a few spots upstairs. They won't be hard to fix."},{"start":2546.307,"end":2549.238,"text":"You are insane. The cellar's the safest place."},{"start":2549.273,"end":2551.044,"text":"I'm telling you, they can't get in here."},{"start":2551.079,"end":2554.093,"text":"And I'm telling you, those things turned over our car."},{"start":2554.128,"end":2555.893,"text":"We were damned lucky to get away at all."},{"start":2556.103,"end":2559.869,"text":"Now you tell me those... things can't get through this lousy pile of wood?"},{"start":2560.498,"end":2564.014,"text":"His wife and kids downstairs. The kid's hurt."},{"start":2566.065,"end":2567.907,"text":"Well, I still think we're better off up here."},{"start":2569.33,"end":2571.297,"text":"We could strengthen everything up, Mr. Cooper."},{"start":2571.507,"end":2574.019,"text":"With all of us working, we could fix this place up in no time."},{"start":2574.06,"end":2575.734,"text":"We have everything we need up here."},{"start":2575.776,"end":2578.539,"text":"We can take all that stuff downstairs with us."},{"start":2578.581,"end":2580.171,"text":"Man, you're really crazy, you know that?"},{"start":2580.34,"end":2581.678,"text":"You got a million windows up here."},{"start":2581.713,"end":2583.018,"text":"All these windows. You're gonna..."},{"start":2583.102,"end":2585.739,"text":"You're gonna make 'em strong enough to keep these things out, huh?"},{"start":2585.781,"end":2587.414,"text":"I told you, those things don't have any strength."},{"start":2587.497,"end":2590.134,"text":"I smashed three of them and pushed another one out the door."},{"start":2590.218,"end":2593.818,"text":"Did you hear me, what I told you? They turned over our car."},{"start":2593.902,"end":2595.701,"text":"Oh hell, any good five men can do that."},{"start":2595.743,"end":2596.916,"text":"That's my point..."},{"start":2596.958,"end":2599.009,"text":"Only there's not going to be five, or even ten."},{"start":2599.051,"end":2601.939,"text":"There's gonna be twenty, thirty, maybe a hundred of those things."},{"start":2601.974,"end":2603.118,"text":"And as soon as they know we're here,"},{"start":2603.153,"end":2604.576,"text":"this place is gonna be crawling with them."},{"start":2604.617,"end":2607.883,"text":"Well, if there're that many, they'll probably get us wherever we are."},{"start":2608.552,"end":2610.729,"text":"Look, the cellar."},{"start":2611.064,"end":2612.697,"text":"The cellar. There's only one door, right?"},{"start":2612.739,"end":2615.585,"text":"Just one door. That's all we have to protect."},{"start":2615.627,"end":2618.809,"text":"Tom and I fixed it so it locks and boards from the inside."},{"start":2619.06,"end":2620.273,"text":"But up here, all these windows,"},{"start":2620.651,"end":2622.869,"text":"Why, we'd never know where they were gonna hit us next."},{"start":2622.904,"end":2624.292,"text":"You got a point, Mr. Cooper."},{"start":2624.417,"end":2627.223,"text":"But down in the cellar, there's no place to run to."},{"start":2627.515,"end":2630.906,"text":"I mean, if they did get in, there'd be no back exit. We'd be done for."},{"start":2632.162,"end":2633.711,"text":"We can get out of here if we have to."},{"start":2633.753,"end":2637.059,"text":"And we got windows to see what's going on outside."},{"start":2637.436,"end":2639.201,"text":"But down there, with no windows,"},{"start":2639.236,"end":2641.538,"text":"if a rescue party did come, we wouldn't even know it."},{"start":2641.622,"end":2643.966,"text":"But the cellar is the strongest place."},{"start":2644.001,"end":2645.557,"text":"The cellar is a death trap."},{"start":2645.724,"end":2649.325,"text":"I don't know, Mr. Cooper. I think he's right."},{"start":2649.827,"end":2651.752,"text":"You know how many's out there?"},{"start":2651.794,"end":2653.468,"text":"I don't know, I figure maybe six or seven."},{"start":2653.678,"end":2657.194,"text":"Look. You two can do whatever you like."},{"start":2657.319,"end":2661.003,"text":"I'm going back down to the cellar and you better decide,"},{"start":2661.087,"end":2663.222,"text":"'cause I'm gonna board up that door,"},{"start":2663.306,"end":2665.44,"text":"and I'm not gonna unlock it again no matter what happens."},{"start":2665.482,"end":2666.863,"text":"Now wait a minute, Mr. Cooper."},{"start":2666.905,"end":2669.961,"text":"No, I'm not gonna wait! I've made my decision, now you make yours."},{"start":2670.045,"end":2672.556,"text":"Now wait a minute! Let's think about this."},{"start":2672.891,"end":2674.859,"text":"We can make it to the cellar if we have to."},{"start":2675.361,"end":2678.919,"text":"And if we do decide to stay down there, We'll need some things from up here."},{"start":2678.961,"end":2681.473,"text":"So let's at least consider this a while."},{"start":2685.617,"end":2686.788,"text":"If you box yourself in the cellar"},{"start":2686.83,"end":2689.216,"text":"and those things get in the house, you've had it."},{"start":2689.259,"end":2691.519,"text":"At least up here, you have a fighting chance."},{"start":2695.412,"end":2697.714,"text":"Yeah, looks like about eight or ten of them now."},{"start":2697.839,"end":2701.733,"text":"That's more than there were. There're a lot out back, too."},{"start":2744.304,"end":2747.318,"text":"Harry? Harry, what's happening?"},{"start":2747.353,"end":2748.615,"text":"It's all right!"},{"start":2763.392,"end":2764.564,"text":"Now take it."},{"start":2804.331,"end":2805.754,"text":"We've gotta fix these boards."},{"start":2806.591,"end":2807.722,"text":"You're crazy!"},{"start":2808.182,"end":2810.736,"text":"Those things are gonna be at every window and door in this place!"},{"start":2810.903,"end":2812.326,"text":"We've got to get down into the cellar."},{"start":2812.452,"end":2814.503,"text":"Go down into your damn cellar and get out of here!"},{"start":2817.391,"end":2819.7,"text":"- I'm... I'm taking the girl with me. - You leave her here."},{"start":2819.735,"end":2822.498,"text":"Keep your hands off her, and everything else that's up here too."},{"start":2822.54,"end":2825.136,"text":"Because if I stay up here, I'm fighting for everything up here,"},{"start":2825.178,"end":2827.605,"text":"and the radio and the food is part of what I'm fighting for."},{"start":2828.108,"end":2829.908,"text":"Now if you're going down in the cellar, get."},{"start":2829.95,"end":2831.205,"text":"The man's insane. He's insane."},{"start":2832.879,"end":2835.809,"text":"We've... we've got to have food down there. We've got a right."},{"start":2835.844,"end":2837.651,"text":"- This your house? - We've got a right."},{"start":2837.986,"end":2839.661,"text":"You going down there with him?"},{"start":2840.457,"end":2843.679,"text":"Yes or no? This is your last chance. No beating around the bush."},{"start":2844.558,"end":2846.316,"text":"Listen, I got a kid down there."},{"start":2846.818,"end":2848.619,"text":"She can't possib... I couldn't bring her up here."},{"start":2848.702,"end":2851.046,"text":"She can't possibly take all the racket from those things"},{"start":2851.081,"end":2852.637,"text":"smashing through the windows."},{"start":2852.672,"end":2853.984,"text":"Well, you're her father."},{"start":2854.019,"end":2857.075,"text":"If you're stupid enough to go die in that trap, that's your business."},{"start":2857.116,"end":2859.502,"text":"However, I am not stupid enough to follow you."},{"start":2860.507,"end":2863.019,"text":"It is tough for the kid that her old man is so stupid."},{"start":2863.312,"end":2866.074,"text":"Now, get the hell down in the cellar."},{"start":2866.2,"end":2868.962,"text":"You can be the boss down there. I'm boss up here."},{"start":2871.014,"end":2872.73,"text":"You bastards!"},{"start":2874.698,"end":2877.586,"text":"You know, I won't open this door again. I mean it."},{"start":2877.837,"end":2880.893,"text":"- Mr. Cooper, with your help... - With my help."},{"start":2880.935,"end":2884.158,"text":"Let him go, man. His mind is made up."},{"start":2886.125,"end":2887.129,"text":"Wait a minute."},{"start":2889.516,"end":2891.357,"text":"Judy? Come on up here, honey."},{"start":2898.851,"end":2900.483,"text":"You're gonna let them get her too, huh?"},{"start":2900.944,"end":2902.492,"text":"It's all right, honey. Go ahead."},{"start":2912.999,"end":2915.72,"text":"If we stick together, man, we can fix it up real good."},{"start":2916.348,"end":2918.902,"text":"There's lots of places we can run to up here."},{"start":2919.739,"end":2922.48,"text":"Mr. Cooper? We'd all be a lot better off"},{"start":2922.515,"end":2925.223,"text":"if all three of us were working together."},{"start":2928.153,"end":2929.66,"text":"Hey. Hey, kid."},{"start":2938.24,"end":2939.58,"text":"He's wrong, you know."},{"start":2940.501,"end":2942.426,"text":"I'm not boxing myself in down there."},{"start":2949.627,"end":2951.762,"text":"Well, we're safe now. It's boarded up tight."},{"start":2954.064,"end":2955.319,"text":"What about Tom and Judy?"},{"start":2955.529,"end":2957.12,"text":"They wanna stay up there. Let 'em."},{"start":2961.599,"end":2966.621,"text":"There are... two other people upstairs. A man and a girl."},{"start":2966.656,"end":2968.296,"text":"We heard the screaming."},{"start":2968.924,"end":2971.184,"text":"Yeah, but I didn't know who they were,"},{"start":2971.435,"end":2973.445,"text":"and I wasn't about to take any unnecessary chances."},{"start":2973.486,"end":2974.994,"text":"Of course not, Harry."},{"start":2988.389,"end":2992.575,"text":"- Is she all right? - I don't know what it is."},{"start":2992.659,"end":2993.998,"text":"She feels warm. Maybe it's shock."},{"start":2994.793,"end":2996.301,"text":"Where'd you get the bandage?"},{"start":2996.845,"end":3000.318,"text":"Some laundry in the basket. I tore a sheet."},{"start":3007.896,"end":3009.947,"text":"Let them stay upstairs."},{"start":3010.909,"end":3011.998,"text":"Let them."},{"start":3013.253,"end":3015.974,"text":"Too many ways those monsters can get in up there."},{"start":3017.314,"end":3019.198,"text":"We'll see who's right."},{"start":3019.407,"end":3022.797,"text":"We'll see, when they come begging me to let them in down here."},{"start":3023.216,"end":3025.435,"text":"- That's important, isn't it? - What?"},{"start":3025.853,"end":3027.528,"text":"To be right. Everybody else to be wrong."},{"start":3027.563,"end":3029.327,"text":"What do you mean by that?"},{"start":3033.011,"end":3035.983,"text":"Does anyone up there know why we're being attacked?"},{"start":3036.988,"end":3039.5,"text":"Whatever it is, it isn't just happening here."},{"start":3039.96,"end":3042.429,"text":"It's some kind of mass murder. It's going on everywhere."},{"start":3043.142,"end":3044.941,"text":"- The radio said to stay inside... - Radio?"},{"start":3046.072,"end":3047.788,"text":"Radio, upstairs. I heard the news bulletin."},{"start":3047.872,"end":3050.802,"text":"There's a radio upstairs and you boarded us in down here?"},{"start":3050.885,"end":3053.104,"text":"- I know what I'm doing. - What did it say?"},{"start":3053.146,"end":3055.281,"text":"Nothing! Nothing. They don't know anything yet."},{"start":3055.783,"end":3057.416,"text":"The... there's mass murder everywhere, and"},{"start":3057.499,"end":3060.681,"text":"people are supposed to look for a safe place to hide."},{"start":3060.723,"end":3062.522,"text":"Take the boards off that door."},{"start":3063.402,"end":3065.411,"text":"We are staying down here, Helen."},{"start":3065.453,"end":3068.257,"text":"Harry, that radio is at least some kind of communication."},{"start":3068.425,"end":3070.309,"text":"If the authorities know what's happening,"},{"start":3070.392,"end":3073.406,"text":"Well, they'll send people for us, or they'll tell us what to do."},{"start":3073.741,"end":3075.332,"text":"How are we going to know what's going on,"},{"start":3075.373,"end":3077.132,"text":"if we lock ourselves in this dungeon?"},{"start":3087.639,"end":3089.732,"text":"We may not enjoy living together..."},{"start":3091.489,"end":3093.791,"text":"But dying together isn't going to solve anything."},{"start":3094.546,"end":3096.68,"text":"Those people aren't our enemies."},{"start":3096.89,"end":3098.187,"text":"Mr. Cooper!"},{"start":3100.112,"end":3103.294,"text":"Mr. Cooper? They found a television set upstairs."},{"start":3105.848,"end":3106.852,"text":"Let's go up."},{"start":3107.103,"end":3108.192,"text":"Tom?"},{"start":3108.652,"end":3109.447,"text":"Yes?"},{"start":3110.452,"end":3113.089,"text":"If Judy would come downstairs for a few minutes,"},{"start":3113.173,"end":3115.308,"text":"Harry and I could come upstairs."},{"start":3116.103,"end":3117.735,"text":"Ok. Yeah. Right away."},{"start":3120.876,"end":3121.838,"text":"Will you do it?"},{"start":3122.424,"end":3123.812,"text":"Do I have to?"},{"start":3123.847,"end":3127.615,"text":"Look, honey. Nothing's gonna get done with them down there and us up here."},{"start":3128.075,"end":3131.843,"text":"- Do this. For me. - Ok."},{"start":3133.349,"end":3134.605,"text":"Ok, open up."},{"start":3156.749,"end":3158.465,"text":"I'll take good care of her, Helen."},{"start":3161.94,"end":3163.279,"text":"She's all I have."},{"start":3165.331,"end":3166.795,"text":"Why don't you go upstairs now?"},{"start":3194.967,"end":3196.349,"text":"Her brother was killed."},{"start":3197.228,"end":3199.028,"text":"Hey... give me a hand with this thing."},{"start":3200.367,"end":3202.334,"text":"I gotta go help Ben with the television."},{"start":3245.785,"end":3247.208,"text":"Don't be afraid of me."},{"start":3247.878,"end":3251.143,"text":"I'm Helen Cooper. Harry's wife."},{"start":3259.18,"end":3262.528,"text":"This place is ridiculous. Look at this."},{"start":3262.738,"end":3264.663,"text":"There's a million weak spots up here."},{"start":3266.798,"end":3268.138,"text":"Give me one of those."},{"start":3272.575,"end":3274.334,"text":"Her brother was killed."},{"start":3282.161,"end":3284.338,"text":"And they talk about these windows."},{"start":3285.049,"end":3286.556,"text":"I can't see a damned thing."},{"start":3287.058,"end":3289.319,"text":"There could be 15 million of those things out there."},{"start":3289.528,"end":3291.203,"text":"That's how much good these windows are."},{"start":3295.807,"end":3298.486,"text":"Why don't you do something to help somebody?"},{"start":3303.594,"end":3306.063,"text":"Here, I have it. Drag a couple of those chairs together."},{"start":3306.482,"end":3307.989,"text":"There's a socket over here."},{"start":3313.095,"end":3316.193,"text":"Now, you'd better watch this and try to understand what's going on."},{"start":3318.077,"end":3319.709,"text":"I don't want anyone's life on my hands."},{"start":3319.751,"end":3321.265,"text":"Is there anything I can do to help?"},{"start":3321.3,"end":3322.974,"text":"I don't want to hear any more from you, mister."},{"start":3323.142,"end":3325.192,"text":"If you stay up here, you take orders from me!"},{"start":3325.445,"end":3327.453,"text":"And that includes leaving the girl alone."},{"start":3327.747,"end":3328.918,"text":"It's on! It's on!"},{"start":3329.002,"end":3330.049,"text":"There's no sound."},{"start":3331.262,"end":3332.644,"text":"Play with the rabbit ears."},{"start":3333.397,"end":3336.16,"text":"Reports, incredible as they seem,"},{"start":3336.202,"end":3338.714,"text":"are not the results of mass hysteria."},{"start":3338.756,"end":3341.895,"text":"\"Mass hysteria. \" What do they think, we're imagining all this?"},{"start":3341.937,"end":3342.774,"text":"Shut up."},{"start":3342.816,"end":3344.407,"text":"In all parts of the country."},{"start":3344.49,"end":3347.965,"text":"The wave of murder which is sweeping the eastern third of the nation"},{"start":3348.007,"end":3350.274,"text":"is being committed by creatures"},{"start":3350.309,"end":3352.737,"text":"who feast upon the flesh of their victims."},{"start":3353.323,"end":3356.176,"text":"First eyewitness accounts of this grisly development"},{"start":3356.211,"end":3360.439,"text":"came from people who were understandably frightened and almost incoherent."},{"start":3360.9,"end":3364.081,"text":"Officials and newsmen at first discounted"},{"start":3364.123,"end":3366.927,"text":"those eyewitness descriptions as being beyond belief."},{"start":3367.136,"end":3369.606,"text":"However, the reports persisted."},{"start":3369.774,"end":3372.251,"text":"Medical examinations of some of the victims"},{"start":3372.286,"end":3376.136,"text":"bore out the fact that they had been partially devoured."},{"start":3378.187,"end":3380.322,"text":"I think we have some late word just arriving"},{"start":3380.699,"end":3382.708,"text":"and we interrupt to bring this to you."},{"start":3384.592,"end":3386.601,"text":"This is the latest disclosure in a report"},{"start":3386.643,"end":3389.322,"text":"from National civil defense headquarters in Washington."},{"start":3389.531,"end":3393.508,"text":"It has been established that persons who have recently died"},{"start":3393.55,"end":3397.652,"text":"have been returning to life and committing acts of murder."},{"start":3398.238,"end":3403.178,"text":"A widespread investigation of reports from funeral homes, morgues & hospitals"},{"start":3403.22,"end":3407.28,"text":"has concluded that the unburied dead are coming back to life"},{"start":3407.322,"end":3409.456,"text":"and seeking human victims."},{"start":3410.294,"end":3413.35,"text":"It's hard for us here to believe what we're reporting to you,"},{"start":3413.385,"end":3414.982,"text":"but it does seem to be a fact."},{"start":3416.154,"end":3417.829,"text":"When this emergency first began,"},{"start":3418.205,"end":3421.638,"text":"radio and television was advising people to stay inside,"},{"start":3421.68,"end":3424.031,"text":"behind locked doors, for safety."},{"start":3424.066,"end":3426.166,"text":"Well, that situation has now changed."},{"start":3426.201,"end":3429.34,"text":"We're able to report a definite course of action for you."},{"start":3429.465,"end":3431.977,"text":"Civil defense machinery has been organized to provide"},{"start":3432.145,"end":3435.207,"text":"rescue stations with food, shelter,"},{"start":3435.242,"end":3438.717,"text":"medical treatment and protection by armed National Guardsmen."},{"start":3439.052,"end":3442.442,"text":"Stay tuned to the broadcasting stations in your local area"},{"start":3442.484,"end":3444.291,"text":"for this list of rescue stations."},{"start":3444.326,"end":3447.423,"text":"This list will be repeated throughout our news coverage."},{"start":3447.507,"end":3450.898,"text":"Look for the name of the rescue station nearest you,"},{"start":3450.982,"end":3454.415,"text":"and make your way to that location as soon as possible."},{"start":3454.624,"end":3457.47,"text":"So we have that truck. If we can get some gas, we can get outta here."},{"start":3457.554,"end":3460.316,"text":"- There's a pump out by the shed. - I know. That's why I pulled in here."},{"start":3460.358,"end":3461.286,"text":"But it's locked."},{"start":3461.321,"end":3463.833,"text":"...called this afternoon by the president."},{"start":3463.875,"end":3467.181,"text":"Since convening, this conference of the presidential cabinet,"},{"start":3467.223,"end":3470.154,"text":"The FBI, the joint chiefs of staff, the CIA"},{"start":3470.196,"end":3473.126,"text":"has not produced any public information."},{"start":3473.251,"end":3476.265,"text":"Why are space experts being consulted"},{"start":3476.3,"end":3478.065,"text":"about an earthbound emergency?"},{"start":3479.07,"end":3482.084,"text":"So far, all the betting on the answer to that question"},{"start":3482.125,"end":3485.223,"text":"centers on the recent explorer satellite shot to Venus."},{"start":3485.809,"end":3489.032,"text":"That satellite, you recall, started back to Earth,"},{"start":3489.067,"end":3490.414,"text":"but never got here."},{"start":3490.79,"end":3493.218,"text":"That's the space vehicle which orbited Venus"},{"start":3493.26,"end":3495.583,"text":"and then was purposely destroyed by NASA,"},{"start":3495.618,"end":3497.906,"text":"when scientists discovered it was carrying"},{"start":3497.948,"end":3500.209,"text":"a mysterious, high-level radiation with it."},{"start":3500.543,"end":3503.097,"text":"Could that radiation be somehow responsible"},{"start":3503.18,"end":3505.818,"text":"for the wholesale murders we're now suffering?"},{"start":3506.446,"end":3508.916,"text":"Newsman Don Quinn in Washington"},{"start":3508.957,"end":3510.005,"text":"has posed those questions."},{"start":3510.046,"end":3512.349,"text":"It's obvious. Our best move is to try to get out of here."},{"start":3512.474,"end":3514.064,"text":"How're you gonna get over to that pump?"},{"start":3514.484,"end":3515.362,"text":"Look!"},{"start":3516.241,"end":3519.214,"text":"You're coming from a meeting regarding the explosion of the Venus probe,"},{"start":3519.255,"end":3520.05,"text":"is that right?"},{"start":3520.176,"end":3522.694,"text":"Yes, yes, that was the subject of the meeting."},{"start":3522.729,"end":3524.99,"text":"Do you feel there is a connection between this and the phenomenon..."},{"start":3525.031,"end":3527.879,"text":"There's a definite connection. A definite connection."},{"start":3527.92,"end":3530.39,"text":"In other words, you feel that the radiation on the Venus probe is enough"},{"start":3530.516,"end":3531.736,"text":"to cause these mutations?"},{"start":3531.771,"end":3533.445,"text":"It was a very high degree of radiation."},{"start":3533.529,"end":3536.417,"text":"Well, just a minute. I'm not sure that that's certain at all."},{"start":3536.459,"end":3539.39,"text":"I don't think that has been... It's the only logical explanation"},{"start":3539.432,"end":3540.143,"text":"that we have at this time."},{"start":3540.478,"end":3542.069,"text":"In other words, it is the military's viewpoint that this..."},{"start":3542.104,"end":3544.831,"text":"the radiation is not the cause of the mutation."},{"start":3544.873,"end":3547.804,"text":"I can't speak for the entire military at this time, gentlemen."},{"start":3548.432,"end":3550.943,"text":"I must disagree with these gentlemen presently,"},{"start":3550.985,"end":3553.58,"text":"until we, until this is irrefutably proved."},{"start":3553.915,"end":3555.924,"text":"Everything is being done that can be done."},{"start":3555.966,"end":3557.933,"text":"We'll have to hurry for our next meeting."},{"start":3559.357,"end":3562.036,"text":"Professor, you feel that there is a definite connection between..."},{"start":3562.12,"end":3565.3,"text":"A definite connection as far as Dr. Keller and myself..."},{"start":3565.342,"end":3568.441,"text":"Doctor, please. I thought we decided that is not proved yet."},{"start":3568.943,"end":3570.283,"text":"Was it... was the satellite..."},{"start":3570.366,"end":3573.212,"text":"- When the satellite was exploded... - It was an unusual amount of radiation,"},{"start":3573.247,"end":3575.891,"text":"enough to cause mutation under certain circumstances."},{"start":3576.226,"end":3578.277,"text":"Could have happened to have a bearing on it."},{"start":3578.737,"end":3580.328,"text":"It does seem to have a bearing on it."},{"start":3580.538,"end":3583.427,"text":"Will there be a reply for the..."},{"start":3584.012,"end":3585.435,"text":"- There will be a reply? - Yes."},{"start":3585.47,"end":3586.44,"text":"Later this afternoon?"},{"start":3588.91,"end":3591.338,"text":"There will be a report this afternoon."},{"start":3591.379,"end":3593.807,"text":"Perhaps there will be a report later..."},{"start":3593.849,"end":3594.812,"text":"Will you close the window?"},{"start":3594.854,"end":3597.449,"text":"We are doing everything possible to solve the problem."},{"start":3603.603,"end":3606.031,"text":"We've heard all we need to know. We have to try to get out of here."},{"start":3606.198,"end":3609.546,"text":"He said the rescue stations have doctors and medical supplies."},{"start":3609.581,"end":3612.016,"text":"If we can get Karen there, we can get help for her."},{"start":3616.077,"end":3618.128,"text":"Willard. I saw a sign. That said Willard."},{"start":3618.463,"end":3620.395,"text":"It's only about 17 miles from here."},{"start":3620.43,"end":3622.565,"text":"You know this area. Are you from around here?"},{"start":3622.691,"end":3624.323,"text":"Judy and I are both from around here."},{"start":3624.365,"end":3626.877,"text":"We were on our way to the lake to go swimming."},{"start":3627.086,"end":3630.017,"text":"Judy had a radio, and we heard the first reports about this."},{"start":3630.142,"end":3632.151,"text":"So we knew the old house was here and we came in,"},{"start":3632.193,"end":3634.118,"text":"And found the lady upstairs, dead."},{"start":3634.83,"end":3637.593,"text":"Then these other people came. We went down into the basement"},{"start":3637.635,"end":3640.314,"text":"and put a bar across the door, and it is pretty strong."},{"start":3640.397,"end":3642.7,"text":"How could we possibly get away from here?"},{"start":3642.909,"end":3646.216,"text":"We've got a sick child, two women, one woman out of her head,"},{"start":3646.258,"end":3649.523,"text":"three men, and the place is surrounded with these things."},{"start":3649.899,"end":3653.709,"text":"For NASA. Dr. Grimes, your entire staff, I know,"},{"start":3653.751,"end":3657.476,"text":"has been working very hard to find some solution"},{"start":3657.56,"end":3659.528,"text":"to these things that are happening."},{"start":3659.611,"end":3661.502,"text":"Do you have any answers at this time?"},{"start":3661.537,"end":3665.849,"text":"Yes, we have some answers. But first let me stress the importance"},{"start":3665.89,"end":3669.489,"text":"of seeking medical attention for anyone who's been injured in any way."},{"start":3669.524,"end":3673.09,"text":"We don't know yet what complications might result from such injuries."},{"start":3673.801,"end":3675.392,"text":"How bad has your kid been hurt?"},{"start":3680.248,"end":3683.303,"text":"Look. You go down there and tell... Judy?"},{"start":3683.555,"end":3686.569,"text":"Yeah, you tell Judy to come up here and you stay with the kid, all right?"},{"start":3686.82,"end":3689.833,"text":"Destructive action taken with regard to the Venus probe."},{"start":3690.713,"end":3694.354,"text":"In the cold room at the university, we had a cadaver."},{"start":3694.69,"end":3698.582,"text":"A cadaver from which all four limbs had been amputated."},{"start":3699.043,"end":3700.592,"text":"Sometime early this morning,"},{"start":3700.885,"end":3704.031,"text":"it opened its eyes and began to move its trunk."},{"start":3704.066,"end":3707.54,"text":"It was dead, but it opened its eyes and tried to move."},{"start":3710.304,"end":3711.726,"text":"They want you upstairs."},{"start":3711.936,"end":3714.866,"text":"- Did she ask for me? - She hasn't said anything."},{"start":3715.996,"end":3717.378,"text":"I don't understand."},{"start":3718.8,"end":3722.066,"text":"Baby? It's mommy."},{"start":3723.154,"end":3724.285,"text":"I hurt."},{"start":3725.666,"end":3728.345,"text":"I'll come back down as soon as I find out what they want."},{"start":3728.931,"end":3730.438,"text":"Thank you, Judy."},{"start":3731.61,"end":3735.336,"text":"The bodies should be disposed of at once, preferably by cremation."},{"start":3735.545,"end":3739.396,"text":"Well, how long after death, then, does the body become reactivated?"},{"start":3739.431,"end":3741.496,"text":"- It's only a matter of minutes. - Minutes?"},{"start":3741.531,"end":3743.464,"text":"That doesn't give people time to make arrangements..."},{"start":3743.499,"end":3747.098,"text":"No, you're right. It doesn't give them time to make funeral arrangements."},{"start":3747.391,"end":3751.577,"text":"The bodies must be carried to the street and burned."},{"start":3751.912,"end":3755.596,"text":"They must be burned immediately. Soak them with gasoline and burn them."},{"start":3756.14,"end":3759.865,"text":"The bereaved will have to forgo the dubious comforts"},{"start":3759.907,"end":3761.707,"text":"that a funeral service will give."},{"start":3762.335,"end":3765.014,"text":"They're just dead flesh. And dangerous."},{"start":3765.684,"end":3768.154,"text":"Judy, I need you to find some bedspreads or sheets"},{"start":3770.373,"end":3772.549,"text":"- Is there a fruit cellar here? - Yes."},{"start":3772.717,"end":3774.021,"text":"We need some bottles or jars"},{"start":3774.056,"end":3776.986,"text":"to make Molotov cocktails to hold them off while we try to escape."},{"start":3777.021,"end":3778.953,"text":"Hey! There's a big can of kerosene down there."},{"start":3779.079,"end":3781.591,"text":"- I'll see what I can find. - I'll look for the bottles."},{"start":3781.675,"end":3783.475,"text":"There's a big key ring down there."},{"start":3783.6,"end":3785.861,"text":"There may be a key to the gas pump on it."},{"start":3786.112,"end":3787.534,"text":"I'll check."},{"start":3787.827,"end":3790.046,"text":"We can toss the cocktails from a window upstairs."},{"start":3790.298,"end":3792.977,"text":"Meantime, some of us can go out and try to get the gas,"},{"start":3793.019,"end":3794.735,"text":"then we can come back for the rest of the people."},{"start":3794.819,"end":3796.534,"text":"But that'll leave a door open someplace."},{"start":3796.576,"end":3799.088,"text":"Yeah, that's right. It better be this door."},{"start":3799.423,"end":3801.013,"text":"It's closer to the truck."},{"start":3801.6,"end":3804.823,"text":"Before we go out, we'll put some supplies behind the cellar door."},{"start":3804.865,"end":3806.665,"text":"While we're gone, the rest of you can hole up in there."},{"start":3806.707,"end":3808.549,"text":"I found some fruit jars in the cellar."},{"start":3808.841,"end":3811.646,"text":"And there's a key on here that's labeled for the gas pump out back."},{"start":3813.237,"end":3816.334,"text":"I'm not really that used to the truck. I found it abandoned."},{"start":3817.004,"end":3818.929,"text":"I can handle the truck, no sweat."},{"start":3822.404,"end":3824.581,"text":"You're it, then. You and I'll go."},{"start":3830.064,"end":3832.744,"text":"We'll put whatever lumber we find behind the cellar door."},{"start":3833.58,"end":3836.51,"text":"You can go upstairs and toss the cocktails from a window."},{"start":3837.264,"end":3839.19,"text":"Tom, you and I will have to unboard this door."},{"start":3839.483,"end":3840.906,"text":"After you toss the cocktails,"},{"start":3840.989,"end":3842.873,"text":"you hustle back down here and lock this door."},{"start":3843.124,"end":3845.72,"text":"It's no good to board it up because we'll have to get back in quickly."},{"start":3847.017,"end":3850.115,"text":"After we get the gas and get back into the house,"},{"start":3850.241,"end":3852.753,"text":"then we'll worry about getting everybody into the truck."},{"start":3853.882,"end":3855.145,"text":"Now, let's move it."},{"start":3855.18,"end":3858.78,"text":"No place to flee for safety, except for the rescue stations"},{"start":3858.822,"end":3859.701,"text":"which have been set up."},{"start":3860.036,"end":3863.636,"text":"Indications are that before this emergency is over,"},{"start":3863.678,"end":3867.194,"text":"we will need many, many more such rescue stations."},{"start":3876.382,"end":3877.931,"text":"You always have a smile for me."},{"start":3878.984,"end":3881.58,"text":"How can you smile like that all the time?"},{"start":3883.308,"end":3884.773,"text":"How many do you have done?"},{"start":3888.525,"end":3890.2,"text":"Come on, honey, we gotta move."},{"start":3891.078,"end":3892.324,"text":"Tom, are you sure about the phone?"},{"start":3892.53,"end":3896.548,"text":"The phone is dead out. All you get is a recorded message."},{"start":3897.057,"end":3900.813,"text":"If I could only call the folks. They're going to be so worried about us."},{"start":3901.773,"end":3903.317,"text":"Everything'll be alright."},{"start":3903.358,"end":3906.948,"text":"As soon as we get to Willard, we'll call them. They might even be there."},{"start":3907.908,"end":3908.827,"text":"I know."},{"start":3913.293,"end":3918.468,"text":"Tom... Are you sure we're doing the right thing, Tom?"},{"start":3918.718,"end":3920.638,"text":"- What, about getting outta here? - Yeah."},{"start":3921.515,"end":3923.644,"text":"Well, the television said that's the right thing to do."},{"start":3923.727,"end":3925.939,"text":"We've got to get to a rescue station."},{"start":3926.315,"end":3927.525,"text":"I don't know."},{"start":3927.817,"end":3930.071,"text":"Come on. You're starting to sound like Mr. Cooper now."},{"start":3930.112,"end":3932.206,"text":"But why do you have to go out there?"},{"start":3932.241,"end":3935.956,"text":"Look, I know how to handle that truck. And I can handle the pump."},{"start":3935.998,"end":3938.085,"text":"Ben doesn't know anything about that stuff."},{"start":3939.845,"end":3941.229,"text":"But we're safe in here."},{"start":3941.264,"end":3943.81,"text":"For how long, honey? We're safe now."},{"start":3943.936,"end":3946.481,"text":"But there's gonna be more and more of those things."},{"start":3946.523,"end":3948.318,"text":"I know. I know all that."},{"start":3952.742,"end":3956.79,"text":"Listen. Remember when we had the big flood?"},{"start":3957.417,"end":3961.507,"text":"Remember how difficult it was for us to convince you that it was right to leave?"},{"start":3961.883,"end":3964.512,"text":"Remember? Remember we had to go to Willard then?"},{"start":3964.804,"end":3966.933,"text":"This isn't a passing thing, honey."},{"start":3967.976,"end":3970.689,"text":"It... it's not like just a wind passing through."},{"start":3970.814,"end":3973.569,"text":"We've got to do something, and fast."},{"start":3979.621,"end":3982.292,"text":"I just don't want you to go out there, that's all."},{"start":3983.962,"end":3985.297,"text":"Hey... smile, honey."},{"start":3986.299,"end":3988.052,"text":"Where's that big smile for me?"},{"start":3992.727,"end":3995.022,"text":"You sure are no use at all, are you?"},{"start":3995.481,"end":4000.281,"text":"We've got work to do, honey. And you... you..."},{"start":4016.683,"end":4018.353,"text":"We better get her downstairs."},{"start":4018.603,"end":4020.857,"text":"We have to go downstairs now, Barbra."},{"start":4022.694,"end":4024.948,"text":"She's right. You have to go downstairs now."},{"start":4025.073,"end":4027.494,"text":"Just for a little while, until we get back."},{"start":4028.329,"end":4032.92,"text":"- Then we can all leave. - Oh, I'd like to leave. Yes."},{"start":4052.077,"end":4053.997,"text":"- Good luck. - Yeah."},{"start":4103.874,"end":4105.751,"text":"- You ready upstairs? - Yeah."},{"start":4105.786,"end":4107.046,"text":"Ok, toss 'em!"},{"start":4147.781,"end":4149.284,"text":"Go ahead! Go on!"},{"start":4165.353,"end":4166.23,"text":"I'm going with him!"},{"start":4166.689,"end":4169.902,"text":"Get back in the cellar! It's too late. Too late!"},{"start":4178.167,"end":4179.669,"text":"Well, is she coming? Come on."},{"start":4181.84,"end":4182.674,"text":"Get in!"},{"start":4255.879,"end":4257.132,"text":"- Come on! - This key won't work."},{"start":4257.167,"end":4258.717,"text":"Watch it."},{"start":4264.06,"end":4266.815,"text":"Watch the torch!"},{"start":4273.451,"end":4274.996,"text":"We've gotta get away from the pump!"},{"start":4286.932,"end":4287.641,"text":"Hang on!"},{"start":4289.147,"end":4291.484,"text":"Stop! I'm telling you guys to get outta the truck!"},{"start":4309.762,"end":4311.724,"text":"Let's get outta here!"},{"start":4313.644,"end":4314.812,"text":"Come on, come on!"},{"start":4314.847,"end":4315.982,"text":"My jacket's caught."},{"start":4384.719,"end":4385.72,"text":"Let me in!"},{"start":4386.847,"end":4387.682,"text":"Cooper!"},{"start":4452.709,"end":4455.047,"text":"I ought to drag you out there and feed you to those things."},{"start":4545.95,"end":4547.829,"text":"Isn't it three o'clock yet?"},{"start":4552.503,"end":4555.676,"text":"There's supposed to be another broadcast at three o'clock."},{"start":4555.759,"end":4557.094,"text":"Ten minutes."},{"start":4559.766,"end":4561.518,"text":"Oh. Only ten more minutes?"},{"start":4561.937,"end":4564.191,"text":"We don't have very long to wait."},{"start":4565.067,"end":4566.319,"text":"We can leave."},{"start":4568.322,"end":4569.908,"text":"Or we better leave soon."},{"start":4570.743,"end":4572.204,"text":"It's ten minutes to three."},{"start":4578.089,"end":4579.967,"text":"You know anything about this area at all?"},{"start":4580.593,"end":4582.138,"text":"I mean, is Willard the nearest town?"},{"start":4584.266,"end":4585.685,"text":"I don't know."},{"start":4588.565,"end":4590.484,"text":"We were..."},{"start":4592.279,"end":4595.744,"text":"Just trying to get to a motel before dark."},{"start":4596.912,"end":4598.624,"text":"You said those things turned your car over."},{"start":4598.832,"end":4601.253,"text":"You think we can get it back on its wheels and drive it? Where is it?"},{"start":4601.295,"end":4603.674,"text":"Seems like it was pretty far away."},{"start":4604.884,"end":4606.471,"text":"Seems like we ran."},{"start":4606.946,"end":4609.074,"text":"Forget it. It's at least a mile."},{"start":4609.449,"end":4611.119,"text":"Johnny has the keys."},{"start":4611.703,"end":4613.664,"text":"You're going to carry that child a mile?"},{"start":4613.705,"end":4615.666,"text":"Through that army of things out there?"},{"start":4615.701,"end":4616.709,"text":"I can carry the kid."},{"start":4617.669,"end":4619.171,"text":"What's wrong with her? How'd she get hurt?"},{"start":4620.673,"end":4623.719,"text":"- One of those things grabbed her. - Bit her on the arm."},{"start":4625.972,"end":4626.807,"text":"What's wrong?"},{"start":4627.391,"end":4629.977,"text":"Who knows what kind of disease those things carry?"},{"start":4630.812,"end":4633.357,"text":"- Is she conscious? - Barely."},{"start":4633.649,"end":4635.944,"text":"She can't walk. She's too weak."},{"start":4638.99,"end":4641.368,"text":"Well, one of us could try to get to the car."},{"start":4641.409,"end":4643.204,"text":"You gonna turn it over by yourself?"},{"start":4643.245,"end":4646.959,"text":"You can't start the car. Johnny has the keys."},{"start":4650.38,"end":4652.967,"text":"You have a car? Where? Where is it?"},{"start":4653.218,"end":4657.014,"text":"- You won't be able to start it. - Yeah. I know. But where is it?"},{"start":4670.282,"end":4671.368,"text":"Good lord."},{"start":4686.639,"end":4690.56,"text":"At this hour, they report the level of the mysterious radiation"},{"start":4690.685,"end":4692.73,"text":"continues to increase steadily."},{"start":4693.273,"end":4695.318,"text":"So long as this situation remains,"},{"start":4695.443,"end":4698.071,"text":"government spokesmen warn that dead bodies"},{"start":4698.113,"end":4701.534,"text":"will continue to be transformed into the flesh-eating ghouls."},{"start":4701.575,"end":4705.79,"text":"All persons who die during this crisis, from whatever cause,"},{"start":4705.831,"end":4708.501,"text":"will come back to life to seek human victims."},{"start":4708.586,"end":4712.007,"text":"Unless their bodies are first disposed of by cremation."},{"start":4712.674,"end":4714.718,"text":"Our News cameras have just returned"},{"start":4715.177,"end":4718.265,"text":"from covering such a search and destroy operation against the ghouls."},{"start":4718.3,"end":4720.769,"text":"This one conducted by sheriff Conan McClellan"},{"start":4720.935,"end":4722.771,"text":"in Butler County, Pennsylvania."},{"start":4722.938,"end":4724.566,"text":"So now let's go to that film report."},{"start":4725.483,"end":4728.487,"text":"All law enforcement agencies and the military"},{"start":4728.57,"end":4732.284,"text":"have been organized to search out and destroy the marauding ghouls."},{"start":4732.451,"end":4734.662,"text":"The survival command center at the Pentagon"},{"start":4734.787,"end":4738.001,"text":"has disclosed that a ghoul can be killed"},{"start":4738.168,"end":4742.131,"text":"by a shot in the head or a heavy blow to the skull."},{"start":4742.799,"end":4744.51,"text":"Officials are quoted as explaining"},{"start":4744.593,"end":4748.222,"text":"that since the brain of a ghoul has been activated by the radiation,"},{"start":4748.64,"end":4752.729,"text":"the plan is, kill the brain and you kill the ghoul."},{"start":4753.897,"end":4757.401,"text":"- Want anything from the supply wagon? - No, we're all right."},{"start":4758.737,"end":4761.038,"text":"Hey, Cass, put that thing all the way in the fire."},{"start":4761.073,"end":4763.702,"text":"- We don't want it getting up again. - All right, I gotcha."},{"start":4763.737,"end":4765.705,"text":"Chief McClellan, how's everything going?"},{"start":4765.746,"end":4768.793,"text":"Oh, things aren't going too bad. Men are taking it pretty good."},{"start":4769.21,"end":4771.546,"text":"You want to get on the other side of the road over there."},{"start":4772.172,"end":4773.966,"text":"Chief, do you think we'll be able to defeat these things?"},{"start":4774.508,"end":4777.137,"text":"Well, we killed 19 of them today, right in this area."},{"start":4777.345,"end":4780.6,"text":"Those last three we caught trying to claw their way into an abandoned shed."},{"start":4780.642,"end":4783.396,"text":"They must have thought somebody was in there. There wasn't, though."},{"start":4783.437,"end":4785.03,"text":"We heard 'em making all kind of noise."},{"start":4785.065,"end":4787.61,"text":"We came over and beat 'em off, blasted 'em down."},{"start":4787.652,"end":4789.863,"text":"Chief, as soon as you're finished, can I see you here?"},{"start":4789.946,"end":4790.739,"text":"Yeah, ok."},{"start":4790.906,"end":4793.869,"text":"Chief, if I were surrounded by six or eight of these things,"},{"start":4793.91,"end":4795.203,"text":"would I stand a chance with them?"},{"start":4795.245,"end":4797.833,"text":"Well, there's no problem. If you had a gun, shoot 'em in the head."},{"start":4797.868,"end":4799.007,"text":"That's a sure way to kill 'em."},{"start":4799.042,"end":4801.212,"text":"If you don't, get yourself a club or a torch."},{"start":4801.253,"end":4803.256,"text":"Beat 'em or burn 'em. They go up pretty easy."},{"start":4803.798,"end":4806.176,"text":"Well, Chief McClellan, how long do you think it'll take"},{"start":4806.211,"end":4807.929,"text":"until you get the situation under control?"},{"start":4808.054,"end":4811.226,"text":"Well, that's pretty hard to say. We don't know how many of 'em there are."},{"start":4811.267,"end":4813.019,"text":"We know when we find 'em, we can kill 'em."},{"start":4814.563,"end":4815.774,"text":"Are they slow-moving, chief?"},{"start":4815.982,"end":4818.909,"text":"Yeah, they're dead. They're all messed up."},{"start":4818.944,"end":4823.158,"text":"Well, in time, would you say you'd be able to wrap this up in 24 hours?"},{"start":4823.534,"end":4826.12,"text":"Well, we don't really know."},{"start":4826.162,"end":4829.792,"text":"We know we'll be into it most of the night, probably into the early morning."},{"start":4829.834,"end":4831.587,"text":"We're working our way toward Willard"},{"start":4831.628,"end":4833.631,"text":"and we'll team up with the National Guard over there,"},{"start":4833.673,"end":4835.634,"text":"and then we'll be able to give a more definite view."},{"start":4835.801,"end":4837.553,"text":"Thank you very much, chief McClellan."},{"start":4837.929,"end":4841.183,"text":"This is Bill Cardille, WIC-TV 11 news."},{"start":4841.725,"end":4843.019,"text":"Thank you, Bill, for that report."},{"start":4843.561,"end":4845.988,"text":"Official spokesmen declined to speculate"},{"start":4846.023,"end":4849.027,"text":"just how long it may take to kill off all the flesh-eaters"},{"start":4849.236,"end":4850.989,"text":"so long as the heavy ra..."},{"start":4857.33,"end":4858.999,"text":"Is the fuse box in the cellar?"},{"start":4859.791,"end":4860.877,"text":"I don't know. I..."},{"start":4865.091,"end":4866.425,"text":"Is... isn't the fuse..."},{"start":4867.552,"end":4868.637,"text":"The power lines are down."},{"start":4871.475,"end":4874.562,"text":"Helen? I have to get that gun."},{"start":4876.398,"end":4878.067,"text":"Haven't you had enough?"},{"start":4878.943,"end":4881.988,"text":"Two people are dead already, on account of that guy."},{"start":4882.073,"end":4883.657,"text":"Take a look out that window. Look at..."},{"start":4942.572,"end":4943.656,"text":"Get over here, man!"},{"start":4945.701,"end":4946.326,"text":"Come on!"},{"start":4964.81,"end":4968.648,"text":"Go ahead. Go ahead. You wanna stay up here now?"},{"start":4969.233,"end":4970.735,"text":"Helen, get in the cellar."},{"start":4973.113,"end":4975.074,"text":"Get in the cellar now! Move!"},{"start":5079.675,"end":5080.51,"text":"Karen?"},{"start":5090.19,"end":5091.192,"text":"Oh, baby."},{"start":5093.612,"end":5094.654,"text":"Baby."},{"start":5099,"end":5103,"text":"[Helen gasping]"},{"start":5107,"end":5132,"text":"[shrieking distorts, reverberates]"},{"start":5151.3,"end":5153.5,"text":"BARBRA: Get out! Get out!"},{"start":5154.989,"end":5160.286,"text":"No... no... No! Johnny!"},{"start":5162,"end":5167.17,"text":"No! Oh, help me, help me!"},{"start":5439.951,"end":5441.037,"text":"Hey, Vince, Bill,"},{"start":5441.579,"end":5444.291,"text":"you wanna get about four or five men and a couple dogs?"},{"start":5444.374,"end":5447.254,"text":"There's a house over here behind those trees. We wanna go check it out."},{"start":5447.546,"end":5448.922,"text":"You still here, Bill?"},{"start":5448.963,"end":5450.508,"text":"Yeah, chief, we're going to stay with it"},{"start":5450.549,"end":5451.975,"text":"till we meet up with the National Guard."},{"start":5452.01,"end":5454.221,"text":"- Where'd you get the coffee? - One of the volunteers."},{"start":5454.256,"end":5455.981,"text":"- You're doing all the work, take it. - Thank you."},{"start":5456.016,"end":5458.727,"text":"We should be wrapped up here. About three or four more hours,"},{"start":5458.853,"end":5460.194,"text":"we'll probably get into Willard's end."},{"start":5460.229,"end":5462.449,"text":"I guess you can go over there and meet the national guard."},{"start":5462.484,"end":5464.669,"text":"Nick, you and the rest of these men wanna come with me?"},{"start":5465.504,"end":5467.34,"text":"Bill, I'm checking the office to see what's happening."},{"start":5467.632,"end":5470.093,"text":"All right, Steve, tell 'em we're going to stay with it"},{"start":5470.128,"end":5473.055,"text":"and everything appears to be under control."},{"start":5522.957,"end":5525.169,"text":"They need you down there by the barn."},{"start":5529.048,"end":5531.176,"text":"You guys can follow the wagon down."},{"start":5531.218,"end":5533.722,"text":"I only need a few men to check out the house."},{"start":5536.643,"end":5539.938,"text":"- Somebody had a cookout here, Vince. - Yeah, sure looks like it, Con."},{"start":5579.159,"end":5580.953,"text":"He's a dead one. Get up here!"},{"start":5582.454,"end":5584.499,"text":"Nick! Tony! Steve!"},{"start":5584.582,"end":5586.877,"text":"You wanna get out in that field and build me a bonfire?"},{"start":5599.812,"end":5602.565,"text":"You. Drag that out of here and throw it on the fire."},{"start":5602.608,"end":5603.525,"text":"Nothing down here."},{"start":5603.609,"end":5605.487,"text":"All right. Go ahead down and give 'em a hand."},{"start":5605.737,"end":5607.03,"text":"Let's go check out the house."},{"start":5607.072,"end":5608.699,"text":"There's something there. I heard a noise."},{"start":5614.04,"end":5616.251,"text":"All right, Vince. Hit him in the head. Right between the eyes."},{"start":5620.173,"end":5623.511,"text":"Good shot. Okay, he's dead. Let's go get him."},{"start":5623.546,"end":5625.097,"text":"That's another one for the fire."},{"start":5646.501,"end":5648.295,"text":"Alright, send a wagon through..."},{"start":5657.079,"end":5659.457,"text":"Keep those dogs back off of those things."},{"start":5720.458,"end":5724.464,"text":"Come ahead with the motorcycle, please. Let's go!"},{"start":5728.258,"end":5730.553,"text":"Hey Randy, light these torches over here."}]},{"id":"other-side-of-the-box","type":"video","provider":"youtube","youtubeId":"OrOYvVf6tIM","title":"Other Side of the Box","creator":"Caleb J. Phillips · ALTER","year":2018,"level":"B2","category":"horror","genre":"horror","durationSeconds":923,"summaryTr":"Bir çiftin kapısına eski bir arkadaşları gelir ve onlara tuhaf bir kutu bırakır. Kutunun içindekinin tek bir kuralı vardır; o kurala uymak düşündüklerinden çok daha zordur.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Gündelik konuşmalar, kısa açıklamalar ve açık talimatlar B2 seviyesine uygundur; fısıltı, gerilim ve hızlı tepkiler ek dikkat gerektirir.","advisoryTr":"Yoğun gerilim, korkutucu görüntüler ve küfür içerir.","downloadable":false,"source":{"name":"ALTER — Other Side of the Box","url":"https://www.youtube.com/watch?v=OrOYvVf6tIM","watchUrl":"https://www.youtube.com/watch?v=OrOYvVf6tIM","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"Caleb J. Phillips · ALTER · Yayıncı: ALTER"},"glossary":{"package":"paket","estranged":"arası açılmış; uzaklaşmış","rule":"kural","stare":"gözünü ayırmadan bakmak","disappear":"kaybolmak","warning":"uyarı"},"captions":[]},{"id":"rha","type":"video","provider":"youtube","youtubeId":"Sgm_4WRcGRo","title":"R’ha","creator":"Kaleb Lechowski","year":2013,"level":"B2","category":"scifi","genre":"fantasy","durationSeconds":360,"summaryTr":"Bir uzaylı asker, kendi uygarlığını yok etmeye çalışan makineler tarafından sorgulanır. Kısa bir animasyon içinde direniş, güven ve hayatta kalma üzerine bir bilim kurgu macerası.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Kısa soru-cevaplar ve emirler açık bir hikâye içinde ilerler; mekanik sesler ve askerî kelimeler dinlemeyi zorlaştırır.","advisoryTr":"İşkence, tehdit ve savaş görüntüleri içerir.","downloadable":false,"source":{"name":"DUST — R’ha","url":"https://www.youtube.com/watch?v=Sgm_4WRcGRo","watchUrl":"https://www.youtube.com/watch?v=Sgm_4WRcGRo","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"Kaleb Lechowski · Yayıncı: DUST"},"glossary":{"interrogation":"sorgulama","resistance":"direniş","survivor":"hayatta kalan","machine":"makine","betrayal":"ihanet","civilization":"uygarlık"},"captions":[]},{"id":"sprite-fright","type":"video","title":"Sprite Fright","creator":"Blender Foundation","year":2021,"level":"B2","category":"fun","durationSeconds":630,"genre":"horror","summaryTr":"Doğa gezisine çıkan bir öğrenci grubu, ormanın küçük sakinleriyle karşılaşır. İngiliz aksanları, hızlı grup konuşmaları ve kelime oyunları içeren bir korku komedisi.","levelNoteTr":"B2, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Hızlı İngiliz İngilizcesi, argo, kısaltılmış söyleyişler ve kelime oyunları vardır. Latince tür adları ve doğa terimleri kelime desteği gerektirebilir.","advisoryTr":"Kanlı çizgi film şiddeti, ölüm, korku sahneleri, zorbalık, alkol ve ağır argo/küfür içerir. Yapımcı 13+ olarak belirtir; küçük çocuklar için uygun değildir.","videoUrl":"https://video.blender.org/object-storage/web_videos/a69d68a5-a0e0-4a80-9d66-49f093c97aaf-720.mp4","qualities":[{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/a69d68a5-a0e0-4a80-9d66-49f093c97aaf-720.mp4","sizeMB":102},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/a69d68a5-a0e0-4a80-9d66-49f093c97aaf-804.mp4","sizeMB":111}],"source":{"name":"Blender Foundation — Sprite Fright","url":"https://studio.blender.org/projects/sprite-fright/","license":"CC BY 1.0","licenseUrl":"https://creativecommons.org/licenses/by/1.0/","credit":"(CC) Blender Foundation | studio.blender.org","licenseSourceUrl":"https://studio.blender.org/projects/sprite-fright/pages/about/","watchUrl":"https://video.blender.org/videos/watch/a69d68a5-a0e0-4a80-9d66-49f093c97aaf","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından değiştirilmeden oynatılır."},"subtitleSource":{"name":"Blender Studio — resmî İngilizce WebVTT altyazısı","url":"https://video.blender.org/object-storage/captions/541aac20-a387-4d4b-be46-fd722b33fe58-en.vtt","license":"CC BY 1.0","licenseUrl":"https://creativecommons.org/licenses/by/1.0/","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"glossary":{"cornu":"Cornu aspersum: bir kara salyangozu türü","aspersum":"Cornu aspersum: bir kara salyangozu türü","motacilla":"Motacilla flava: sarı kuyruksallayan kuşu","flava":"Motacilla flava: sarı kuyruksallayan kuşu","fungis":"mantarlar; fun guys (eğlenceli tipler) kelime oyunu","dorkwad":"aptal, ezik (aşağılayıcı argo)","innit":"öyle değil mi? (isn’t it, İngiliz argosu)","oy":"hey! (seslenme)","phil":"Phil (karakter adı)","bbq":"barbekü, mangal","piss":"işemek (kaba); piss break: tuvalet molası","shagged":"cinsel ilişkiye girmiş (kaba argo)","sprite":"orman perisi; burada yaratıkların adı/kelime oyunu","sprites":"orman perileri; filmdeki yaratıklar","psycho":"psikopat, kaçık (argo)","bitches":"sürtükler (ağır hakaret)","bastards":"alçaklar (ağır hakaret)","geezer":"herif, adam (İngiliz argosu)","weenie":"ödlek, pısırık (argo)","wagtail":"kuyruksallayan kuşu","ribbing":"takılma, alay etme","wasted":"sarhoş, kafası iyi (argo)","buns":"çörekler; Sugar Buns: tatlım (hitap)","cakes":"kekler; Sweet cakes: tatlım (hitap)","muffin":"muffin; Love muffin: sevgilim (hitap)","punks":"serseriler","aaaah":"aaa! (çığlık)","nuh":"hayır (nuh-uh: olumsuzluk ünlemi)","uh":"ee (duraksama)","mtv":"MTV (müzik televizyon kanalı)","c'mon":"haydi, hadi (come on)","dilly":"dilly-dally: oyalanmak","outta":"out of: içinden, dışarı (konuşma dili)"},"captions":[{"start":17.375,"end":19.458,"text":"Hello, Mr.Snail!"},{"start":19.458,"end":22.333,"text":"Aw, you cute little cornu aspersum."},{"start":22.333,"end":25.125,"text":"Latin name bonus-points!"},{"start":28.375,"end":30.833,"text":"Can’t believe we got stuck with the tree hugger."},{"start":30.833,"end":34.667,"text":"If I have to hear the latin name for one more animal, I swear I'm gonna kill her."},{"start":34.667,"end":39.542,"text":"Relax, Sugar Buns. While she does all the work we’ll have all the fun."},{"start":39.542,"end":42.583,"text":"Yeah! And get wasted out of our minds!"},{"start":42.583,"end":44.25,"text":"Way ahead of you, man."},{"start":44.25,"end":48.625,"text":"C’mon, team! We mustn’t dilly-dally when there’s so much nature to see!"},{"start":48.625,"end":53.667,"text":"I was thinking we should call our class project, “Fungis in a Forest!”"},{"start":53.667,"end":56.167,"text":"Get it? Because we’re a group of fun guys."},{"start":56.167,"end":57.667,"text":"And also fungis which-"},{"start":57.667,"end":62.458,"text":"Shush! That’s a yellow wagtail. And she’s in distress!"},{"start":62.75,"end":66.333,"text":"There, there, my little motacilla flava."},{"start":67.792,"end":70.042,"text":"Oh! Look at her go!"},{"start":70.375,"end":71.5,"text":"Wow!"},{"start":71.5,"end":74.417,"text":"Out of the way, dorkwad! We're camping here."},{"start":74.417,"end":77.5,"text":"Finally! Time to get that BBQ burning."},{"start":78.417,"end":80.167,"text":"Oh. Oh, dear."},{"start":87.333,"end":88.875,"text":"Gross!"},{"start":90.833,"end":95.458,"text":"Oh. Easy, guys. We’re supposed to be studying nature, not wrecking it."},{"start":95.458,"end":97.958,"text":"Piss break!"},{"start":100.708,"end":104.667,"text":"Oy, fungus freak! Make yourself useful and fix the tent."},{"start":104.667,"end":108.917,"text":"Oh, a bit of friendly campsite ribbing. Fun."},{"start":109.875,"end":112.583,"text":"She wouldn't survive 5 minutes alone in these woods."},{"start":112.583,"end":116.792,"text":"Yeah. She's a real weenie that one, innit?"},{"start":116.792,"end":119,"text":"Oy, Phil! How those sausages coming?"},{"start":119,"end":122.458,"text":"Almost ready! Just need a bit more salt..."},{"start":156.333,"end":159.208,"text":"It's incredible. It's a new species."},{"start":159.208,"end":161.875,"text":"What the bloody hell are those things?"},{"start":161.875,"end":164.542,"text":"It's like a gnome shagged a mushroom."},{"start":177.375,"end":179.583,"text":"They’re absolutely adorable."},{"start":179.583,"end":182,"text":"Yeah, absolutely bloody adorable."},{"start":182,"end":185.625,"text":"And I bet we’ll make a fortune if we catch one of those things."},{"start":185.625,"end":186.958,"text":"We'd be famous!"},{"start":186.958,"end":188.292,"text":"Get on MTV."},{"start":188.292,"end":189.875,"text":"I wonder what they taste like."},{"start":189.875,"end":192.5,"text":"We really shouldn't disrupt their habitat."},{"start":192.5,"end":195.917,"text":"Right. Sure, sure."},{"start":195.917,"end":197.5,"text":"Greetings."},{"start":197.5,"end":199,"text":"Welcome, friends."},{"start":199,"end":201.208,"text":"I'll be right down."},{"start":206.25,"end":208.75,"text":"Could I interest you in some peppermint tea?"},{"start":208.75,"end":210.667,"text":"What are you guys?"},{"start":210.667,"end":214.417,"text":"We are Sprites. We sprite balance to the forest."},{"start":214.417,"end":219.667,"text":"We take care of the animals, plants, birds, moss..."},{"start":221,"end":223.917,"text":"Guys? Guys, I..."},{"start":226.583,"end":231.542,"text":"Hey, uh, little mushroom geezer, you cool with us camping here for the night?"},{"start":231.542,"end":236.333,"text":"Absolutely. A friend of the forest is a friend of the sprites."},{"start":237.708,"end":241.375,"text":"Maybe it was just ketchup... or something... like..."},{"start":241.375,"end":249.125,"text":"Red paint? Yeah, maybe they were just painting their little hats or... something..."},{"start":255.5,"end":257.04200000000003,"text":"Guys?"},{"start":260.08299999999997,"end":261.625,"text":"Guys?"},{"start":262.41700000000003,"end":263.95799999999997,"text":"Guys, this isn't funny."},{"start":265.08299999999997,"end":266.625,"text":"Guys?"},{"start":287.20799999999997,"end":290.16700000000003,"text":"We were just gonna catch one! But they’re psycho!"},{"start":290.16700000000003,"end":292.95799999999997,"text":"You gotta get me outta these! Hurry! They’re gonna kill us!"},{"start":295.66700000000003,"end":296.58299999999997,"text":"Hurry!"},{"start":296.58299999999997,"end":299.45799999999997,"text":"Right foot, left foot, leaf and stone."},{"start":299.45799999999997,"end":303.583,"text":"You picked the wrong camping spot, bitches."},{"start":303.583,"end":305.292,"text":"Sprite them!"},{"start":305.833,"end":307.542,"text":"Run!!!"},{"start":330.25,"end":332.08299999999997,"text":"Aaaah! My eyes!"},{"start":357.625,"end":359.625,"text":"Sugar Buns?! Help me!"},{"start":367.125,"end":368.875,"text":"Sweet cakes!"},{"start":371.292,"end":373.208,"text":"Love muffin..."},{"start":374.167,"end":375.667,"text":"Huh?"},{"start":400.04200000000003,"end":403.45799999999997,"text":"No, no, no! I can’t swim!"},{"start":415.08299999999997,"end":416.875,"text":"Yes!"},{"start":418.29200000000003,"end":419.70799999999997,"text":"No!"},{"start":432.833,"end":436.20799999999997,"text":"I don’t want to hurt you! Just keep your distance!"},{"start":437.20799999999997,"end":441.125,"text":"All right, then. Eat salt, you little green bastards!"},{"start":476.83299999999997,"end":478.54200000000003,"text":"Nuh-uh-uh."},{"start":478.54200000000003,"end":483.333,"text":"Those punks treated the world as their own personal rubbish bin."},{"start":483.333,"end":485.625,"text":"And you set them free!"},{"start":485.625,"end":487.833,"text":"Now you'll join them!"},{"start":525.875,"end":529.167,"text":"I’ll give you that one, Brother Bird!"},{"start":530,"end":535.417,"text":"Alright sprites, let’s burn the bodies and have some peppermint tea."}]},{"id":"the-chair","type":"video","provider":"youtube","youtubeId":"mhazCS14Tas","title":"The Chair","creator":"Curry Barker","year":2023,"level":"B2","category":"horror","genre":"horror","durationSeconds":1462,"summaryTr":"Eve getirilen eski bir sandalye, bir çiftin hayatını giderek daha tuhaf ve ürkütücü hâle getirir. Gündelik konuşmalardan psikolojik korkuya dönüşen bir kısa film.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Gündelik çift konuşmaları ve kısa tartışmalar B2 seviyesine uygundur; kesintili anlatı, argo ve fısıltılar takibi zorlaştırabilir.","advisoryTr":"Kan, şiddet, rahatsız edici görüntüler, küfür ve psikolojik korku içerir.","downloadable":false,"source":{"name":"that's a bad idea — The Chair","url":"https://www.youtube.com/watch?v=mhazCS14Tas","watchUrl":"https://www.youtube.com/watch?v=mhazCS14Tas","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"Curry Barker · Yayıncı: that's a bad idea"},"glossary":{"antique":"antika","malevolent":"kötücül","possess":"burada: birine veya nesneye musallat olmak","doubt":"şüphe","memory":"anı; bellek","haunt":"musallat olmak"},"captions":[]},{"id":"the-expert","type":"video","provider":"youtube","youtubeId":"BKorP55Aqvg","title":"The Expert","creator":"Lauris Beinerts","year":2014,"level":"B2","category":"fun","genre":"comedy","durationSeconds":454,"summaryTr":"Bir uzman, iş toplantısında kendisinden istenen imkânsız görevi açıklamaya çalışır. Herkesin çok emin konuştuğu ama kimsenin birbirini anlamadığı bir ofis komedisi.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. İş toplantısı dili, kibar itiraz, açıklama ve tekrar eden kelimeler B2 dinlemeye uygundur; ironi ve mantık oyunları ek dikkat ister.","advisoryTr":"","downloadable":false,"source":{"name":"Lauris Beinerts — The Expert","url":"https://www.youtube.com/watch?v=BKorP55Aqvg","watchUrl":"https://www.youtube.com/watch?v=BKorP55Aqvg","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"Lauris Beinerts · Yayıncı: Lauris Beinerts"},"glossary":{"expert":"uzman","perpendicular":"birbirine dik","transparent":"saydam","requirement":"gereklilik; istenen özellik","assumption":"varsayım","solution":"çözüm"},"captions":[]},{"id":"the-shaman","type":"video","provider":"youtube","youtubeId":"80EQZaYV9TA","title":"The Shaman","creator":"Marco Kalantari","year":2015,"level":"B2","category":"adventure","genre":"fantasy","durationSeconds":1043,"summaryTr":"Savaşın durmadığı bir gelecekte, bir şaman dev bir savaş makinesinin ruhuna ulaşmak için görevlendirilir. Büyü, teknoloji ve aksiyonu bir araya getiren fantastik bir bilim kurgu filmi.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Kısa görev konuşmaları ve emirler görsellerle desteklenir; askerî dil, sembolik ifadeler ve farklı aksanlar B2 için ek dikkat gerektirir.","advisoryTr":"Savaş, ölüm, kan ve rahatsız edici görüntüler içerir.","downloadable":false,"source":{"name":"Marco Kalantari — The Shaman","url":"https://www.youtube.com/watch?v=80EQZaYV9TA","watchUrl":"https://www.youtube.com/watch?v=80EQZaYV9TA","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"Marco Kalantari · Yayıncı: Marco Kalantari"},"glossary":{"shaman":"şaman","colossus":"devasa varlık veya yapı","soul":"ruh","mission":"görev","ritual":"ritüel; ayin","battle":"savaş; çatışma"},"captions":[]},{"id":"the-terror","type":"video","title":"The Terror","creator":"Roger Corman","year":1963,"level":"B2","category":"horror","genre":"horror","durationSeconds":4755,"summaryTr":"Genç bir subay, kıyıda karşılaştığı gizemli kadının izini eski bir şatoya kadar sürer. Şatonun sakladığı sırları keşfederken resmî hitapları, sorgulamaları ve gotik korku dilini dinle.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Çoğunlukla anlaşılır ve görece yavaş diyaloglar vardır; dönem dili, unvanlar ve sırlarla ilgili kelimeler ek destek gerektirir.","advisoryTr":"Ölüm, boğulma, şiddet ve doğaüstü korku sahneleri içerir.","videoUrl":"https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e7/The_Terror_%281963%29.webm/The_Terror_%281963%29.webm.480p.vp9.webm","qualities":[{"label":"232p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e7/The_Terror_%281963%29.webm/The_Terror_%281963%29.webm.240p.vp9.webm","sizeMB":160},{"label":"464p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/e/e7/The_Terror_%281963%29.webm/The_Terror_%281963%29.webm.480p.vp9.webm","sizeMB":421}],"source":{"name":"Wikimedia Commons — The Terror","url":"https://commons.wikimedia.org/wiki/File:The_Terror_(1963).webm","watchUrl":"https://commons.wikimedia.org/wiki/File:The_Terror_(1963).webm","license":"Kamu malı (ABD)","licenseUrl":"https://commons.wikimedia.org/wiki/File:The_Terror_(1963).webm","credit":"Roger Corman · Özgün film; Wikimedia Commons aktarımı","creditNoteTr":"Video, kaynak sürümüyle ve jeneriğiyle birlikte değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText%3AThe%20Terror%20(1963).webm.en.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar altyazı sayfasının geçmişinde)","changeNoteTr":"Sözler ve zamanlar korunmuştur; biçim etiketleri kaldırılıp satırlar birleştirilerek zamanlar saniyeye dönüştürülmüştür."},"glossary":{"cemetery":"mezarlık","shelter":"sığınak; sığınmak","cellar":"mahzen","flesh":"et; vücudun yumuşak dokusu","regiment":"askerî alay","baron":"baron; soyluluk unvanı","baroness":"barones","crypt":"yeraltı mezar odası","portrait":"portre","duvalier":"Duvalier (karakterin soyadı)","helene":"Helene (karakter adı)"},"captions":[{"start":304.387,"end":305.387,"text":"Hello!"},{"start":308.224,"end":309.224,"text":"Hello?"},{"start":309.424,"end":312.227,"text":"Do you know the road to Colbin?"},{"start":312.437,"end":317.858,"text":"I was separated from my regiment at Arshstadt."},{"start":318.067,"end":322.446,"text":"Do you have any drinking water?"},{"start":323.448,"end":325.824,"text":"I'm very thirsty!"},{"start":363.571,"end":364.654,"text":"Clear water from the mountain."},{"start":381.089,"end":383.423,"text":"Thank you, I-"},{"start":400.858,"end":401.858,"text":"Hello."},{"start":401.943,"end":404.027,"text":"I'd like a word with you."},{"start":404.237,"end":405.278,"text":"You never said goodbye to me."},{"start":405.488,"end":407.739,"text":"In fact, you never even said hello."},{"start":413.413,"end":417.416,"text":"It isn't an act of treason to talk to me."},{"start":417.625,"end":419.793,"text":"I'm a weary, disillusioned soldier."},{"start":420.002,"end":421.92,"text":"And you're the only pleasant sight"},{"start":422.13,"end":423.964,"text":"that I've seen in seven months."},{"start":425.007,"end":426.007,"text":"Go ahead."},{"start":426.207,"end":428.385,"text":"It's permitted for you to laugh."},{"start":429.637,"end":430.637,"text":"Wait."},{"start":430.837,"end":431.837,"text":"You haven't told me your name."},{"start":432.037,"end":432.556,"text":"My name's Helene."},{"start":432.932,"end":435.35,"text":"I want to show you something."},{"start":477.351,"end":478.351,"text":"Wait!"},{"start":478.436,"end":480.312,"text":"Where are you going?"},{"start":483.816,"end":484.816,"text":"What's wrong?"},{"start":578.703,"end":580.245,"text":"Rest yourself, young man."},{"start":580.454,"end":582.539,"text":"You're safe here."},{"start":582.748,"end":585.333,"text":"Here, take this for your strength."},{"start":588.671,"end":591.131,"text":"God knows help is a very rare thing in this forest."},{"start":591.34,"end":592.632,"text":"Take it whenever it's offered to you."},{"start":609.442,"end":611.484,"text":"That bird."},{"start":611.694,"end":613.57,"text":"He attacked me."},{"start":613.779,"end":615.405,"text":"I'm afraid you're wrong."},{"start":615.615,"end":616.615,"text":"She's quite harmless."},{"start":625.666,"end":626.75,"text":"Here, hold out your arm."},{"start":629.712,"end":631.671,"text":"She only seems dangerous."},{"start":631.881,"end":633.84,"text":"Actually, she's very affectionate,"},{"start":634.05,"end":637.26,"text":"which is very unusual for a bird."},{"start":637.47,"end":638.72,"text":"Take it back."},{"start":638.929,"end":641.348,"text":"Oh, that is too bad."},{"start":641.557,"end":643.85,"text":"Little girl liked him, didn't you?"},{"start":646.771,"end":647.771,"text":"This is Gustav."},{"start":650.191,"end":651.691,"text":"He brought you here."},{"start":651.901,"end":653.985,"text":"Gustav fed your horse."},{"start":654.195,"end":656.529,"text":"Where is Helene?"},{"start":656.739,"end":657.781,"text":"This is Helene."},{"start":657.99,"end":659.866,"text":"No, not the bird, the girl."},{"start":660.076,"end":661.076,"text":"Where is the girl?"},{"start":661.276,"end":663.161,"text":"There is no girl."},{"start":663.371,"end":664.621,"text":"Of course there's a girl."},{"start":664.83,"end":665.83,"text":"I saw her."},{"start":666.03,"end":667.03,"text":"She spoke to me."},{"start":669.585,"end":672.045,"text":"Perhaps you were tired from your long journey,"},{"start":672.254,"end":674.089,"text":"and had a pleasant illusion."},{"start":676.717,"end":682.389,"text":"Gustav, have you ever seen a girl here?"},{"start":682.598,"end":685.85,"text":"Gustav sometimes imagines things."},{"start":686.06,"end":688.645,"text":"If he could speak, I think we would"},{"start":688.854,"end":692.107,"text":"find that his mind is warped."},{"start":692.316,"end":697.654,"text":"Such is the will of God, to endow and deprive."},{"start":700.991,"end":705.787,"text":"The only thing of beauty you'll find in this forest is Helene."},{"start":815.856,"end":816.856,"text":"Hello."},{"start":820.82,"end":822.07,"text":"I was afraid you'd drowned."},{"start":838.754,"end":841.714,"text":"So you are real."},{"start":841.924,"end":844.008,"text":"I started to think-"},{"start":849.431,"end":852.684,"text":"Who are you?"},{"start":910.034,"end":912.911,"text":"Wait, wait, danger."},{"start":924.924,"end":930.887,"text":"Quick sand — the girl was trying to kill me."},{"start":931.096,"end":932.263,"text":"She knows not what she does."},{"start":932.473,"end":934.599,"text":"Her will is not her own."},{"start":934.808,"end":936.643,"text":"You mean she's insane?"},{"start":936.852,"end":939.437,"text":"Possessed, she needs your help."},{"start":939.647,"end":941.272,"text":"Help?"},{"start":941.482,"end":943.024,"text":"How can I help her?"},{"start":943.233,"end":947.278,"text":"The castle of the Baron von Leppe, you will find her there."},{"start":947.488,"end":948.488,"text":"I can say no more."},{"start":948.614,"end":949.906,"text":"There's great danger."},{"start":950.115,"end":951.908,"text":"Find Eric, Eric knows."},{"start":969.551,"end":972.679,"text":"The Ride to Colbin is long and far safer by day."},{"start":972.888,"end":976.975,"text":"If you leave now, you can rejoin your regiment by dusk."},{"start":977.184,"end":979.727,"text":"Where is Gustav?"},{"start":979.937,"end":981.854,"text":"What do you want him for?"},{"start":982.064,"end":984.357,"text":"I want him to show me where the castle of the Baron von Leppe"},{"start":984.566,"end":985.9,"text":"is."},{"start":986.11,"end":987.735,"text":"No one's lived in the castle for years."},{"start":987.945,"end":992.448,"text":"And, besides, Gustav has gone away for a few days."},{"start":992.658,"end":996.953,"text":"Perhaps you'd show me the way to the castle."},{"start":997.162,"end":999.205,"text":"Why are you so interested in the Baron?"},{"start":999.415,"end":1001.457,"text":"I never said that I was."},{"start":1001.667,"end":1005.044,"text":"But the girl that I followed last night and spoke to,"},{"start":1005.254,"end":1007.672,"text":"I believe that she lives there."},{"start":1007.881,"end":1011.342,"text":"I told you, there is no girl."},{"start":1011.552,"end":1013.511,"text":"That is nonsense."},{"start":1013.721,"end":1015.096,"text":"You recognize her, don't you?"},{"start":1018.35,"end":1019.35,"text":"No."},{"start":1029.194,"end":1031.154,"text":"I'll find the castle myself."},{"start":1031.363,"end":1032.363,"text":"No!"},{"start":1040.456,"end":1042.29,"text":"Don't go to the castle."},{"start":1042.499,"end":1044,"text":"I have told you the truth."},{"start":1044.209,"end":1045.209,"text":"There is no girl."},{"start":1045.409,"end":1046.409,"text":"Mark me, you are getting yourself"},{"start":1046.462,"end":1048.212,"text":"into things beyond your understanding."},{"start":1048.422,"end":1050.798,"text":"Leave now, while you can."},{"start":1051.008,"end":1053.301,"text":"I intend to find her."},{"start":1053.51,"end":1056.012,"text":"Please don't tell the Baron that I am here."},{"start":1168.25,"end":1171.085,"text":"Hello!"},{"start":1171.295,"end":1172.795,"text":"Is anyone here?"},{"start":1177.217,"end":1179.177,"text":"Hello, it's me, Andre."},{"start":1198.405,"end":1201.657,"text":"In the name of the government of France,"},{"start":1201.867,"end":1203.701,"text":"I order you to open this door!"},{"start":1207.206,"end":1209.999,"text":"Your pardon, young sir, I was at my devotions."},{"start":1210.209,"end":1211.5,"text":"I did not hear you."},{"start":1211.71,"end":1212.919,"text":"I'm sorry, sir."},{"start":1213.128,"end":1217.256,"text":"But surely I made enough noise to awaken the dead."},{"start":1217.466,"end":1218.925,"text":"The government of France."},{"start":1219.134,"end":1224.096,"text":"I've seen the uniforms of many governments in my time."},{"start":1224.306,"end":1226.974,"text":"What would a soldier of France be wanting here?"},{"start":1227.184,"end":1228.643,"text":"Shelter, for one thing."},{"start":1228.852,"end":1233.856,"text":"Permit me to introduce myself, Lieutenant Andre Duvalier."},{"start":1234.066,"end":1237.151,"text":"Baron Victor Frederick von Lepp."},{"start":1237.361,"end":1240.154,"text":"I suggest you will find better shelter at the village inn."},{"start":1240.364,"end":1241.364,"text":"Thank you, Baron."},{"start":1241.49,"end":1243.658,"text":"But I've had my fill of village inns."},{"start":1243.867,"end":1246.41,"text":"Surely, you wouldn't want to inconvenience a French officer."},{"start":1248.705,"end":1249.705,"text":"Come in."},{"start":1257.339,"end":1264.553,"text":"What you see, Lieutenant, are the remains of a noble house-"},{"start":1264.763,"end":1270.351,"text":"relics, ghosts of past glories."},{"start":1270.56,"end":1273.562,"text":"A noble heritage is something to be proud of, Baron."},{"start":1273.772,"end":1276.148,"text":"I'm afraid we've forgotten that in France."},{"start":1276.358,"end":1280.194,"text":"Ah yes, your name, Duvalier, your family-"},{"start":1280.404,"end":1283.364,"text":"My father was the Count Duvalier — was,"},{"start":1283.573,"end":1285.95,"text":"until they spilled his head into a basket one morning"},{"start":1286.159,"end":1287.41,"text":"in the Place de la Concorde."},{"start":1287.619,"end":1290.997,"text":"Forgive me for reviving painful memories."},{"start":1291.206,"end":1294.166,"text":"You must be cold and tired, Lieutenant."},{"start":1294.376,"end":1295.418,"text":"Some cognac?"},{"start":1295.627,"end":1297.378,"text":"I'd like that, Baron, thank you."},{"start":1297.587,"end":1298.921,"text":"Sit down."},{"start":1304.3029999999999,"end":1305.3029999999999,"text":"Yes, Baron?"},{"start":1305.345,"end":1308.723,"text":"Cognac, for our guest."},{"start":1308.932,"end":1311.142,"text":"Yes, Baron."},{"start":1311.351,"end":1313.227,"text":"Baron, I wonder if I might ask, who"},{"start":1313.437,"end":1315.021,"text":"was the young woman I saw in the window"},{"start":1315.23,"end":1317.565,"text":"before you came to the door?"},{"start":1317.774,"end":1319.817,"text":"Young woman?"},{"start":1320.027,"end":1322.278,"text":"Oh, I'm afraid you're mistaken."},{"start":1322.487,"end":1324.155,"text":"No, I'm not mistaken."},{"start":1324.364,"end":1329.076,"text":"I saw her, dark hair and eyes, about 20."},{"start":1329.286,"end":1333.331,"text":"Well, I'm quite sure you think you saw someone."},{"start":1333.54,"end":1334.54,"text":"But-"},{"start":1334.74,"end":1337.585,"text":"Baron, I am in full possession of my faculties."},{"start":1337.794,"end":1341.213,"text":"Please, allow me to show you something."},{"start":1349.598,"end":1351.265,"text":"You should never believe everything"},{"start":1351.475,"end":1354.393,"text":"your eyes tell you, young man."},{"start":1354.603,"end":1358.147,"text":"Is that the girl you think you saw?"},{"start":1358.357,"end":1359.357,"text":"Yes, of course-"},{"start":1359.557,"end":1363.069,"text":"Before you say anything, examine the portrait closely,"},{"start":1363.278,"end":1366.238,"text":"the signature — and above all, the date."},{"start":1371.244,"end":1375.039,"text":"1786?"},{"start":1375.248,"end":1376.916,"text":"But that's 20 years ago."},{"start":1377.125,"end":1378.125,"text":"It's incredible."},{"start":1378.325,"end":1379.325,"text":"It's the same girl."},{"start":1379.525,"end":1381.128,"text":"And she hasn't changed a bit."},{"start":1381.338,"end":1383.422,"text":"She has been dead for 20 years."},{"start":1387.511,"end":1389.345,"text":"With all respect, Baron, for a ghost,"},{"start":1389.554,"end":1393.265,"text":"she's very active young woman."},{"start":1393.475,"end":1396.644,"text":"You're speaking of the Baroness von Lepp, my wife."},{"start":1396.853,"end":1399.397,"text":"I beg your pardon, Baron, I meant no offense."},{"start":1399.606,"end":1402.691,"text":"Perhaps the resemblance was not quite as much as I had thought."},{"start":1402.901,"end":1403.901,"text":"The girl at the window-"},{"start":1403.944,"end":1408.155,"text":"Lieutenant Duvalier, the only occupants of this castle"},{"start":1408.365,"end":1411.45,"text":"are Stefan and myself."},{"start":1411.66,"end":1415.329,"text":"You are the first visitor since the turn of the century."},{"start":1415.539,"end":1416.539,"text":"Of course, Baron."},{"start":1416.54,"end":1418.666,"text":"Stefan will see you to your room."},{"start":1418.875,"end":1419.875,"text":"Thank you."},{"start":1487.527,"end":1489.987,"text":"Hello down there!"},{"start":1490.1970000000001,"end":1491.28,"text":"I'm coming down!"},{"start":1491.49,"end":1492.49,"text":"Wait for me!"},{"start":1547.337,"end":1549.463,"text":"Alright, unlock this door."},{"start":1549.673,"end":1551.465,"text":"Do you hear me?"},{"start":1551.675,"end":1555.01,"text":"Unlock this door or I'm going to shoot through the door!"},{"start":1752.125,"end":1753.125,"text":"Ah!"},{"start":1806.679,"end":1807.93,"text":"I kept in the shadows, sir."},{"start":1808.139,"end":1809.139,"text":"He did not see me."},{"start":1809.14,"end":1810.724,"text":"He's a strange one, though."},{"start":1810.934,"end":1812.768,"text":"He showed no fear."},{"start":1812.977,"end":1813.977,"text":"He must leave at once."},{"start":1814.187,"end":1816.48,"text":"Do you think, perhaps, he is not merely a traveler?"},{"start":1816.689,"end":1817.773,"text":"Why do you say that?"},{"start":1817.982,"end":1819.817,"text":"He might have heard things in the village."},{"start":1820.026,"end":1821.193,"text":"Oh, nonsense, he's a soldier."},{"start":1821.402,"end":1823.695,"text":"He doesn't listen to old wives' tales."},{"start":1823.905,"end":1828.826,"text":"The important thing is that he leave with all due speed."},{"start":1829.035,"end":1830.494,"text":"I shall see to it, sir."},{"start":1830.703,"end":1831.87,"text":"But of his own accord."},{"start":1832.08,"end":1833.872,"text":"We must show him the respect that his position"},{"start":1834.082,"end":1835.874,"text":"and rank demand."},{"start":1836.084,"end":1837.793,"text":"How quickly."},{"start":1838.002,"end":1839.002,"text":"I understand, sir."},{"start":1866.281,"end":1869.7,"text":"So, must you intrude on the dead as well as the living?"},{"start":1869.909,"end":1871.66,"text":"If I intrude, Stefan, I shall leave it"},{"start":1871.87,"end":1873.328,"text":"to my host to so inform me."},{"start":1873.538,"end":1874.872,"text":"Why have you come to Castle von Leppe?"},{"start":1875.081,"end":1876.957,"text":"What do you want here?"},{"start":1877.166,"end":1879.084,"text":"You seem to have things strangely confused"},{"start":1879.294,"end":1880.294,"text":"in your mind."},{"start":1880.503,"end":1883.505,"text":"You're the servant, not I. I'll ask the questions."},{"start":1893.224,"end":1894.892,"text":"This was once a place of worship."},{"start":1895.101,"end":1897.269,"text":"Why have the holy objects been removed?"},{"start":1897.478,"end":1902.316,"text":"The baron ordered it when his wife passed away."},{"start":1902.525,"end":1903.65,"text":"Then this became her tomb?"},{"start":1903.86,"end":1905.694,"text":"No, just the entrance to it."},{"start":1905.904,"end":1908.28,"text":"The von Leppe family crypt lies below, beneath the cemetery."},{"start":1908.489,"end":1910.49,"text":"She rests there with four centuries of von Leppes."},{"start":1913.161,"end":1916.288,"text":"That's been sealed for 20 years."},{"start":1916.497,"end":1918.04,"text":"Nonsense."},{"start":1918.249,"end":1919.541,"text":"It must have been open last night."},{"start":1919.751,"end":1921.96,"text":"The girl must have passed through here."},{"start":1922.17,"end":1923.837,"text":"As the Baron told you, sir, there is no girl."},{"start":1924.047,"end":1925.589,"text":"No girl."},{"start":1925.798,"end":1927.007,"text":"Well, we shall see."},{"start":1927.216,"end":1928.342,"text":"Come with me to the stable, Stefan."},{"start":1928.551,"end":1929.885,"text":"I wish to attend to my horse."},{"start":1930.094,"end":1931.72,"text":"Wait, Lieutenant."},{"start":1931.93,"end":1933.43,"text":"That's what I came to tell you."},{"start":1933.64,"end":1934.89,"text":"Your horse is gone."},{"start":1935.099,"end":1936.683,"text":"Apparently, it bolted during the night."},{"start":1936.893,"end":1938.06,"text":"Impossible, you're lying."},{"start":1938.269,"end":1939.269,"text":"Why?"},{"start":1939.469,"end":1941.146,"text":"No, sir, I'm not lying."},{"start":1941.356,"end":1942.856,"text":"Hear me well, Stefan."},{"start":1943.066,"end":1946.818,"text":"I'm sick of all of these lies- first the old woman, then"},{"start":1947.028,"end":1948.028,"text":"the baron, and now you."},{"start":1948.154,"end":1949.154,"text":"The old woman, you mean-"},{"start":1949.28,"end":1950.28,"text":"Never mind."},{"start":1950.406,"end":1951.907,"text":"What about my horse?"},{"start":1952.116,"end":1954.409,"text":"I shall get you another one from the village at once, sir."},{"start":1954.619,"end":1956.078,"text":"Believe me, lieutenant, I have no desire"},{"start":1956.287,"end":1958.205,"text":"to interfere with your departure from this castle."},{"start":1958.414,"end":1960.916,"text":"You seem very anxious to be rid of me."},{"start":1961.125,"end":1964.086,"text":"Is it because you're afraid I might find out about Eric?"},{"start":1967.215,"end":1969.883,"text":"Eric?"},{"start":1970.093,"end":1971.802,"text":"So there is an Eric?"},{"start":1972.011,"end":1974.012,"text":"That at least was not a lie."},{"start":1974.222,"end":1976.765,"text":"Lieutenant, please, don't involve yourself"},{"start":1976.975,"end":1978.6,"text":"in these dead matters."},{"start":1978.81,"end":1981.937,"text":"There is nothing here but an old man and his decaying memories."},{"start":1982.146,"end":1983.981,"text":"I beg of you, leave him in peace!"},{"start":1992.615,"end":1994.032,"text":"Will you join me, lieutenant?"},{"start":1994.242,"end":1995.742,"text":"No thank you, Baron."},{"start":1995.952,"end":1997.452,"text":"I've just come from the stables."},{"start":1997.662,"end":1998.704,"text":"My horse is gone."},{"start":1998.913,"end":2001.039,"text":"Your horse is gone?"},{"start":2001.249,"end":2002.916,"text":"Yes, I believe it was stolen, Baron."},{"start":2003.126,"end":2005.711,"text":"Oh, impossible."},{"start":2005.92,"end":2009.089,"text":"The stable door perhaps was left open and the animal bolted-"},{"start":2009.298,"end":2011.008,"text":"not an unusual thing."},{"start":2011.217,"end":2014.011,"text":"In itself, no, but there are certain other mysteries"},{"start":2014.22,"end":2015.512,"text":"I would like to have explained, Baron."},{"start":2015.722,"end":2017.806,"text":"And I mean to have them explained."},{"start":2018.016,"end":2020.1,"text":"How dare you take that tone with me."},{"start":2020.309,"end":2021.393,"text":"I don't know to be abrupt."},{"start":2021.602,"end":2022.602,"text":"But I will have answers."},{"start":2026.024,"end":2028.108,"text":"Well-"},{"start":2028.317,"end":2032.07,"text":"Now, why did you the portrait of the Baroness from the wall?"},{"start":2032.28,"end":2034.573,"text":"I sent it away for renovation."},{"start":2034.782,"end":2036.616,"text":"The, the dampness of these walls"},{"start":2036.826,"end":2038.201,"text":"puts a mold on the pigment."},{"start":2038.411,"end":2040.162,"text":"You evade very cleverly, Baron."},{"start":2040.371,"end":2042.998,"text":"Can you also explain the violin music and the girl"},{"start":2043.207,"end":2044.583,"text":"in the chapel last night?"},{"start":2044.792,"end":2045.792,"text":"You saw her again?"},{"start":2045.992,"end":2046.992,"text":"So you admit there's a girl?"},{"start":2047.086,"end":2048.086,"text":"Ilsa."},{"start":2048.286,"end":2049.286,"text":"Ilsa, is that her name?"},{"start":2049.486,"end":2050.172,"text":"Answer me, Baron."},{"start":2050.298,"end":2051.423,"text":"Please, please, leave me in peace."},{"start":2051.632,"end":2054.509,"text":"If I leave you now, Baron, I will come back"},{"start":2054.719,"end":2055.719,"text":"with a company of my men."},{"start":2055.803,"end":2057.888,"text":"And I will tear this place down around your ears"},{"start":2058.097,"end":2059.097,"text":"until I find her."},{"start":2059.297,"end":2060.297,"text":"Is that clear?"},{"start":2062.435,"end":2063.435,"text":"Very clear."},{"start":2063.644,"end":2065.353,"text":"All right, now what happened to the Baroness?"},{"start":2065.563,"end":2066.855,"text":"Was her death violent?"},{"start":2067.065,"end":2068.607,"text":"Yes, her death was violent."},{"start":2068.816,"end":2070.692,"text":"How did she die?"},{"start":2070.902,"end":2074.029,"text":"Can you spare me nothing?"},{"start":2074.238,"end":2077.866,"text":"20 years ago, I was not the man you're looking at now."},{"start":2078.076,"end":2080.368,"text":"This land, this estate prospered."},{"start":2080.578,"end":2082.996,"text":"My people live well and were happy."},{"start":2083.206,"end":2085.04,"text":"My wife had died some years before."},{"start":2085.249,"end":2086.666,"text":"And I was lonely."},{"start":2086.876,"end":2089.044,"text":"Then one day in the village, I saw"},{"start":2089.253,"end":2092.631,"text":"Ilsa, a peasant girl who'd come to live there with her mother."},{"start":2092.84,"end":2096.093,"text":"Oh, I could have taken her as nobles"},{"start":2096.302,"end":2098.136,"text":"have taken the daughters of peasants"},{"start":2098.346,"end":2100.097,"text":"since the beginning of time."},{"start":2100.306,"end":2103.058,"text":"But I loved her."},{"start":2103.267,"end":2107.479,"text":"And she became the Baroness von Leppe."},{"start":2107.688,"end":2110.023,"text":"Almost immediately afterwards, I was called away"},{"start":2110.233,"end":2112.067,"text":"for military service, a rebellion"},{"start":2112.276,"end":2114.653,"text":"in the Polish province."},{"start":2114.862,"end":2116.196,"text":"I was gone for nearly a year."},{"start":2116.405,"end":2121.201,"text":"When the fighting was over, I hurried home to my bride."},{"start":2123.663,"end":2126.123,"text":"No one knew of my coming."},{"start":2126.332,"end":2127.666,"text":"I surprised her in her room."},{"start":2127.875,"end":2129.835,"text":"She was not alone."},{"start":2130.044,"end":2134.422,"text":"She laughed at me, said her bed was not for me to find another."},{"start":2134.632,"end":2139.136,"text":"And with my own hands, I killed her."},{"start":2139.345,"end":2142.013,"text":"And her lover?"},{"start":2142.223,"end":2146.56,"text":"Stefan took care of him."},{"start":2146.769,"end":2150.856,"text":"Later, I gave out a story that she had died of some malaise."},{"start":2151.065,"end":2156.236,"text":"No one ever knew of her betrayal of me, or how, in fact, she did"},{"start":2156.445,"end":2158.029,"text":"die."},{"start":2158.239,"end":2160.574,"text":"Except for Stefan."},{"start":2160.783,"end":2163.368,"text":"For 20 years, I've not set foot beyond the walls"},{"start":2163.578,"end":2165.829,"text":"of this castle."},{"start":2166.038,"end":2170.834,"text":"I've lived here alone with the memory of that dreadful thing"},{"start":2171.043,"end":2174.254,"text":"I did that night."},{"start":2174.463,"end":2176.923,"text":"That is my penance."},{"start":2177.133,"end":2178.633,"text":"And now you believe what?"},{"start":2178.843,"end":2181.052,"text":"That the ghost of Ilsa has come back to relieve you"},{"start":2181.262,"end":2183.054,"text":"of your penance, is that it?"},{"start":2183.264,"end":2184.306,"text":"Yes."},{"start":2184.515,"end":2187.142,"text":"How long has the spirit been coming to the castle?"},{"start":2187.351,"end":2191.271,"text":"It, it all began two years ago."},{"start":2191.48,"end":2192.647,"text":"At first, I was terrified."},{"start":2192.857,"end":2197.569,"text":"But now I — I'm eager for our every meeting."},{"start":2197.778,"end":2199.821,"text":"One more question, Baron."},{"start":2200.031,"end":2203.742,"text":"Has anyone else except yourself seen this spirit, Stefan,"},{"start":2203.951,"end":2204.951,"text":"for instance?"},{"start":2209.207,"end":2212.667,"text":"You think I'm mad, don't you?"},{"start":2212.877,"end":2216.171,"text":"Right now, Baron, I'm not sure just what I think."},{"start":2216.38,"end":2218.506,"text":"Ah, but don't forget."},{"start":2218.716,"end":2221.885,"text":"You saw her too."},{"start":2222.094,"end":2223.345,"text":"Perhaps we are both mad."},{"start":2250.831,"end":2256.294,"text":"Ilsa, Ilsa."},{"start":2256.504,"end":2257.837,"text":"Ilsa?"},{"start":2258.047,"end":2261.758,"text":"The name sounds strange to me here by the sea."},{"start":2261.968,"end":2263.051,"text":"It your name."},{"start":2263.261,"end":2265.845,"text":"Don't you remember?"},{"start":2266.055,"end":2268.014,"text":"My name is Helene."},{"start":2268.224,"end":2269.516,"text":"The old woman told me."},{"start":2269.725,"end":2271.685,"text":"She lies."},{"start":2271.894,"end":2274.729,"text":"She summoned me from the sea."},{"start":2274.939,"end":2276.481,"text":"You must go back."},{"start":2276.691,"end":2278.858,"text":"Your soul is troubled, Ilsa."},{"start":2279.068,"end":2280.068,"text":"Go back?"},{"start":2280.111,"end":2281.444,"text":"To Eric?"},{"start":2281.654,"end":2285.24,"text":"To the sea."},{"start":2285.449,"end":2287.909,"text":"Only when the sea enters the crypt."},{"start":2291.038,"end":2295.333,"text":"We shall rest there together, he and I, beneath the sea."},{"start":2295.543,"end":2296.626,"text":"It is an evil thing."},{"start":2296.836,"end":2299.212,"text":"You must not do it, Ilsa."},{"start":2299.422,"end":2301.423,"text":"I must obey the old woman."},{"start":2309.39,"end":2313.435,"text":"The Frenchman, he can help you, Ilsa."},{"start":2313.644,"end":2314.644,"text":"Andre?"},{"start":2329.327,"end":2330.618,"text":"The old one calls."},{"start":2333.831,"end":2338.376,"text":"She warned you, Gustav, do not interfere."},{"start":2338.586,"end":2342.088,"text":"She's been patient with you long enough, but no more."},{"start":2400.981,"end":2404.442,"text":"Oh, powers of darkness, let the spirit of Ilsa"},{"start":2404.652,"end":2409.364,"text":"sink deeper, deeper into this mortal fog."},{"start":2409.573,"end":2416.413,"text":"Helene, be as though you never were."},{"start":2416.622,"end":2421.084,"text":"Spirit of Ilsa, see through these eyes."},{"start":2421.293,"end":2422.794,"text":"Speak through these lips."},{"start":2423.003,"end":2424.796,"text":"Do my bidding."},{"start":2425.005,"end":2430.76,"text":"For only then, shall you find release from your torment."},{"start":2437.476,"end":2442.313,"text":"You are becoming stronger now, quite strong."},{"start":2442.523,"end":2446.276,"text":"Soon you shall have the strength to carry out"},{"start":2446.485,"end":2450.28,"text":"my vengeance, vengeance."},{"start":2450.489,"end":2453.241,"text":"And the dark powers will set you free."},{"start":2453.451,"end":2457.245,"text":"For I have promised them a richer prize."},{"start":2477.641,"end":2478.725,"text":"Good afternoon."},{"start":2478.934,"end":2480.56,"text":"Who are you?"},{"start":2480.769,"end":2481.811,"text":"An appropriate question, but I'm"},{"start":2482.021,"end":2484.022,"text":"afraid I'm the one who should be doing the asking."},{"start":2484.231,"end":2485.356,"text":"I'm invited in, of course."},{"start":2488.068,"end":2489.36,"text":"What do you want of me?"},{"start":2489.57,"end":2491.905,"text":"You realize that this is the property of the Baron Victor"},{"start":2492.114,"end":2493.114,"text":"von Leppe?"},{"start":2493.314,"end":2494.866,"text":"And that it is forbidden for any of the villagers"},{"start":2495.075,"end":2498.244,"text":"to set foot here, much less make it their home."},{"start":2498.454,"end":2499.537,"text":"How long have you been living here?"},{"start":2499.747,"end":2502.707,"text":"Only two months."},{"start":2502.917,"end":2504.417,"text":"Perhaps I should tell you, you see,"},{"start":2504.627,"end":2505.877,"text":"I've just come from Kleinschmidt,"},{"start":2506.086,"end":2507.462,"text":"where you are not totally unknown."},{"start":2509.757,"end":2512.842,"text":"You have lived here slightly more than two years."},{"start":2513.052,"end":2514.052,"text":"Your name is Katherina."},{"start":2514.252,"end":2515.252,"text":"And you originally come from Colbin,"},{"start":2515.452,"end":2516.387,"text":"where you were quite unpopular because"},{"start":2516.597,"end":2520.183,"text":"of, uh, certain activities."},{"start":2520.392,"end":2523.269,"text":"They call you Katherina the Heretic, the Witch."},{"start":2523.479,"end":2525.855,"text":"They were fools."},{"start":2526.065,"end":2527.065,"text":"Why do you live here?"},{"start":2527.265,"end":2528.525,"text":"What do you want?"},{"start":2528.734,"end":2530.36,"text":"I haven't any money."},{"start":2530.569,"end":2533.613,"text":"This was the only place that wasn't burned to the ground."},{"start":2533.822,"end":2536.991,"text":"So I, I brought my things in here."},{"start":2537.201,"end":2539.452,"text":"Where did you find the girl?"},{"start":2539.662,"end":2542.789,"text":"There's no girl."},{"start":2542.998,"end":2544.499,"text":"I saw her."},{"start":2544.708,"end":2547.293,"text":"She was sitting in this chair."},{"start":2547.503,"end":2549.295,"text":"There is no girl!"},{"start":2549.505,"end":2551.422,"text":"I know what she is."},{"start":2551.632,"end":2555.301,"text":"Old woman, I know what she is!"},{"start":2555.511,"end":2557.387,"text":"Listen to me, and listen to me very carefully."},{"start":2557.596,"end":2559.055,"text":"I don't know what you want, nor do I fully"},{"start":2559.265,"end":2561.057,"text":"understand your black abilities."},{"start":2561.267,"end":2563.434,"text":"But if the two of you have not returned to Colbin within one"},{"start":2563.644,"end":2567.605,"text":"night, I shall come back and kill you with my own hands,"},{"start":2567.815,"end":2571.609,"text":"and burn this place to the ground once and for all."},{"start":2571.819,"end":2575.029,"text":"Then you know who once lived here all those years ago?"},{"start":2577.741,"end":2580.66,"text":"You know who lived here?"},{"start":2593.132,"end":2594.132,"text":"Is the Frenchman gone?"},{"start":2594.216,"end":2595.216,"text":"No."},{"start":2595.416,"end":2596.416,"text":"Why not?"},{"start":2596.616,"end":2597.176,"text":"He now refuses to leave."},{"start":2597.386,"end":2599.137,"text":"I don't think he will leave of his own accord."},{"start":2599.346,"end":2600.43,"text":"He must."},{"start":2600.639,"end":2602.307,"text":"I gave you definite orders."},{"start":2602.516,"end":2604.976,"text":"Baron, no one knows this officer is here."},{"start":2605.185,"end":2607.186,"text":"If he should never arrive in Copeland-"},{"start":2607.396,"end":2609.063,"text":"Are you suggesting that-"},{"start":2609.273,"end":2610.94,"text":"It's the only way."},{"start":2611.15,"end":2613.484,"text":"That I will never."},{"start":2613.694,"end":2616.154,"text":"God knows I have enough upon my conscience"},{"start":2616.363,"end":2619.616,"text":"without the senseless murder of a young man who"},{"start":2619.825,"end":2620.825,"text":"never harmed me."},{"start":2620.826,"end":2622.493,"text":"How do you know what harm he plans?"},{"start":2622.703,"end":2624.37,"text":"You want him wandering around the castle?"},{"start":2624.58,"end":2625.913,"text":"Do you want him down in the crypt?"},{"start":2626.123,"end":2629.25,"text":"Enough, the crypt is no concern of yours."},{"start":2791.83,"end":2792.83,"text":"Andre?"},{"start":2795.876,"end":2797.293,"text":"Andre?"},{"start":2797.503,"end":2799.837,"text":"Help me."},{"start":2804.176,"end":2806.01,"text":"Come to me."},{"start":2806.22,"end":2809.514,"text":"Come to me, Andre."},{"start":2809.723,"end":2811.724,"text":"I need you."},{"start":2811.934,"end":2814.727,"text":"Where are you?"},{"start":2919.207,"end":2922.793,"text":"What is the meaning of this intrusion?"},{"start":2923.003,"end":2924.003,"text":"I'm sorry, Baron."},{"start":2924.171,"end":2925.963,"text":"I thought I heard voices."},{"start":2926.173,"end":2929.967,"text":"Does that give you the right to burst into my room unannounced?"},{"start":2930.177,"end":2931.928,"text":"I beg your pardon, Baron."},{"start":2932.137,"end":2935.89,"text":"Stefan has gone to the village to get you another horse."},{"start":2936.099,"end":2938.392,"text":"It will save us both embarrassment if you will"},{"start":2938.602,"end":2940.478,"text":"leave the moment he returns."},{"start":2940.687,"end":2942.188,"text":"There can be no doubt of it, sir."},{"start":2953.158,"end":2955.952,"text":"Ilsa?"},{"start":2956.161,"end":2958.245,"text":"You're doing the best thing, Lieutenant."},{"start":2958.455,"end":2959.914,"text":"The Baron often does things which"},{"start":2960.123,"end":2962.166,"text":"may seem strange to you and me."},{"start":2962.376,"end":2964.794,"text":"But the death of the Baroness was a severe shock to him,"},{"start":2965.003,"end":2967.129,"text":"one from which I fear he has never fully recovered."},{"start":2967.339,"end":2968.839,"text":"I understand completely, Stefan."},{"start":2977.766,"end":2980.601,"text":"Tell me something, Stefan."},{"start":2980.811,"end":2982.603,"text":"If I can."},{"start":2982.813,"end":2983.813,"text":"Who is Eric?"},{"start":2987.067,"end":2989.402,"text":"You recall the Baron spoke of returning from the war"},{"start":2989.611,"end":2991.404,"text":"and finding the Baroness with another?"},{"start":2991.613,"end":2992.613,"text":"Yes."},{"start":2992.813,"end":2994.073,"text":"Eric was that other."},{"start":3075.28,"end":3076.781,"text":"Wait!"},{"start":3163.285,"end":3165.536,"text":"Gustav?"},{"start":3165.745,"end":3168.164,"text":"She has seen you."},{"start":3168.373,"end":3171.125,"text":"She loves you."},{"start":3171.334,"end":3173.21,"text":"You must help her."},{"start":3177.257,"end":3185.257,"text":"Tonight, her soul cries out for release."},{"start":3185.682,"end":3189.101,"text":"Go back."},{"start":3248.036,"end":3250.287,"text":"I've waited for you so long."},{"start":3250.497,"end":3253.916,"text":"I've been searching for you to help you,"},{"start":3254.125,"end":3260.381,"text":"but you wander in strange places at strange hours."},{"start":3260.59,"end":3263.384,"text":"You're really here."},{"start":3263.593,"end":3264.593,"text":"Of course I'm here."},{"start":3264.594,"end":3268.305,"text":"And I'll never leave you again."},{"start":3268.515,"end":3269.515,"text":"Never?"},{"start":3273.895,"end":3277.356,"text":"When the night comes, I get cold."},{"start":3280.193,"end":3283.696,"text":"My arms and my shoulders get cold."},{"start":3283.905,"end":3287.283,"text":"I don't like the night."},{"start":3287.492,"end":3290.619,"text":"I want to be free of it."},{"start":3290.829,"end":3292.246,"text":"You are free."},{"start":3292.455,"end":3297.543,"text":"Only in here, in this holy place."},{"start":3297.752,"end":3300.17,"text":"No, everywhere with me."},{"start":3300.38,"end":3302.715,"text":"You must come away with me now."},{"start":3302.924,"end":3307.97,"text":"No, I can't, not until-"},{"start":3308.179,"end":3310.973,"text":"Until what?"},{"start":3311.182,"end":3313.309,"text":"The crypt."},{"start":3313.518,"end":3318.772,"text":"It must be destroyed, and with it the dead."},{"start":3318.982,"end":3320.399,"text":"Don't speak of the dead anymore."},{"start":3320.608,"end":3324.236,"text":"You're with me now."},{"start":3324.446,"end":3326.363,"text":"I am possessed of the dead."},{"start":3326.573,"end":3327.614,"text":"You're a warm, living woman."},{"start":3327.824,"end":3329.867,"text":"Who has told you these things?"},{"start":3330.076,"end":3331.076,"text":"The dead."},{"start":3331.077,"end":3333.829,"text":"In Paris, they're doing wonderful things"},{"start":3334.039,"end":3337.458,"text":"to discover the nature of the mind."},{"start":3337.667,"end":3338.667,"text":"I'll take you there."},{"start":3338.877,"end":3341.295,"text":"There are doctors who can free you from this-"},{"start":3341.504,"end":3342.504,"text":"From the dead?"},{"start":3342.505,"end":3347.468,"text":"The dead cannot reach out from the grave."},{"start":3347.677,"end":3350.471,"text":"You must come away with me now."},{"start":3350.68,"end":3352.097,"text":"No."},{"start":3352.307,"end":3354.099,"text":"I'm afraid."},{"start":3354.309,"end":3356.06,"text":"The night."},{"start":3356.269,"end":3358.145,"text":"There's nothing to be afraid of."},{"start":3370.45,"end":3371.95,"text":"You see?"},{"start":3372.16,"end":3376.33,"text":"Love me and there is no fear."},{"start":3376.539,"end":3381.001,"text":"Yes, I do love you."},{"start":3384.422,"end":3386.006,"text":"Then come away with me."},{"start":3400.605,"end":3403.857,"text":"Wait here."},{"start":3404.067,"end":3405.567,"text":"It's all right."},{"start":3567.313,"end":3573.527,"text":"Ilsa, my love, you are not alone."},{"start":3573.736,"end":3576.488,"text":"I am here with you now."},{"start":3576.698,"end":3580.826,"text":"Soon, I will join you in eternal sleep."},{"start":3581.035,"end":3587.249,"text":"Stefan will flood the crypt and seal us here together"},{"start":3587.458,"end":3588.667,"text":"with our love."},{"start":3593.339,"end":3595.549,"text":"Ilsa?"},{"start":3595.758,"end":3596.758,"text":"Ilsa?"},{"start":3599.679,"end":3602.139,"text":"Ilsa?"},{"start":3602.348,"end":3604.6,"text":"Why do you not talk to me?"},{"start":3607.645,"end":3610.105,"text":"I am here."},{"start":3610.315,"end":3613.483,"text":"I've been waiting for you."},{"start":3613.693,"end":3616.153,"text":"My love, my love."},{"start":3621.2,"end":3623.577,"text":"You know what you must do."},{"start":3623.786,"end":3625.537,"text":"No, anything I will do."},{"start":3625.747,"end":3627.08,"text":"But that, I dare not."},{"start":3627.29,"end":3629.207,"text":"Do not ask me, I beg of you."},{"start":3629.417,"end":3633.378,"text":"You must, or we can never be together."},{"start":3633.588,"end":3634.588,"text":"No, no, I cannot."},{"start":3634.589,"end":3637.466,"text":"I dare not."},{"start":3637.675,"end":3638.925,"text":"Look at me, Victor."},{"start":3649.395,"end":3651.647,"text":"Why do you torment me so?"},{"start":3651.856,"end":3653.649,"text":"You must do it, Victor."},{"start":3653.858,"end":3659.696,"text":"Only then can we be together — only then, Victor."},{"start":3659.906,"end":3661.615,"text":"I cannot."},{"start":3661.824,"end":3663.7,"text":"I dare not."},{"start":3663.91,"end":3667.788,"text":"My soul will be damned to eternal perdition."},{"start":3667.997,"end":3669.748,"text":"Let me see who you really are!"},{"start":3672.71,"end":3673.71,"text":"No!"},{"start":3673.795,"end":3674.795,"text":"No, go back!"},{"start":3674.796,"end":3675.796,"text":"You must not!"},{"start":3675.996,"end":3676.996,"text":"No!"},{"start":3677.131,"end":3679.716,"text":"Let me go!"},{"start":3679.926,"end":3682.427,"text":"What kind of a woman are you?"},{"start":3685.056,"end":3686.306,"text":"Where you are you?"},{"start":3694.482,"end":3695.816,"text":"Who are you?"},{"start":3700.238,"end":3701.238,"text":"Helene?"},{"start":3717.588,"end":3719.256,"text":"Is there a doctor in the village?"},{"start":3719.465,"end":3721.717,"text":"his illness is not of the flesh."},{"start":3721.926,"end":3722.926,"text":"I have seen this before."},{"start":3722.927,"end":3725.595,"text":"In a day or two, his mind will return."},{"start":3725.805,"end":3727.723,"text":"We can only wait."},{"start":3727.932,"end":3729.307,"text":"The Baron tells me you've been with him"},{"start":3729.517,"end":3732.686,"text":"since the Polish campaign."},{"start":3732.895,"end":3735.063,"text":"That is true,"},{"start":3735.273,"end":3737.858,"text":"Then you must have been in this castle for 20 years."},{"start":3738.067,"end":3741.153,"text":"You must know every section of the estate."},{"start":3741.362,"end":3743.822,"text":"He's regaining consciousness."},{"start":3744.031,"end":3747.951,"text":"No, he often moans during these seizures."},{"start":3748.161,"end":3749.786,"text":"You have keys."},{"start":3749.996,"end":3752.289,"text":"Fetch them, I'd like to see the chapel."},{"start":3752.498,"end":3754.166,"text":"The chapel?"},{"start":3754.375,"end":3755.667,"text":"Yes, if you don't mind."},{"start":3794.832,"end":3796.541,"text":"The hinges have rusted solid."},{"start":3796.751,"end":3798.668,"text":"Do you have a crowbar?"},{"start":3798.878,"end":3799.878,"text":"Yes, come with me."},{"start":3812.308,"end":3813.308,"text":"What is it?"},{"start":3813.476,"end":3816.228,"text":"That light there, that's the Baroness's bedroom"},{"start":3816.437,"end":3817.687,"text":"in the tower."},{"start":3817.897,"end":3819.689,"text":"The room has been sealed ever since that night."},{"start":3819.899,"end":3822.359,"text":"Not even the Baron would enter."},{"start":3822.568,"end":3823.568,"text":"Come with me."},{"start":3847.218,"end":3848.969,"text":"Where's the key?"},{"start":3849.178,"end":3852.472,"text":"Only the Baron has the key to this lock."},{"start":3852.682,"end":3853.723,"text":"Lieutenant, don't!"},{"start":3865.111,"end":3867.946,"text":"If the Baron should find out we've entered this room-"},{"start":3879.125,"end":3880.792,"text":"Did the Baroness have a child?"},{"start":3881.002,"end":3882.002,"text":"I don't know."},{"start":3882.128,"end":3883.211,"text":"I never though she did."},{"start":3883.421,"end":3885.171,"text":"You spare me nothing."},{"start":3888.134,"end":3890.468,"text":"Baron, if you'll permit me, I think that I can explain."},{"start":3891.053,"end":3892.053,"text":"Forgive me, Baron."},{"start":3892.263,"end":3893.263,"text":"Stefan!"},{"start":3895.182,"end":3897.517,"text":"Take this gun."},{"start":3897.727,"end":3900.02,"text":"Escort this gentleman from the castle."},{"start":3903.983,"end":3907.569,"text":"If he resists, kill him."},{"start":3907.778,"end":3909.613,"text":"Yes, Baron."},{"start":3909.822,"end":3910.822,"text":"Lieutenant."},{"start":3928.049,"end":3931.927,"text":"My love, my love."},{"start":3932.136,"end":3933.345,"text":"I am here, Victor."},{"start":3939.393,"end":3942.228,"text":"I'm weary, Ilsa."},{"start":3942.438,"end":3946.024,"text":"My soul cries out for relief."},{"start":3946.233,"end":3949.861,"text":"There is but one way, Victor."},{"start":3950.071,"end":3955.617,"text":"No, the holy covenants of God forbid it."},{"start":3955.826,"end":3957.953,"text":"You will be forgiven."},{"start":3958.162,"end":3959.829,"text":"If I could be sure."},{"start":3960.039,"end":3963.333,"text":"Take your life as you took mine."},{"start":3963.542,"end":3969.923,"text":"Let your own hand destroy you and bring us together forever."},{"start":3970.132,"end":3972.467,"text":"Forever."},{"start":3972.677,"end":3975.303,"text":"No more torment, Victor, forever."},{"start":3977.89,"end":3978.89,"text":"Forever."},{"start":3981.477,"end":3983.269,"text":"I will, Ilsa."},{"start":3983.479,"end":3986.773,"text":"I will."},{"start":3986.983,"end":3989.859,"text":"I promise you, Lieutenant, if you return to von Leppe castle,"},{"start":3990.069,"end":3992.07,"text":"I shall not hesitate to kill you."},{"start":4030.943,"end":4031.943,"text":"Where is she?"},{"start":4032.143,"end":4033.403,"text":"Let me be."},{"start":4033.612,"end":4036.99,"text":"Why did you lie to me about the girl?"},{"start":4041.078,"end":4043.204,"text":"Call it off."},{"start":4048.669,"end":4051.046,"text":"It doesn't matter now."},{"start":4051.255,"end":4052.839,"text":"You're too late."},{"start":4053.049,"end":4054.591,"text":"Tonight, he damns himself."},{"start":4054.8,"end":4058.762,"text":"Yes, even now she taunts him to his own eternal doom."},{"start":4058.971,"end":4062.057,"text":"You control the girl, just as you control that bird."},{"start":4062.266,"end":4063.308,"text":"How?"},{"start":4063.517,"end":4065.143,"text":"Mesmerism?"},{"start":4065.352,"end":4066.644,"text":"Mesmerism, you fool."},{"start":4066.854,"end":4067.937,"text":"Why?"},{"start":4068.147,"end":4071.149,"text":"Answer me, old woman, or I'll break your neck."},{"start":4071.358,"end":4074.36,"text":"To avenge myself on the Baron von Leppe."},{"start":4074.57,"end":4080.158,"text":"She will drive him to God's one unpardonable sin, suicide."},{"start":4080.367,"end":4081.367,"text":"For what offense?"},{"start":4081.41,"end":4083.119,"text":"What has the Baron done to you?"},{"start":4086.123,"end":4089.542,"text":"He killed my son, Eric."},{"start":4089.752,"end":4091.002,"text":"Eric was your son?"},{"start":4091.212,"end":4093.129,"text":"Yes."},{"start":4093.339,"end":4095.632,"text":"And tonight, the Baron pays for Eric's life"},{"start":4095.841,"end":4099.177,"text":"with his own immortal soul!"},{"start":4099.386,"end":4103.014,"text":"She spoke of destroying the crypt."},{"start":4103.224,"end":4105.85,"text":"Too late, too late."},{"start":4132.878,"end":4135.13,"text":"Baron!"},{"start":4135.339,"end":4137.465,"text":"Baron, you mustn't go — ah!"},{"start":4157.57,"end":4158.57,"text":"Baron!"},{"start":4179.216,"end":4180.216,"text":"Where's the Baron?"},{"start":4180.301,"end":4181.301,"text":"We must get to him."},{"start":4181.501,"end":4182.677,"text":"He's locked himself in the crypt."},{"start":4182.887,"end":4184.679,"text":"Eric is avenged."},{"start":4184.889,"end":4186.264,"text":"Eric avenged?"},{"start":4186.473,"end":4190.226,"text":"She's used the girl as a puppet to drive the Baron to suicide."},{"start":4190.811,"end":4192.645,"text":"She thinks it was the Baron that killed her son."},{"start":4192.855,"end":4194.23,"text":"She never knew it was you."},{"start":4194.44,"end":4195.44,"text":"What do you mean?"},{"start":4195.64,"end":4197.192,"text":"He killed my Eric!"},{"start":4197.401,"end":4199.194,"text":"Eric is her son?"},{"start":4199.403,"end":4200.528,"text":"You murdered!"},{"start":4200.738,"end":4202.53,"text":"No, wait!"},{"start":4202.74,"end":4205.116,"text":"Don't you see now it was all a lie?"},{"start":4205.326,"end":4208.119,"text":"The Baron did return that night to find Eric with the Baroness."},{"start":4208.329,"end":4209.329,"text":"And he did kill her."},{"start":4209.529,"end":4210.529,"text":"But there was a struggle."},{"start":4210.729,"end":4213.166,"text":"And in the fight, it was not Eric who died, but the Baron!"},{"start":4213.375,"end":4215.126,"text":"I killed the Baron."},{"start":4215.336,"end":4217.629,"text":"Then Eric is still alive?"},{"start":4217.838,"end":4218.838,"text":"He took the Baron's place."},{"start":4218.964,"end":4221.09,"text":"And for 20 years, no one has known."},{"start":4221.3,"end":4224.01,"text":"But he took the Baron's place in mind as well as body."},{"start":4224.22,"end":4227.305,"text":"In his mind, he is the Baron von Leppe."},{"start":4227.514,"end":4231.226,"text":"The crypt — she's told him to flood the cellars."},{"start":4231.435,"end":4233.436,"text":"Now they'll both be killed."},{"start":4233.646,"end":4234.979,"text":"Eric!"},{"start":4235.189,"end":4236.856,"text":"Flood the cellars, how?"},{"start":4237.066,"end":4240.193,"text":"There's a tunnel that leads from the sea to the crypt."},{"start":4240.402,"end":4241.402,"text":"Come with me."},{"start":4258.837,"end":4260.213,"text":"He's locked it from the inside."},{"start":4273.936,"end":4274.936,"text":"You keep on here."},{"start":4275.136,"end":4276.646,"text":"I'll try and get in through the chapel."},{"start":4295.874,"end":4297.041,"text":"I may need you."},{"start":4297.251,"end":4298.668,"text":"No, no, not the chapel!"},{"start":4298.877,"end":4300.378,"text":"I may not enter the house of God!"},{"start":4300.587,"end":4302.213,"text":"I have made my pact with another!"},{"start":4302.423,"end":4304.424,"text":"No!"},{"start":4304.624,"end":4305.624,"text":"No closer!"},{"start":4305.824,"end":4307.176,"text":"No!"},{"start":4353.432,"end":4360.646,"text":"I'm here, Ilsa, my love, this time forever."},{"start":4360.856,"end":4363.274,"text":"Now, Victor, now."},{"start":4363.484,"end":4364.734,"text":"I am waiting."},{"start":4372.368,"end":4375.328,"text":"Hurry, Victor, hurry!"},{"start":4393.68,"end":4397.392,"text":"Now, Victor, bring the sea into the crypt"},{"start":4397.601,"end":4399.477,"text":"to mantle us forever."},{"start":4418.872,"end":4422.291,"text":"We will be together again, Victor,"},{"start":4422.501,"end":4425.128,"text":"together with our love here beneath the sea."},{"start":4429.466,"end":4430.967,"text":"Come to me, my love."},{"start":4431.176,"end":4433.302,"text":"Draw the veil."},{"start":4433.512,"end":4435.513,"text":"Look at me."},{"start":4435.722,"end":4441.811,"text":"Come see how eagerly I await your embrace."},{"start":4449.862,"end":4451.696,"text":"What have you done to me?"},{"start":4451.905,"end":4454.949,"text":"I have damned you as you damned me."},{"start":4455.159,"end":4457.618,"text":"The part of me that loved you lies there, Victor,"},{"start":4457.828,"end":4460.204,"text":"rotting in the coffin."},{"start":4460.414,"end":4461.581,"text":"Look at it."},{"start":4461.79,"end":4464.167,"text":"See what your evil love has done to me."},{"start":4464.376,"end":4467.503,"text":"And die with that vision in your brain."},{"start":4467.713,"end":4469.38,"text":"Why have you done this to me?"},{"start":4469.59,"end":4472.3,"text":"I am the spirit of Ilsa that your unholy sin gave over"},{"start":4472.509,"end":4475.011,"text":"to the dark powers."},{"start":4475.22,"end":4477.388,"text":"But now, by giving your immortal soul to them,"},{"start":4477.598,"end":4481.35,"text":"I will be free, Eric."},{"start":4687.182,"end":4688.683,"text":"You're safe now."},{"start":4691.853,"end":4693.854,"text":"It's over."},{"start":4694.064,"end":4695.064,"text":"It's over."},{"start":4695.264,"end":4696.264,"text":"Do you understand?"},{"start":4698.36,"end":4699.61,"text":"You're free now."},{"start":4703.115,"end":4705.324,"text":"Free?"},{"start":4705.534,"end":4706.575,"text":"Andre."}]},{"id":"laboratory-conditions","type":"video","provider":"youtube","youtubeId":"1N25e4Ss34Q","title":"Laboratory Conditions","creator":"Jocelyn Stamat","year":2018,"level":"C1","category":"scifi","genre":"fantasy","durationSeconds":1022,"summaryTr":"Bir doktor, hastanedeki kayıp bir hastanın izini sürerken sıra dışı bir deneyle karşılaşır. Marisa Tomei ve Minnie Driver’ın oynadığı bu filmde bilim, etik ve doğaüstü gerilim birbirine karışır.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Tıbbi ve deneysel kelimeler, etik tartışma, örtük niyetler ve hızlı karşı çıkışlar C1 seviyesinde dinleme gerektirir.","advisoryTr":"Ölüm, tıbbi deneyler, rahatsız edici görüntüler ve küfür içerir.","downloadable":false,"source":{"name":"DUST — Laboratory Conditions","url":"https://www.youtube.com/watch?v=1N25e4Ss34Q","watchUrl":"https://www.youtube.com/watch?v=1N25e4Ss34Q","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"Jocelyn Stamat · Yayıncı: DUST"},"glossary":{"experiment":"deney","consciousness":"bilinç","consent":"rıza; onay","ethical":"etik; ahlaki açıdan uygun","hypothesis":"hipotez; sınanabilir varsayım","patient":"hasta","specimen":"numune; örnek"},"captions":[]},{"id":"rakka","type":"video","provider":"youtube","youtubeId":"VjQ2t_yNHQs","title":"Rakka","creator":"Neill Blomkamp · Oats Studios","year":2017,"level":"C1","category":"scifi","genre":"fantasy","durationSeconds":1313,"summaryTr":"Dünya uzaylıların kontrolüne girmiştir. Bir direniş grubu, insanlığın geleceği için son bir şans arar. Sigourney Weaver’ın da yer aldığı karanlık bir bilim kurgu ve aksiyon filmi.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Yoğun anlatıcı metni, farklı aksanlar, savaş ve işgal dili ile açıkça söylenmeyen neden-sonuç bağlantıları ileri seviye dinleme gerektirir.","advisoryTr":"Yoğun kanlı şiddet, işkence, insan deneyleri ve ağır küfür içerir.","downloadable":false,"source":{"name":"Oats Studios — Rakka","url":"https://www.youtube.com/watch?v=VjQ2t_yNHQs","watchUrl":"https://www.youtube.com/watch?v=VjQ2t_yNHQs","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"Neill Blomkamp · Oats Studios · Yayıncı: Oats Studios"},"glossary":{"occupation":"işgal","insurgency":"silahlı isyan","resistance":"direniş","enslave":"köleleştirmek","surveillance":"gözetim","weapon":"silah","humanity":"insanlık"},"captions":[]},{"id":"six","type":"video","provider":"youtube","youtubeId":"za2fY2ZFelo","title":"Six","creator":"L. Gustavo Cooper","year":2016,"level":"C1","category":"adventure","genre":"fantasy","durationSeconds":672,"summaryTr":"Genç bir vampir, kendisi gibi olanları avlayan gizli bir örgütün eline düşer. Ona sunulan teklif, fantastik korku ile aksiyonu bir araya getirir.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Hızlı sorgulamalar, tehdit, argo, örtük pazarlık ve farklı karakterlerin tonlarını ayırt etme C1 dinleme çalışması sunar.","advisoryTr":"Kan, vampir saldırıları, silahlı şiddet, küfür ve yetişkinlere yönelik temalar içerir.","downloadable":false,"source":{"name":"DUST — Six","url":"https://www.youtube.com/watch?v=za2fY2ZFelo","watchUrl":"https://www.youtube.com/watch?v=za2fY2ZFelo","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"L. Gustavo Cooper · Yayıncı: DUST"},"glossary":{"vampire":"vampir","clandestine":"gizli; örtülü","eliminate":"ortadan kaldırmak","hunt":"avlamak","bargain":"pazarlık","agent":"ajan; görevli","offer":"teklif"},"captions":[]},{"id":"nasa-carbon-cycle","type":"video","title":"The Carbon Cycle: The Living Planet","creator":"NASA · Dr. Lola Fatoyinbo","year":2014,"level":"C1","category":"real","genre":"documentary","durationSeconds":441,"summaryTr":"Bitkiler, okyanuslar ve insan faaliyetleri karbonu nasıl etkiler? Uydu görüntüleri üzerinden karbon döngüsünü anlatan bir bilim konuşması.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Yoğun biyoloji ve çevre kelimeleri, sayıların sözlü anlatımı ve karmaşık süreçlerin açıklanması ileri seviye dinleme gerektirir. 2014 tarihli konuşmada sayılar ve görev planları o dönemi yansıtır.","videoUrl":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Lola.Fatoyinbo.2014_ipod_lg.m4v","qualities":[{"label":"240p","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Lola.Fatoyinbo.2014_ipod_sm.mp4","sizeMB":37},{"label":"360p","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Lola.Fatoyinbo.2014_ipod_lg.m4v","sizeMB":87},{"label":"540p","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Lola.Fatoyinbo.2014_appletv.m4v","sizeMB":211}],"downloadable":false,"source":{"name":"NASA Goddard — The Carbon Cycle: The Living Planet","url":"https://svs.gsfc.nasa.gov/11668/#media_group_344476","watchUrl":"https://svs.gsfc.nasa.gov/11668/#media_group_344476","license":"NASA medya kullanım koşulları · Eğitim amaçlı kullanım","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","credit":"NASA's Goddard Space Flight Center · NASA · Dr. Lola Fatoyinbo","creditNoteTr":"Özgün video ve jenerik değiştirilmeden oynatılır."},"subtitleSource":{"name":"NASA — resmî İngilizce WebVTT altyazısı","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Lola_Fatoyinbo.en_US.vtt","license":"NASA medya kullanım koşulları","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","changeNoteTr":"Sözler ve kaynak zamanları korunmuştur; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür. Kaynak altyazıda yazım veya aktarım hataları bulunabilir."},"glossary":{"biosphere":"biyosfer; canlıların yaşadığı katman","vegetation":"bitki örtüsü","decomposition":"ayrışma; çürüme","productivity":"üretkenlik","carbon":"karbon","emissions":"salım; emisyonlar","depletion":"tükenme; azalım"},"captions":[{"start":0.02,"end":4.05,"text":"[Applause]"},{"start":4.05,"end":8.06,"text":"The most visual"},{"start":8.06,"end":12.11,"text":"manifestation of life on earth happens every year when springtime"},{"start":12.11,"end":16.13,"text":"comes and fresh green leaves and grasses appear all around us."},{"start":16.13,"end":20.2,"text":"The biosphere, our living world is fueled by"},{"start":20.2,"end":24.22,"text":"the seasonal pulse of energy that the change in season brings."},{"start":24.22,"end":28.24,"text":"In this visualization, we can see the seasonal changes"},{"start":28.24,"end":32.33,"text":"to plants on land and in the oceans. Using data"},{"start":32.33,"end":36.45,"text":"like these, we can estimate agricultural yield worldwide,"},{"start":36.45,"end":40.49,"text":"predict famines, fires and algae blooms"},{"start":40.49,"end":44.54,"text":"or help with land management. This global view of our biosphere"},{"start":44.54,"end":48.56,"text":"is also crucial for studying the flow of carbon to the Earth system"},{"start":48.56,"end":52.59,"text":"and predicting the rate and effect of climate change on our home planet."},{"start":52.59,"end":56.64,"text":"In fact, the vegetation on land and in the"},{"start":56.64,"end":60.66,"text":"oceans are crucial component of the global carbon cycle"},{"start":60.66,"end":64.68,"text":"and climate change science. Plants are the real lungs"},{"start":64.68,"end":68.73,"text":"of the Earth, absorbing the carbon dioxide from the atmosphere"},{"start":68.73,"end":72.78999999999999,"text":"and producing the oxygen that we breathe. Here we see what's call net primary"},{"start":72.78999999999999,"end":76.81,"text":"productivity; maps are aware and how much carbon"},{"start":76.81,"end":80.85,"text":"is taken up or released by plants on a monthly basis."},{"start":80.85,"end":84.91,"text":"The colors are on these maps indicate how fast carbon"},{"start":84.91,"end":88.93,"text":"was taken in for every square meter of land and you could see how"},{"start":92.97999999999999,"end":96.99000000000001,"text":"where majority of the land masses lie. Maps such as these,"},{"start":96.99000000000001,"end":101.02000000000001,"text":"allow a scientist to routinely monitor plant's role in the global carbon"},{"start":101.02000000000001,"end":105.05,"text":"cycle and monitor how they're affecting and affected by"},{"start":105.05,"end":109.12,"text":"or changing climate. Carbon is"},{"start":109.12,"end":113.14,"text":"emitted into the atmosphere from natural sources such as forest"},{"start":113.14,"end":117.18,"text":"clearing, decomposition, or volcanic activity."},{"start":117.18,"end":121.2,"text":"90% of the non-natural emissions result"},{"start":121.2,"end":125.23,"text":"from power production, cement production and transportation."},{"start":125.23,"end":129.32,"text":"Over time 50%"},{"start":129.32,"end":133.43,"text":"of that carbon that's emitted stays in the atmosphere while"},{"start":133.43,"end":137.47,"text":"25% gets taken up by trees and plants and the remaining"},{"start":137.47,"end":141.55,"text":"25% is taken up by our oceans."},{"start":141.55,"end":145.57,"text":"And in fact, we can measure the contribution in vegetation growth and"},{"start":145.57,"end":149.57999999999998,"text":"human's emissions on the carbon that is stored in the atmosphere using satellite data."},{"start":149.57999999999998,"end":153.59,"text":"So this visualization is a time series of the global"},{"start":153.59,"end":157.63,"text":"distribution and variation of carbon dioxide in the atmosphere as observed by NASA"},{"start":157.63,"end":161.68,"text":"satellite since the year 2000. For comparison we've overlaid"},{"start":161.68,"end":165.72,"text":"a graph of the seasonal and inter-annual annual changed increase of carbon"},{"start":165.72,"end":169.77,"text":"dioxide that was measured at the Mauna Loa Observatory in Hawaii."},{"start":169.77,"end":173.85,"text":"So these data sets show us that the amount of carbon dioxide stored in"},{"start":173.85,"end":177.88,"text":"the atmosphere is steadily increasing as we continuously pump"},{"start":177.88,"end":181.95,"text":"carbon into the atmosphere and decrease our forested and vegetated"},{"start":181.95,"end":185.95,"text":"areas. And even though we still see that"},{"start":185.95,"end":189.99,"text":"semi annual depth in concentrations with the growth of vegetation in the springtime,"},{"start":189.99,"end":194.03,"text":"the increasing trend of carbon dioxide concentrations"},{"start":194.03,"end":198.06,"text":"is leading to the warming and changing of our planet."},{"start":198.06,"end":202.11,"text":"The seasonal"},{"start":202.11,"end":206.19,"text":"pulse of vegetation growth is crucial for the well-being and balance of life on Earth."},{"start":206.19,"end":210.2,"text":"This visualization of carbon dioxide concentrations in the atmosphere"},{"start":210.2,"end":214.24,"text":"shows how every springtime when forests, grasslands and agricultural"},{"start":214.24,"end":218.3,"text":"lands Green up they suck up the carbon dioxide contained in the atmosphere"},{"start":218.3,"end":222.32,"text":"through photosynthesis, but in the winter months that photosynthetic"},{"start":222.32,"end":226.36,"text":"uptake is not there and the large amounts of carbon dioxide stay in"},{"start":226.36,"end":230.37,"text":"the atmosphere and in fact data from satellite sensors have"},{"start":230.37,"end":234.39,"text":"shown us that during the Northern Hemisphere's growing season,"},{"start":234.39,"end":238.44,"text":"the Midwest region of the United States boasts more photosynthetic activity"},{"start":238.44,"end":242.5,"text":"than anywhere else on Earth. But with"},{"start":242.5,"end":246.53,"text":"changes in the distribution and type of land cover on earth,"},{"start":246.53,"end":250.58,"text":"the natural cycle of growth and carbon dioxide uptake is being"},{"start":250.58,"end":254.65,"text":"disturbed and more and more carbon dioxide is accumulating in the atmosphere."},{"start":258.71,"end":262.73,"text":"Forest fires are one of the leading causes of vegetation change"},{"start":262.73,"end":266.77,"text":"and land use change emissions globally, but the cause of fires"},{"start":266.77,"end":270.8,"text":"can be both natural or human induced. In Africa"},{"start":270.8,"end":274.85,"text":"forest fires are used to clear land for agricultural activity"},{"start":274.85,"end":278.87,"text":"and the amount and timing of fires is clearly linked to the seasonal changes"},{"start":278.87,"end":282.9,"text":"from healthy green vegetation to dry grasses"},{"start":282.9,"end":286.96,"text":"leading to these sweeping waves of fire that move from south to north"},{"start":286.96,"end":290.97,"text":"and north to south each season. As these areas are getting"},{"start":290.97,"end":295,"text":"hotter and drier with climate change, the intensity and amount of fire"},{"start":295,"end":299.04,"text":"increases leading to even more clearing."},{"start":299.04,"end":303.09,"text":"But our satellite sensors don't just show us the health and changes"},{"start":303.09,"end":307.12,"text":"in vegetation on large scales. We can also monitor the human impact"},{"start":307.12,"end":311.15,"text":"on our planet on the scale of the city or our neighborhood."},{"start":311.15,"end":315.19,"text":"So this image series shows of the massive growth spurt of"},{"start":315.19,"end":319.2,"text":"Las Vegas since 1972. Those large red areas are"},{"start":319.2,"end":323.22,"text":"actually green spaces such as city parks or golf"},{"start":323.22,"end":327.26,"text":"courses but now take a look at Lake Mead"},{"start":327.26,"end":331.33,"text":"we can see how with the influx of people into the area, the water"},{"start":331.33,"end":335.36,"text":"table is steadily decreasing."},{"start":335.36,"end":339.43,"text":"These images from Landsat really"},{"start":339.43,"end":343.45,"text":"show us how we humans have changed our planet."},{"start":343.45,"end":347.5,"text":"Here we see the impact of mountaintop removal in West Virginia"},{"start":347.5,"end":351.56,"text":"from 1984 to the present."},{"start":355.6,"end":359.65999999999997,"text":"In Saudi Arabia"},{"start":359.65999999999997,"end":363.67,"text":"we're able to see how irrigation technology has led to agriculture"},{"start":363.67,"end":367.69,"text":"expansion in deserts but also to water table depletion"},{"start":367.69,"end":371.73,"text":"n nearby reservoirs."},{"start":371.73,"end":375.77,"text":"All of these examples are"},{"start":375.77,"end":379.79,"text":"showing how we humans are changing the look of the planet and consequently"},{"start":379.79,"end":383.84,"text":"significantly affecting its vital signs. Our last example"},{"start":383.84,"end":387.88,"text":"shows a recent map of a forest cover loss that is highlighted the extensive changes"},{"start":387.88,"end":391.93,"text":"happening since just the year 2000. These images show"},{"start":391.93,"end":396.04,"text":"forest clearing from wildfires in Colorado from 2000"},{"start":396.04,"end":400.1,"text":"to 2012 fueled by record temperatures and dry conditions."},{"start":400.1,"end":404.21,"text":"In general, wildfires in the Western United States"},{"start":404.21,"end":408.22,"text":"are increasing in frequency and duration due to higher temperatures"},{"start":408.22,"end":412.27,"text":"and longer growing seasons and this has resulted in"},{"start":412.27,"end":416.29,"text":"twice as many acres burnt each year compared to just 40 years ago."},{"start":416.29,"end":420.32,"text":"These seasons are like the heartbeat of the planet,"},{"start":420.32,"end":424.39,"text":"fueling the growth of vegetation worldwide"},{"start":424.39,"end":428.42,"text":"and just as the seasons can affect the health of forested areas,"},{"start":428.42,"end":432.47,"text":"they're also affecting the health of our ice caps and glaciers"},{"start":432.47,"end":436.53,"text":"and on that note I would like to thank you for listening and introduce the next speaker,"},{"start":436.53,"end":440.54,"text":"Dr. Thorsten Markus. [Applause]"},{"start":440.54,"end":440.621,"text":"[Applause]"}]},{"id":"the-gunfighter","type":"video","provider":"youtube","youtubeId":"cWs4WA--eKU","title":"The Gunfighter","creator":"Eric Kissack · Nick Offerman","year":2014,"level":"C1","category":"fun","genre":"comedy","durationSeconds":529,"summaryTr":"Bir silahşör salona girer; hikâyenin anlatıcısı herkesin sırlarını yüksek sesle söylemeye başlar. Karakterlerin anlatıcıyla tartıştığı, western ve kara mizahı birleştiren bir kısa film.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Hızlı atışmalar, argo, dolaylı hakaretler, anlatıcıyla karakterler arasındaki geçişler ve mizahın ima yoluyla kurulması C1 için zorlayıcıdır.","advisoryTr":"Ağır küfür, cinsel göndermeler, silahlı çatışma ve ölüm içerir.","downloadable":false,"source":{"name":"MAGNETFILM — The Gunfighter","url":"https://www.youtube.com/watch?v=cWs4WA--eKU","watchUrl":"https://www.youtube.com/watch?v=cWs4WA--eKU","license":"Yayıncının YouTube oynatıcısı","licenseUrl":"https://www.youtube.com/static?template=terms","credit":"Eric Kissack · Nick Offerman · Yayıncı: MAGNETFILM"},"glossary":{"gunfighter":"silahşör","narrator":"anlatıcı","bounty":"başına konan ödül","saloon":"western filmlerindeki bar","standoff":"tarafların birbirini tehdit ettiği çıkmaz","omniscient":"her şeyi bilen","secret":"sır"},"captions":[]},{"id":"little-shop-of-horrors","type":"video","title":"The Little Shop of Horrors","creator":"Roger Corman","year":1960,"level":"C1","category":"fun","genre":"comedy","durationSeconds":4310,"summaryTr":"Seymour’un çiçekçiye getirdiği sıra dışı bitki, dükkânı bir anda popüler yapar. Bitkinin iştahı büyüdükçe işler kontrolden çıkar. Hızlı atışmaları ve absürt mizahı olan bir korku komedisi.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Hızlı komedi diyalogları, farklı aksanlar, argo ve söylenenle kastedilen arasındaki farklar C1 için iyi bir dinleme çalışması sunar.","advisoryTr":"Cinayet, kan, insan yiyen bitki, kara mizah ve yetişkinlere yönelik göndermeler içerir.","videoUrl":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/The_Little_Shop_of_Horrors_%281960%29_by_Roger_Corman.webm/The_Little_Shop_of_Horrors_%281960%29_by_Roger_Corman.webm.480p.vp9.webm","qualities":[{"label":"240p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/The_Little_Shop_of_Horrors_%281960%29_by_Roger_Corman.webm/The_Little_Shop_of_Horrors_%281960%29_by_Roger_Corman.webm.240p.vp9.webm","sizeMB":142},{"label":"480p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/20/The_Little_Shop_of_Horrors_%281960%29_by_Roger_Corman.webm/The_Little_Shop_of_Horrors_%281960%29_by_Roger_Corman.webm.480p.vp9.webm","sizeMB":381}],"source":{"name":"Wikimedia Commons — The Little Shop of Horrors","url":"https://commons.wikimedia.org/wiki/File:The_Little_Shop_of_Horrors_(1960)_by_Roger_Corman.webm","watchUrl":"https://commons.wikimedia.org/wiki/File:The_Little_Shop_of_Horrors_(1960)_by_Roger_Corman.webm","license":"Kamu malı (ABD)","licenseUrl":"https://commons.wikimedia.org/wiki/File:The_Little_Shop_of_Horrors_(1960)_by_Roger_Corman.webm","credit":"Roger Corman · Özgün film; Wikimedia Commons aktarımı","creditNoteTr":"Video, kaynak sürümüyle ve jeneriğiyle birlikte değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText%3AThe%20Little%20Shop%20of%20Horrors%20(1960)%20by%20Roger%20Corman.webm.en.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar altyazı sayfasının geçmişinde)","changeNoteTr":"Sözler korunmuştur; biçim etiketleri kaldırılıp satırlar birleştirilerek zamanlar saniyeye dönüştürülmüştür. Bir altyazının bitişi, sonraki altyazıyla çakışmaması için 0,001 saniye kısaltılmıştır."},"glossary":{"chamber":"oda; salon","homicide":"cinayet","florist":"çiçekçi","feed":"beslemek","customer":"müşteri","audrey":"Audrey (karakter adı)","seymour":"Seymour (karakter adı)","mushnick":"Mushnick (karakter adı)"},"captions":[{"start":21.079,"end":22.414,"text":"My name is Sergeant Joe Fink..."},{"start":22.616,"end":24.985,"text":"... working a 24 hour shift on a homicide."},{"start":25.491,"end":26.624,"text":"And this is my workshop."},{"start":27.195,"end":30.226,"text":"The part of town that everybody knows about but that nobody wants to see."},{"start":30.741,"end":33.07,"text":"Where the tragedies is a deeper, the ecstasies wilder..."},{"start":33.095,"end":35.679,"text":"... and the crime rate consistently higher than anywhere else"},{"start":36.405,"end":37.405,"text":"Skid Row"},{"start":37.523,"end":38.523,"text":"My beat."},{"start":111.708,"end":114.09,"text":"The most terrifying period in the history of my beat..."},{"start":114.11500000000001,"end":117.22399999999999,"text":"... began in a little rundown floral shop called Mushnick's."},{"start":122.115,"end":124.771,"text":"Ah, good morning Mrs. Shiva, how's things today?"},{"start":124.796,"end":127.404,"text":"The same as usual, Mr. Mushnick."},{"start":127.601,"end":129.858,"text":"My sister's nephew Stanley died."},{"start":129.883,"end":131.257,"text":"In Little Rock, Arkansas."},{"start":131.282,"end":132.726,"text":"Aww. What happened?"},{"start":132.928,"end":134.856,"text":"He got blown up who knows how."},{"start":134.881,"end":135.733,"text":"That's nice."},{"start":135.81,"end":139.14600000000002,"text":"Well, you would like, maybe, as usual some flowers for the funural?"},{"start":139.216,"end":141.552,"text":"♪ Should auld acquaintance be forgot,..."},{"start":141.577,"end":143.732,"text":"♪ ... and never brought to mind?"},{"start":143.757,"end":145.288,"text":"I thought, possibly,..."},{"start":145.47,"end":148.389,"text":"... because I always give you all my funeral business..."},{"start":148.421,"end":151.147,"text":"... and maybe you should possibly give to me, eh..."},{"start":151.36599999999999,"end":152.546,"text":"... a little cut today."},{"start":152.608,"end":154.439,"text":"Look on me, Mrs. Shiva."},{"start":154.483,"end":156.171,"text":"What am I? A philatelist?"},{"start":156.236,"end":159.1,"text":"I sell on Skid Row nothing but cheap carnations."},{"start":159.654,"end":161.185,"text":"And I should give you a cut rate."},{"start":161.21,"end":163.677,"text":"I can't even afford water for the flowers!"},{"start":163.79399999999998,"end":165.77100000000002,"text":"To my throat I would be giving a cut."},{"start":165.959,"end":170.27100000000002,"text":"♪ I dreamt I dwelt in Marble Halls"},{"start":170.381,"end":173.154,"text":"- ♪ With vassals and... - Shut up from the back!"},{"start":175.357,"end":176.888,"text":"Excuse me, Mrs. Shiva."},{"start":176.92000000000002,"end":179.662,"text":"- That Seymour... - He's a nice boy."},{"start":179.743,"end":181.985,"text":"- Why don't you let him sing? - What sing?!"},{"start":182.01,"end":183.977,"text":"Look: Here I got a new customer."},{"start":184.002,"end":185.321,"text":"Brand new in the yellow vest."},{"start":185.346,"end":186.439,"text":"I should let the clean up boy..."},{"start":186.464,"end":189.628,"text":"... but I can't even afford chase them out right away."},{"start":193.915,"end":196.657,"text":"Flowers fresh as the spring time. Mushnick. Hello?"},{"start":196.767,"end":198.142,"text":"Oh, hello Dr. Farb."},{"start":198.251,"end":199.423,"text":"What can I do for you today?"},{"start":199.625,"end":201.446,"text":"Listen, Mushink, I haven't got much time."},{"start":201.477,"end":203.961,"text":"Send me over two gladiolas and a fern."},{"start":204.4,"end":207.023,"text":"Excellent, that's two dozen glads, one pottet fern."},{"start":207.141,"end":209.094,"text":"No, no, no, Mushnick!"},{"start":209.119,"end":211.32999999999998,"text":"Two gladiolas and one fern."},{"start":213.63400000000001,"end":216.251,"text":"You want I should put two gladiolas in the pot with the fern."},{"start":216.53199999999998,"end":218.50900000000001,"text":"No, one fern, one piece."},{"start":218.534,"end":220.564,"text":"Altogether three pieces."},{"start":220.594,"end":221.984,"text":"I need it for my waiting room."},{"start":222.922,"end":224.461,"text":"- A filling fell out. - What?"},{"start":224.486,"end":227.196,"text":"- A filling fell out. - Good, I'll drill a bigger hole."},{"start":227.632,"end":230.265,"text":"You mean you want two crummy gladiolas and one crummy fern?"},{"start":230.29,"end":232.125,"text":"What kind of a decoration is that?"},{"start":232.203,"end":234.335,"text":"This is my flower budget for the week."},{"start":234.459,"end":235.982,"text":"Mushnick."},{"start":236.24,"end":238.186,"text":"Who can be a dentist on Skid Row?"},{"start":238.232,"end":240.654,"text":"Fine, excellent. I'll send Seymour right away."},{"start":240.865,"end":242.63,"text":"Who am I to argue with science?"},{"start":243.146,"end":244.411,"text":"Make it snappy."},{"start":245.302,"end":247.123,"text":"Now you are going to get ..."},{"start":247.209,"end":250.209,"text":"...oh, you are going to get it."},{"start":250.474,"end":251.709,"text":"Look."},{"start":254.888,"end":256.388,"text":"Seymour Krelborn!"},{"start":257.005,"end":259.818,"text":"Now, Mrs. Shiva. We were talking from the funeral flowers."},{"start":259.864,"end":260.731,"text":"But the little..."},{"start":264.013,"end":265.715,"text":"Did you call me, Mr. Mushnick?"},{"start":265.747,"end":270.918,"text":"No. I was calling John D. Rockefeller for to make a loan on my Rolls Royce."},{"start":270.981,"end":272.18399999999997,"text":"Sorry I said it."},{"start":272.286,"end":273.599,"text":"Now look Seymour."},{"start":275.03499999999997,"end":276.84000000000003,"text":"You take two gladiolas."},{"start":276.918,"end":278.528,"text":"You'll cut them nice and even."},{"start":278.558,"end":281.09000000000003,"text":"You'll take one fern. You'll wrap them in a package..."},{"start":281.115,"end":283.058,"text":"... and you'll take them to Dr. Farb."},{"start":283.08299999999997,"end":284.1,"text":"Right?"},{"start":285.058,"end":286.371,"text":"Now go already!"},{"start":287.368,"end":288.837,"text":"Now what can I do for you, sir?"},{"start":288.908,"end":290.204,"text":"Uh, my name is Burson Fouch."},{"start":290.251,"end":292.095,"text":"Excellent! I am Gravis Mushnick."},{"start":292.12,"end":292.954,"text":"Oh, that's a good one."},{"start":293.001,"end":294.806,"text":"Who is gonna get my roses?"},{"start":294.831,"end":296.422,"text":"I'll take care of you, Mrs. Shiva."},{"start":296.447,"end":297.548,"text":"Come right over here."},{"start":298.359,"end":301.609,"text":"You would like, maybe, some orchids for a nice girl?"},{"start":301.61,"end":303.672,"text":"No, I think I'd like a couple of dozen carnations."},{"start":303.907,"end":304.907,"text":"Carnations."},{"start":305.524,"end":308.852,"text":"A person find a lot of these these that somebody shouldn't drop dead!"},{"start":309.093,"end":311.795,"text":"You had more than your share of bad luck, Mrs. Shiva."},{"start":311.896,"end":313.256,"text":"Bad luck, she calls it."},{"start":313.342,"end":315.405,"text":"You should have so many people kicked off."},{"start":317.342,"end":319.104,"text":"About the carnations..."},{"start":319.474,"end":320.81,"text":"You said you wanted some roses."},{"start":320.834,"end":322.725,"text":"Yeah. For Stanley."},{"start":325.967,"end":327.303,"text":"My carnations."},{"start":330.295,"end":332.328,"text":"You should see wha-- See, Morris."},{"start":332.329,"end":333.938,"text":"Oh, here are your carnations."},{"start":334.134,"end":336.954,"text":"- Wait, I'll wrap them for you. - No, it's all right. I'll eat them here."},{"start":341.985,"end":342.774,"text":"Why not?"},{"start":345.977,"end":347.414,"text":"Of course. What else?"},{"start":348.604,"end":349.604,"text":"They are alright?"},{"start":349.629,"end":350.54,"text":"Well, I've had better."},{"start":350.72,"end":352.416,"text":"Well, this is a small shop."},{"start":352.44100000000003,"end":353.439,"text":"That's ok."},{"start":353.634,"end":354.658,"text":"You know: These big places..."},{"start":354.79,"end":356.759,"text":"...they are full of pretty flowers, expensive flowers."},{"start":356.923,"end":359.798,"text":"When you raise them for looks and smell you're bound to lose some food value."},{"start":359.946,"end":361.775,"text":"I like these little out-of-the-way places."},{"start":363.555,"end":365.173,"text":"Such a thing - eating flowers."},{"start":365.599,"end":367.309,"text":"Look: Don't knock it until you try it, huh?"},{"start":369.341,"end":370.341,"text":"Look what happened."},{"start":372.528,"end":375.234,"text":"This is what I was trying to tell you before"},{"start":375.294,"end":376.70799999999997,"text":"Look on him, everybody!"},{"start":376.841,"end":378.911,"text":"Look at the quality of his work!"},{"start":379.034,"end":381.011,"text":"I ask you: When I fire him..."},{"start":381.363,"end":383.348,"text":"... where is he gonna get such another good job?"},{"start":383.738,"end":384.738,"text":"You mean I'm fired?"},{"start":384.762,"end":387.761,"text":"No, I'm electing you president from the United States."},{"start":388.24,"end":389.474,"text":"Yes, you are fired!"},{"start":389.591,"end":392.028,"text":"- Gravis, you can't do that. - Who? Who can't?"},{"start":393.084,"end":395.029,"text":"- I didn't mean it. - You didn't mean it."},{"start":395.091,"end":396.528,"text":"You never mean it."},{"start":396.529,"end":400.255,"text":"You didn't mean it the time you put up the bouquet with the get well card..."},{"start":400.28,"end":401.396,"text":"... in the funeral parlour."},{"start":401.421,"end":403.169,"text":"And send the black lilies..."},{"start":403.194,"end":405.819,"text":"... to the old lady in the hospital, you didn't mean it."},{"start":405.842,"end":406.967,"text":"But this time..."},{"start":406.992,"end":409.929,"text":"... I, Gravis Mushnick, mean it!"},{"start":411.007,"end":412.007,"text":"He means it."},{"start":412.969,"end":416.344,"text":"But see, Mr. Mushnick, don't I always try to do what's right?"},{"start":416.421,"end":417.608,"text":"And i'm crazy about flowers."},{"start":417.633,"end":419.921,"text":"I like flowers almost as much as Audrey does."},{"start":420.178,"end":421.795,"text":"Excellent. You're fired."},{"start":421.849,"end":423.638,"text":"Why don't you give him a chance to resurrect himself?"},{"start":423.663,"end":425.349,"text":"I give him a chance to quit."},{"start":425.374,"end":427.786,"text":"- I ain't gonna quit. - You're a brave boy. You're fired!"},{"start":428.591,"end":430.49,"text":"But that ain't fair, Mr. Mushnick."},{"start":430.661,"end":431.746,"text":"You know what I'm doin'?"},{"start":432.15,"end":435.179,"text":"I'm working on a special surprise plant just for you."},{"start":435.247,"end":437.145,"text":"I'm growing a plant like you ain't never seen before."},{"start":437.17,"end":439.817,"text":"Excellent! I can't even sell the plants I got in my shop."},{"start":439.842,"end":441.567,"text":"- Out, you! - Now, wait a minute."},{"start":442.036,"end":443.755,"text":"If he's got a new kind of plant you'll look at it."},{"start":443.856,"end":446.006,"text":"I don't look on flowers, Mr. Yellowvest."},{"start":446.186,"end":449.326,"text":"I got ancestors in the flower business for 200 years."},{"start":449.351,"end":452.369,"text":"But I got one shop on Skid Row, one stinking shop."},{"start":452.37,"end":454.58,"text":"- I don't even like flowers! - Now, you don't understand what I mean."},{"start":455.276,"end":457.964,"text":"Look: I've been eating in flower shops all over the world."},{"start":458.306,"end":461.524,"text":"And I have noticed that the places that have the mosts weird and unusal plants were the best business."},{"start":461.549,"end":462.228,"text":"See?"},{"start":462.253,"end":463.479,"text":"- See? - See?"},{"start":463.729,"end":465.338,"text":"What is this? A tango?"},{"start":466.197,"end":467.197,"text":"Alright."},{"start":467.931,"end":469.04,"text":"Explain me more."},{"start":469.548,"end":470.548,"text":"Well..."},{"start":470.719,"end":473.376,"text":"I remember one place that had a whole wall covered with poison ivy."},{"start":473.401,"end":475.173,"text":"And people came from miles around to look at the wall."},{"start":475.198,"end":476.259,"text":"And they stayed to buy."},{"start":476.324,"end":477.354,"text":"The owner got rich?"},{"start":477.526,"end":480.135,"text":"No. He scratched himself to death in an insane asylum."},{"start":480.16,"end":481.094,"text":"Oh!"},{"start":481.119,"end":482.789,"text":"That was my cousin Harry."},{"start":483.541,"end":484.541,"text":"Alright."},{"start":485.135,"end":486.135,"text":"Alright."},{"start":486.714,"end":489.979,"text":"You go home and you get this fancy schmancy plant and you bring it back here."},{"start":490.004,"end":493.414,"text":"And if Mr. Yellowvest Fouch says it's a draw, you still got a job."},{"start":493.51,"end":495.989,"text":"If he don't - out you go to Bodeo, right?"},{"start":495.99,"end":497.724,"text":"Dont' worry. You'll like it - you'll see."},{"start":516.428,"end":518.443,"text":"This is Radio KSIK"},{"start":518.7090000000001,"end":521.725,"text":"You've been listening to \"Music for Old Invalids\"."},{"start":521.967,"end":523.811,"text":"Our next selection is entitled..."},{"start":523.9590000000001,"end":525.162,"text":"... \"Sickroom Serenade\""},{"start":526.787,"end":528.295,"text":"Seymour, is that you?"},{"start":528.467,"end":529.647,"text":"Yeah, ma."},{"start":530.006,"end":531.225,"text":"Get in here. Look at my tongue"},{"start":532.865,"end":534.92,"text":"But ma, I've already seen your tongue."},{"start":536.287,"end":538.514,"text":"There be no sympathy for your poor mother?"},{"start":538.568,"end":540.943,"text":"Laughing at her and mocking her illness..."},{"start":540.968,"end":542.974,"text":"... and she's got one foot in the grave."},{"start":543.154,"end":545.294,"text":"- I didn't mean it. - Oh, you never mean it."},{"start":545.319,"end":547.06,"text":"Oh, come on. Look at my tongue."},{"start":547.92,"end":550.397,"text":"That tongue is a tongue, ma. They all look the same to me."},{"start":551.389,"end":554.694,"text":"Did you stop at Dr. Mallard and get the results of my tests?"},{"start":554.943,"end":556.74,"text":"Yeah,he said there's nothing wrong with you."},{"start":556.827,"end":558.256,"text":"Oh, not Dr. Mallard."},{"start":558.281,"end":560.862,"text":"He-He is one doctor I thought would tell the truth."},{"start":560.896,"end":563.014,"text":"He said you sould be playing fullback for the Rams."},{"start":563.068,"end":564.49,"text":"He wants me dead."},{"start":565.099,"end":567.021,"text":"I'll bet he is assistant coroner."},{"start":567.168,"end":569.324,"text":"Well, I gotta... - A-A-And I know I got..."},{"start":569.597,"end":573.378,"text":"My goiter's coming back. I can feel it every morning after breakfast."},{"start":573.445,"end":574.781,"text":"Yeah, that's when you take those great..."},{"start":577.344,"end":579.312,"text":"What you got? A little surprise for me?"},{"start":579.734,"end":581.335,"text":"- Open it up and see. - Alright."},{"start":587.702,"end":590.507,"text":"Dr. Slurpsaddle's famous tonic."},{"start":591.29,"end":592.493,"text":"Wait here."},{"start":594.337,"end":598.267,"text":"To be taken internally or externally for pain and neuritis..."},{"start":598.462,"end":601.032,"text":"... neuralgia, headaches, ..."},{"start":601.447,"end":604.134,"text":"... i-if hit by a truck, call your physician."},{"start":604.669,"end":608.189,"text":"Alcoholic content: 98 percent!"},{"start":610.091,"end":611.56,"text":"Oh, Seymour."},{"start":611.599,"end":614.599,"text":"You'll never know what it is gonna do for me."},{"start":621.332,"end":626.222,"text":"Oh, I can feel that surge of warm health going through me already."},{"start":627.131,"end":630.24,"text":"Look, ma. I gotta get my plant and hurry back to the shop."},{"start":630.381,"end":632.327,"text":"You mean that lousy weed out in the kitchen?"},{"start":632.521,"end":635.092,"text":"Yeah. If Mr. Mushnick doesn't like it, he's gonna fire me."},{"start":637.4,"end":640.4,"text":"Apparently, my hearing is goin' out on me."},{"start":640.963,"end":642.978,"text":"I just had the faint impression..."},{"start":643.064,"end":647.228,"text":"that your job security depends on what Muchnick thanks of that thing."},{"start":647.338,"end":650.056,"text":"It looks worse than it did this morning when I went to work."},{"start":650.189,"end":651.86,"text":"I wish I knew what to do with it."},{"start":652.142,"end":654.759,"text":"Well, if you ask me, I'd pitch it out in the trash."},{"start":654.76,"end":657.369,"text":"I don't like my house cluttered up with rotten vegetables."},{"start":657.394,"end":659.674,"text":"Look ma, I gotta hurry. Can I bring you anything?"},{"start":659.705,"end":662.814,"text":"Oh yeah, yeah. Bring me the Evening News."},{"start":662.954,"end":665.836,"text":"They're running a-a self-diagnosis contest."},{"start":665.861,"end":668.149,"text":"The winner gets to go to to Mayo Clinic."},{"start":668.174,"end":669.835,"text":"- Ha, ha. - Bye, ma."},{"start":669.86,"end":673.219,"text":"Bye, son. I'll see you at the rosy edge of dawn!"},{"start":673.781,"end":677.383,"text":"♪ Drink to me only with thine eyes"},{"start":677.408,"end":679.063,"text":"♪ And I will ..."},{"start":683.908,"end":685.43,"text":"And put this on my bill."},{"start":688.439,"end":689.705,"text":"Here it is everybody."},{"start":690.252,"end":691.666,"text":"What do you think of it?"},{"start":691.691,"end":692.861,"text":"Well..."},{"start":693.165,"end":694.345,"text":"It sure is different."},{"start":694.37,"end":696.531,"text":"It looks delicious but don't you think it's kind of stale?"},{"start":696.556,"end":698.389,"text":"I hasn't been feeling too well."},{"start":698.414,"end":699.744,"text":"You call that a fancy plant?"},{"start":699.79,"end":702.626,"text":"It looks like it never spent an healthy day in its entire life."},{"start":702.743,"end":703.766,"text":"I don't care."},{"start":703.931,"end":705.079,"text":"I like it anyway."},{"start":705.22,"end":707.212,"text":"You, you like even skunk cabbage."},{"start":707.237,"end":708.438,"text":"Yeah."},{"start":708.797,"end":710.624,"text":"What kind of a plant is this, Seymour?"},{"start":710.79,"end":712.055,"text":"Well, I'm not sure."},{"start":712.172,"end":715.16,"text":"I got the seeds from a Japanese gardener over on Central Avenue."},{"start":715.414,"end":718.82,"text":"He found them in with an order he got from a plantation next to a cranberry farm."},{"start":718.845,"end":719.805,"text":"Fine."},{"start":719.882,"end":722.468,"text":"Fine. You don't even know what is this plant you're groing."},{"start":722.703,"end":724.82,"text":"- Well, I gave it a name. - What name?"},{"start":726.249,"end":729.085,"text":"What? You gave it a dirty name you can't even mention it?"},{"start":729.422,"end":730.422,"text":"Well..."},{"start":730.617,"end":731.812,"text":"I named it Audrey Jr."},{"start":732.843,"end":734.757,"text":"You named it after me?"},{"start":734.782,"end":735.819,"text":"Oh, really?"},{"start":736.077,"end":738.78,"text":"That's the most exiting thing anyone's ever done to me."},{"start":738.842,"end":740.088,"text":"You poor kid."},{"start":740.308,"end":741.566,"text":"I don't think it's so much..."},{"start":741.591,"end":745.135,"text":"... I should keep on spending ten dollars a week on your salary."},{"start":745.16,"end":746.011,"text":"But Gravis..."},{"start":746.0360000000001,"end":747.462,"text":"... he named it after me!"},{"start":747.487,"end":749.844,"text":"I know and if they keep it they'll name it Mushnick's Folly..."},{"start":749.869,"end":752.455,"text":"... because I'll be in jail because of non-payment of taxes."},{"start":752.48,"end":753.885,"text":"- Are you crazy? - Who? Who?"},{"start":753.91,"end":754.91,"text":"You. You."},{"start":754.946,"end":757.146,"text":"That's probably the only plant of its kind in the world."},{"start":757.171,"end":759.282,"text":"Don't you realize if Seymour can nurse that thing back to health..."},{"start":759.307,"end":761.212,"text":"... you have people coming here from all over?"},{"start":761.275,"end":763.376,"text":"- You think so, you Fouch? - I know so, you Mushnick?"},{"start":763.55,"end":765.05,"text":"That's all I'm saying on the subject."},{"start":765.3389999999999,"end":767.8,"text":"Sod, I got to get home. My wife's making gardenias for dinner."},{"start":769.855,"end":771.394,"text":"- Good night, sir. - Good night."},{"start":771.55,"end":772.55,"text":"I'll see you tomorrow."},{"start":773.417,"end":774.909,"text":"Crazy about kosher flowers."},{"start":776.245,"end":777.62,"text":"He's a nice man."},{"start":778.222,"end":780.144,"text":"Maybe he knows what he's talking about."},{"start":780.526,"end":781.881,"text":"Maybe it's not so stupid."},{"start":782.886,"end":784.073,"text":"I'll tell you what I'll do."},{"start":784.776,"end":786.955,"text":"I'll keep you and this Dumbell Jr. for a week."},{"start":786.98,"end":789.354,"text":"If you can nurse it back to health, you both can stay."},{"start":789.379,"end":791.3,"text":"If you can't, you're both fired."},{"start":791.325,"end":793.236,"text":"Aw, gee. Thank you, Mr. Mushnick."},{"start":796.856,"end":799.149,"text":"Don't feel sad, Seymour."},{"start":799.681,"end":802.525,"text":"Don't waste your pity on me Audrey, I'm not worth it."},{"start":802.55,"end":804.283,"text":"Who says you're not?"},{"start":804.946,"end":806.055,"text":"Everybody."},{"start":806.08,"end":807.33,"text":"Yeah, I know."},{"start":807.986,"end":810.986,"text":"But I think you're a fine figurative of a man, and..."},{"start":811.533,"end":816.072,"text":"... and I know that Audrey Jr. will be the sweetest thing in the whole, wide world!"},{"start":816.306,"end":817.658,"text":"Well, I don't know."},{"start":817.993,"end":822.259,"text":"I've given it every kind of fancy fertilizer and atomic plant food and..."},{"start":822.284,"end":825.58,"text":"... distilled mineral water that you can buy but I just gets sicker and sicker."},{"start":825.9639999999999,"end":827.097,"text":"Don't worry."},{"start":827.55,"end":830.003,"text":"You're gonna be another Luther Glendale."},{"start":830.065,"end":831.065,"text":"Pasadena."},{"start":831.237,"end":832.237,"text":"Burbank."},{"start":833.346,"end":834.557,"text":"Good night, Seymour."},{"start":834.995,"end":836.369,"text":"G'night, Audrey."},{"start":845.465,"end":847.043,"text":"What's the matter little plant?"},{"start":847.925,"end":850.441,"text":"Haven't I done everything I could for you?"},{"start":850.973,"end":852.433,"text":"Where did I goof?"},{"start":854.277,"end":858.832,"text":"You're the first little plant I ever tried to grow, and if you die, I dunno what I'll do!"},{"start":858.989,"end":860.364,"text":"Please don't die."},{"start":862.528,"end":864.255,"text":"I'll get you some water, ok?"},{"start":882.277,"end":883.613,"text":"Oh, gee."},{"start":883.738,"end":887.235,"text":"You opened up just like you do every night at sunset."},{"start":887.26,"end":889.417,"text":"I wish I knew how to make you grow."},{"start":890.465,"end":892.871,"text":"Here, let me move this out of your way so you can breathe."},{"start":892.972,"end":895.2139999999999,"text":"Ow! Ow, ow, ow, ow!"},{"start":896.98,"end":898.689,"text":"Hey, what happened?"},{"start":898.746,"end":900.15,"text":"How come you woke up?"},{"start":901.644,"end":902.644,"text":"Blood?"},{"start":902.847,"end":904.23,"text":"You like blood?"},{"start":907.187,"end":908.484,"text":"You must be kidding."},{"start":909.468,"end":910.468,"text":"Well, we'll see."},{"start":919.456,"end":920.871,"text":"You know, what I'm doing for you..."},{"start":930.46,"end":932.663,"text":"Aww, who could have thought it?"},{"start":933.757,"end":934.757,"text":"Well..."},{"start":934.782,"end":937.639,"text":"I guess there's just no accounting for people's taste."},{"start":949.023,"end":951.078,"text":"- Seymour! - My boy."},{"start":951.103,"end":954.109,"text":"You're the most magnanimous person in the whole world!"},{"start":954.179,"end":955.914,"text":"Look on him, Audrey. Isn't he beautiful?"},{"start":955.992,"end":957.25,"text":"Isn't he delicious?"},{"start":957.468,"end":959.241,"text":"Isn't he got a two dollar raise?"},{"start":959.32,"end":960.656,"text":"What happened to your fingers?"},{"start":960.681,"end":961.804,"text":"Bee stings."},{"start":961.874,"end":963.983,"text":"So how come I'm all of a sudden so wonderful?"},{"start":964.015,"end":965.858,"text":"Five bees? One for each finger?"},{"start":965.921,"end":967.005,"text":"Ten bees."},{"start":967.03,"end":968.796,"text":"Did you say I was getting a two dollar raise?"},{"start":968.821,"end":970.71,"text":"Correct, my very excellent Seymour."},{"start":970.735,"end":972.826,"text":"- Indeed. - What did I do now?"},{"start":973.1,"end":974.733,"text":"Don't you know what you did?"},{"start":977.725,"end":979.647,"text":"Oh, boy! Look at that!"},{"start":980.279,"end":981.279,"text":"It grew."},{"start":981.304,"end":983.013,"text":"It's almost a foot long."},{"start":983.139,"end":984.498,"text":"Isn't it empirical?"},{"start":984.662,"end":987.201,"text":"It grows like a cold sore from the lips."},{"start":988.553,"end":991.975,"text":"Oh, hello young pretty ladies. What can Gravis Mushnick do for you?"},{"start":992.014,"end":994.185,"text":"Well, we saw your sign outside. About the Audrey Jr."},{"start":994.21,"end":996.159,"text":"So we thought we'd come in and take a look."},{"start":996.184,"end":997.184,"text":"Well, give a look."},{"start":997.2090000000001,"end":1000.095,"text":"That makes four people today who come in just to look at it."},{"start":1000.128,"end":1003.677,"text":"- Oh, dig Shirley. - Is that just too much?"},{"start":1003.702,"end":1005.178,"text":"Oh, what kind of plant is it?"},{"start":1005.203,"end":1006.474,"text":"It's an Audrey Jr."},{"start":1006.499,"end":1008.4639999999999,"text":"How was it you got in trouble with ten bees?!"},{"start":1008.489,"end":1010.609,"text":"Is that all? I mean, doesn't it have a scientific name?"},{"start":1010.634,"end":1011.804,"text":"Yes, of course."},{"start":1011.829,"end":1012.968,"text":"But who could denounce it."},{"start":1012.993,"end":1014.969,"text":"You would like maybe to buy something."},{"start":1014.994,"end":1016.298,"text":"Well, we don't have any money..."},{"start":1016.323,"end":1017.993,"text":"... except 2000 dollars."},{"start":1018.915,"end":1020.595,"text":"But that's just to spend on flowers."},{"start":1020.62,"end":1022.006,"text":"So we don't have any of our own."},{"start":1022.199,"end":1023.199,"text":"Isn't that a drag?"},{"start":1023.224,"end":1025.435,"text":"You got t-t-t-two thousand dollars..."},{"start":1025.46,"end":1027.489,"text":"... just for to spend on flowers?"},{"start":1027.514,"end":1028.777,"text":"- Mhm. - That's right."},{"start":1028.802,"end":1030.646,"text":"Who died? The Chamber of Commerce?"},{"start":1030.671,"end":1032.005,"text":"We're all from Cucamonga high school."},{"start":1032.03,"end":1033.17,"text":"We're building a float."},{"start":1033.201,"end":1035.404,"text":"- For the Rose Bowl parade. - Which is made of flowers."},{"start":1035.429,"end":1037.301,"text":"- Thousands of them. - And we're on the comittee."},{"start":1037.326,"end":1039.817,"text":"- That picks the florist. - And then glues on the flowers."},{"start":1041.591,"end":1044.895,"text":"- Gee, that sure is a mad plant. - Wow, yeah."},{"start":1045.014,"end":1046.49,"text":"Seymour here invented it."},{"start":1046.553,"end":1049.006,"text":"- He didn't! - Oh!"},{"start":1049.115,"end":1051.014,"text":"Girls! Girls, girls, girls!"},{"start":1051.06,"end":1053.794,"text":"Please don't damage the horticulturalist."},{"start":1054.52,"end":1058.645,"text":"Tell me, how come you don't buy all these thousands of flowers from Gravis Mushnick?"},{"start":1058.958,"end":1061.509,"text":"My flowers got something the others don't."},{"start":1061.534,"end":1062.942,"text":"- What's that? - They're cheap."},{"start":1062.967,"end":1063.967,"text":"Well, cheap."},{"start":1064,"end":1066.235,"text":"If your shop is good enough to develop the Audrey Jr..."},{"start":1066.335,"end":1068.57,"text":"- I guess it can get everything we need. - Yeah."},{"start":1068.603,"end":1070.305,"text":"We'll talk it over with the rest of the committee."},{"start":1070.344,"end":1072.133,"text":"- Excellent. - We've got to run now. Bye."},{"start":1072.158,"end":1073.882,"text":"- Bye! - Bye!"},{"start":1074.063,"end":1075.258,"text":"Bye, girls."},{"start":1079.433,"end":1080.433,"text":"A son."},{"start":1081.335,"end":1082.335,"text":"A son."},{"start":1082.36,"end":1083.443,"text":"Look, Audrey!"},{"start":1083.669,"end":1085.404,"text":"I got a son."},{"start":1085.716,"end":1087.333,"text":"Oh, gee, Mr Mushnick."},{"start":1087.358,"end":1088.27,"text":"What, Mr. Mushnick?"},{"start":1088.295,"end":1090.709,"text":"I don't want you should call me Mr. Mushnick anymore."},{"start":1090.734,"end":1092.686,"text":"I want you should call me dad."},{"start":1092.858,"end":1094.296,"text":"Ok, dad."},{"start":1094.592,"end":1096.099,"text":"Isn't that beautiful?"},{"start":1096.124,"end":1097.647,"text":"Seymour Krelborn..."},{"start":1097.733,"end":1099.435,"text":"... come over here, my son."},{"start":1099.749,"end":1101.983,"text":"I want to talk on you about the future."},{"start":1102.35,"end":1104.205,"text":"Look on this fly trap."},{"start":1104.23,"end":1105.23,"text":"Look on it."},{"start":1105.35,"end":1107.715,"text":"Soon we got no more Skid Row."},{"start":1107.865,"end":1110.068,"text":"We will be rich. Us."},{"start":1110.271,"end":1111.896,"text":"I am building for you..."},{"start":1111.97,"end":1115.38,"text":"... a giant greenhouse in which you are making impossible flowers..."},{"start":1115.611,"end":1118.774,"text":"... which in turn I am selling at ridiculous prices..."},{"start":1118.799,"end":1122.338,"text":"... in my giant new flower saloon in Beverly Hills."},{"start":1123.345,"end":1125.821,"text":"Do you see that big sign in the sky?"},{"start":1126.604,"end":1127.76,"text":"It is saying..."},{"start":1128.243,"end":1130.47,"text":"... \"Gravis Mushnick\", in French."},{"start":1130.618,"end":1131.97,"text":"Isn't it exciting?"},{"start":1132.376,"end":1135.415,"text":"And we'll have an orchestra right by the cash register, ..."},{"start":1135.56,"end":1137.412,"text":"... and Gravis will wave his arms..."},{"start":1137.437,"end":1140.482,"text":"... and the orchestra will play Mendelssohn's Spring Song."},{"start":1141.044,"end":1144.473,"text":"I'll come out in a gown, wrapped by someone expensive and say:"},{"start":1144.685,"end":1147.255,"text":"\"The carnations are 600 dollars a dozen,\"..."},{"start":1147.28,"end":1148.52,"text":"... \"two dozen for a thousand.\""},{"start":1148.545,"end":1151.161,"text":"- It's a bargain! - Get 'em while they last"},{"start":1151.186,"end":1152.247,"text":"Stop shouting."},{"start":1152.356,"end":1158.75,"text":"My uncle Moishen's brother Yankel just passed away in New Jersey."},{"start":1159.036,"end":1160.036,"text":"Tell me..."},{"start":1160.207,"end":1162.121,"text":"... how much are the carnations today?"},{"start":1162.146,"end":1164.364,"text":"The carnations are 600 dollars a dozen."},{"start":1164.389,"end":1166.637,"text":"And why are they letting him run around loose?"},{"start":1166.677,"end":1169.168,"text":"Please. Please excuse my son, Mrs. Shiva."},{"start":1169.215,"end":1171.56,"text":"Just point anything in the store and it is yours."},{"start":1171.585,"end":1172.83,"text":"You mean anything?"},{"start":1172.855,"end":1173.855,"text":"That's right."},{"start":1173.88,"end":1175.835,"text":"- The cash register, maybe, huh? - Ah."},{"start":1175.86,"end":1176.997,"text":"Wait a minute."},{"start":1177.022,"end":1178.255,"text":"Here."},{"start":1178.28,"end":1181.325,"text":"Here are several dozen carnations..."},{"start":1181.59,"end":1185.692,"text":"... on the house courtesey of Gravis Mushnick, the bloom tycoon."},{"start":1185.724,"end":1187.808,"text":"- That's my dad. - Thanks."},{"start":1188.45,"end":1189.591,"text":"Thanks very much."},{"start":1190.751,"end":1191.868,"text":"Only, tell me..."},{"start":1192.252,"end":1193.494,"text":"Why are you so happy?"},{"start":1193.65,"end":1197.884,"text":"Not only did my uncle Moishe's brother Yankel die..."},{"start":1198.377,"end":1200.002,"text":"... in New Jersey..."},{"start":1201.515,"end":1204.296,"text":"... we should also give some flowers to that poor dead plant there."},{"start":1205.71,"end":1207.218,"text":"Good morning, Mr. Mushnick."},{"start":1208.271,"end":1209.271,"text":"Good morning."},{"start":1209.851,"end":1210.983,"text":"Good morning, Mrs. Shiva."},{"start":1211.046,"end":1213.062,"text":"Look what happened to my plant, dad."},{"start":1213.087,"end":1214.726,"text":"Who're you calling dad? Who? Who?"},{"start":1214.751,"end":1215.751,"text":"Oh no!"},{"start":1216.147,"end":1218.975,"text":"- It was so beautiful just a few seconds ago. - Excellent."},{"start":1219.021,"end":1222.107,"text":"Just a few seconds ago I gave away dozens of carnations."},{"start":1222.132,"end":1223.482,"text":"Free! To Mrs. Shiva."},{"start":1223.507,"end":1224.514,"text":"I didn't mean it."},{"start":1225.263,"end":1227.693,"text":"You have perhaps an explanation."},{"start":1227.904,"end":1230.319,"text":"No, but if you give me a minute I'll think of one."},{"start":1230.344,"end":1231.771,"text":"I can see it all now."},{"start":1231.951,"end":1233.631,"text":"We're in the poorhouse."},{"start":1233.677,"end":1237.059,"text":"The big sign in the sky it is reading:"},{"start":1237.16,"end":1240.434,"text":"\"Seymour Krelborn. Rest in Peace.\""},{"start":1240.459,"end":1241.661,"text":"In Arabic!"},{"start":1241.7,"end":1243.614,"text":"Oh, you've got to give him another chance."},{"start":1243.849,"end":1245.825,"text":"You promised me a week, Mr. Mushnick."},{"start":1245.982,"end":1247.614,"text":"I'd sit up all night with that plant."},{"start":1247.639,"end":1249.496,"text":"It'll be healthy in the morning, you'll see."},{"start":1249.599,"end":1250.654,"text":"I promise."},{"start":1251.051,"end":1252.231,"text":"I promise."},{"start":1261.507,"end":1264.301,"text":"Feed meeee."},{"start":1268.497,"end":1271.52,"text":"Feed meeee."},{"start":1272.717,"end":1274.491,"text":"Feed meeee!"},{"start":1278.288,"end":1279.381,"text":"Who said that?"},{"start":1279.538,"end":1280.538,"text":"You said that."},{"start":1280.655,"end":1281.881,"text":"You said that!"},{"start":1281.99,"end":1284.661,"text":"Mhm. Feed me!"},{"start":1286.302,"end":1287.443,"text":"You said that."},{"start":1288.334,"end":1289.529,"text":"You can talk."},{"start":1289.967,"end":1291.685,"text":"I got a talking plant."},{"start":1292.389,"end":1293.616,"text":"- Say it again. - Feed me."},{"start":1294.819,"end":1295.944,"text":"Oh boy!"},{"start":1296.538,"end":1298.866,"text":"I've never been to college and I ain't been around much..."},{"start":1299.381,"end":1302.557,"text":"... but I would be willing to bet there ain't no such thing as a talking plant!"},{"start":1303.17,"end":1304.756,"text":"I'll take your word for it."},{"start":1305.366,"end":1307.42,"text":"Gee, Junior, I'd-I'd like to feed you."},{"start":1307.795,"end":1309.366,"text":"But I've used up all my fingers."},{"start":1309.741,"end":1312.092,"text":"Feeeeeeed."},{"start":1314.709,"end":1316.905,"text":"Look at me, I'm all cut to pieces."},{"start":1317.152,"end":1320.206,"text":"But maybe I can find another drop here someplace."},{"start":1326.597,"end":1328.246,"text":"That's the best I can do."},{"start":1328.528,"end":1331.072,"text":"More! More!"},{"start":1331.097,"end":1332.778,"text":"But I'm already anaemic."},{"start":1333.433,"end":1336.23,"text":"Feed me more!"},{"start":1336.512,"end":1337.512,"text":"See, Junior,..."},{"start":1337.551,"end":1339.645,"text":"I'd be happy to give you anything I got..."},{"start":1339.988,"end":1343.3,"text":"... but I gotta keep a little blood for myself or I'll be in worse shape than ma."},{"start":1343.335,"end":1344.553,"text":"Mmm."},{"start":1345.264,"end":1346.694,"text":"I'm sorry, Junior."},{"start":1347.053,"end":1349.412,"text":"I'll go for a walk. Maybe I'll think of something."},{"start":1512.828,"end":1514.828,"text":"Feed me!"},{"start":1515.781,"end":1517.765,"text":"Feed me!"},{"start":1517.859,"end":1519.031,"text":"Look, chow-hound."},{"start":1519.859,"end":1521.961,"text":"Don't bother me. I got problems of my own."},{"start":1522.328,"end":1523.539,"text":"Feed me!"},{"start":1523.999,"end":1526.953,"text":"I am sorry, pal. I am fresh out of blood. Talk to somebody else."},{"start":1526.983,"end":1528.717,"text":"I am hungry!"},{"start":1528.742,"end":1530.327,"text":"I don't care what you are."},{"start":1530.851,"end":1532.234,"text":"Can't you see I am knocked out?"},{"start":1532.351,"end":1533.624,"text":"I just killed a man."},{"start":1534.202,"end":1535.374,"text":"I'm a murderer."},{"start":1535.9279999999999,"end":1537.631,"text":"Think it's fun to be a murderer?"},{"start":1537.671,"end":1538.843,"text":"You think it's fun to..."},{"start":1538.936,"end":1540.358,"text":"...haul around a sack full of..."},{"start":1540.42,"end":1542.3029999999999,"text":"...fooooood."},{"start":1542.49,"end":1545.646,"text":"No, no, Junior! What kind of guy do you think I am?"},{"start":1545.671,"end":1547.662,"text":"I'm starved."},{"start":1551.317,"end":1552.71,"text":"Maybe just a snack."},{"start":1562.185,"end":1563.443,"text":"That looks great."},{"start":1576.495,"end":1577.494,"text":"What you call that salad?"},{"start":1577.519,"end":1578.519,"text":"Nefarious."},{"start":1579.57,"end":1581.117,"text":"Well, before the next course..."},{"start":1581.601,"end":1583.255,"text":"... I think I'll have a nice cigar."},{"start":1583.28,"end":1584.28,"text":"Alright?"},{"start":1584.812,"end":1586.28,"text":"You would like maybe a cigar?"},{"start":1586.395,"end":1587.809,"text":"- Ha-ha-ha. - Ha-ha-ha."},{"start":1587.834,"end":1589.785,"text":"Ah, you don't smoke cigars, right."},{"start":1589.949,"end":1592.207,"text":"What am I thinking about? Where are the matches?"},{"start":1593.286,"end":1594.434,"text":"Oh, oi!"},{"start":1595.285,"end":1596.332,"text":"You know what I found?"},{"start":1597.065,"end":1598.526,"text":"I'm looking for the matches..."},{"start":1599.244,"end":1601.329,"text":"And I found I left the money in the red suit."},{"start":1604.556,"end":1606.392,"text":"Here's your mock chicken leg."},{"start":1606.5720000000001,"end":1607.721,"text":"You don't have any money?"},{"start":1611.579,"end":1613.259,"text":"So what else is new?"},{"start":1613.361,"end":1614.869,"text":"Alright. Alright!"},{"start":1614.894,"end":1616.025,"text":"I made a mistake."},{"start":1616.15,"end":1617.986,"text":"After all, a man is entitled."},{"start":1618.571,"end":1620.282,"text":"Go on. This is your story."},{"start":1620.524,"end":1621.923,"text":"I'll wait for the punch."},{"start":1622.134,"end":1624.454,"text":"Don't get smart with me, girlie."},{"start":1624.578,"end":1627.46,"text":"I'll have you know that in my shop in the cash register..."},{"start":1627.485,"end":1630.079,"text":"... I'm having the total day's receipts..."},{"start":1630.25,"end":1632.868,"text":"... which is summing up to more than nine dollars."},{"start":1633.008,"end":1634.687,"text":"You'll bring the rest of the food..."},{"start":1634.712,"end":1637.031,"text":"... and I'll go the the shop and get the money!"},{"start":1637.585,"end":1640.507,"text":"You are playing my favorite song."},{"start":1641.069,"end":1642.499,"text":"Now, look here, buster."},{"start":1642.733,"end":1645.514,"text":"One of you is gonna go down right now and get the loot..."},{"start":1645.539,"end":1649.226,"text":"... while the other one stays here until the first one gets back."},{"start":1649.531,"end":1651.367,"text":"If you get what I mean?"},{"start":1651.392,"end":1652.421,"text":"Oh, fine."},{"start":1652.446,"end":1656.335,"text":"In this fancy schmancy restaurant you are holding hostages, right?"},{"start":1656.36,"end":1657.36,"text":"Right."},{"start":1658.695,"end":1659.695,"text":"Excellent."},{"start":1660.772,"end":1662.299,"text":"You eat up, Audrey."},{"start":1662.749,"end":1665.288,"text":"I'll be back in a flash with the cash."},{"start":1665.313,"end":1666.313,"text":"Bye, Gravis."},{"start":1683.689,"end":1686.486,"text":"♪ 'tis the season to be jolly"},{"start":1686.869,"end":1689.994,"text":"♪ Fa-la-la-la-la, la-la-la-la-la-la-la."},{"start":1690.763,"end":1694.504,"text":"♪ 'tis the season to be jolly"},{"start":1694.919,"end":1696.529,"text":"♪ Fa-la-la-la"},{"start":1696.99,"end":1699.521,"text":"♪ La-la-la"},{"start":1700.068,"end":1702.295,"text":"♪ 'tis the season"},{"start":1703.31,"end":1705.091,"text":"♪ To be jolly"},{"start":1705.247,"end":1707.868,"text":"♪ Fa-la-la-la"},{"start":1707.935,"end":1709.974,"text":"♪ La-la-la"},{"start":1713.942,"end":1715.294,"text":"You're flush now, right?"},{"start":1716.224,"end":1719.279,"text":"Bring me whiskey, rum, wine, gin, bourbon."},{"start":1719.458,"end":1723.747,"text":"- Why? - Scotch, rye, tequila, sake, manishevitz"},{"start":1723.772,"end":1725.061,"text":"Did you bring the money?"},{"start":1725.086,"end":1728.32,"text":"Don't mock me with the money. I got to get drunk now."},{"start":1728.391,"end":1729.656,"text":"What's with him?"},{"start":1729.681,"end":1730.681,"text":"- I don't know. - Look."},{"start":1730.914,"end":1732.914,"text":"Here, take it. Bring me anything."},{"start":1732.953,"end":1735.326,"text":"Bring everything. Creme de menthe. Everything you've got!"},{"start":1735.351,"end":1736.382,"text":"Ok!"},{"start":1737.742,"end":1738.742,"text":"Gravis?"},{"start":1738.93,"end":1740.563,"text":"- What happened? - Don't ask."},{"start":1740.774,"end":1742.172,"text":"You look like you've seen a ghost."},{"start":1742.227,"end":1744.461,"text":"Ghosts I could handle. Don't ask."},{"start":1744.64,"end":1746.224,"text":"Why don't you tell me? Maybe I could help you."},{"start":1746.249,"end":1747.71,"text":"Help, you couldn't."},{"start":1748.296,"end":1750.647,"text":"Try and eat something. It'll calm your agrimation."},{"start":1753.702,"end":1755.07,"text":"In mine own shop..."},{"start":1755.851,"end":1757.367,"text":"Audrey, you wouldn't believe it."},{"start":1757.889,"end":1759.318,"text":"I wish you'd break out and tell me."},{"start":1759.343,"end":1760.467,"text":"Alright, I'll tell you."},{"start":1760.492,"end":1763.334,"text":"Tomorrow. Right after I am telling the police."},{"start":1766.271,"end":1768.176,"text":"But Mushnick didn't come to the police."},{"start":1768.975,"end":1769.975,"text":"If he had..."},{"start":1770.154,"end":1772.471,"text":"... that might have been the finish of the unhappy story."},{"start":1772.975,"end":1773.975,"text":"It was not."},{"start":1791.418,"end":1792.418,"text":"Hi, Gravis."},{"start":1792.838,"end":1796.316,"text":"85 dollars worth of business already, and we've barely opened!"},{"start":1799.254,"end":1800.254,"text":"What'd I tell you?"},{"start":1800.279,"end":1803.23,"text":"You wouldn't be interested in selling a half-interest to this place, huh?"},{"start":1803.652,"end":1805.574,"text":"- Mr. Mushnick. - We talked to the comittee."},{"start":1805.628,"end":1808.056,"text":"- And they said we could use your flowers. - On the float."},{"start":1808.081,"end":1810.674,"text":"- And guess what? - We're going to feature Audrey Jr."},{"start":1810.699,"end":1813.174,"text":"- Right on top. - Can't you just picture it?"},{"start":1813.199,"end":1815.846,"text":"- I can picture it. - Oh, won't the people just eat it up?"},{"start":1815.871,"end":1817.152,"text":"Eat up the people."},{"start":1817.245,"end":1819.113,"text":"And we're gonna have the big part of it open."},{"start":1819.245,"end":1820.574,"text":"- Of course she can fit in it. - Who?"},{"start":1820.599,"end":1822.832,"text":"- The queen. - With her crown and scepter."},{"start":1823.099,"end":1824.434,"text":"She'll be so cute!"},{"start":1824.459,"end":1827.052,"text":"- Oh, you could just eat her up. - Eat up the girl."},{"start":1827.099,"end":1828.568,"text":"Oh, there's Seymour!"},{"start":1828.638,"end":1830.388,"text":"Oh, Seymour!"},{"start":1830.413,"end":1831.874,"text":"Ow, ow, ow, ow! I got a toothache."},{"start":1831.899,"end":1833.75,"text":"Ow, I got a toothache. Really, I..."},{"start":1834.492,"end":1835.492,"text":"You..."},{"start":1835.531,"end":1837.851,"text":"- Come with me. - I got a toothache! It hurts!"},{"start":1837.876,"end":1839.476,"text":"Ow, let go of my jaw."},{"start":1840.922,"end":1842.187,"text":"Ow, my jaw. Ow, ow."},{"start":1842.398,"end":1843.664,"text":"Owwww."},{"start":1843.758,"end":1844.875,"text":"Now, Seymour."},{"start":1845.068,"end":1846.068,"text":"Talk on me!"},{"start":1846.093,"end":1848.046,"text":"I got a toothache. What do you wanna talk about?"},{"start":1848.071,"end":1850.968,"text":"That plant. Is that a nice subject for to talk?"},{"start":1851.226,"end":1852.617,"text":"The plant is great, it's..."},{"start":1852.642,"end":1854.163,"text":"... it's it's four times bigger than it was yesterday."},{"start":1854.188,"end":1857.257,"text":"I saw, I saw. How come the plant is now so big?"},{"start":1857.687,"end":1858.859,"text":"I don't know."},{"start":1859.639,"end":1861.42,"text":"But look at them people out there."},{"start":1861.553,"end":1864.631,"text":"We only been open a half hour we already done 70 dollars worth of business."},{"start":1864.756,"end":1866.592,"text":"85. Now look, Seymour."},{"start":1867.552,"end":1870.175,"text":"You gave this plant a fancy name: Audrey Jr."},{"start":1870.2,"end":1873.054,"text":"But I want to know right now what do just people call it?"},{"start":1873.371,"end":1874.371,"text":"Well..."},{"start":1874.396,"end":1876.677,"text":"well it's a cross between a butterworth and a venus flytrap."},{"start":1876.702,"end":1878.293,"text":"Venus flytrap!"},{"start":1878.318,"end":1880.81,"text":"And what are the habbits of this Venus flytrap?"},{"start":1881.037,"end":1882.825,"text":"Well, the book says it eats insects."},{"start":1882.85,"end":1884.896,"text":"It eats them three times in it's life..."},{"start":1884.952,"end":1886.842,"text":"- ... and then it's full grown. - Excellent!"},{"start":1886.994,"end":1889.49,"text":"And how many times is this one eat?"},{"start":1889.615,"end":1890.615,"text":"Well..."},{"start":1891.077,"end":1892.209,"text":"Once or twice."},{"start":1892.528,"end":1893.965,"text":"You don't remember?"},{"start":1894.402,"end":1897.082,"text":"Well, this is kind of an unusual type flytrap."},{"start":1897.207,"end":1899.309,"text":"That is a possibility."},{"start":1900.05,"end":1902.76,"text":"It may never eat again. I don't see how it could get any bigger."},{"start":1903.355,"end":1906.324,"text":"Then you think it don't need any more flies?"},{"start":1907.105,"end":1908.105,"text":"Yeah."},{"start":1910.62,"end":1912.714,"text":"Ow, my tooth is just killing me."},{"start":1913.565,"end":1914.565,"text":"Alright. Excellent."},{"start":1915.296,"end":1917.007,"text":"You run along to the dentist."},{"start":1917.397,"end":1918.829,"text":"I'll take care of things here."},{"start":1919.381,"end":1920.381,"text":"Thanks, boss."},{"start":1921.077,"end":1924.085,"text":"Gravis! We got to order more flowers."},{"start":1924.256,"end":1925.545,"text":"Tons of them."},{"start":1931.61,"end":1933.251,"text":"I'm making lots of money."},{"start":1944.733,"end":1946.936,"text":"Argh! Argh! Argh!"},{"start":1947.647,"end":1949.03,"text":"Please don't hurt!"},{"start":1949.155,"end":1950.491,"text":"Please don't hurt me!"},{"start":1950.804,"end":1952.475,"text":"Argh! Argh!"},{"start":1956.444,"end":1958.967,"text":"That'll teach you to keep your bill up to date, you deadbeat!"},{"start":1959.022,"end":1961.296,"text":"Argh! Argh! Argh!"},{"start":1966.386,"end":1967.706,"text":"Well, then run, you snivelling dog!"},{"start":1968.104,"end":1970.386,"text":"I'm glad, I hurt you. I'm glad. I'm glad."},{"start":1970.932,"end":1971.932,"text":"Seymour."},{"start":1972.065,"end":1973.862,"text":"Seymore. Got a bad tooth, huh?"},{"start":1973.887,"end":1975.385,"text":"No, I thought this was the men's room!"},{"start":1975.417,"end":1978.644,"text":"Seymour, come back here, you bad dog. You get in there."},{"start":1980.23,"end":1983.823,"text":"So, you are the young man who ruined my gladiolas, huh?"},{"start":1983.848,"end":1984.848,"text":"Sit down."},{"start":1984.873,"end":1986.23,"text":"Come on."},{"start":1991.475,"end":1992.475,"text":"Guess what?"},{"start":1992.492,"end":1994.209,"text":"- My tooth stopped hurting. - My tooth stopped hurting."},{"start":1994.234,"end":1995.28,"text":"Yes, I know."},{"start":1995.413,"end":1996.413,"text":"Let's see."},{"start":1996.929,"end":1998.272,"text":"Shut up and open up."},{"start":1998.569,"end":1999.569,"text":"Uh-huh."},{"start":2000.809,"end":2001.809,"text":"Ah."},{"start":2004.178,"end":2005.709,"text":"- Argh! - Does that hurt?"},{"start":2005.803,"end":2008.178,"text":"- Yeah! - Good. You haven't felt anything yet."},{"start":2008.388,"end":2010.778,"text":"- Ah-ha. - It's this one over here."},{"start":2010.943,"end":2013.216,"text":"Seymour. Who is the dentist here, you or me?"},{"start":2013.482,"end":2014.849,"text":"I'll find that tooth."},{"start":2014.92,"end":2015.92,"text":"M-hm."},{"start":2015.997,"end":2016.997,"text":"Ah-ha."},{"start":2017.785,"end":2020.66,"text":"Look at that stalagmite."},{"start":2020.707,"end":2023.41,"text":"But don't worry. It's going to be an easy one, Seymour."},{"start":2023.435,"end":2024.857,"text":"I won't even use Novocaine."},{"start":2025.061,"end":2027.232,"text":"Ow, you poked the mirror in my mouth."},{"start":2027.257,"end":2029.24,"text":"Well, don't tell me about it, stupid. Just swallow it."},{"start":2030.591,"end":2032.929,"text":"Alright. Here's the thing now, Seymour."},{"start":2033.45,"end":2035.958,"text":"I think I'll have this one and this one..."},{"start":2036.169,"end":2038.169,"text":"... and that one and I have to have this one, Seymour!"},{"start":2038.194,"end":2039.443,"text":"It's only one tooth."},{"start":2039.468,"end":2040.553,"text":"Seymour, who is the dentist here, ..."},{"start":2040.578,"end":2043.132,"text":".. you or me? Are you practising dentistry without a license?"},{"start":2044.171,"end":2045.828,"text":"- Alright - Uh-hu."},{"start":2045.976,"end":2047.117,"text":"Let's see."},{"start":2048.406,"end":2050.57,"text":"Oh shit! Seymour."},{"start":2050.859,"end":2054.062,"text":"- ♪ Seymour, don't be... - Argh!"},{"start":2054.218,"end":2055.961,"text":"Argh!"},{"start":2056.437,"end":2057.437,"text":"Look at that."},{"start":2057.569,"end":2059.468,"text":"Will you look at that, Seymour?"},{"start":2059.493,"end":2061.211,"text":"I didn't know you were an elk."},{"start":2061.353,"end":2062.353,"text":"Good."},{"start":2062.853,"end":2063.853,"text":"You know..."},{"start":2064.048,"end":2066.055,"text":"... I can't afford an assistant,..."},{"start":2066.219,"end":2069.172,"text":"... so I get this ready instant mix."},{"start":2069.563,"end":2071.462,"text":"It doesn't last very long but it tastes good."},{"start":2071.759,"end":2072.759,"text":"Mmm."},{"start":2073.641,"end":2074.976,"text":"Alright, Seymour."},{"start":2075.11,"end":2076.399,"text":"Stay away from me!"},{"start":2076.437,"end":2078.578,"text":"See? You're trying to kill me."},{"start":2078.618,"end":2080.618,"text":"A duel! Ah-ha!"},{"start":2093.905,"end":2095.639,"text":"Is this doctor's office?"},{"start":2095.671,"end":2096.975,"text":"Just a minute!"},{"start":2098.85,"end":2100.514,"text":"Aww, yes."},{"start":2102.35,"end":2103.569,"text":"I see it is."},{"start":2107.219,"end":2109.336,"text":"I... you-you can come in now."},{"start":2117.227,"end":2119.236,"text":"My name is Wilbur Force."},{"start":2119.384,"end":2120.829,"text":"Wilburforce what?"},{"start":2121.181,"end":2122.181,"text":"Just..."},{"start":2122.742,"end":2123.812,"text":"Wilbur Force."},{"start":2123.836,"end":2127.11,"text":"My first name is Wilbur, my last name is Force."},{"start":2128.008,"end":2129.539,"text":"I don't have a middle name."},{"start":2129.641,"end":2131.453,"text":"Well, you have an appointment, maybe?"},{"start":2131.842,"end":2134.889,"text":"I don't have a middle name well you have an appointment may be no but you were"},{"start":2135.202,"end":2136.475,"text":"... one of your patients."},{"start":2136.508,"end":2138.288,"text":"A Mrs. S. Shiva."},{"start":2138.313,"end":2141.093,"text":"I do a lot of undertaking for her relatives."},{"start":2142.179,"end":2144.258,"text":"Well, as you could see, I have a customer now..."},{"start":2144.757,"end":2148.444,"text":"... and I'm all booked up for the rest of the day, so you have to come back tomorrow."},{"start":2148.686,"end":2150.303,"text":"Oh, I couldn't do that."},{"start":2150.343,"end":2152.327,"text":"I have three or four abscesses..."},{"start":2152.352,"end":2153.739,"text":"... a touch of pyorrhea..."},{"start":2153.764,"end":2155.389,"text":"... nine or ten cavities..."},{"start":2155.414,"end":2158.365,"text":"I lost my pivot tooth and I'm in terrible pain."},{"start":2159.409,"end":2161.174,"text":"Well, I-I can't help you today."},{"start":2161.511,"end":2163.292,"text":"Oh, that's alright."},{"start":2163.323,"end":2165.339,"text":"I'll go just wait outside."},{"start":2175.493,"end":2179.055,"text":"The patient came to me with a large hole in his abdomen..."},{"start":2179.914,"end":2183.046,"text":"... caused by a fire poker used on him by his wife."},{"start":2184.273,"end":2187.187,"text":"He almost bled to death and gangrene had set in."},{"start":2187.89,"end":2189.921,"text":"I didn't give me much of a chance."},{"start":2190.304,"end":2191.96,"text":"There were other complications."},{"start":2192.343,"end":2196.929,"text":"The man had cancer, tuberculosis, leprosy ..."},{"start":2197.085,"end":2198.898,"text":"... and a touch of the grippe."},{"start":2199.999,"end":2201.788,"text":"I decided to operate."},{"start":2201.874,"end":2204.023,"text":"My... my patient just left."},{"start":2204.078,"end":2205.499,"text":"You cou... you could come in now."},{"start":2206.006,"end":2207.077,"text":"Oh goodie."},{"start":2209.694,"end":2212.343,"text":"- I didn't see the other man leave. - Well..."},{"start":2212.452,"end":2214.045,"text":"... he went out the back door"},{"start":2217.896,"end":2220.677,"text":"You know, most people don't like to go to the dentist..."},{"start":2220.709,"end":2223.878,"text":"... but I rather enjoy it myself, don't you?"},{"start":2223.911,"end":2225.09,"text":"I mean there is such..."},{"start":2225.115,"end":2227.324,"text":"... there is a real feeling of growth, of ..."},{"start":2227.699,"end":2228.699,"text":"... of..."},{"start":2229.379,"end":2231.02,"text":"... progress when that..."},{"start":2231.067,"end":2232.895,"text":"... that old drill goes in..."},{"start":2233.068,"end":2237.059,"text":"... and I'd almost rather go to the dentist than anywhere, wouldn't you?"},{"start":2237.084,"end":2238.084,"text":"Yeah."},{"start":2239.029,"end":2240.529,"text":"Now, no Novocaine."},{"start":2240.554,"end":2241.959,"text":"It dulls the senses."},{"start":2243.28,"end":2245.71,"text":"This is gonna hurt you more than it is me."},{"start":2245.735,"end":2247.749,"text":"Oh, goodie goodie, here it comes."},{"start":2249.28,"end":2250.382,"text":"Argh!"},{"start":2251.233,"end":2252.428,"text":"Argh!"},{"start":2254.194,"end":2255.139,"text":"Argh!"},{"start":2255.725,"end":2258.561,"text":"Oh my god, don't stop now!"},{"start":2258.967,"end":2260.279,"text":"Well, I made a lot of holes..."},{"start":2260.304,"end":2262.639,"text":"... and now I've gotta fill it with this silver stuff."},{"start":2262.709,"end":2264.67,"text":"Well, aren't you gonna pull any?"},{"start":2265.045,"end":2267.826,"text":"- Well, uh... - Oh, come on."},{"start":2269.045,"end":2270.818,"text":"Well, it's your mouth."},{"start":2279.198,"end":2280.261,"text":"Argh!"},{"start":2281.448,"end":2282.573,"text":"Argh!"},{"start":2284.089,"end":2285.042,"text":"Argh!"},{"start":2288.409,"end":2289.698,"text":"Well, Dr. Farb..."},{"start":2289.885,"end":2291.839,"text":"... it's been quite an afternoon."},{"start":2292.028,"end":2295.494,"text":"I can truly say I've never enjoyed myself so much."},{"start":2295.573,"end":2298.279,"text":"I'll recommend you to all my friends."},{"start":2298.28,"end":2299.397,"text":"Thank you. Bye."},{"start":2299.422,"end":2300.819,"text":"Bye, now."},{"start":2309.519,"end":2311.555,"text":"Feed me!"},{"start":2311.605,"end":2312.909,"text":"Oh, take it easy, Dracula."},{"start":2312.934,"end":2315.214,"text":"What do you think I'm carrying here? My dirty laundry?"},{"start":2320.325,"end":2321.434,"text":"Feed!"},{"start":2321.566,"end":2323.56,"text":"I'm coming! I'm coming already."},{"start":2328.869,"end":2330.29,"text":"This should be enough for anybody."},{"start":2330.315,"end":2331.315,"text":"Mhm."},{"start":2331.34,"end":2333.057,"text":"Fooood."},{"start":2338.162,"end":2340.068,"text":"Well, goodbye Dr. Farb."},{"start":2340.638,"end":2343.224,"text":"You may have been a crummy dentist but you were a nice fellow."},{"start":2343.855,"end":2346.12,"text":"I never meant to kill anybody in my whole life."},{"start":2346.175,"end":2348.57,"text":"Now I killed two in the last two days."},{"start":2349.62,"end":2352.448,"text":"Well, he asked for it coming at me with that knife and all."},{"start":2353.808,"end":2355.425,"text":"Bon voyage, Dr Farb."},{"start":2356.19,"end":2357.237,"text":"Want anything else?"},{"start":2357.511,"end":2359.244,"text":"[BURP]"},{"start":2359.541,"end":2360.541,"text":"[BURP]"},{"start":2361.291,"end":2362.596,"text":"See you in the morning."},{"start":2382.419,"end":2383.419,"text":"Come in."},{"start":2384.857,"end":2385.857,"text":"It's me, Joe."},{"start":2386.342,"end":2387.342,"text":"Good morning, Frank."},{"start":2388.287,"end":2389.369,"text":"How's the wife, Frank?"},{"start":2389.451,"end":2391.193,"text":"- Not bad, Joe. - Glad to hear it."},{"start":2391.443,"end":2393.014,"text":"- The kids? - Lost one yesterday."},{"start":2393.21,"end":2394.842,"text":"Awful, eh? How did that happen?"},{"start":2395.015,"end":2396.335,"text":"Playing with matches."},{"start":2396.36,"end":2397.538,"text":"Well, those are the breaks."},{"start":2397.749,"end":2398.749,"text":"Yeah, I guess so."},{"start":2399.079,"end":2400.165,"text":"Got a strange one here."},{"start":2400.352,"end":2402.938,"text":"Railroad people say the last one of their best detectives the other night."},{"start":2402.963,"end":2403.883,"text":"Where?"},{"start":2403.908,"end":2404.907,"text":"Down by the yards."},{"start":2405.039,"end":2406.562,"text":"He was watching refrigerator cars."},{"start":2406.905,"end":2408.109,"text":"Refrigerator cars?"},{"start":2408.648,"end":2410.874,"text":"- Ice thieves. - Oh yeah? What happened?"},{"start":2410.899,"end":2411.898,"text":"Don't know."},{"start":2411.898,"end":2413.796,"text":"- Vanished, right on the tracks. - Clues?"},{"start":2414.608,"end":2415.608,"text":"None."},{"start":2415.633,"end":2416.633,"text":"Anything else?"},{"start":2416.781,"end":2418.211,"text":"Dentist. Farb."},{"start":2418.351,"end":2419.796,"text":"- Dead? - Missing."},{"start":2420.023,"end":2421.132,"text":"Clues?"},{"start":2421.234,"end":2422.632,"text":"- Blood in the office. - Where?"},{"start":2422.679,"end":2424.444,"text":"- Skid Row. - Ideas?"},{"start":2425.171,"end":2426.296,"text":"- None. - Check it out?"},{"start":2427.288,"end":2428.288,"text":"Yeah."},{"start":2436.421,"end":2437.882,"text":"Now we were on the case,"},{"start":2438.273,"end":2439.851,"text":"... officer Frank Stoolie and me."},{"start":2440.609,"end":2441.726,"text":"My name is Fink."},{"start":2442.617,"end":2443.726,"text":"Sergeant Joe Fink."},{"start":2444.773,"end":2445.773,"text":"I'm a fink."},{"start":2465.035,"end":2466.339,"text":"Morning, Mr Mushnick."},{"start":2467.207,"end":2469.152,"text":"Oh, boy, look at that!"},{"start":2469.426,"end":2470.73,"text":"Hi, everybody."},{"start":2471.777,"end":2473.566,"text":"Oh, my god!"},{"start":2473.652,"end":2475.511,"text":"- Ain't it something? - It's..."},{"start":2476.05,"end":2477.824,"text":"It's monstrositous!"},{"start":2478.034,"end":2479.034,"text":"Yeah."},{"start":2479.542,"end":2481.886,"text":"And to think that you did it."},{"start":2483.589,"end":2485.565,"text":"Gee, Audrey. You don't have to kiss me."},{"start":2486.081,"end":2487.699,"text":"Don't you like me to kiss you?"},{"start":2488.284,"end":2490.596,"text":"Yeah, but... you don't like to kiss me."},{"start":2491.05,"end":2492.128,"text":"Why shouldn't I?"},{"start":2492.518,"end":2494.167,"text":"Nobody else ever did."},{"start":2494.526,"end":2495.831,"text":"Well, I do like to."},{"start":2495.994,"end":2498.274,"text":"You do? You really do? You like to kiss me?"},{"start":2498.299,"end":2499.206,"text":"Sure, I do."},{"start":2499.231,"end":2500.847,"text":"Would... would you like to kiss me again?"},{"start":2501.19,"end":2502.19,"text":"Ok."},{"start":2502.215,"end":2503.627,"text":"That plant..."},{"start":2506.569,"end":2509.374,"text":"Oh, boy! You kiss good, Audrey."},{"start":2509.428,"end":2511.795,"text":"Oh, I guess I just have a good kisser."},{"start":2511.82,"end":2513.662,"text":"H-h-h-how d-d-did..."},{"start":2513.687,"end":2515.912,"text":"Would you like to go out on a date with me some night?"},{"start":2516.053,"end":2518.186,"text":"- When...? - Oh, sure I would, Seymour."},{"start":2518.211,"end":2519.906,"text":"- Any time. - Tonight?"},{"start":2520.224,"end":2521.255,"text":"Ok."},{"start":2521.639,"end":2524.076,"text":"- Oh, boy! - A-a-a-about that plant..."},{"start":2525.037,"end":2526.475,"text":"- We got the list. - Of flowers."},{"start":2526.5,"end":2528.514,"text":"- For the float. - For the rose parade."},{"start":2528.561,"end":2530.514,"text":"I can't talk to you now, girls."},{"start":2530.764,"end":2531.879,"text":"Talk on Audrey."},{"start":2531.88,"end":2533.662,"text":"- We got the list. - With the float."},{"start":2533.687,"end":2535.452,"text":"- It's ok. Let's take a look at it. - Ok."},{"start":2535.569,"end":2536.593,"text":"Hi, what's cookin'?"},{"start":2536.679,"end":2537.679,"text":"Look at my plant."},{"start":2537.983,"end":2540.24,"text":"- My, what a large one. - Yeah."},{"start":2545.817,"end":2547.864,"text":"Hello, Mrs. Shiva. What's new?"},{"start":2548.059,"end":2550.075,"text":"Oy, I got terrible news."},{"start":2550.739,"end":2553.379,"text":"My nephew Frankie just lost his little boy."},{"start":2553.481,"end":2554.887,"text":"Oh, that's too bad."},{"start":2554.912,"end":2555.927,"text":"How did it happen?"},{"start":2555.952,"end":2557.606,"text":"He was playing with matches."},{"start":2557.757,"end":2559.553,"text":"Would you like to buy, maybe, some flowers?"},{"start":2559.811,"end":2561.967,"text":"Nah... about 50 cents worth."},{"start":2562.085,"end":2564.1,"text":"So I'll get the for you. Look at my plant!"},{"start":2564.202,"end":2565.608,"text":"I'm looking."},{"start":2571.584,"end":2574.568,"text":"- Your name Gravis Mushnick? - M-M-Mushnick, Gravis. That's my name."},{"start":2574.732,"end":2575.865,"text":"Just want to ask you a few questions."},{"start":2575.89,"end":2578.059,"text":"- Questions ask me why? - Just want to ask a few questions."},{"start":2578.084,"end":2579.326,"text":"I-I didn't do it."},{"start":2579.38,"end":2580.686,"text":"- Do what? - Whatever."},{"start":2580.779,"end":2581.621,"text":"Ever see this man?"},{"start":2581.646,"end":2583.021,"text":"Man... see... picture..."},{"start":2583.209,"end":2584.208,"text":"Why are you so nervous?"},{"start":2584.233,"end":2585.233,"text":"You got a guilty conscience?"},{"start":2585.278,"end":2586.575,"text":"No! Why should I?"},{"start":2586.6,"end":2587.379,"text":"Ever see this man?"},{"start":2587.404,"end":2589.223,"text":"Man... see... this-this picture..."},{"start":2589.248,"end":2590.497,"text":"Dr. Farb."},{"start":2591.363,"end":2592.933,"text":"- So you know him? - He's my dentist."},{"start":2592.995,"end":2595.105,"text":"He... eh... maybe did something?"},{"start":2595.262,"end":2596.824,"text":"- He disappeared. - Blood in his office."},{"start":2596.849,"end":2597.746,"text":"Another man, too."},{"start":2597.771,"end":2599.511,"text":"Blood on the railroad tracks."},{"start":2600.333,"end":2602.989,"text":"- Dr. Farb is murdered? - Is he?"},{"start":2603.091,"end":2605.13,"text":"Who knows? Not me!"},{"start":2606.075,"end":2607.075,"text":"What do you think?"},{"start":2607.786,"end":2608.904,"text":"He doesn't know anything."},{"start":2609.318,"end":2610.318,"text":"Ok, Mushnick."},{"start":2610.505,"end":2612.068,"text":"If you hear anything about these men..."},{"start":2612.093,"end":2613.012,"text":"...call our office."},{"start":2613.067,"end":2614.683,"text":"Sure, I'll be glad to..."},{"start":2614.731,"end":2616.637,"text":"...cooperate with the police."},{"start":2616.895,"end":2617.895,"text":"Hello, aunt Siddie."},{"start":2617.92,"end":2620.949,"text":"Oh, isn't it terrible what happened to your boy, Frankie?"},{"start":2620.974,"end":2622.489,"text":"Those are the breaks."},{"start":2626.966,"end":2628.005,"text":"Alright, Seymour."},{"start":2628.03,"end":2631.645,"text":"Now you tell me if this plant is finished all grown up."},{"start":2632.138,"end":2634.529,"text":"- It's finished all growning up. - You wouldn't kid your father?"},{"start":2634.591,"end":2636.364,"text":"- My father came home? - Me, idiot!"},{"start":2636.389,"end":2637.864,"text":"It's a finger of speech."},{"start":2637.989,"end":2638.989,"text":"Now look..."},{"start":2639.014,"end":2641.25,"text":"I can't stand anymore that plant."},{"start":2641.275,"end":2643.715,"text":"It's growing me out of house and home."},{"start":2644.075,"end":2646.02,"text":"It ain't gonna grow anymore. I promise."},{"start":2646.059,"end":2647.637,"text":"How can you be so sure?"},{"start":2648.028,"end":2649.629,"text":"It ate three times already."},{"start":2649.925,"end":2651.206,"text":"Who... I mean..."},{"start":2651.386,"end":2653.425,"text":"...what did it eat this time?"},{"start":2653.589,"end":2655.995,"text":"Well, abou... about a million Japanese beetles."},{"start":2656.48,"end":2657.948,"text":"So don't eat no more?"},{"start":2659.159,"end":2660.159,"text":"It's full."},{"start":2660.253,"end":2661.253,"text":"Gravis?"},{"start":2662.83,"end":2665.353,"text":"There's a lady from some kind of a committance outside."},{"start":2665.44,"end":2666.908,"text":"I think it's important."},{"start":2668.134,"end":2669.134,"text":"Excellent."},{"start":2669.205,"end":2670.213,"text":"By the by..."},{"start":2670.791,"end":2673.384,"text":"...I understand you want to take Audrey out on a date tonight."},{"start":2673.807,"end":2675.072,"text":"That's very good with me."},{"start":2675.384,"end":2678.556,"text":"Because I am staying to keep an eye on that meshugana plant."},{"start":2683.158,"end":2685.002,"text":"So, where are we gonna go tonight, Seymour."},{"start":2685.494,"end":2687.781,"text":"I-I-I just remembered: I don't have any money."},{"start":2688.463,"end":2689.619,"text":"Well, that's ok."},{"start":2690.009,"end":2692.728,"text":"We could take a walk along the ocean or something."},{"start":2693.681,"end":2695.978,"text":"I got a great idea. We could eat dinner at my house."},{"start":2696.063,"end":2698.493,"text":"- My mom's a great cook. - Oh, that's swell!"},{"start":2698.532,"end":2700.423,"text":"Oh, boy, I'll call later and tell her."},{"start":2700.517,"end":2701.306,"text":"Ok."},{"start":2705.359,"end":2708.195,"text":"Oh, that's remarkable."},{"start":2708.702,"end":2709.702,"text":"You like?"},{"start":2710.829,"end":2713.69,"text":"I neither like nor dislike anything, my goodness."},{"start":2715.676,"end":2718.028,"text":"I happen to represent the society of..."},{"start":2718.314,"end":2721.34,"text":"... Silent Flower Observers of Southern California."},{"start":2721.403,"end":2722.793,"text":"How about that?"},{"start":2723.145,"end":2724.145,"text":"Tell me..."},{"start":2724.34,"end":2727.48,"text":"... who created this magnificent bloom?"},{"start":2728.858,"end":2730.233,"text":"I did. Me."},{"start":2730.258,"end":2731.083,"text":"Oh."},{"start":2731.108,"end":2733.303,"text":"A-a-and what might your name be?"},{"start":2733.421,"end":2735.272,"text":"Seymour Krelborn, with a K."},{"start":2735.685,"end":2737.49,"text":"- Krelboind? - Krelborn."},{"start":2738.013,"end":2739.646,"text":"Raised in the coffee can."},{"start":2740.45,"end":2741.45,"text":"This..."},{"start":2741.685,"end":2742.566,"text":"Well..."},{"start":2742.591,"end":2744.349,"text":"Tell me, Mr. Krelboind..."},{"start":2744.7,"end":2747.911,"text":"Is this a freak or can more be raised from the seeds?"},{"start":2747.998,"end":2749.153,"text":"We should live so long."},{"start":2749.192,"end":2751.612,"text":"Well, I don't think there gonna be will be any more, Miss, uh,..."},{"start":2751.637,"end":2752.637,"text":"Feuchtwanger."},{"start":2752.661,"end":2754.427,"text":"Mrs Hortense Feuchtwanger."},{"start":2754.551,"end":2757.746,"text":"I think this is gonna be the only one, Mrs. Fishswinger."},{"start":2758.316,"end":2759.316,"text":"Feuchtwanger."},{"start":2759.965,"end":2760.981,"text":"Feuchtwanger?"},{"start":2761.092,"end":2762.855,"text":"Well, it's probably indigestible anyway."},{"start":2766.014,"end":2767.014,"text":"At any rate..."},{"start":2767.686,"end":2770.881,"text":"... I have the honour to tell you, Seymour Krelboind,..."},{"start":2771.381,"end":2774.881,"text":"... that you have been selected to receive the annual trophy..."},{"start":2774.906,"end":2778.638,"text":"of the Society of Silent Flower Observers of Southern California."},{"start":2778.686,"end":2780.084,"text":"A trophy? Me?"},{"start":2780.131,"end":2782.217,"text":"Such is justice..."},{"start":2782.443,"end":2786.175,"text":"But tell me: When do you suppose those large buds will open?"},{"start":2786.528,"end":2789.52,"text":"Well according to what the book says about the plants that I crossed..."},{"start":2789.82,"end":2792.219,"text":"... they should open the day after tomorrow at sunset."},{"start":2792.346,"end":2793.567,"text":"Ah, very well."},{"start":2793.598,"end":2795.903,"text":"Then I shall return at that time to present the trophy"},{"start":2796.115,"end":2797.115,"text":"Good day."},{"start":2803.895,"end":2805.051,"text":"Remarkable."},{"start":2809.613,"end":2811.668,"text":"Oh boy! I'm gonna get a trophy!"},{"start":2811.699,"end":2813.698,"text":"Oh, Seymour. I'm so proud of you."},{"start":2813.723,"end":2816.526,"text":"Oh, a real trophy for Audrey Jr.!"},{"start":2816.551,"end":2818.764,"text":"- We'll put it on the float. - In the rose parade."},{"start":2818.801,"end":2820.028,"text":"Oh, boy!"},{"start":2823.8,"end":2825.847,"text":"Don't look at me. I-I'm a terrible sight."},{"start":2826.019,"end":2827.777,"text":"I-I'm a complete sea hag."},{"start":2827.948,"end":2829.886,"text":"- She always says that. - O, well, it's true."},{"start":2829.957,"end":2832.05,"text":"I haven't been feelin' very well lately."},{"start":2832.245,"end":2834.683,"text":"Audrey, this is my ma, Winifred Krelborn."},{"start":2834.729,"end":2836.37,"text":"Ma, this is Audrey Fulquard."},{"start":2836.395,"end":2837.292,"text":"She's my girl."},{"start":2837.317,"end":2839.113,"text":"Hi Audrey. Are you hungry?"},{"start":2839.138,"end":2841.145,"text":"I sure am. I could eat a horse."},{"start":2841.17,"end":2844.473,"text":"Oh. Well, sit right down, and I'll go get the first course."},{"start":2848.348,"end":2849.348,"text":"Sit here, Audrey."},{"start":2850.598,"end":2851.785,"text":"You want me to take your sweater?"},{"start":2852.043,"end":2853.317,"text":"Well... yeah."},{"start":2861.732,"end":2862.803,"text":"Never mind that."},{"start":2863.069,"end":2864.569,"text":"Well, now try this."},{"start":2871.382,"end":2873.163,"text":"It tastes like cough syrup."},{"start":2873.265,"end":2875.273,"text":"Dr. Phlegm's cough syrup"},{"start":2875.5,"end":2876.5,"text":"A toast?"},{"start":2877.794,"end":2880.42,"text":"- To Audrey Jr.! - No, to Audrey Sr.!"},{"start":2904.16,"end":2906.277,"text":"You! You glutton, you!"},{"start":2906.596,"end":2908.112,"text":"Tonight I keep an eye on you."},{"start":2908.137,"end":2910.761,"text":"I don't let nobody get near you."},{"start":2921.22,"end":2922.618,"text":"Coming soup."},{"start":2924.173,"end":2926.642,"text":"No, don't touch it till I get a little flavouring."},{"start":2927.806,"end":2928.806,"text":"Gee, Audrey."},{"start":2928.844,"end":2930.62,"text":"You sure look good by candlelight."},{"start":2931.079,"end":2932.665,"text":"Do I really, Seymour?"},{"start":2932.704,"end":2934.493,"text":"- Yes. - Here you are."},{"start":2937.375,"end":2938.375,"text":"Now try."},{"start":2939.227,"end":2940.578,"text":"Sure smells different."},{"start":2940.664,"end":2941.836,"text":"It's different."},{"start":2943.039,"end":2944.711,"text":"Some kind of oil, isn't it?"},{"start":2945.045,"end":2946.248,"text":"Cod liver oil."},{"start":2946.802,"end":2948.208,"text":"Wonderful for the colon."},{"start":2948.326,"end":2950.349,"text":"And that's sulphur powder on top."},{"start":2955.669,"end":2958.888,"text":"Feed me."},{"start":2962.49,"end":2965.052,"text":"Feed me!"},{"start":2966.974,"end":2969.178,"text":"I'm hungry."},{"start":2977.647,"end":2978.647,"text":"Open it is."},{"start":2978.818,"end":2980.116,"text":"Feed me!"},{"start":2983.647,"end":2984.678,"text":"I didn't hear it."},{"start":2985.069,"end":2986.318,"text":"Feed me!"},{"start":2986.343,"end":2987.343,"text":"I heard it."},{"start":2988.256,"end":2990.647,"text":"I want food."},{"start":2991.733,"end":2993.451,"text":"A talking plant we got."},{"start":2993.592,"end":2995.608,"text":"I'm hungry."},{"start":2995.959,"end":2996.959,"text":"No."},{"start":2997.358,"end":2998.358,"text":"Hungry?"},{"start":2998.865,"end":3001.108,"text":"And other fine kettle von fish!"},{"start":3001.974,"end":3003.974,"text":"Who would you like to have tonight?"},{"start":3004.669,"end":3006.427,"text":"You look fat enough."},{"start":3008.622,"end":3012.192,"text":"We not only got a talking plant, we got one that makes with smart cracks."},{"start":3012.849,"end":3015.903,"text":"Will you listen to me, you botanical bum?"},{"start":3016.239,"end":3017.567,"text":"Food you wouldn't get."},{"start":3017.958,"end":3019.45,"text":"Not from Gravis Mushnick."},{"start":3019.583,"end":3021.184,"text":"I'm starved."},{"start":3021.3,"end":3022.411,"text":"Excellent."},{"start":3022.856,"end":3025.146,"text":"You would unpopulate all Skid Row."},{"start":3025.341,"end":3026.341,"text":"Well..."},{"start":3027.208,"end":3028.829,"text":"You can forget about it."},{"start":3029.223,"end":3031.83,"text":"You wouldn't get fed from Gravis mushnick tonight."},{"start":3033.473,"end":3034.473,"text":"Good night"},{"start":3035.051,"end":3036.762,"text":"You'll get yours."},{"start":3043.949,"end":3045.644,"text":"I kinda like this chow mein."},{"start":3045.831,"end":3047.308,"text":"Uh, if it tastes a little bitter..."},{"start":3047.333,"end":3050.316,"text":"... it's because it's made of Chinese herbs and it's..."},{"start":3050.527,"end":3052.069,"text":"... flavored with accra myosin."},{"start":3052.238,"end":3053.238,"text":"Epsom salt."},{"start":3053.675,"end":3056.059,"text":"There ain't another cook in the whole world like my ma."},{"start":3056.105,"end":3058.738,"text":"That's what your old man said before the last ran out on me."},{"start":3058.808,"end":3061.738,"text":"You know, if you're gonna be married, you gotta be a good cook."},{"start":3062.239,"end":3063.942,"text":"Maybe you could teach me."},{"start":3064.083,"end":3065.458,"text":"You thinkin' to get married?"},{"start":3066.31,"end":3068.638,"text":"- He hasn't asked me yet. - Who hasn't?"},{"start":3068.865,"end":3069.865,"text":"Seymour."},{"start":3070.091,"end":3071.849,"text":"Seymour's too young to get married."},{"start":3071.997,"end":3075.235,"text":"Look here. A boy's got to go and play around a little bit."},{"start":3075.356,"end":3076.528,"text":"Go out on the makin'."},{"start":3076.553,"end":3077.623,"text":"Have a ball."},{"start":3077.856,"end":3080.63,"text":"Gee, ma. I don't wanna have a ball. I wanna be with Audrey."},{"start":3080.778,"end":3082.602,"text":"- Now look, Seymour. - Oh, Seymour."},{"start":3082.689,"end":3086.252,"text":"You promised you wouldn't get married until you bought me an iron lung."},{"start":3086.588,"end":3088.494,"text":"You've been breathing for years, ma."},{"start":3088.619,"end":3089.83,"text":"Well, it ain't easy."},{"start":3090.041,"end":3091.682,"text":"It ain't easy, son."},{"start":3113.687,"end":3114.851,"text":"Nobody's here."},{"start":3115.32,"end":3117.398,"text":"Black cats, 13th job..."},{"start":3117.423,"end":3119.9,"text":"Friday 13th. Stupid superstition."},{"start":3124.235,"end":3125.235,"text":"Alright, you."},{"start":3125.26,"end":3126.329,"text":"Come out of there."},{"start":3126.831,"end":3128.034,"text":"Don't shoot, Mister."},{"start":3128.455,"end":3131.252,"text":"I'm old and sick. I wouldn't hurt even a fly."},{"start":3132.502,"end":3134.219,"text":"Come out in the light where I can see you."},{"start":3135.798,"end":3136.798,"text":"Come on."},{"start":3136.823,"end":3137.979,"text":"Please don't shoot."},{"start":3138.081,"end":3139.081,"text":"Please."},{"start":3139.197,"end":3141.612,"text":"Please. I'm only Gravis Mushnick. You wouldn't want to kill me."},{"start":3141.643,"end":3142.843,"text":"Where would you hide the body?"},{"start":3143.245,"end":3145.175,"text":"Don't worry. I'm not gonna shoot you."},{"start":3145.643,"end":3147.244,"text":"- Not unless you try something. - Try something?"},{"start":3147.269,"end":3148.854,"text":"I never tried anything in my life."},{"start":3149.167,"end":3151.526,"text":"I wouldn't try anything now. You want my money? Take it."},{"start":3151.551,"end":3154.853,"text":"You want I should go out and steal you some more? That's alright, too. I'll do it."},{"start":3155.228,"end":3156.603,"text":"Thank you very much."},{"start":3157.572,"end":3159.642,"text":"I like your brand of hospitality."},{"start":3160.54,"end":3163.11,"text":"You'll excuse it isn't more. I'm only a poor florist"},{"start":3163.135,"end":3164.135,"text":"Yeah, yeah."},{"start":3165.336,"end":3166.821,"text":"You got about 30 bucks here."},{"start":3167.5,"end":3169.039,"text":"Come on now. Where's the rest of it?"},{"start":3169.179,"end":3172.406,"text":"I was in here this afternoon. I saw about 30,000 people in here..."},{"start":3172.53,"end":3173.921,"text":"They must have spent some money. Where is it?"},{"start":3174,"end":3176.156,"text":"There ain't no more money. They came in to look on the plant."},{"start":3176.181,"end":3178.265,"text":"It's a big attraction. Audrey Jr."},{"start":3178.681,"end":3179.72,"text":"The plant. Don't try to snow me, Jim."},{"start":3179.745,"end":3181.845,"text":"30,000 square didn't come in just to look for a plant."},{"start":3181.87,"end":3182.869,"text":"I want it!"},{"start":3184,"end":3186.289,"text":"I don't got no more money. Honest. Believe me."},{"start":3186.336,"end":3187.414,"text":"Ok, let's try this."},{"start":3187.656,"end":3188.656,"text":"One..."},{"start":3188.867,"end":3189.867,"text":"Two..."},{"start":3189.938,"end":3190.938,"text":"Three..."},{"start":3191.084,"end":3193.423,"text":"- Four... - I ain't got no more money, honest!"},{"start":3193.654,"end":3195.997,"text":"Alright. Try it the other way around. Five..."},{"start":3196.053,"end":3197.053,"text":"Four..."},{"start":3197.091,"end":3198.091,"text":"Three..."},{"start":3198.139,"end":3199.217,"text":"- Two... - Alright."},{"start":3199.242,"end":3200.31,"text":"Alright."},{"start":3200.429,"end":3201.757,"text":"Alright, big bad. Where?"},{"start":3203.515,"end":3204.718,"text":"In the plant."},{"start":3205.495,"end":3206.754,"text":"In the plant?"},{"start":3207.443,"end":3209.402,"text":"The big plant, Audrey Jr."},{"start":3212.791,"end":3214.299,"text":"I-inside the big leaf?"},{"start":3214.487,"end":3216.183,"text":"That's right. Inside."},{"start":3217.267,"end":3219.12,"text":"H-h-how do you get it open?"},{"start":3220.815,"end":3221.815,"text":"Just knock."},{"start":3238.274,"end":3239.274,"text":"In there?"},{"start":3239.299,"end":3240.299,"text":"In there."},{"start":3241.071,"end":3242.071,"text":"Inside."},{"start":3242.328,"end":3243.468,"text":"In the bottom."},{"start":3243.493,"end":3244.696,"text":"I don't see anything."},{"start":3246.249,"end":3247.609,"text":"Way inside."},{"start":3248.141,"end":3249.477,"text":"Right at the bottom."},{"start":3262.792,"end":3264.23,"text":"Argh!"},{"start":3268.927,"end":3270.502,"text":"Oi, what I did?"},{"start":3274.425,"end":3277.198,"text":"I don't care about you got a date with Audrey tonight."},{"start":3277.223,"end":3280.175,"text":"I am no more sitting up with that no-goodnik plant."},{"start":3282.503,"end":3285.159,"text":"But, see, Mr. Mushnick, you don't have to sit up with it any more."},{"start":3285.184,"end":3286.847,"text":"- It's all grown up now. - Excellent."},{"start":3287.3,"end":3290.05,"text":"Smart guy. How do you know it don't be hungry no more?"},{"start":3290.075,"end":3292.398,"text":"- Well because... - Tonight you are staying!"},{"start":3292.563,"end":3295.024,"text":"Then tomorrow they are coming and they are going to give you a trophy..."},{"start":3295.049,"end":3299.117,"text":"... and then after that we are getting rid once and for all for that plant!"},{"start":3299.281,"end":3302.328,"text":"- Getting rid of it? Why? - Don't ask. Why? Why?"},{"start":3302.405,"end":3304.28,"text":"The end. Into the garbage can."},{"start":3304.305,"end":3305.757,"text":"Aloha."},{"start":3305.843,"end":3308.078,"text":"Oi. Yes, Mrs. Shiva?"},{"start":3308.14,"end":3309.32,"text":"Oh, Seymour."},{"start":3309.351,"end":3311.029,"text":"Your wonderful plant!"},{"start":3311.054,"end":3312.468,"text":"Oh, that's alright, Audrey."},{"start":3312.546,"end":3314.898,"text":"I'll grow other plants, even more wonderful ones."},{"start":3315.171,"end":3316.499,"text":"I know you will."},{"start":3317.147,"end":3319.124,"text":"Did you figure out what we're doing tonight?"},{"start":3319.64,"end":3322.467,"text":"Yeah we're going to place full of beautiful flowers."},{"start":3322.932,"end":3324.885,"text":"- We have to stay here. - Yeah."},{"start":3325.205,"end":3327.598,"text":"Well, never mind. We'll have a picnic."},{"start":3327.682,"end":3329.51,"text":"It'll be just like going to the country."},{"start":3329.611,"end":3330.925,"text":"- Oh, boy! - ...flowers and..."},{"start":3330.95,"end":3332.502,"text":"... and pink azaleas, for the arbour,..."},{"start":3332.527,"end":3335.392,"text":"- ... and the 9000 yellow mons for the... - For the border."},{"start":3335.519,"end":3338.578,"text":"- And the... the roses - I got them around the back."},{"start":3339.996,"end":3343.58,"text":"What do you mean you're going to a picnic at night with that Fulquard girl?"},{"start":3343.8,"end":3345.261,"text":"Don't you like Audrey, ma?"},{"start":3345.339,"end":3346.788,"text":"She's out after your money."},{"start":3347.034,"end":3348.308,"text":"I don't have any money."},{"start":3348.37,"end":3350.295,"text":"Oh, she's a smart one."},{"start":3350.495,"end":3354.542,"text":"She'll latch onto ya till ya get some and then goodbye, fortune!"},{"start":3354.761,"end":3356.636,"text":"But Audrey's honest girl, ma."},{"start":3356.698,"end":3359.597,"text":"Yeah, never trust a woman who's too healthy"},{"start":3359.971,"end":3362.283,"text":"But Audrey had a bad cold a few weeks ago."},{"start":3362.354,"end":3364.698,"text":"Oh, cold, a puny cold."},{"start":3364.955,"end":3367.065,"text":"Why don't you get yourself a real female with..."},{"start":3367.09,"end":3368.487,"text":"... something decent like..."},{"start":3368.512,"end":3371.133,"text":"... pneumonoconiosis, or-or gall stones?"},{"start":3371.188,"end":3373.088,"text":"Well, maybe she could catch something like that."},{"start":3373.113,"end":3375.598,"text":"The only thing she'll catch is you."},{"start":3376.23,"end":3378.98,"text":"And she'll take you off to some shady sanatorium..."},{"start":3379.005,"end":3382.334,"text":"... and leave me to chiropractors and faith healers."},{"start":3382.919,"end":3384.84,"text":"I know when I'm not wanted."},{"start":3385.919,"end":3387.512,"text":"Oh, gee, ma."},{"start":3387.537,"end":3389.341,"text":"Don't feel sorry for me."},{"start":3390.068,"end":3392.825,"text":"I'll just find a nice, wet alley somewhere..."},{"start":3392.85,"end":3394.896,"text":"... and curl up and wait for the end."},{"start":3395.154,"end":3397.763,"text":"Oh, please don't die till I get back, will you ma?"},{"start":3397.841,"end":3400.333,"text":"I'll take care of you. I'll always take care of you, I promise!"},{"start":3400.358,"end":3401.763,"text":"- Yeah. - Bye."},{"start":3407.99,"end":3410.404,"text":"Gee, Audrey, I've never tasted food like this before."},{"start":3410.795,"end":3413.013,"text":"It's a peanut butter and jelly sandwich"},{"start":3413.146,"end":3415.058,"text":"Peanut butter and jelly - what does that cure?"},{"start":3415.575,"end":3417.354,"text":"Nothing. It's just a food."},{"start":3417.441,"end":3419.331,"text":"What good is it if it doesn't clear up pimples..."},{"start":3419.356,"end":3421.348,"text":"... or shrink your sinus tissues or something?"},{"start":3421.449,"end":3423.629,"text":"You're just being silly, Seymour."},{"start":3424.996,"end":3427.13,"text":"Seymour, what do you wanna be?"},{"start":3427.902,"end":3429.582,"text":"Oh, I wanna grow things."},{"start":3429.963,"end":3432.019,"text":"If I had a lot of money, I'd go to the South Seas,.."},{"start":3432.044,"end":3434.417,"text":"... where they grow the most fabulous plants in the world."},{"start":3434.511,"end":3436.065,"text":"That sounds exciting."},{"start":3436.41,"end":3437.41,"text":"Yeah."},{"start":3437.435,"end":3439.855,"text":"I'd like to go to the South Seas, too."},{"start":3439.956,"end":3441.846,"text":"There's no reason why you couldn't go."},{"start":3442.494,"end":3444.429,"text":"Would you take me with you, Seymour?"},{"start":3444.494,"end":3447.198,"text":"Oh, I couldn't very well go without you, Audrey."},{"start":3447.456,"end":3448.456,"text":"Why not?"},{"start":3448.979,"end":3449.979,"text":"Because..."},{"start":3450.214,"end":3451.768,"text":"Because I'm in love with you, Audrey."},{"start":3452.026,"end":3454.135,"text":"Oh, I'm in love with you, too, Seymour."},{"start":3455.08,"end":3456.361,"text":"Feed me."},{"start":3457.345,"end":3458.345,"text":"What'd you say?"},{"start":3458.525,"end":3459.9,"text":"I'm... I'm just kidding."},{"start":3460.971,"end":3462.752,"text":"I'm hungry!"},{"start":3462.784,"end":3463.784,"text":"Seymour!"},{"start":3463.955,"end":3466.369,"text":"- I didn't mean it. - Why did you say it?"},{"start":3466.525,"end":3469.088,"text":"Oh. Food."},{"start":3469.697,"end":3470.994,"text":"You didn't even say that."},{"start":3471.019,"end":3472.744,"text":"Oh yes I did. I said it. I said it."},{"start":3472.783,"end":3474.533,"text":"Oh, I'm looking right at you."},{"start":3474.876,"end":3476.869,"text":"Well, I'm a ventriloquist."},{"start":3476.988,"end":3477.805,"text":"You're what?"},{"start":3477.83,"end":3479.946,"text":"- A ventrilo... - Feed me!"},{"start":3480.774,"end":3482.47,"text":"Seymour, do you feel all right?"},{"start":3482.495,"end":3484.547,"text":"Well, I don't know. I'm not sure."},{"start":3484.735,"end":3487.517,"text":"Well, then stop all this nonsense and kiss me."},{"start":3488.423,"end":3490.673,"text":"I'm dying from hunger!"},{"start":3490.698,"end":3493.344,"text":"Alright, if you're so hungry, eat something but..."},{"start":3493.547,"end":3494.649,"text":"... forget about me."},{"start":3494.817,"end":3495.817,"text":"Gee, I'm sorry, Audrey."},{"start":3495.842,"end":3497.662,"text":"Give me to eat!"},{"start":3497.701,"end":3500.185,"text":"If you can't control yourself, I'm going home."},{"start":3500.21,"end":3502.334,"text":"I need some chow."},{"start":3504.468,"end":3506.827,"text":"Ooh, my empty stomach."},{"start":3508.109,"end":3510.414,"text":"Audrey, please wait. Listen to me."},{"start":3510.508,"end":3513.43,"text":"I've listened to all the nonsense I wanna hear, Seymour."},{"start":3513.664,"end":3514.727,"text":"You're a nut."},{"start":3514.801,"end":3518.279,"text":"You tell me that you love me and then you you act like a complete idiot."},{"start":3518.28,"end":3519.82,"text":"Please listen, Audrey."},{"start":3519.883,"end":3522,"text":"I'll be able to explain everything soon."},{"start":3522.15,"end":3524.095,"text":"Why can't you explain now?"},{"start":3524.697,"end":3526.806,"text":"Because so many things are so important."},{"start":3527.283,"end":3528.423,"text":"I wanna marry you."},{"start":3528.548,"end":3530.368,"text":"But I gotta take care of mom."},{"start":3530.595,"end":3533.204,"text":"Well, that plant in there is gonna make it all come true."},{"start":3533.958,"end":3536.458,"text":"Tomorrow they're gonna give me a trophy and I'll be famous."},{"start":3536.591,"end":3538.099,"text":"I'll be a big botanist."},{"start":3538.552,"end":3541.231,"text":"And then we can go to the South Seas just like we planned and all."},{"start":3541.256,"end":3544.349,"text":"But that doesn't have anything to do with what went on in there."},{"start":3545.052,"end":3547.388,"text":"When you're ready to come to your senses, Seymour,..."},{"start":3547.716,"end":3549.115,"text":"... then I'll talk to you."},{"start":3549.778,"end":3550.949,"text":"Good night, Seymour."},{"start":3559.662,"end":3561.271,"text":"Feed."},{"start":3562.122,"end":3563.802,"text":"I'm getting pretty tired of you."},{"start":3564.006,"end":3565.912,"text":"I need food."},{"start":3565.951,"end":3567.224,"text":"I don't care what you need."},{"start":3567.287,"end":3568.498,"text":"Look what you've done to me."},{"start":3568.568,"end":3571.404,"text":"You not only made a butcher outta me, you drove my girl away."},{"start":3571.45,"end":3573.982,"text":"Shut up, and bring on the food!"},{"start":3574.426,"end":3576.278,"text":"Don't tell me to shut up - you shut up!"},{"start":3577.044,"end":3578.847,"text":"Who raised you from a bunch of little seeds?"},{"start":3579.004,"end":3582.859,"text":"Who fed you all them high-class fertilizers and sat up with you when you were sick?"},{"start":3583.223,"end":3585.012,"text":"Nodody else would have done that for you."},{"start":3585.073,"end":3588.011,"text":"You think anybody else would have brought you human beings to eat?"},{"start":3588.362,"end":3589.714,"text":"Darm right, they wouldn't."},{"start":3590.077,"end":3592.756,"text":"Well, I've helped you and you've helped me."},{"start":3592.781,"end":3595.031,"text":"Now shut your trap and go to sleep. I'm tired."},{"start":3595.187,"end":3596.187,"text":"Krelborn!"},{"start":3596.905,"end":3597.905,"text":"Turn around!"},{"start":3600.28,"end":3601.764,"text":"Close your eyes."},{"start":3603.538,"end":3605.21,"text":"You are asleep."},{"start":3606.444,"end":3607.78,"text":"Open your eyes."},{"start":3609.1,"end":3611.322,"text":"Now you will do as I say."},{"start":3611.405,"end":3612.756,"text":"Will you follow me?"},{"start":3612.842,"end":3614.038,"text":"Yes, master."},{"start":3614.318,"end":3618.646,"text":"You will go out and find me some food!"},{"start":3618.959,"end":3620.185,"text":"Yes, master."},{"start":3620.326,"end":3621.771,"text":"Now begone."},{"start":3622.192,"end":3623.864,"text":"And waste no time."},{"start":3644.551,"end":3645.551,"text":"Idiot!"},{"start":3685.995,"end":3687.995,"text":"My name is Leonora Clyde."},{"start":3688.665,"end":3690.581,"text":"How's the rain on the rhubarb?"},{"start":3691.88,"end":3693.706,"text":"Master is hungry."},{"start":3703.392,"end":3704.759,"text":"Well, hello there."},{"start":3735.148,"end":3737.46,"text":"I gotta find food for master."},{"start":3738.187,"end":3740.21,"text":"Food I gotta find for master."},{"start":3741.147,"end":3743.716,"text":"For master I gotta find food."},{"start":3744.897,"end":3746.42,"text":"Maybe I can help."},{"start":3747.264,"end":3749.935,"text":"- Who're you? - My name is Leonora Clyde."},{"start":3749.96,"end":3751.365,"text":"I love you."},{"start":3752.515,"end":3754.366,"text":"Master wants food."},{"start":3754.765,"end":3756.413,"text":"Let the old goat wait."},{"start":3756.491,"end":3758.827,"text":"The night is young and so are we."},{"start":3759.069,"end":3760.757,"text":"Master doesn't eat goat."},{"start":3765.308,"end":3768.089,"text":"Well what kind of food does he like?"},{"start":3770.855,"end":3771.987,"text":"Oooh."},{"start":3772.777,"end":3774.192,"text":"That's more like it."},{"start":3774.217,"end":3775.217,"text":"Kiss me!"},{"start":3779.122,"end":3781.059,"text":"What's the matter, don't you like me?"},{"start":3781.333,"end":3782.575,"text":"Too bony."},{"start":3782.613,"end":3783.719,"text":"Too bony?"},{"start":3783.72,"end":3785.292,"text":"Nobody ever told me that before."},{"start":3785.317,"end":3787.152,"text":"Beef is better than veal."},{"start":3787.848,"end":3788.848,"text":"Ach."},{"start":3788.91,"end":3790.395,"text":"You're such a dodo."},{"start":3790.511,"end":3792.863,"text":"What do you call this? Chopped liver?"},{"start":3793.754,"end":3794.754,"text":"Mmm."},{"start":3795.339,"end":3796.738,"text":"Haha."},{"start":3797.074,"end":3799.121,"text":"Master would like more fat."},{"start":3799.394,"end":3801.315,"text":"Speak for yourself, John."},{"start":3803.167,"end":3804.639,"text":"My name is Seymour."},{"start":3804.752,"end":3806.393,"text":"\"My name is Seymour.\""},{"start":3806.651,"end":3808.003,"text":"That's my name, too."},{"start":3808.893,"end":3812.221,"text":"Ach. Are you interested are you just wasting my time?"},{"start":3812.573,"end":3814.745,"text":"I never thought anybody would volunteer."},{"start":3814.886,"end":3816.05,"text":"Do you volunteer?"},{"start":3816.144,"end":3817.48,"text":"Sure I do."},{"start":3818.042,"end":3820.674,"text":"Alright, if you're sure you want to... volunteer."},{"start":3821.057,"end":3823.159,"text":"Alright. My place or yours?"},{"start":3823.321,"end":3824.415,"text":"I don't care."},{"start":3824.721,"end":3826.667,"text":"Well,... flip a coin."},{"start":3827.073,"end":3828.448,"text":"I don't have a coin."},{"start":3828.995,"end":3830.635,"text":"Flip anything, silly."},{"start":3831.285,"end":3832.69,"text":"Well, there's a rock."},{"start":3835.456,"end":3836.822,"text":"Wet or dry?"},{"start":3836.901,"end":3837.901,"text":"Wet."},{"start":3855.869,"end":3856.962,"text":"The search was narrowing..."},{"start":3857.197,"end":3859.228,"text":"... and we knew that soon we would have the killer."},{"start":3859.751,"end":3861.782,"text":"Not that we had any more clues than before."},{"start":3861.892,"end":3863.517,"text":"But we had to tell the chief something."},{"start":3863.726,"end":3866.765,"text":"I had that feeling in my bones that the mystery was drawing to its climax."},{"start":3866.852,"end":3868.665,"text":"And I was determined to be on hand."},{"start":3869.719,"end":3871.015,"text":"Alright. Out, out, out."},{"start":3871.04,"end":3872.047,"text":"Nobody is in."},{"start":3872.072,"end":3874.625,"text":"Today we have a special occasion for Seymour Krelborn..."},{"start":3874.65,"end":3876.515,"text":"... which has invented a big plant."},{"start":3876.54,"end":3879.001,"text":"So I want everybody just please stay out of the way."},{"start":3879.026,"end":3882.258,"text":"We want Seymour! We want Seymour!"},{"start":3882.282,"end":3883.978,"text":"We want Seymour!"},{"start":3889.79,"end":3894.047,"text":"I tell you, this business is worse than being a conductor in a revoluting door."},{"start":3894.103,"end":3896.204,"text":"I'll be glad when this day is finished."},{"start":3896.229,"end":3897.385,"text":"But the celebration!"},{"start":3897.41,"end":3899.775,"text":"They're presenting my son with a trophy."},{"start":3899.903,"end":3901.557,"text":"Yeah? What'd he do - run away from home?"},{"start":3901.869,"end":3903.713,"text":"Please don't look at me that way, Audrey."},{"start":3903.854,"end":3905.088,"text":"I wanna talk to you."},{"start":3905.432,"end":3906.736,"text":"I'm sorry Seymour."},{"start":3907.401,"end":3909.057,"text":"I just don't understand you."},{"start":3909.082,"end":3911.135,"text":"I'll explain everything after the ceremony."},{"start":3911.16,"end":3913.074,"text":"Yo! Police - what are you doing here?"},{"start":3913.099,"end":3914.777,"text":"Heard there was something going on here this evening."},{"start":3914.802,"end":3916.644,"text":"Just so, we'd keep come by, keep an eye on things"},{"start":3916.669,"end":3919.24,"text":"Look we don't need no eyes kept on nothing. Everything..."},{"start":3919.265,"end":3922.123,"text":"The Society Of Silent Flower Observers has arrived..."},{"start":3922.148,"end":3924.308,"text":"and sunset is almost upon us."},{"start":3924.53,"end":3926.288,"text":"Welcome, lady and gentlemen."},{"start":3926.351,"end":3928.586,"text":"We are honoured for to have you."},{"start":3929.476,"end":3930.976,"text":"Still working on those disappearances."},{"start":3931.132,"end":3932.187,"text":"We think they were murdered."},{"start":3932.212,"end":3933.578,"text":"Hey, look here young man."},{"start":3933.603,"end":3935.462,"text":"That's no way to talk at a time like this."},{"start":3935.525,"end":3936.775,"text":"Let me see your tongue."},{"start":3937.329,"end":3938.392,"text":"M-hm."},{"start":3938.422,"end":3939.494,"text":"You know what you got?"},{"start":3939.519,"end":3940.587,"text":"Just the facts, ma'am."},{"start":3940.652,"end":3941.452,"text":"Trench mouth."},{"start":3941.597,"end":3943.323,"text":"Oh, I know, I had it back in '09."},{"start":3943.348,"end":3945.828,"text":"- Better have that looked into, Frank. - Whatever you say, Joe."},{"start":3947.144,"end":3948.402,"text":"Mr. Krelborn?"},{"start":3948.529,"end":3951.513,"text":"Uh, the sun is going down now and, uh..."},{"start":3952.208,"end":3954.64,"text":"... you do think those buds are going to open?"},{"start":3955.021,"end":3956.138,"text":"I hope so."},{"start":3956.184,"end":3958.825,"text":"Because if they don't, Mr. Krelborn,..."},{"start":3958.95,"end":3961.66,"text":"... we shall just have to present the award at another time."},{"start":3961.832,"end":3964.16,"text":"Oh! It's starting to open!"},{"start":3965.707,"end":3966.707,"text":"Remarkable!"},{"start":3968.879,"end":3971.676,"text":"Oh. Well, the first bud is open."},{"start":3976.917,"end":3978.519,"text":"- Isn't that... - The railroad cop."},{"start":3978.745,"end":3979.761,"text":"Look at the rest."},{"start":3990,"end":3991.859,"text":"Aaaah!"},{"start":3992.968,"end":3993.968,"text":"What do you think, Frank?"},{"start":3994.001,"end":3995.323,"text":"They're all there, Joe."},{"start":3995.548,"end":3996.548,"text":"Yes, you're right."},{"start":3996.672,"end":3998.703,"text":"Mr. Krelborn, how do you explain this?"},{"start":3998.728,"end":4000.251,"text":"I didn't mean it. I didn't mean it!"},{"start":4000.276,"end":4002.509,"text":"That's right, officer. He didn't mean to kill them."},{"start":4002.666,"end":4003.533,"text":"Oh!"},{"start":4003.626,"end":4006.072,"text":"Seymour, you promised you'd explain."},{"start":4006.532,"end":4007.821,"text":"He's getting away, Joe."},{"start":4007.846,"end":4009.915,"text":"Yes, you're right. Let's catch him."},{"start":4010.117,"end":4011.117,"text":"Right."},{"start":4015.968,"end":4019.21,"text":"- Oh, now the float will be perfect! - Yeah."},{"start":4210.56,"end":4212.99,"text":"You wouldn't find him here with the toilets."},{"start":4213.155,"end":4214.561,"text":"Let's go back."},{"start":4237.005,"end":4240.065,"text":"You dirty rat plant. You messed up my whole life!"},{"start":4240.397,"end":4243.811,"text":"Feed meeeee!"},{"start":4244.155,"end":4245.561,"text":"I'll feed you."},{"start":4249.262,"end":4251.895,"text":"I'll feed you like you've never been fed before."},{"start":4274.693,"end":4276.411,"text":"Better to give up, gentlemen."},{"start":4277.169,"end":4278.895,"text":"You wouldn't find him tonight."},{"start":4278.926,"end":4280.965,"text":"Look. The door is open, Frank."},{"start":4287.659,"end":4289.665,"text":"He was such a good boy."},{"start":4293.573,"end":4295.081,"text":"Seymour!"},{"start":4295.479,"end":4297.042,"text":"I didn't mean it."}]},{"id":"nasa-water-cycle","type":"video","title":"The Water Cycle: Taking the Pulse of Our Planet","creator":"NASA · Dr. Gail Skofronick Jackson","year":2014,"level":"C1","category":"real","genre":"documentary","durationSeconds":430,"summaryTr":"Yağmur, kar, okyanus ve uydular: Dünya’daki suyun hareketini görsellerle açıklayan kısa bir bilim konuşması. Teknik açıklama ve sunum dilini çalış.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. Akademik sunum dili, su döngüsü terimleri, yoğun neden-sonuç açıklamaları ve verilerin sözlü yorumlanması vardır. 2014 tarihli konuşmada sayılar ve görev planları o dönemi yansıtır.","videoUrl":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Gail_Skofronick_Jackson.2014_ipod_lg.m4v","qualities":[{"label":"240p","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Gail_Skofronick_Jackson.2014_ipod_sm.mp4","sizeMB":42},{"label":"360p","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Gail_Skofronick_Jackson.2014_ipod_lg.m4v","sizeMB":85},{"label":"540p","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Gail_Skofronick_Jackson.2014_appletv.m4v","sizeMB":214}],"downloadable":false,"source":{"name":"NASA Goddard — The Water Cycle: Taking the Pulse of Our Planet","url":"https://svs.gsfc.nasa.gov/11668/#media_group_344475","watchUrl":"https://svs.gsfc.nasa.gov/11668/#media_group_344475","license":"NASA medya kullanım koşulları · Eğitim amaçlı kullanım","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","credit":"NASA's Goddard Space Flight Center · NASA · Dr. Gail Skofronick Jackson","creditNoteTr":"Özgün video ve jenerik değiştirilmeden oynatılır."},"subtitleSource":{"name":"NASA — resmî İngilizce WebVTT altyazısı","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Gail_Skofronic_Jackson.en_US.vtt","license":"NASA medya kullanım koşulları","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","changeNoteTr":"Sözler ve kaynak zamanları korunmuştur; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür. Kaynak altyazıda yazım veya aktarım hataları bulunabilir."},"glossary":{"aquifer":"yeraltı suyu taşıyan tabaka","aquifers":"yeraltı suyu taşıyan tabakalar","precipitation":"yağış","evaporation":"buharlaşma","condensation":"yoğuşma","salinity":"tuzluluk","circulation":"dolaşım","spaceborne":"uzaydan çalışan; uzaya taşınmış","constellation":"burada: birlikte çalışan uydu grubu","blizzard":"tipi; şiddetli kar fırtınası","biosphere":"biyosfer; canlıların yaşadığı katman"},"captions":[{"start":0.01,"end":4.03,"text":"[Applause]"},{"start":4.03,"end":8.09,"text":"[Applause]"},{"start":8.09,"end":12.11,"text":"Thank you! Our Earth is a water planet"},{"start":12.11,"end":16.18,"text":"from the oceans, ice, rivers, lakes"},{"start":16.18,"end":20.33,"text":"and aquifers to the water suspend in our atmosphere,"},{"start":20.33,"end":24.38,"text":"our Earth is definitely a water planet. Take a look at"},{"start":24.38,"end":28.44,"text":"our lovely Earth? Did you know that 99.5% of that water"},{"start":28.44,"end":32.47,"text":"is stored in our salty seas or locked up in glaciers"},{"start":32.47,"end":36.48,"text":"and other inaccessible locations, leaving precious little fresh water"},{"start":36.48,"end":40.52,"text":"available to support our life on Earth?"},{"start":40.52,"end":44.58,"text":"So one of the vital signs of our Earth is the water cycle"},{"start":44.58,"end":48.61,"text":"and understanding it and knowing it will help us to monitor our"},{"start":48.61,"end":52.78,"text":"freshwater resources and we can do this by measuring"},{"start":52.78,"end":56.8,"text":"where, how the water moves within our planet"},{"start":56.8,"end":60.86,"text":"and I will talk about that today."},{"start":60.86,"end":64.92,"text":"This is a cartoon of our water cycle. It shows the"},{"start":64.92,"end":68.95,"text":"linkages between the surface water, condensation,"},{"start":68.95,"end":72.99,"text":"precipitation, and evaporation. The water cycle is a"},{"start":72.99,"end":77.06,"text":"complex system that drives the movement of water and actually"},{"start":77.06,"end":81.1,"text":"heat and energy around our planet;"},{"start":81.1,"end":85.15,"text":"let's start by exploring the role of our deep and vast oceans"},{"start":85.15,"end":89.23,"text":"in the water cycle. As you can see in this visualization"},{"start":89.23,"end":93.27000000000001,"text":"of satellite data, the"},{"start":93.27000000000001,"end":97.34,"text":"ocean surface temperatures are not uniform around the oceans."},{"start":97.34,"end":101.46000000000001,"text":"The warm waters is in red and the cool waters"},{"start":101.46000000000001,"end":105.47,"text":"is in blue; drive the movement of water and heat"},{"start":105.47,"end":109.57,"text":"throughout the oceans which can in turn then influence our"},{"start":109.57,"end":113.59,"text":"weather patterns such as might be saying during El Niño and"},{"start":113.59,"end":117.61,"text":"La Niña Years. Also, driving the movement of water"},{"start":117.61,"end":121.66,"text":"in our oceans is salinity. As shown in this"},{"start":121.66,"end":125.68,"text":"visualization of Aquarius satellite data from NASA"},{"start":125.68,"end":129.73,"text":"where evaporation occurs, our oceans get saltier,"},{"start":129.73,"end":133.75,"text":"it's shown in red, where precipitation falls, ice melts"},{"start":133.75,"end":137.78,"text":"or rivers discharge our oceans get fresher as shown in the"},{"start":137.78,"end":141.88,"text":"blue. As your ocean water becomes saltier it"},{"start":141.88,"end":145.92000000000002,"text":"becomes more dense and settles down to the bottom of the ocean and"},{"start":145.92000000000002,"end":149.99,"text":"vice versa for the less salty water which rises to the top."},{"start":149.99,"end":154.06,"text":"Taken together, surface temperatures,"},{"start":154.06,"end":158.19,"text":"salinity and also the ocean winds, the winds"},{"start":158.19,"end":162.22,"text":"above the ocean, combine in a complex stance"},{"start":162.22,"end":166.27,"text":"that drives the ocean circulation patterns as shown here."},{"start":166.27,"end":170.37,"text":"The oceans also store massive amounts of heat"},{"start":170.37,"end":174.4,"text":"and are very slow to release it which makes them"},{"start":174.4,"end":178.43,"text":"a major driver in our Earth's climate system."},{"start":178.43,"end":182.47,"text":"The oceans and the atmosphere actually"},{"start":182.47,"end":186.5,"text":"work together. Without the oceans, the water stays"},{"start":186.5,"end":190.54,"text":"on surface and we need the atmosphere as well."},{"start":190.54,"end":194.57,"text":"For example, intense sunlight in the tropics"},{"start":194.57,"end":198.64,"text":"causes evaporation from the salty oceans"},{"start":198.64,"end":202.75,"text":"and that water forms in to massive clouds. Those"},{"start":202.75,"end":206.79,"text":"massive clouds, that are moved by the atmospheric winds to the"},{"start":206.79,"end":210.88,"text":"mid-latitudes where precipitation occurs either in the form of rain"},{"start":210.88,"end":214.98,"text":"or snow. The only way to get a global perspective"},{"start":214.98,"end":219.05,"text":"of precipitation patterns is to measure from spaceborne"},{"start":219.05,"end":223.07999999999998,"text":"platforms. Six months ago NASA and the Japan"},{"start":223.07999999999998,"end":227.14,"text":"Aerospace Exploration Agency launched our"},{"start":227.14,"end":231.23,"text":"joint Global Precipitation Measurement Core Observatory Satellite"},{"start":231.23,"end":235.26,"text":"or GPM for short."},{"start":235.26,"end":239.32999999999998,"text":"With two advanced instruments, the Core Observatory for the first time is able"},{"start":239.32999999999998,"end":243.35,"text":"to measure all phases of precipitation from very, very"},{"start":243.35,"end":247.4,"text":"heavy rain to light rain to falling snow."},{"start":247.4,"end":251.48,"text":"The GPM spacecraft serves as an anchor"},{"start":251.48,"end":255.5,"text":"to a domestic and international constellation of satellite"},{"start":255.5,"end":259.54,"text":"partners, which collectively provide precipitation"},{"start":259.54,"end":263.6,"text":"estimates everywhere in the world every three hours,"},{"start":263.6,"end":267.68,"text":"in essence taking the pulse of the"},{"start":267.68,"end":271.72,"text":"planet's precipitation."},{"start":271.72,"end":275.78,"text":"This imagery shows one of the very first events"},{"start":275.78,"end":279.92,"text":"measured by the GPM spacecraft."},{"start":279.92,"end":283.94,"text":"It was one of the late-season falling snow events"},{"start":283.94,"end":288.02,"text":"here in East Coast on March 17. The resulting"},{"start":288.02,"end":292.13,"text":"7 inches of snow in the Washington DC area may have"},{"start":292.13,"end":296.18,"text":"affected your St. Patrick's Day plans this year."},{"start":296.18,"end":300.27,"text":"Off the coast of the Carolinas, the high cloud tops"},{"start":300.27,"end":304.29,"text":"are icy, down at the surface heavy rains shown in red"},{"start":304.29,"end":308.32,"text":"fell in the Atlantic Ocean. Further North, overland,"},{"start":308.32,"end":312.44,"text":"the storm has much lower cloud tops and they are composed of snow"},{"start":312.44,"end":316.46,"text":"shown in blue which fell at the surface and we can see this information"},{"start":316.46,"end":320.53,"text":"because the GPM spacecraft has two advanced instruments;"},{"start":320.53,"end":324.64,"text":"one of them which I like to call the x-ray through the clouds"},{"start":324.64,"end":328.66,"text":"measures the precipitation all way through the cloud and provides"},{"start":328.66,"end":332.73,"text":"what I would call an x-ray at the surface. It's a two-dimensional view of the precipitation."},{"start":332.73,"end":336.85,"text":"The other instrument on board is what I like to call"},{"start":336.85,"end":340.89,"text":"taking a CAT scan of the clouds and it takes layer by layer"},{"start":340.89,"end":344.97,"text":"within the clouds information about the precipitation that's vital for"},{"start":344.97,"end":348.99,"text":"helping us to understand precipitation and weather forecasting"},{"start":348.99,"end":353.04,"text":"and climate models."},{"start":353.04,"end":357.08,"text":"So we're very excited about this data. Where else but"},{"start":357.08,"end":361.1,"text":"NASA with our partners, are we able to achieve"},{"start":361.1,"end":365.14,"text":"such success so early in the mission. GPM"},{"start":365.14,"end":369.23,"text":"also uses this data for applications to provide societal"},{"start":369.23,"end":373.33,"text":"benefit. GPM observes hurricanes and blizzards but as"},{"start":373.33,"end":377.35,"text":"shown in the top two panels here, we are also able to look at the"},{"start":377.35,"end":381.38,"text":"conditions that might lead to landslides and floods. On"},{"start":381.38,"end":385.49,"text":"the other hand for trial and water availability maps as"},{"start":385.49,"end":389.67,"text":"shown in the bottom two images, we need to know how little it has"},{"start":389.67,"end":393.73,"text":"precipitated over time and GPM can tell us that too."},{"start":393.73,"end":397.75,"text":"Emergency management then can use this data in near real time"},{"start":397.75,"end":401.76,"text":"to make evacuation plans."},{"start":401.76,"end":405.87,"text":"Precipitation in the water cycle influences"},{"start":405.87,"end":409.90999999999997,"text":"every person, every day, everywhere,"},{"start":409.90999999999997,"end":414.05,"text":"may be one of the greatest impacts of NASA's data"},{"start":414.05,"end":418.08,"text":"is just used in improving weather forecasting models and climate"},{"start":418.08,"end":422.1,"text":"change models for our everyday lives and our long-term future."},{"start":422.1,"end":426.18,"text":"Now I would like introduce Lola who is going to talk about"},{"start":426.18,"end":429.64300000000003,"text":"the pulse of our planet's biosphere."}]},{"id":"his-girl-friday","type":"video","title":"His Girl Friday","creator":"Howard Hawks","year":1940,"level":"C2","category":"fun","genre":"comedy","durationSeconds":5518,"summaryTr":"Bir muhabir mesleği bırakıp yeni bir hayat kurmak ister; eski eşi ve editörü ise onu son bir büyük habere çekmeye çalışır. İğneli mizah, haber kovalamaca ve hiç durmayan atışmalarla dolu bir komedi.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. C2 için zorlayıcı bir dinleme seçkisidir: çok hızlı ve üst üste konuşma, dönem argosu, gazetecilik ve hukuk dili, alay, ima ve söz oyunları vardır. Altyazı ve tekrar önerilir.","advisoryTr":"İdam, intihar, cinayet suçlaması ve dönemin ayrımcı ifadeleri içerir.","videoUrl":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fb/His_Girl_Friday_%281940%29.webm/His_Girl_Friday_%281940%29.webm.480p.vp9.webm","qualities":[{"label":"240p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fb/His_Girl_Friday_%281940%29.webm/His_Girl_Friday_%281940%29.webm.240p.vp9.webm","sizeMB":176},{"label":"480p","url":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fb/His_Girl_Friday_%281940%29.webm/His_Girl_Friday_%281940%29.webm.480p.vp9.webm","sizeMB":491}],"source":{"name":"Wikimedia Commons — His Girl Friday","url":"https://commons.wikimedia.org/wiki/File:His_Girl_Friday_(1940).webm","watchUrl":"https://commons.wikimedia.org/wiki/File:His_Girl_Friday_(1940).webm","license":"Kamu malı (ABD)","licenseUrl":"https://commons.wikimedia.org/wiki/File:His_Girl_Friday_(1940).webm","credit":"Howard Hawks · Özgün film; Wikimedia Commons aktarımı","creditNoteTr":"Video, kaynak sürümüyle ve jeneriğiyle birlikte değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText%3AHis%20Girl%20Friday%20(1940).webm.en.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar altyazı sayfasının geçmişinde)","changeNoteTr":"Sözler ve zamanlar korunmuştur; biçim etiketleri kaldırılıp satırlar birleştirilerek zamanlar saniyeye dönüştürülmüştür."},"glossary":{"morgue":"morg","flesh":"et; vücudun yumuşak dokusu","boarding":"boarding house: pansiyon","feed":"beslemek","reporter":"muhabir","editor":"editör; yazı işleri müdürü","scoop":"atlatma haber; rakiplerden önce yayımlanan haber","reprieve":"cezanın ertelenmesi","sheriff":"şerif","bail":"kefalet","governor":"vali","exclusive":"özel; sadece bir yayıncıya verilen","racket":"burada: iş; gürültü; yasa dışı düzen","hildy":"Hildy (karakter adı)","walter":"Walter (karakter adı)"},"captions":[{"start":61.87,"end":65.08,"text":"(chattering)"},{"start":65.165,"end":67.583,"text":"MAN: Wait a minute. Copyboy!"},{"start":69.377,"end":72.29599999999999,"text":"-Make it snappy and hurry back. -Where's the rest of this story?"},{"start":72.38,"end":74.048,"text":"-Morning Post. -Morning Post."},{"start":74.132,"end":76.842,"text":"-City desk? Just a moment. I'll connect you. -Just a moment, please."},{"start":76.926,"end":79.511,"text":"If anybody asks for me, I'm down at the courthouse."},{"start":79.596,"end":81.93,"text":"-Morning Post. -Elevator! Going down!"},{"start":86.85300000000001,"end":89.688,"text":"-Hello, Hildy. -Oh, hi, Skinny."},{"start":89.773,"end":92.483,"text":"-Hello, Ruth. Hello, Maisie. -Hello, Hildy!"},{"start":92.56700000000001,"end":94.985,"text":"-Tell me, is the lord of the universe in? -Yes, he's in."},{"start":95.07,"end":97.655,"text":"-In a bad humor. -Somebody must have stolen the crown jewels."},{"start":97.739,"end":100.199,"text":"-Shall we announce you? -Oh, no, no, I'll blow my own horn."},{"start":100.99199999999999,"end":103.702,"text":"He's in, Bruce. You'd better wait here. I'll be back in ten minutes."},{"start":103.787,"end":106.747,"text":"Even ten minutes is a long time to be away from you."},{"start":107.832,"end":110.125,"text":"-What did you say? -Huh?"},{"start":110.87700000000001,"end":112.336,"text":"-Well ̶ -Go on."},{"start":112.42,"end":115.464,"text":"-Uh ̶ (chuckles) -Well, go ahead."},{"start":115.548,"end":118.926,"text":"I just said even ten minutes is a long time to be away from you."},{"start":119.00999999999999,"end":122.93,"text":"I heard you the first time. I like it. That's why I asked you to say it again."},{"start":123.014,"end":127.142,"text":"I can stand being spoiled a little. The gentleman I'm going in to see did very little spoiling."},{"start":127.227,"end":130.145,"text":"I'd like to spoil him just once. Sure you don't want me to go in with you?"},{"start":130.23,"end":132.481,"text":"-No, I can handle it. -If things get rough, remember I'm here."},{"start":132.565,"end":134.566,"text":"I'll come a-runnin', partner."},{"start":135.527,"end":137.444,"text":"-Well, hello, Jim. -Well, hello, Hildy."},{"start":137.529,"end":139.446,"text":"-How are you? -Hi, Hildy! Welcome back!"},{"start":139.531,"end":143.409,"text":"-Hello, Hildy. How ya been? -Hi, Hildy."},{"start":143.493,"end":145.994,"text":"Oh, hello, Beatrice. How's \"Advice to the Lovelorn\"?"},{"start":146.079,"end":148.497,"text":"-Fine. My cat just had kittens again. -It's your own fault."},{"start":148.581,"end":150.666,"text":"-Hello, Hildy. Glad to see you back. -Glad to see you."},{"start":150.75,"end":154.461,"text":"-Hi, Tim. Mildred, he still around? -Oh, hello, Hildy."},{"start":154.546,"end":157.548,"text":"-(buzzing) -MAN: A little more around the chin, boss."},{"start":158.258,"end":161.677,"text":"-What do ya want? -Your ex-wife is here. Do you want to see her?"},{"start":162.595,"end":165.639,"text":"Well... Well, hello, Hildy."},{"start":165.724,"end":168.016,"text":"-Hello, Walter. -Hi, Hildy."},{"start":168.101,"end":170.686,"text":"Oh, hello, Louie. How's the fixed slot machine king?"},{"start":170.77,"end":174.148,"text":"Oh, I ain't doin' that no more. I'm retired. Ya know what I mean?"},{"start":174.232,"end":176.15,"text":"-Say, Walter ̶ Hello, Hildy. -I'm busy, Duffy."},{"start":176.234,"end":178.152,"text":"-Get going. I'm busy. -I thought you ought to know"},{"start":178.236,"end":180.154,"text":"-the governor didn't sign that reprieve. -What?"},{"start":180.238,"end":183.073,"text":"Tomorrow morning Earl Williams dies and makes a sucker out of us."},{"start":184.2,"end":186.869,"text":"-Well, what are you gonna do? -Get the governor on the phone."},{"start":186.953,"end":188.203,"text":"-I can't. -Why not?"},{"start":188.288,"end":191.373,"text":"-Can't locate him. He's out fishing. -How many places to fish are there?"},{"start":191.458,"end":193.292,"text":"At least two ̶ the Atlantic and Pacific."},{"start":193.376,"end":195.294,"text":"-All right. That simplifies it, doesn't it? -Oh, yeah."},{"start":195.378,"end":197.379,"text":"-Get him on the phone. -And tell him what?"},{"start":197.464,"end":199.673,"text":"HILDY: Quiet, Duffy, he's thinking."},{"start":199.758,"end":202.63400000000001,"text":"Tell him if he'll reprieve Earl Williams, we'll support him for senator."},{"start":202.761,"end":205.345,"text":"-What? -The Morning Post will be behind him hook, line and sinker."},{"start":205.43,"end":206.722,"text":"-You can't do that! -Why not?"},{"start":206.806,"end":209.475,"text":"Because we've been a Democratic paper for over 20 years."},{"start":209.559,"end":212.519,"text":"All right, after we get the reprieve, we'll be Democratic again."},{"start":212.60399999999998,"end":214.313,"text":"-Oh, Walter ̶ -Go on, Duffy! Get going!"},{"start":214.397,"end":217.483,"text":"Remember, the Morning Post expects every city editor to do his duty."},{"start":217.567,"end":219.94299999999998,"text":"-You too, Louie. Get outta here. -Okay, boss."},{"start":221.988,"end":224.406,"text":"-(Hildy chuckles) -WALTER: Mmm."},{"start":224.49099999999999,"end":226.909,"text":"Well, Walter, I see you're still at it."},{"start":226.993,"end":230.496,"text":"Yeah. First time I ever double-crossed a governor. What can I do for you?"},{"start":230.57999999999998,"end":232.414,"text":"Would you mind if I sat down?"},{"start":232.499,"end":235.626,"text":"There's been a lamp burning in the window for you, honey. Here."},{"start":235.71,"end":238.879,"text":"Oh, I jumped out that window a long time ago, Walter."},{"start":238.963,"end":240.964,"text":"(Walter chuckles)"},{"start":242.133,"end":244.13400000000001,"text":"Oh, may I have one of those?"},{"start":245.136,"end":246.762,"text":"Thank you."},{"start":248.848,"end":250.224,"text":"And a match."},{"start":251.226,"end":252.768,"text":"Thank you."},{"start":256.439,"end":259.983,"text":"-Well, well, how long is it? -How long is what?"},{"start":260.068,"end":263.779,"text":"You know what. How long is it since we've seen each other?"},{"start":264.656,"end":266.824,"text":"Oh, well, let's see."},{"start":266.908,"end":269.117,"text":"I spent six weeks in Reno, then Bermuda ̶"},{"start":269.202,"end":272.621,"text":"Oh, about four months, I guess. Seems like yesterday to me."},{"start":273.373,"end":275.123,"text":"Maybe it was yesterday, Hildy."},{"start":275.20799999999997,"end":277.41700000000003,"text":"Been seeing me in your dreams?"},{"start":277.502,"end":279.461,"text":"No, no, Mama doesn't dream about you anymore."},{"start":279.546,"end":281.797,"text":"-You wouldn't know the old girl now. -Ah, yes, I would."},{"start":281.881,"end":285.217,"text":"-I'd know you anytime, anyplace ̶ -Anyplace, anywhere."},{"start":285.301,"end":288.846,"text":"You're repeating yourself, Walter. That's the speech you made the night you proposed."},{"start":288.93,"end":291.139,"text":"-I notice you still remember it. -Of course I remember it."},{"start":291.224,"end":293.141,"text":"If I didn't, I wouldn't have divorced you."},{"start":293.226,"end":295.644,"text":"-Sort of wish you hadn't done that, Hildy. -Done what?"},{"start":295.728,"end":298.814,"text":"Divorced me. It makes a fellow lose all faith in himself."},{"start":298.898,"end":301.817,"text":"Gives him a ̶ almost gives him a feeling he wasn't wanted."},{"start":301.901,"end":304.236,"text":"Oh, now look, Junior, that's what divorces are for."},{"start":304.32,"end":306.154,"text":"Nonsense. You've got an old-fashioned idea"},{"start":306.239,"end":308.907,"text":"divorce is something that lasts forever, till death do us part."},{"start":308.992,"end":311.326,"text":"Why, divorce doesn't mean anything nowadays, Hildy."},{"start":311.411,"end":314.079,"text":"Just a few words mumbled over you by a judge."},{"start":314.163,"end":316.832,"text":"We've got something between us nothing can change."},{"start":317.33299999999997,"end":320.961,"text":"-Mmm, well, I suppose you're right in a way. -Sure, I'm right."},{"start":321.045,"end":324.047,"text":"-I am fond of you, you know. -That-a-girl."},{"start":324.132,"end":326.592,"text":"-I often wish you weren't such a stinker. -Eh ̶"},{"start":327.927,"end":330.846,"text":"Latin, I suppose. You must meet my mother. She'd like that phrase."},{"start":330.93,"end":333.056,"text":"Then why did you promise not to fight the divorce"},{"start":333.141,"end":335.68399999999997,"text":"and do everything you possibly could to gum up the whole works?"},{"start":335.76800000000003,"end":338.02,"text":"I meant to let you go, but you know how it is."},{"start":338.104,"end":340.188,"text":"You never miss the water till the well runs dry."},{"start":340.273,"end":343.19100000000003,"text":"Oh, a big, fat lummox like you hiring an airplane"},{"start":343.276,"end":347.529,"text":"to write, \"Hildy, don't be hasty. Remember my dimple. Walter.\""},{"start":347.614,"end":350.24,"text":"Delayed our divorce 20 minutes while the judge went out to watch it."},{"start":350.325,"end":354.536,"text":"I don't want to brag, but I've still got the dimple, and in the same place."},{"start":354.621,"end":358.206,"text":"Look, Hildy, I only acted like any husband that didn't want to see his home broken up."},{"start":358.291,"end":360.709,"text":"-What home? -Don't you remember the home I promised you?"},{"start":360.793,"end":364.212,"text":"Sure, I do. That was the one we were to have right after the honeymoon."},{"start":364.297,"end":366.214,"text":"(laughs) That honeymoon."},{"start":366.299,"end":370.177,"text":"Was it my fault? Did I know that coal mine was gonna have another cave-in?"},{"start":370.261,"end":373.221,"text":"I intended to be with you on our honeymoon, Hildy. Honest, I did."},{"start":373.306,"end":376.558,"text":"All I know is that instead of two weeks in Atlantic City with my bridegroom,"},{"start":376.64300000000003,"end":379.728,"text":"I spent two weeks in a coal mine with John Kruptzky."},{"start":379.812,"end":382.397,"text":"-You don't deny that, do you, Walter? -Deny it? I'm proud of it!"},{"start":382.48199999999997,"end":384.9,"text":"-We beat the whole country on that story. -Suppose we did?"},{"start":384.984,"end":386.902,"text":"That isn't what I got married for!"},{"start":386.986,"end":389.738,"text":"Oh, what is the good of ̶ Look ̶ Now look, Walter."},{"start":389.822,"end":391.74,"text":"What I came up here to tell you"},{"start":391.824,"end":395.28499999999997,"text":"is that you must stop phoning me a dozen times a day, sending me 20 telegrams ̶"},{"start":395.37,"end":397.621,"text":"I write a beautiful telegram, don't I? Everybody says so."},{"start":397.705,"end":401.249,"text":"-Are you going to listen to what I have to say? -Look, what's the use of fighting, Hildy?"},{"start":401.334,"end":403.627,"text":"I tell you what ̶ come back to work on the paper."},{"start":403.711,"end":407.714,"text":"If we find we can't get along in a friendly fashion, we'll get married again."},{"start":407.799,"end":410.592,"text":"-What? -Certainly. I haven't any hard feelings."},{"start":410.677,"end":413.762,"text":"Oh, Walter, you're wonderful in a loathsome sort of way."},{"start":413.846,"end":416.64,"text":"Now please be quiet long enough for me to tell you what I came to say."},{"start":416.724,"end":418.68399999999997,"text":"-We'll have some lunch ̶ -I have a lunch date already."},{"start":418.76800000000003,"end":420.644,"text":"-Well, break it. -I cannot break it."},{"start":420.77,"end":424.189,"text":"-Take your hands off me! What are you playing, osteopath? -Temper, temper."},{"start":424.273,"end":428.735,"text":"Oh, listen, Walter, you are no longer my husband and no longer my boss."},{"start":428.82,"end":431.571,"text":"-And you're not going to be my boss. -What's that supposed to mean?"},{"start":431.656,"end":434.658,"text":"-Just what I say. -You're not coming back to the paper?"},{"start":434.742,"end":436.743,"text":"You are right, Mr. Burns, for the first time today."},{"start":436.828,"end":440.038,"text":"-Uh-huh. Got a better offer, huh? -You bet I've got a better offer."},{"start":440.123,"end":442.207,"text":"All right, go on. Take it. Work for somebody else."},{"start":442.291,"end":444.209,"text":"-That's the gratitude I get! -Stop hamming."},{"start":444.293,"end":448.714,"text":"What were you five years ago? A college girl from a school of journalism. A doll-faced hick!"},{"start":448.798,"end":450.674,"text":"You wouldn't take me if I hadn't been doll-faced."},{"start":450.758,"end":453.969,"text":"I thought it'd be a novelty ̶ a face around here a man could look at without shuddering."},{"start":454.053,"end":456.138,"text":"-Listen, Walter ̶ -I made a great reporter out of you, Hildy."},{"start":456.222,"end":458.64,"text":"But you won't be half as good on any other paper. We're a team!"},{"start":458.725,"end":461.14300000000003,"text":"-(imitating auctioneer) -You need me, I need you, the paper needs both of us!"},{"start":461.227,"end":463.645,"text":"-Sold, American! -Oh, all right, go ahead."},{"start":463.73,"end":465.731,"text":"-Listen, Walter, please. -Mm-hmm."},{"start":465.815,"end":469.276,"text":"The paper's gonna have to get along without me. So are you."},{"start":469.36,"end":470.902,"text":"Just didn't work out, Walter."},{"start":470.987,"end":474.781,"text":"Well, it would've worked out if you'd been satisfied with just being editor and reporter."},{"start":474.866,"end":476.992,"text":"But not you. You had to marry me, spoil everything."},{"start":477.076,"end":478.53499999999997,"text":"I wasn't satisfi ̶"},{"start":478.619,"end":480.996,"text":"-I suppose I proposed to you? -Well, you practically did."},{"start":481.08,"end":484.916,"text":"Making goo-goo eyes at me for two years until I broke down. \"Oh, Walter.\""},{"start":485.001,"end":487.085,"text":"I still claim I was tight the night I proposed."},{"start":487.17,"end":489.379,"text":"If you'd have been a gentleman, you'd have forgotten about it."},{"start":489.464,"end":491.173,"text":"-Why, you ̶ -You're losing your eye."},{"start":491.257,"end":492.758,"text":"You used to pitch better than that."},{"start":492.842,"end":494.76,"text":"Hello. Yeah. What?"},{"start":494.844,"end":496.803,"text":"Sweeney? What can I do for you?"},{"start":496.888,"end":499.765,"text":"What? Wait a minute. I'm not Sweeney. I'm Duffy."},{"start":499.849,"end":502.934,"text":"Listen, Sweeney, you can't do that to me! Not today of all days!"},{"start":503.019,"end":505.52,"text":"What's the matter with you? Are you loony?"},{"start":506.397,"end":509.608,"text":"Jumping Jehoshaphat! Now listen, Sweeney, this is no time ̶"},{"start":511.027,"end":513.445,"text":"Oh, all right, I suppose so."},{"start":513.529,"end":515.947,"text":"Yes, if you have to, you have to."},{"start":516.032,"end":518.575,"text":"-He had to. -Everything happens to me."},{"start":518.659,"end":521.953,"text":"365 days in the year, and this has to be the day."},{"start":522.038,"end":523.538,"text":"-What's the matter, Walter? -Sweeney."},{"start":523.623,"end":525.415,"text":"-Dead? -He might just as well be."},{"start":525.5,"end":528.418,"text":"The only man on the paper that can write, and he picks today to have a baby!"},{"start":528.503,"end":530.128,"text":"He didn't do it on purpose, did he?"},{"start":530.213,"end":533.34,"text":"I don't care! He's supposed to be covering the Earl Williams case. And where is he?"},{"start":533.424,"end":536.426,"text":"Walking up and down in a hospital. Is there no sense of honor in this country?"},{"start":536.511,"end":539.012,"text":"-Haven't you got anybody else? -No."},{"start":539.097,"end":541.348,"text":"No, there's nobody else on the paper that can write."},{"start":541.432,"end":542.849,"text":"This will break me."},{"start":542.934,"end":545.143,"text":"Unless ̶ Hildy."},{"start":545.228,"end":548.438,"text":"-No. Not a chance. Don't bother me. -You gotta help me just this once."},{"start":548.523,"end":550.941,"text":"-Get outta here, Duffy. I'm busy! Now look ̶ -Save your breath."},{"start":551.025,"end":553.235,"text":"This will bring us back together, the way we used to be."},{"start":553.319,"end":555.278,"text":"That's what I'm afraid of ̶ \"Anytime, anyplace, anywhere!\""},{"start":555.363,"end":558.949,"text":"This is bigger than anything that ever happened to us! Don't do it for me. Do it for the paper."},{"start":559.033,"end":562.369,"text":"-Scram, Svengali. -If you won't do it for love, how about money?"},{"start":562.453,"end":564.454,"text":"Forget the other offer. I'll raise you 25 bucks a week."},{"start":564.539,"end":567.541,"text":"-Listen to me, you bumble-headed baboon. -Thirty-five bucks and not a cent more."},{"start":567.625,"end":569.417,"text":"-Walter, are you gonna listen? -Good grief!"},{"start":569.502,"end":572.003,"text":"-How much is that other paper gonna pay you? -There isn't any other paper."},{"start":572.088,"end":575.132,"text":"Oh. Well, in that case, the raise is off. You go back to your old salary."},{"start":575.216,"end":577.342,"text":"-Trying to blackjack me ̶ -I want to show you something."},{"start":577.426,"end":579.344,"text":"-I'm busy. -It's a ring. Take a good look."},{"start":579.428,"end":581.721,"text":"You know what it is? It's an engagement ring."},{"start":584.684,"end":586.393,"text":"Engagement ring?"},{"start":586.477,"end":588.103,"text":"Uh-huh."},{"start":589.355,"end":593.191,"text":"I tried to tell you right away, but you would start reminiscing."},{"start":594.068,"end":595.443,"text":"I'm getting married, Walter,"},{"start":595.528,"end":599.656,"text":"and I'm also getting as far away from the newspaper business as I can get."},{"start":599.74,"end":602.367,"text":"-What? -(chuckles) I am through."},{"start":602.451,"end":604.828,"text":"Get married all you want, but you can't quit the newspaper business."},{"start":604.912,"end":607.956,"text":"-Oh, why not? -I know what quitting would mean to you."},{"start":608.04,"end":610.125,"text":"-What would it mean? -It would kill you!"},{"start":610.209,"end":612.46,"text":"-You can't sell me that, Walter Burns. -Who says I can't?"},{"start":612.545,"end":614.546,"text":"-You're a newspaperman. -That's why I'm quitting."},{"start":614.63,"end":617.716,"text":"-I want to go someplace where I can be a woman. -You mean be a traitor."},{"start":617.8,"end":619.801,"text":"-A traitor to what? -A traitor to journalism."},{"start":619.886,"end":623.346,"text":"-You're a journalist, Hildy! -A journalist? Now, what does that mean?"},{"start":623.431,"end":626.391,"text":"Peeking through keyholes? Chasing after fire engines?"},{"start":626.475,"end":629.144,"text":"Waking people up to ask them if Hitler's gonna start another war?"},{"start":629.228,"end":631.146,"text":"Stealing pictures off old ladies?"},{"start":631.23,"end":632.939,"text":"I know all about reporters, Walter."},{"start":633.024,"end":635.483,"text":"A lot of daffy buttinskies running around without a nickel in their pockets"},{"start":635.568,"end":638.486,"text":"so a million hired girls and motormen's wives will know what's going on."},{"start":638.571,"end":640.322,"text":"Why, I ̶"},{"start":640.406,"end":642.699,"text":"Oh, what's the use?"},{"start":642.783,"end":646.1610000000001,"text":"Walter, you wouldn't know what it means to... well, to want to be respectable"},{"start":646.245,"end":648.705,"text":"and live a halfway normal life."},{"start":650.0409999999999,"end":652.5,"text":"The point is, I ̶ I'm through."},{"start":654.587,"end":656.63,"text":"Where'd you meet this man?"},{"start":656.7139999999999,"end":658.798,"text":"-Bermuda. -Rich, huh?"},{"start":658.883,"end":662.677,"text":"He's not what you call rich. Makes about 5,000 a year."},{"start":662.762,"end":665.68,"text":"-What's his line? -He's in the insurance business."},{"start":665.765,"end":667.515,"text":"-Insurance business? -Uh-huh."},{"start":667.6,"end":670.518,"text":"-That's a good, honest business, isn't it? -Oh, certainly, it's honest."},{"start":670.603,"end":672.52,"text":"It's also adventurous. It's romantic."},{"start":672.605,"end":675.899,"text":"Listen, Hildy, I can't picture you being surrounded by policies."},{"start":675.983,"end":678.86,"text":"Well, I can, and I like it, what's more."},{"start":678.945,"end":681.529,"text":"Besides, he forgets the office when he's with me."},{"start":681.614,"end":684.866,"text":"He doesn't treat me like an errand boy either. He treats me like a woman."},{"start":684.951,"end":688.2860000000001,"text":"He does, does he? Mm-hmm. How did I treat you? Like a water buffalo?"},{"start":688.371,"end":691.206,"text":"I don't know from water buffaloes, but I do know about him."},{"start":691.29,"end":693.667,"text":"-He's kind and sweet and considerate. -(mocking, high-pitched) Mm-hmm."},{"start":693.751,"end":695.877,"text":"-He wants a home and children. -(chuckles)"},{"start":695.962,"end":698.63,"text":"Sounds more like a guy I ought to marry. What's his name?"},{"start":698.7139999999999,"end":701.049,"text":"Uh, Baldwin. Bruce Baldwin."},{"start":701.133,"end":703.051,"text":"Baldwin, Baldwin. Oh, I knew a Baldwin once."},{"start":703.135,"end":705.47,"text":"A horse thief in Mississippi. Couldn't be the same fellow, could it?"},{"start":705.554,"end":708.932,"text":"You're now talking about the man I'm marrying tomorrow."},{"start":710.017,"end":712.602,"text":"Tomorrow? As soon as that?"},{"start":712.687,"end":714.312,"text":"Mm-hmm."},{"start":717.191,"end":720.568,"text":"Well, at last I got out what I came up here to tell you."},{"start":722.154,"end":725.532,"text":"Guess there isn't any more to the story."},{"start":725.616,"end":728.451,"text":"-So long, Walter. -So long, Hildy."},{"start":728.536,"end":731.288,"text":"-And better luck to you next time. -Thanks."},{"start":732.123,"end":734.374,"text":"-Oh, Hildy. -Huh?"},{"start":734.458,"end":739.462,"text":"Uh... well, you kind of took the wind out of my sails."},{"start":740.256,"end":743.925,"text":"Look, honey, I just want to wish you everything I couldn't give you."},{"start":744.01,"end":745.302,"text":"Thank you, Walter."},{"start":746.345,"end":750.724,"text":"This other fellow ̶ Well, I'm sorry I didn't get a chance to see him."},{"start":750.808,"end":753.977,"text":"I'm more or less particular about whom my wife marries."},{"start":754.061,"end":758.273,"text":"-Where is he? -He's right on the job, waiting for me out there."},{"start":758.357,"end":760.608,"text":"Oh. Do you mind if I meet him?"},{"start":760.693,"end":762.777,"text":"Oh, no, Walter. It wouldn't do any good, really."},{"start":762.862,"end":765.53,"text":"-You're not afraid, are you? -Afraid? Of course not."},{"start":765.614,"end":768.199,"text":"Well, then, come on. Let's see this paragon."},{"start":768.284,"end":770.452,"text":"-Is he as good as you say? -Why, he's better."},{"start":770.5360000000001,"end":772.746,"text":"-Then what does he want with you? -Oh, now you got me."},{"start":772.83,"end":774.873,"text":"Back in an hour, Mildred."},{"start":774.957,"end":777.25,"text":"Oh! Oh, I am sorry, Hildy."},{"start":777.335,"end":778.918,"text":"-I suppose Bruce ̶ What's his name? -Baldwin."},{"start":779.003,"end":780.754,"text":"-I suppose he opens doors for you. -He does."},{"start":780.838,"end":784.09,"text":"-When he's with a lady, he takes his hat off. -Oh, I am sorry."},{"start":784.175,"end":786.634,"text":"And when he walks with a lady, he waits for her."},{"start":786.719,"end":788.636,"text":"Oh, well, in that case ̶"},{"start":790.556,"end":792.057,"text":"Allow me."},{"start":794.727,"end":798.772,"text":"Well, I can see right away my wife picked out the right husband for herself."},{"start":798.856,"end":802.025,"text":"-How do you do, sir? -Must be some mistake. I'm already married."},{"start":802.109,"end":804.402,"text":"Already married? (clicks tongue)"},{"start":805.363,"end":808.698,"text":"Oh, Hildy, you should've told me. Congratulations again, Mr. Baldwin."},{"start":808.783,"end":810.158,"text":"-No, my name is ̶ -Mr. Burns."},{"start":810.242,"end":813.328,"text":"Excuse me. I'm terribly busy. Just leave your card. What did you say?"},{"start":813.412,"end":815.038,"text":"-Mr. Burns. Mr. Burns. -My name is ̶"},{"start":815.122,"end":817.624,"text":"Some other time. I'm busy with Mr. Bruce Baldwin here."},{"start":817.708,"end":820.293,"text":"-I didn't hear what you said. -I was going to say that my name ̶"},{"start":820.378,"end":823.546,"text":"-Look, what is it with you? -I'm Bruce Baldwin."},{"start":823.631,"end":825.215,"text":"-Oh, you're Bruce Baldwin. -Yes."},{"start":825.299,"end":828.635,"text":"-Well, who is he? Who are you? -My name's Pete Davis."},{"start":828.719,"end":831.304,"text":"-Mr. Davis, is this any concern of yours? -No."},{"start":831.389,"end":833.973,"text":"From now on I'll thank you to keep your nose out of my affairs."},{"start":834.058,"end":835.934,"text":"And don't let it happen again."},{"start":836.018,"end":840.188,"text":"Mr. Baldwin, I'm sorry about this mistake. This is indeed a pleasure."},{"start":840.272,"end":842.023,"text":"Oh, that's wrong, isn't it?"},{"start":842.108,"end":844.401,"text":"Well, Bruce ̶ You don't mind if I call you Bruce?"},{"start":844.485,"end":847.32,"text":"-After all, we're practically related. -No, not at all."},{"start":847.405,"end":850.156,"text":"You see, my wife ̶ That is, your wife ̶ I mean, Hildy ̶"},{"start":850.241,"end":853.535,"text":"Hildy, you led me to expect you were marrying a much older man."},{"start":853.619,"end":855.87,"text":"Oh, really? What did I say that led you to expect such ̶"},{"start":855.955,"end":858.623,"text":"Don't worry about it. I realize you didn't mean old in years."},{"start":858.707,"end":860.75,"text":"(chuckles)"},{"start":860.835,"end":864.337,"text":"-You always carry an umbrella, Bruce? -Well, it looked a little cloudy this morning."},{"start":864.422,"end":866.172,"text":"That's right. Rubbers too, I hope."},{"start":867.091,"end":869.801,"text":"Attaboy. A man ought to be prepared for any emergency."},{"start":869.885,"end":872.595,"text":"-I think we'd better be running along. -Yes, we'd better be going."},{"start":872.68,"end":875.723,"text":"-Where are we going? -I'm taking you two to lunch. Didn't you tell him?"},{"start":875.808,"end":879.018,"text":"-No, she didn't. -I guess she wanted to surprise you."},{"start":879.103,"end":881.479,"text":"After you. After you, Hildy."},{"start":881.564,"end":884.274,"text":"You're wasting your time. It won't do a bit of good."},{"start":884.358,"end":886.693,"text":"No, I'm glad to do it. Glad to do it."},{"start":890.156,"end":891.948,"text":"Well, hello, Gus."},{"start":892.032,"end":895.243,"text":"-Don't tell me it's you, Hildy. -It's none other. How have things been?"},{"start":895.327,"end":897.078,"text":"-I can't complain. -I can. I'm hungry."},{"start":897.163,"end":899.164,"text":"Get me a roast beef sandwich. Rare on white ̶ Oh."},{"start":899.248,"end":901.708,"text":"-Sorry. -On white bread. Over there, Bruce."},{"start":901.792,"end":904.419,"text":"-You, Hildy? -I'll have the same, I guess."},{"start":904.503,"end":907.005,"text":"-You, sir? -Yes, that's all right for me."},{"start":907.089,"end":909.924,"text":"-Bring some mustard too, Gus. -Yes, sir."},{"start":910.009,"end":912.302,"text":"Ah, well, well, well."},{"start":912.386,"end":914.971,"text":"-So, you two are gonna get married, huh? -(Bruce chuckles)"},{"start":915.055,"end":917.932,"text":"-Well, how's it feel, Bruce? -Feels awful good. Yes, sir."},{"start":918.017,"end":921.186,"text":"-You're getting a great little girl. -I realize that."},{"start":921.27,"end":925.857,"text":"Things have been different for me ever since I met Hildy. I've never met anyone like her."},{"start":925.941,"end":927.942,"text":"Everybody else I've ever known,"},{"start":928.027,"end":932.113,"text":"well, you could always tell ahead of time what they were gonna say or do."},{"start":932.198,"end":936.034,"text":"But Hildy's not like that. You can't tell that about her."},{"start":936.118,"end":938.7860000000001,"text":"-That's nice. -Yes. You're getting something else too."},{"start":938.871,"end":941.873,"text":"-You're getting a great newspaperman. -No orchids, Walter."},{"start":941.957,"end":945.752,"text":"One of the best I ever knew. Sorry to see her go. Darn sorry, Hildy."},{"start":945.836,"end":948.129,"text":"-I'd like to believe you meant that. -I do mean it."},{"start":948.2139999999999,"end":950.298,"text":"If you ever want to come back to the newspaper business ̶"},{"start":950.382,"end":951.966,"text":"Which I won't."},{"start":952.051,"end":956.054,"text":"Ah, well, in spite of everything, if I ever do, there's only one man I'd work for."},{"start":956.138,"end":959.724,"text":"-I'd kill you if you ever worked for anybody else. -Hear that, Bruce? That's my diploma."},{"start":959.808,"end":962.519,"text":"It must be quite a business if it's ̶"},{"start":962.603,"end":966.189,"text":"-Hildy, are you sure you want to quit? -What do you mean?"},{"start":966.273,"end":969.609,"text":"I mean, if there's any doubt about it, or if there's anything that ̶"},{"start":969.693,"end":974.489,"text":"No. This is your chance to have a home and to be, like you said, a human being."},{"start":974.573,"end":979.077,"text":"-And I'm going to make you take that chance. -Certainly. Why, I wouldn't let her stay."},{"start":979.1610000000001,"end":983.665,"text":"No, she deserves all this happiness, Bruce, all the things I couldn't give her."},{"start":983.749,"end":987.502,"text":"-Yeah, all she ever wanted was a home. -I'll certainly try to give her one."},{"start":987.586,"end":990.338,"text":"-I know you will. Where you gonna live? -Albany."},{"start":990.422,"end":993.466,"text":"-Albany, huh? Got a family up there? -Just my mother."},{"start":993.551,"end":996.01,"text":"Just your mother, huh? Mmm. You're gonna live with your mother?"},{"start":996.095,"end":998.304,"text":"Well, just for the first year."},{"start":998.389,"end":1000.974,"text":"Oh, well, that will be nice. Yes, yes."},{"start":1001.058,"end":1003.726,"text":"A home with Mother. In Albany too."},{"start":1004.853,"end":1007.814,"text":"Mighty nice town, Albany. They've got the state capitol there."},{"start":1007.898,"end":1010.441,"text":"Yeah, I know. We were there once."},{"start":1014.28,"end":1017.991,"text":"Listen, will you ever forget the night you brought the governor back to the hotel?"},{"start":1018.075,"end":1021.786,"text":"You see, I was in taking a bath. I came walking out without ̶"},{"start":1021.87,"end":1023.288,"text":"(clears throat)"},{"start":1024.373,"end":1026.749,"text":"She didn't know I was in town."},{"start":1026.834,"end":1029.919,"text":"Well, uh, Bruce, how is business up there? Any better?"},{"start":1030.004,"end":1032.422,"text":"Well, Albany's a mighty good insurance town."},{"start":1032.506,"end":1036.843,"text":"-Most people there take it out early in life. -Yeah, well, I can see why they would."},{"start":1036.927,"end":1038.553,"text":"Statistics show that most of our policies̶"},{"start":1038.637,"end":1042.557,"text":"You know, I've got a feeling I ought to have taken out a little insurance."},{"start":1042.641,"end":1045.435,"text":"Course, that really doesn't matter now that Hildy and I have, uh ̶"},{"start":1045.519,"end":1049.856,"text":"Well, you know, we've, uh ̶ pfft. Does it? Or does it? What do you think?"},{"start":1049.94,"end":1053.067,"text":"Still, it might've been a good idea if we ̶ if I had."},{"start":1053.152,"end":1058.031,"text":"Well, I honestly feel that way. I figure I'm in one business that really helps people."},{"start":1058.115,"end":1061.367,"text":"Course, we don't help you much while you're alive, but afterward."},{"start":1061.452,"end":1062.869,"text":"-That's what counts. -Sure."},{"start":1062.953,"end":1064.579,"text":"(Hildy's foot bangs against table)"},{"start":1064.663,"end":1066.247,"text":"-I don't get it. -Ouch!"},{"start":1067.249,"end":1070.209,"text":"-Nice going. -I'm so sorry, Gus. My foot must've slipped."},{"start":1070.294,"end":1073.546,"text":"Oh. That's all right. What would you like to drink?"},{"start":1073.631,"end":1076.174,"text":"-Coffee, Gus. -Shall I put rum in? It's a nasty day."},{"start":1076.258,"end":1077.717,"text":"-Sure. -Me too, Gus, please."},{"start":1077.801,"end":1079.385,"text":"-And you, sir? -Not for me, thanks."},{"start":1079.47,"end":1082.138,"text":"-Go on, Bruce. -No, I have a lot to do this afternoon."},{"start":1082.222,"end":1085.516,"text":"-I have to buy the tickets, check the baggage. -Do it tomorrow. There's plenty of time."},{"start":1085.601,"end":1089.812,"text":"But we're leaving today at 4:00. Taking the sleeper for Albany."},{"start":1089.897,"end":1091.898,"text":"Oh. You, uh ̶"},{"start":1091.982,"end":1093.9,"text":"You're leaving today at 4:00, huh?"},{"start":1093.984,"end":1095.818,"text":"-Mm-hmm. -Say, that's only two hours."},{"start":1095.903,"end":1098.988,"text":"-Doesn't give us much time. -No, and I've got a lot to do ̶"},{"start":1099.073,"end":1101.991,"text":"Look at that! Isn't that silly? All down over my front."},{"start":1102.076,"end":1105.286,"text":"-That's nothing new. Here. -Never mind. Hey, Gus."},{"start":1105.371,"end":1107.455,"text":"Gus, do something about this, will you?"},{"start":1107.539,"end":1110.124,"text":"(whispering) Call me to the telephone as soon as I get back to the table."},{"start":1110.209,"end":1111.501,"text":"-Sure. -(normal voice) Thanks, Gus."},{"start":1111.585,"end":1113.544,"text":"That's fine. Thanks, it's fine."},{"start":1113.629,"end":1116.714,"text":"(clears throat) I'm terribly sorry about that. Silly, wasn't it?"},{"start":1116.799,"end":1120.802,"text":"Listen, Bruce, let me get that straight. I must've misunderstood you."},{"start":1120.886,"end":1123.805,"text":"You're taking the sleeper today and then getting married tomorrow?"},{"start":1123.889,"end":1127.016,"text":"-Oh, well, it's not like that. -Well, what is it like?"},{"start":1127.101,"end":1129.602,"text":"Oh, poor Walter. He'll toss and turn all night."},{"start":1129.687,"end":1132.105,"text":"Perhaps we'd better tell him Mother's coming along too."},{"start":1132.189,"end":1135.441,"text":"-Mother? Your mother kicked the bucket ̶ -No, my mother. My mother."},{"start":1135.526,"end":1137.985,"text":"Oh, your m ̶ Well, that relieves my mind."},{"start":1138.07,"end":1140.321,"text":"It was cruel of us to let you suffer that way."},{"start":1140.406,"end":1142.949,"text":"Isn't Walter sweet? Always wanting to protect me."},{"start":1143.033,"end":1146.744,"text":"Well, I admit I wasn't much of a husband. But you can always count on me, Hildy."},{"start":1146.829,"end":1150.79,"text":"I don't think she'll need you, Mr. Burns. I aim to do most of the protecting myself."},{"start":1150.874,"end":1152.625,"text":"Mr. Burns, telephone."},{"start":1152.71,"end":1154.085,"text":"-For me? -Yes, sir."},{"start":1154.169,"end":1157.171,"text":"That's strange. Uh, pardon me."},{"start":1159.591,"end":1161.592,"text":"Hildy, he's not such a bad fellow."},{"start":1161.677,"end":1163.97,"text":"No. He should make some girl real happy."},{"start":1164.054,"end":1166.055,"text":"-Mm-hmm. -(whispering) Slaphappy."},{"start":1166.14,"end":1169.726,"text":"He's not the man for you. I can see that. But I sort of like him."},{"start":1169.81,"end":1171.561,"text":"He's got a lot of charm."},{"start":1171.645,"end":1175.106,"text":"Well, he comes by it naturally. His grandfather was a snake."},{"start":1176.65,"end":1179.152,"text":"Hello? Hello? Hey, Duffy, listen."},{"start":1179.236,"end":1182.4470000000001,"text":"Is there any way we can stop the 4:00 train to Albany from leaving town?"},{"start":1182.531,"end":1185.074,"text":"-We might dynamite it. -Could we?"},{"start":1185.159,"end":1188.369,"text":"Oh, well, maybe we couldn't. All right, now get this."},{"start":1188.454,"end":1192.415,"text":"Get ahold of Sweeney and send him out of town on a two-weeks vacation."},{"start":1192.499,"end":1195.46,"text":"All right, keep your shirt on. Hildy's coming back."},{"start":1195.544,"end":1198.212,"text":"She doesn't know it yet, but I promise you she's staying here."},{"start":1198.297,"end":1201.424,"text":"Tell Louie to stick around the office. I may need him. Good-bye."},{"start":1203.385,"end":1205.052,"text":"Thanks, Gus."},{"start":1205.137,"end":1207.388,"text":"-This is bad business. -What's the matter, Walter?"},{"start":1207.473,"end":1210.558,"text":"-Oh, the Earl Williams case. -I've been reading about that."},{"start":1210.642,"end":1212.685,"text":"-It's pretty bad. -What is the lowdown on it?"},{"start":1212.77,"end":1216.147,"text":"Simple, honey. Poor little dope who lost his job and went berserk."},{"start":1216.231,"end":1219.484,"text":"Shot a cop who was coming to quiet him down. They're gonna hang him tomorrow."},{"start":1219.568,"end":1220.902,"text":"-What a shame. -Your paper ̶"},{"start":1220.986,"end":1223.154,"text":"-You've been taking his side, haven't you? -Mm-hmm."},{"start":1223.238,"end":1226.616,"text":"If he was out of his mind, why doesn't the state just put him away?"},{"start":1226.7,"end":1229.327,"text":"It happened to be a colored policeman. You know what that means, Hildy."},{"start":1229.411,"end":1232.121,"text":"Mm-hmm. The colored vote's very important in this town."},{"start":1232.206,"end":1234.123,"text":"Especially with an election coming up three or four days."},{"start":1234.208,"end":1237.043,"text":"That mayor, he'd hang his own grandmother to be reelected."},{"start":1237.127,"end":1239.545,"text":"I should think you could just show that the man wasn't responsible."},{"start":1239.63,"end":1243.591,"text":"-That's not so easy. -Mmm, maybe it isn't so hard either."},{"start":1243.675,"end":1245.426,"text":"What do you mean, Hildy?"},{"start":1245.511,"end":1248.012,"text":"Don't they have to have another expert examine him before they hang him?"},{"start":1248.096,"end":1251.682,"text":"Sure. A bird named Egelhoffer is gonna do it. He'll say the same as the rest."},{"start":1251.767,"end":1254.143,"text":"-Suppose he does? -What's your scheme, Hildy?"},{"start":1254.228,"end":1258.815,"text":"Look, you get the interview with Earl Williams, print Egelhoffer's statement."},{"start":1258.899,"end":1262.318,"text":"And right alongside of it, you know, double column, run your interview."},{"start":1262.402,"end":1264.862,"text":"Alienist says he's sane. Interview shows he's goofy."},{"start":1264.947,"end":1267.615,"text":"Hildy, you could do it! You could save that poor devil's life."},{"start":1267.699,"end":1269.951,"text":"-Uh-uh-uh. No. -You could ̶ Oh, yeah."},{"start":1270.035,"end":1271.744,"text":"-You're going away. I forgot. -That's right."},{"start":1271.829,"end":1276.374,"text":"-How long would the interview take? -An hour. Another to write it. That's all."},{"start":1276.458,"end":1279.252,"text":"We could take the 6:00 train if it'd save a man's life."},{"start":1279.336,"end":1280.837,"text":"No, Bruce."},{"start":1280.921,"end":1284.006,"text":"If you want to save Earl Williams' life, you write the interview yourself."},{"start":1284.091,"end":1286.884,"text":"-You're still a good reporter. -You know I can't write that kind of thing."},{"start":1286.969,"end":1290.012,"text":"-It takes a woman's touch, that heart ̶ -Don't get poetic."},{"start":1290.097,"end":1293.182,"text":"Get Sweeney. He's the best man on the paper for that sob-sister stuff."},{"start":1293.267,"end":1298.187,"text":"Poor Sweeney. Duffy just told me his wife finally had twins. Isn't that terrible?"},{"start":1298.272,"end":1301.023,"text":"Sweeney went out to celebrate, and now we can't find him anymore."},{"start":1301.108,"end":1303.526,"text":"So, Sweeney has twins, Earl Williams gets hanged tomorrow."},{"start":1303.61,"end":1306.696,"text":"-Now, Walter, look ̶ -You argue with her."},{"start":1306.78,"end":1309.073,"text":"Otherwise you're going on a honeymoon with blood on your hands."},{"start":1309.157,"end":1310.908,"text":"How can you have happiness after that?"},{"start":1310.993,"end":1313.744,"text":"All through the years you'll remember that a man went to the gallows"},{"start":1313.829,"end":1316.414,"text":"because she was too selfish to wait two hours."},{"start":1316.498,"end":1318.833,"text":"Earl Williams' face will come between you on the train tonight"},{"start":1318.917,"end":1321.294,"text":"and at the preacher's tomorrow and all the rest of your lives."},{"start":1321.378,"end":1323.588,"text":"-Stop, Walter! The whole place'll hear you. -Stop what?"},{"start":1323.672,"end":1325.464,"text":"-What an act. -Huh? Huh?"},{"start":1325.549,"end":1329.302,"text":"I just remembered Sweeney was only married four months ago."},{"start":1329.386,"end":1332.388,"text":"(Walter snickers, laughs)"},{"start":1333.473,"end":1335.474,"text":"All right, Hildy, you win. I'm licked."},{"start":1335.559,"end":1338.686,"text":"-Then Mrs. Sweeney didn't have twins. -(Hildy chuckles)"},{"start":1338.77,"end":1343.566,"text":"-No, indeed. The twins were Walter's. All his. -Oh, it was nothing."},{"start":1343.65,"end":1346.569,"text":"Well, let's forget it. We'll start all over again."},{"start":1346.653,"end":1349.28,"text":"-I'll offer you two a business proposition. -We're not interested."},{"start":1349.364,"end":1353.034,"text":"-You'll be interested. You're a smart young man. -Don't listen. I know him from way back."},{"start":1353.118,"end":1356.579,"text":"Excuse me, will you? I'm talking to him. Now look, Bruce."},{"start":1356.663,"end":1360.499,"text":"Persuade Hildy to do the story and you can write out a fat insurance policy for me."},{"start":1360.584,"end":1363.711,"text":"Oh, no. I wouldn't use my wife for business purposes."},{"start":1363.795,"end":1364.921,"text":"Wait a minute, Bruce."},{"start":1365.005,"end":1367.465,"text":"-Walter, how big a policy? -Oh, $25,000."},{"start":1367.549,"end":1368.799,"text":"-What? -$50,000."},{"start":1368.884,"end":1372.094,"text":"-What's the commission on a $100,000 policy? -Around $1,000. But, Hildy ̶"},{"start":1372.179,"end":1375.097,"text":"What's wrong with $1,000? We could use that money."},{"start":1375.182,"end":1379.101,"text":"-How long would it take to get him examined? -I could get a doctor here in 20 minutes."},{"start":1379.186,"end":1381.52,"text":"-Well, get him. -You keep out of this."},{"start":1381.605,"end":1384.857,"text":"All right, Bruce, suppose you have Mr. Burns examined over in his office"},{"start":1384.942,"end":1387.86,"text":"and see what they'll allow on that old carcass of his."},{"start":1387.945,"end":1391.489,"text":"-Say, I'm better than I ever was. -It was never anything to brag about."},{"start":1391.573,"end":1395.451,"text":"Now look, Bruce, I'll go back and change. After you get the check, you phone me."},{"start":1395.535,"end":1398.329,"text":"I'll be in the press room at the criminal courts building."},{"start":1398.413,"end":1401.999,"text":"Walter, by the way, I think you'd better make that a certified check."},{"start":1402.084,"end":1405.544,"text":"-What do you think I am, a crook? -Yes. No certified check, no story. Get me?"},{"start":1405.629,"end":1409.048,"text":"-It'll be certified. Want my fingerprints? -No. I've still got those."},{"start":1409.132,"end":1411.133,"text":"Gus, how much do I owe you?"},{"start":1412.052,"end":1415.972,"text":"-Thank you, dear. Oh, Bruce ̶ -Oh, I'm sorry."},{"start":1416.056,"end":1419.225,"text":"-How much money have you got with you? -Everything we have ̶ $500."},{"start":1419.309,"end":1421.227,"text":"-Give me the $500. -I have to buy the tickets."},{"start":1421.311,"end":1423.854,"text":"I'll buy the tickets. I know what I'm doing."},{"start":1423.939,"end":1426.315,"text":"-He'll get you in a crap game or ̶ -I don't gamble."},{"start":1426.4,"end":1430.236,"text":"I know a lot of people that never did anything till they met Walter Burns."},{"start":1430.32,"end":1432.571,"text":"All right, but remember, it's everything we have."},{"start":1432.656,"end":1434.281,"text":"-I know. -WALTER: Oh, Bruce."},{"start":1434.366,"end":1435.825,"text":"-You got change of ten? -I just ̶"},{"start":1435.909,"end":1439.12,"text":"-See what I mean, don't you, Bruce? -I just gave everything I had to Hildy."},{"start":1439.204,"end":1440.913,"text":"-All I've got left is ̶ -Come on, Hildy."},{"start":1440.998,"end":1443.624,"text":"-Not me. Sign it. -Oh, all right."},{"start":1445.836,"end":1447.253,"text":"For the waiter."},{"start":1447.337,"end":1449.88,"text":"-(Bruce laughs) -Come on, Bruce. Really."},{"start":1453.552,"end":1455.72,"text":"-I'll open for a dime. -I'm in."},{"start":1455.804,"end":1458.347,"text":"-I'll stay. -Wilcox 3-400."},{"start":1458.432,"end":1460.391,"text":"-(phone ringing) -I'm in. Two."},{"start":1460.475,"end":1463.352,"text":"Take that, one of you birds. You ain't doing anything, Ernie."},{"start":1463.437,"end":1465.354,"text":"-I'll take two. -And one for the dealer."},{"start":1465.439,"end":1469.775,"text":"What's the matter with you guys? Crippled or something?"},{"start":1469.86,"end":1472.028,"text":"Press room. Huh? Wait a minute."},{"start":1472.112,"end":1474.405,"text":"Hello, Sarge. McCue talking. Hold the line, will ya."},{"start":1474.489,"end":1478.534,"text":"What? No, I told you this is the press room in the criminal courts building."},{"start":1478.618,"end":1480.536,"text":"Jake, new lead on the hanging."},{"start":1480.62,"end":1483.748,"text":"This alienist from New York, Dr. Max J. Egelhoffer ̶"},{"start":1483.832,"end":1485.332,"text":"Egelhoffer. Yeah."},{"start":1485.417,"end":1488.127,"text":"He's going to interview Williams in about half an hour in the sheriff's office."},{"start":1488.211,"end":1490.629,"text":"Must be about the tenth alienist they've put on Williams."},{"start":1490.714,"end":1494.091,"text":"If he wasn't crazy before, he would be by the time ten of those babies got through."},{"start":1494.176,"end":1495.468,"text":"Give me the desk."},{"start":1495.552,"end":1498.387,"text":"-Is this guy Egelhoffer any good? -Figure it out for yourself."},{"start":1498.472,"end":1501.724,"text":"He's the guy they sent to Washington to interview the brain trust."},{"start":1501.808,"end":1503.434,"text":"He said they were sane."},{"start":1503.518,"end":1507.021,"text":"-Here's the situation on the eve of the hanging. -I'll pick up a little fudge."},{"start":1507.105,"end":1509.815,"text":"This is Murphy. More slop on the hanging."},{"start":1509.9,"end":1512.443,"text":"A double guard has been thrown around the jail, municipal buildings,"},{"start":1512.527,"end":1514.403,"text":"railroad terminals and elevated stations"},{"start":1514.488,"end":1516.947,"text":"to prepare for the expected general uprising of radicals ̶"},{"start":1517.032,"end":1518.657,"text":"-Ready? -at the hour of execution."},{"start":1518.742,"end":1521.619,"text":"The sheriff has just put 200 more relatives on the payroll"},{"start":1521.703,"end":1525.915,"text":"to protect the city from the red army, which is leaving Moscow in a couple of minutes."},{"start":1525.999,"end":1530.044,"text":"Trouble is, when the real red menace shows, the sheriff will still be cryin' wolf."},{"start":1530.128,"end":1532.046,"text":"-What do ya got? -Is that good?"},{"start":1532.13,"end":1535.674,"text":"-HILDY: Sure looks good from here. -Hildy, when did you get back?"},{"start":1535.759,"end":1538.01,"text":"-Hi, Ernie. -Hiya, Hildy. Glad to see ya."},{"start":1538.095,"end":1540.888,"text":"-Where'd you get the hat? -I paid 12 bucks for that hat."},{"start":1540.972,"end":1543.432,"text":"-Going back to work? -It's just a farewell appearance."},{"start":1543.517,"end":1545.726,"text":"-I'm going into business for myself. -What doin'?"},{"start":1545.811,"end":1548.187,"text":"-I'm getting married tomorrow. -What? Again?"},{"start":1548.271,"end":1550.815,"text":"-She'll never learn. -Are we invited to the wedding?"},{"start":1550.899,"end":1553.734,"text":"-I might use you for a bridesmaid, Roy. -Uh-oh."},{"start":1553.819,"end":1556.904,"text":"-How are you, Murphy? -What are you gettin' married for, Hildy?"},{"start":1556.988,"end":1560.324,"text":"-None of your business. -You ain't foolin' us, are you, Hildy?"},{"start":1560.408,"end":1564.578,"text":"Look what I've got in here. Three tickets to Albany on the 6:00 train tonight."},{"start":1564.663,"end":1566.872,"text":"-What do you mean, three? -For me and my beau."},{"start":1566.957,"end":1570.709,"text":"-And hats off, boys, his sweet darling mom. -Oh, that's nice."},{"start":1570.794,"end":1573.963,"text":"-What kind of marriage is that? -It's gonna be all right. I'm gonna settle down."},{"start":1574.047,"end":1575.965,"text":"I'm through with the newspaper business."},{"start":1576.049,"end":1579.135,"text":"Can you picture Hildy singing lullabies and hanging out didies?"},{"start":1579.219,"end":1581.47,"text":"-Swapping lies over the back fence. -Sour grapes."},{"start":1581.555,"end":1583.472,"text":"She'll be back soon as she gets tired of beating rugs."},{"start":1583.557,"end":1585.474,"text":"-I'm not gonna beat any rugs. -(bell ringing)"},{"start":1585.559,"end":1588.602,"text":"Hey, that's Third and Jefferson. Isn't that where Central School is?"},{"start":1588.687,"end":1592.439,"text":"-No school this time of day. -What do you care? You quit."},{"start":1592.524,"end":1594.65,"text":"Just thought it might be a good fire, that's all."},{"start":1594.734,"end":1596.569,"text":"-(thuds) -What's that?"},{"start":1596.653,"end":1599.321,"text":"Just practicing for the Williams party in the morning."},{"start":1599.406,"end":1602.032,"text":"-Gonna miss a nice hanging, Hildy. -Not interested."},{"start":1602.117,"end":1604.118,"text":"Tell 'em to pipe down."},{"start":1608.498,"end":1612.877,"text":"Hey, keep quiet down there! How do you expect us to get any work done?"},{"start":1612.961,"end":1615.546,"text":"Aw, shut up!"},{"start":1615.63,"end":1617.798,"text":"Very little respect for the press around here."},{"start":1618.8,"end":1621.343,"text":"-Did anybody phone me? -Not that I know of."},{"start":1621.428,"end":1625.055,"text":"-Say, does Walter know you're gettin' married? -Just had lunch with him."},{"start":1625.14,"end":1628.225,"text":"-Does he know you're quittin'? -Yes, I told him. Any more questions?"},{"start":1628.31,"end":1630.394,"text":"-Shall I deal you in? -I haven't got time."},{"start":1630.478,"end":1632.438,"text":"I have to do a yarn on Williams."},{"start":1632.522,"end":1634.815,"text":"Did he know what he was doing when he fired that gun?"},{"start":1634.9,"end":1638.027,"text":"If you ask us, no. If you ask the state alienist, yes."},{"start":1638.111,"end":1640.321,"text":"-Who is he? What's he do? -He was a bookkeeper."},{"start":1640.405,"end":1644.241,"text":"He starts at $20 a week and after 14 years he gradually works himself up to 17.50."},{"start":1644.326,"end":1645.451,"text":"-Got more gum? -No."},{"start":1645.535,"end":1648.495,"text":"McClosky company goes out of business, and Williams loses his job."},{"start":1648.58,"end":1650.414,"text":"-Can't get another? -No."},{"start":1650.498,"end":1651.832,"text":"I'm in."},{"start":1651.917,"end":1653.584,"text":"So he starts hanging around the park,"},{"start":1653.668,"end":1657.504,"text":"listening to soapbox spellbinders making phony speeches and begins to believe 'em."},{"start":1657.589,"end":1659.131,"text":"And makes some of his own."},{"start":1659.216,"end":1661.05,"text":"-Up a dime. -I'm in."},{"start":1662.01,"end":1662.051,"text":"-(exhales sharply) Anything else, Doc? -No, that'll be about all, Mr. Burns."},{"start":1662.052,"end":1665.971,"text":"-(exhales sharply) Anything else, Doc? -No, that'll be about all, Mr. Burns."},{"start":1666.056,"end":1669.016,"text":"-Everything okay? -You have nothing to worry about."},{"start":1669.1,"end":1671.227,"text":"Good, good. How you doing, Bruce?"},{"start":1671.311,"end":1674.647,"text":"-Uh, there's just one more thing. -Good day, Mr. Burns, Mr. Baldwin."},{"start":1674.731,"end":1677.107,"text":"-Good-bye, Doc. Thanks very much. -Good day, Doc."},{"start":1677.192,"end":1680.069,"text":"-Who's the beneficiary? -Uh, excuse me? Excuse me?"},{"start":1680.153,"end":1683.489,"text":"That is, in case of your death, who do we pay the money to?"},{"start":1683.573,"end":1685.574,"text":"Why, Hildy, of course!"},{"start":1685.659,"end":1688.911,"text":"Aw, I don't know. That'd make me feel pretty funny."},{"start":1688.995,"end":1692.498,"text":"Oh, now, why shouldn't I make Hildy my, uh, whatever it was?"},{"start":1692.582,"end":1696.919,"text":"-I feel I should take care of her. -But you will take care of her, Bruce."},{"start":1697.003,"end":1700.047,"text":"Say, if that doctor's right, I'm good for a long time, yes?"},{"start":1700.131,"end":1703.425,"text":"Look, Bruce, this is a debt of honor with me."},{"start":1703.51,"end":1706.22,"text":"I was a bad husband to Hildy."},{"start":1706.304,"end":1709.89,"text":"She could've claimed a lot of alimony if she'd wanted to, but she wouldn't take any."},{"start":1709.975,"end":1712.142,"text":"She had it coming to her, but she was too independent."},{"start":1712.227,"end":1715.145,"text":"-Well, I'm independent too. -I know you are, Bruce. I know you are."},{"start":1715.23,"end":1717.69,"text":"But look, you just figure it this way."},{"start":1717.774,"end":1721.568,"text":"I'm good for, well, we'll say at least 25 years yet."},{"start":1721.653,"end":1725.906,"text":"By that time, you'll probably have made enough so that the money won't mean anything to you."},{"start":1725.991,"end":1727.908,"text":"But suppose you haven't made good, Bruce."},{"start":1727.993,"end":1730.661,"text":"What about Hildy's old age? Think of Hildy."},{"start":1730.745,"end":1733.163,"text":"Ah, I can see her now."},{"start":1733.248,"end":1736.625,"text":"White haired. Lavender and old lace."},{"start":1736.71,"end":1739.503,"text":"-Can't you see her, Bruce? -Yes. Yes, I can."},{"start":1739.587,"end":1741.422,"text":"She's old, isn't she?"},{"start":1741.506,"end":1744.425,"text":"Now, Bruce, don't you think that Hildy's entitled"},{"start":1744.509,"end":1748.012,"text":"to spend her last remaining years without worries of money?"},{"start":1748.096,"end":1751.807,"text":"-Of course you do, Bruce. -Of course, if you put it that way."},{"start":1752.517,"end":1755.102,"text":"WALTER: And remember, I love her too."},{"start":1756.271,"end":1759.106,"text":"Yes, I'm beginning to realize that."},{"start":1759.19,"end":1762.985,"text":"And the beauty of it is, she'll never have to know until I've passed on."},{"start":1764.446,"end":1767.531,"text":"WALTER: Oh, well, maybe she'll think kindly of me"},{"start":1767.615,"end":1769.95,"text":"after I'm gone."},{"start":1774.164,"end":1775.831,"text":"Gee."},{"start":1776.708,"end":1778.709,"text":"(blowing nose)"},{"start":1780.211,"end":1783.505,"text":"You make me feel like a heel comin' between ya."},{"start":1783.59,"end":1786.3,"text":"No, Bruce, you didn't come between us."},{"start":1786.384,"end":1788.969,"text":"It was all over for her before you came on the scene. For me ̶"},{"start":1789.054,"end":1792.139,"text":"-Hey, Walter. -It'll never be. What do you want?"},{"start":1792.223,"end":1794.767,"text":"Can I see you a minute, please?"},{"start":1795.727,"end":1797.311,"text":"Excuse me, Bruce."},{"start":1798.521,"end":1800.105,"text":"-Did you get it? -Yeah."},{"start":1800.19,"end":1802.024,"text":"-Where is it? Come on. -There."},{"start":1802.108,"end":1805.694,"text":"-Certified? -Sure. But, Walter, that's for $2,500."},{"start":1807.989,"end":1811.158,"text":"-Bruce, here we are, certified and everything. -Certified."},{"start":1812.035,"end":1817.414,"text":"Gosh, I'm afraid Hildy will feel ashamed to think she hasn't trusted you."},{"start":1817.499,"end":1819.625,"text":"-But she'll know someday. -Ah, yes."},{"start":1819.709,"end":1822.086,"text":"Bruce, you promised to phone her as soon as you got the check."},{"start":1822.17,"end":1824.171,"text":"Oh, yes, yes. Of course."},{"start":1824.255,"end":1827.383,"text":"Get me Hildy Johnson, press room, criminal courts building."},{"start":1827.467,"end":1830.803,"text":"-Sit down. The operator will get her for you. -Thank you."},{"start":1832.055,"end":1833.931,"text":"-Excuse me, will you? -Yes."},{"start":1834.015,"end":1837.393,"text":"Hello? Yes, I'll wait. Thank you."},{"start":1837.477,"end":1839.228,"text":"(ringing)"},{"start":1839.312,"end":1840.813,"text":"Start hollerin'."},{"start":1840.897,"end":1843.023,"text":"-Hildegarde. -Thank you."},{"start":1843.858,"end":1846.485,"text":"Hildy Johnson speaking. Oh, hello, Bruce."},{"start":1846.569,"end":1849.071,"text":"-I've got a dime left. -We've been playing for an hour!"},{"start":1849.155,"end":1851.407,"text":"Take it easy, will you?"},{"start":1851.491,"end":1854.952,"text":"Hello, Bruce. Did you get the check? Is it certified?"},{"start":1855.036,"end":1858.122,"text":"Certified and everything. I have it right in my pocket."},{"start":1858.206,"end":1860.374,"text":"Oh, in your pocket. That's fine."},{"start":1860.458,"end":1862.876,"text":"Wait. Maybe it isn't so fine. Bruce, where are you?"},{"start":1862.961,"end":1865.254,"text":"-I'm in Mr. Burns' office. -Is he there?"},{"start":1866.131,"end":1870.592,"text":"Look, Bruce, I don't want you to carry that check in your pocket."},{"start":1870.677,"end":1874.471,"text":"Well, because ̶ Yes, yes, I know all that, but, uh ̶"},{"start":1874.556,"end":1877.891,"text":"Bruce, there's an old newspaper superstition"},{"start":1877.976,"end":1881.061,"text":"that the first big check you get, you put in the lining of your hat."},{"start":1881.98,"end":1884.94,"text":"In your hat! It brings good luck."},{"start":1885.024,"end":1887.276,"text":"-I've never heard that before. -Neither did I."},{"start":1887.36,"end":1891.905,"text":"It sounds silly, but do it for me, please. Yes, yes, right now."},{"start":1891.99,"end":1894.074,"text":"(chuckling) All right. Just a minute."},{"start":1903.334,"end":1906.003,"text":"There you are. I've done it. Anything else?"},{"start":1907.13,"end":1912.092,"text":"Oh, yes. All right. Uh-huh."},{"start":1912.177,"end":1916.263,"text":"-Yes, yes, I'll tell him. Good-bye. -Everything all right?"},{"start":1916.347,"end":1918.807,"text":"-Hildy said to tell you she'll get right to work. -Fine."},{"start":1918.892,"end":1920.976,"text":"-Well, I must be going now. -All right."},{"start":1921.06,"end":1924.188,"text":"-Oh, Bruce, don't forget this. It might rain. -Oh, thanks."},{"start":1924.272,"end":1928.817,"text":"-You don't mind if I don't show you out? -No. Thanks for everything."},{"start":1928.902,"end":1931.028,"text":"-Excuse me, what'd you say? -I said, thanks for everything."},{"start":1931.112,"end":1934.156,"text":"Nonsense. Don't thank me. I should thank you."},{"start":1934.24,"end":1936.7,"text":"-So long. -So long."},{"start":1949.005,"end":1952.508,"text":"-Hello, Cooley. -Hello, Hildy. What are you doing here?"},{"start":1952.592,"end":1955.719,"text":"-I want an interview with Earl Williams. -Mm-mmm. No more interviews."},{"start":1955.8029999999999,"end":1956.97,"text":"-Why not? -Sheriff's orders."},{"start":1957.055,"end":1959.681,"text":"Besides, the doctor's coming over. Can't do it."},{"start":1959.766,"end":1961.266,"text":"Say, is this your money?"},{"start":1961.351,"end":1962.809,"text":"-I don't think it is ̶ -Twenty bucks."},{"start":1962.894,"end":1965.145,"text":"-Yeah, I guess maybe it is. -That's what I thought. Come on."},{"start":1965.23,"end":1967.856,"text":"Hey, Joe, open up here."},{"start":1967.941,"end":1969.983,"text":"-Now, Hildy, don't be ̶ -I won't be long."},{"start":1975.156,"end":1977.074,"text":"-Hello, Earl. -Hello."},{"start":1977.158,"end":1980.035,"text":"My name's Johnson. Mind if I talk to you for a few minutes?"},{"start":1980.119,"end":1983.789,"text":"-No. I haven't anything else to do. -I guess that's right."},{"start":1987.835,"end":1991.713,"text":"So, you see, I couldn't plead insanity because I'm just as sane as anybody else."},{"start":1991.798,"end":1994.258,"text":"-You didn't mean to kill that policeman, huh? -Why, of course not."},{"start":1994.342,"end":1996.343,"text":"It's against everything I've ever stood for."},{"start":1996.427,"end":1999.346,"text":"They know it was an accident. I'm not guilty."},{"start":1999.43,"end":2001.723,"text":"It's... It's just the world."},{"start":2002.684,"end":2006.019,"text":"I see what you mean. Sorry about the lipstick, Earl."},{"start":2006.104,"end":2009.523,"text":"Look, after you lost your job, what did you do?"},{"start":2009.607,"end":2013.36,"text":"-I tried to find another job. -I mean, how did you spend your time?"},{"start":2013.444,"end":2017.406,"text":"I used to sit around the park, anyplace. Oh, I don't smoke."},{"start":2017.49,"end":2020.492,"text":"When you were in the park, did you hear any of those speeches?"},{"start":2020.577,"end":2023.912,"text":"-You mean those fellas that talk too much? -Yeah."},{"start":2023.997,"end":2025.914,"text":"Well, I didn't pay any attention."},{"start":2025.999,"end":2028.25,"text":"-Did you hear anything they said? -Yes."},{"start":2028.334,"end":2031.712,"text":"Well, is there anything you remember? Anything in particular?"},{"start":2031.796,"end":2033.922,"text":"-There was one fella ̶ -What did he talk about?"},{"start":2034.007,"end":2037.593,"text":"-He talked about production for use. -Production for use."},{"start":2037.677,"end":2041.054,"text":"Yes, he said everything should be made use of."},{"start":2041.139,"end":2045.392,"text":"-Makes quite a bit of sense. -Yes. He was a good speaker."},{"start":2045.476,"end":2050.147,"text":"When you found yourself with that gun and that policeman coming at you,"},{"start":2050.231,"end":2052.399,"text":"-what did you think about? -I don't know exactly."},{"start":2052.483,"end":2055.694,"text":"You must've thought of something. Could it have been \"production for use\"?"},{"start":2055.778,"end":2059.406,"text":"-I don't know. I... -What's a gun for, Earl?"},{"start":2059.49,"end":2060.782,"text":"-A gun? -Mmm."},{"start":2060.867,"end":2063.577,"text":"-Why, to shoot, of course. -Oh."},{"start":2063.661,"end":2066.121,"text":"-And maybe that's why you used it. -Maybe."},{"start":2066.205,"end":2069.666,"text":"-Seems reasonable. -Yes. Yes, it is."},{"start":2069.751,"end":2072.21,"text":"I've never had a gun in my hand before."},{"start":2072.295,"end":2075.631,"text":"That's what a gun's for, isn't it? M-Maybe that's why."},{"start":2075.715,"end":2077.924,"text":"-Sure, it is. -Yes, that's what I thought of."},{"start":2078.009,"end":2079.468,"text":"Production for use."},{"start":2079.552,"end":2081.928,"text":"-It's simple, isn't it? -Very simple."},{"start":2082.013,"end":2084.806,"text":"-There's nothing crazy about that, is there? -No, nothing at all."},{"start":2084.891,"end":2087.559,"text":"-You'll write about that in your paper, won't you? -You bet I will."},{"start":2087.644,"end":2091.188,"text":"-Who sent you the roses? -Miss Mollie Malloy. She's a wonderful person."},{"start":2091.272,"end":2094.566,"text":"-That her picture? -Yes. She's beautiful, isn't she?"},{"start":2094.651,"end":2096.652,"text":"-COOLEY: Time's up, Hildy. -Oh, all right."},{"start":2097.945,"end":2101.156,"text":"-I guess that's all. -I like talking to you."},{"start":2101.24,"end":2102.949,"text":"Good-bye, Miss Johnson."},{"start":2103.951,"end":2105.911,"text":"Good-bye, Earl."},{"start":2105.995,"end":2107.496,"text":"Good luck."},{"start":2110.041,"end":2110.248,"text":"-Three landladies, boys. -You did well, didn't ya?"},{"start":2110.249,"end":2112.834,"text":"-Three landladies, boys. -You did well, didn't ya?"},{"start":2112.919,"end":2115.003,"text":"I wonder what the Post's gonna do without Hildy."},{"start":2115.088,"end":2117.422,"text":"Do you suppose Walter Burns will ever let her go?"},{"start":2117.507,"end":2120.133,"text":"Remember what he did to Bill Fenton when he wanted to go to Hollywood."},{"start":2120.218,"end":2122.26,"text":"-Had him thrown in jail for arson. -Forgery."},{"start":2122.345,"end":2123.595,"text":"-Was that it? -Yeah."},{"start":2123.68,"end":2126.014,"text":"-Gimme some change. -Hey, Mac."},{"start":2126.099,"end":2128.35,"text":"-Hey, Stairway Sam. -Huh?"},{"start":2128.434,"end":2130.477,"text":"-Would you mind turning on some lights? -Sure."},{"start":2130.561,"end":2132.479,"text":"So dark you can't see anything in this place."},{"start":2132.563,"end":2135.941,"text":"-Who's this guy Hildy's gonna marry? -I don't know. Bruce something."},{"start":2136.025,"end":2138.276,"text":"-I give the marriage six months. -Why?"},{"start":2138.361,"end":2140.862,"text":"Because she won't be able to stay away from the paper."},{"start":2140.947,"end":2142.864,"text":"Did you see her when that bell went off?"},{"start":2142.949,"end":2146.952,"text":"At that, it must be pretty nice to be able to walk out and quit."},{"start":2147.036,"end":2150.497,"text":"I had a publicity job offered to me last year. Should've taken it."},{"start":2150.581,"end":2152.791,"text":"That's what I'd like ̶ a job on the side."},{"start":2152.875,"end":2156.628,"text":"With a desk and a stenographer. I wouldn't mind a nice, big blonde."},{"start":2156.713,"end":2160.841,"text":"-With big brown eyes. -I'll bet 10-to-1 it don't last six months."},{"start":2160.925,"end":2163.844,"text":"She's just like us, and we wouldn't be stickin' around, waitin' for that guy ̶"},{"start":2163.928,"end":2166.722,"text":"-Well, well, Miss Mollie Malloy. -Hello, Mollie."},{"start":2166.806,"end":2169.641,"text":"-Hi, Mollie. How's tricks? -I've been lookin' for you tramps."},{"start":2169.726,"end":2172.102,"text":"-Come to pay a call on Williams? -He's right across the courtyard."},{"start":2172.186,"end":2174.438,"text":"-You'd better hurry up. -Nice roses you sent to Earl."},{"start":2174.522,"end":2176.523,"text":"What do you want done with 'em tomorrow morning?"},{"start":2176.607,"end":2179.443,"text":"-A lot of wise guys, ain't you? -You're breaking up the game, Mollie."},{"start":2179.527,"end":2181.611,"text":"-What do you want? -I came to ̶"},{"start":2183.114,"end":2186.867,"text":"-I came to tell ya what I think of all of ya. -Keep your shirt on."},{"start":2186.951,"end":2189.828,"text":"If you was worth breakin' my nails on, I'd tear your face wide open."},{"start":2189.912,"end":2193.749,"text":"What are you sore about? Wasn't that a swell story we gave ya?"},{"start":2193.833,"end":2197.085,"text":"You crumbs have been making a fool outta me long enough."},{"start":2197.17,"end":2200.756,"text":"I never said I loved Earl Williams and was willing to marry him on the gallows."},{"start":2200.84,"end":2202.09,"text":"You made that up."},{"start":2202.175,"end":2205.761,"text":"-And about my havin' a love nest with him. -You did, didn't you?"},{"start":2205.845,"end":2208.555,"text":"You've been sticking around that cuckoo ever since they threw him in the death house."},{"start":2208.639,"end":2211.641,"text":"-That's a lie! -Everybody knows you're his girlfriend."},{"start":2211.726,"end":2213.518,"text":"I met Mr. Williams just once in my life."},{"start":2213.603,"end":2214.895,"text":"-How many? -Two."},{"start":2214.979,"end":2218.523,"text":"When he was wandering around in the rain without his hat and coat on, like a sick dog."},{"start":2218.608,"end":2220.692,"text":"-The day before the shootin'. -Give me one."},{"start":2220.777,"end":2224.613,"text":"I went up to him like any human being would and I asked him what was the matter."},{"start":2224.697,"end":2228.784,"text":"And ̶ And he told me about bein' fired after bein' on the same job for 14 years."},{"start":2228.868,"end":2230.452,"text":"-Who bets? -Bet 20 cents."},{"start":2230.536,"end":2233.038,"text":"I brought him up to my room because it was warm there."},{"start":2233.122,"end":2235.081,"text":"MURPHY: Oh, put it on a phonograph."},{"start":2235.166,"end":2237.501,"text":"MOLLIE: Aw, listen to me, please!"},{"start":2237.585,"end":2241.588,"text":"I tell ya he just sat there talkin' to me all night."},{"start":2241.672,"end":2244.049,"text":"He never once laid a hand on me."},{"start":2244.133,"end":2249.012,"text":"And in the morning he went away, and I never saw him again till that day at the trial."},{"start":2249.096,"end":2251.807,"text":"-MOLLIE: Sure I was his witness! -WILSON: And what a witness."},{"start":2251.891,"end":2253.85,"text":"That's why you're persecutin' me!"},{"start":2253.935,"end":2256.978,"text":"Because Earl Williams treated me decent and not like an animal, and I said so!"},{"start":2257.063,"end":2259.981,"text":"-This is the press room. We're busy! -Go see your boyfriend."},{"start":2260.066,"end":2263.527,"text":"-Yeah, he's got a nice room. -He won't have it long. He left a call for 7:00 AM."},{"start":2263.611,"end":2267.531,"text":"(gasps) It's a wonder a bolt of lightning don't come down and strike you all dead!"},{"start":2267.615,"end":2269.741,"text":"(trap door slams)"},{"start":2279.001,"end":2280.21,"text":"What's that?"},{"start":2280.294,"end":2283.964,"text":"They're fixin' up a pain in the neck for your boyfriend."},{"start":2284.048,"end":2287.133,"text":"Shame on ya. Shame on ya!"},{"start":2287.218,"end":2291.513,"text":"(sobs) A poor little fella that never meant nobody no harm,"},{"start":2291.597,"end":2294.766,"text":"sittin' there this minute with the angel of death beside him, and you crack a joke?"},{"start":2294.851,"end":2296.601,"text":"All right, get outta here."},{"start":2296.686,"end":2299.229,"text":"-Take your hands off of me! -Come on, Mollie, let's get outta here."},{"start":2299.313,"end":2301.356,"text":"-They ain't human. -I know. They're newspapermen."},{"start":2301.44,"end":2304.86,"text":"All they've been doin' is lyin'. All they've been doin' is writin' lies!"},{"start":2304.944,"end":2307.946,"text":"-I know, Mollie. -Why won't they listen to me?"},{"start":2308.03,"end":2310.657,"text":"MOLLIE: Why won't they listen to me?"},{"start":2322.503,"end":2325.505,"text":"(rings)"},{"start":2327.55,"end":2331.511,"text":"Hello? Who? Hildy Johnson?"},{"start":2331.596,"end":2334.598,"text":"Hang on. She'll be back in a minute."},{"start":2337.643,"end":2340.061,"text":"-You guys wanna play any more cards? -No."},{"start":2340.146,"end":2342.647,"text":"What's the use? I can't win anyway."},{"start":2359.457,"end":2361.666,"text":"Gentlemen of the press."},{"start":2363.586,"end":2366.087,"text":"Hildy, phone for ya."},{"start":2368.132,"end":2369.674,"text":"Hello?"},{"start":2369.759,"end":2371.426,"text":"Oh, hello, Bruce."},{"start":2372.595,"end":2375.68,"text":"What? Where are you?"},{"start":2375.765,"end":2377.599,"text":"You're where?"},{"start":2377.683,"end":2381.394,"text":"Well, how did that happen? Never mind, never mind. I'll be right down."},{"start":2384.231,"end":2386.191,"text":"Oh! I'm sorry! Sorry!"},{"start":2386.275,"end":2388.944,"text":"-Ooh! Ow! -Hiya, Sheriff. How ya doin'?"},{"start":2389.028,"end":2392.781,"text":"My shin! My back! What's going on around here?"},{"start":2392.865,"end":2395.575,"text":"-Bruce was in trouble. -Lioness rushes to defend cub."},{"start":2395.66,"end":2398.078,"text":"-But ̶ -Man forgets hankie. Mama goes to wipe nose."},{"start":2398.162,"end":2402.499,"text":"-I still give that marriage six months. -I don't know what you fellas are talking about."},{"start":2402.583,"end":2405.627,"text":"-What do you want, Pete? -Oh, uh, uh ̶"},{"start":2405.711,"end":2407.921,"text":"I've got the tickets for the hanging here, boys."},{"start":2408.005,"end":2409.255,"text":"-Pete? -Huh? What?"},{"start":2409.34,"end":2413.218,"text":"Pete, why can't you hang this guy at 5:00 instead of 7:00?"},{"start":2413.302,"end":2415.72,"text":"It won't hurt you, and we can make the city edition."},{"start":2415.805,"end":2417.43,"text":"That's kinda raw, Roy."},{"start":2417.515,"end":2420.558,"text":"After all, I can't hang a man in his sleep just to please a newspaper."},{"start":2420.643,"end":2424.104,"text":"No, but you can reprieve him twice so the hanging's three days before election."},{"start":2424.188,"end":2426.564,"text":"You can run on a law-and-order ticket. You can do that."},{"start":2426.649,"end":2429.359,"text":"Honest, boys, I had absolutely nothing to do with those reprieves."},{"start":2429.443,"end":2431.611,"text":"Yeah? How do we know there won't be another reprieve tonight?"},{"start":2431.696,"end":2433.947,"text":"What if this Egelhoffer finds Williams insane?"},{"start":2434.031,"end":2436.199,"text":"He won't find him insane because he isn't."},{"start":2436.283,"end":2438.284,"text":"-He's just as sane as I am. -(together) Saner!"},{"start":2438.369,"end":2440.412,"text":"-(all chuckling) -Now, be serious, boys."},{"start":2440.496,"end":2444.165,"text":"After all, this is a hanging, and it's gonna go according to schedule."},{"start":2444.25,"end":2446.835,"text":"7:00 in the morning and not a minute earlier."},{"start":2446.919,"end":2449.254,"text":"After all, there's such a thing as being humane, you know."},{"start":2449.338,"end":2451.297,"text":"All right, Pinky, wait till you want a favor."},{"start":2451.382,"end":2453.925,"text":"-And please don't call me Pinky! -Why not?"},{"start":2454.01,"end":2456.72,"text":"Because I got a name, see, and it's Peter B. Hartwell."},{"start":2456.804,"end":2459.055,"text":"-What's the \"B\" for? -Bull."},{"start":2459.14,"end":2462.934,"text":"But I'm innocent. I didn't do anything. I never stole a watch in my life."},{"start":2463.019,"end":2465.311,"text":"I know you didn't, Bruce. All right, Mike. Let him out."},{"start":2465.396,"end":2468.69,"text":"I can't, Hildy. He's accused of stealing a watch, and they found the watch on him."},{"start":2468.774,"end":2471.151,"text":"-But I never stole ̶ -Please, Bruce. And who accused him?"},{"start":2471.235,"end":2473.486,"text":"-Diamond Louie, the biggest crook in town. -I know. It's no good, Hildy."},{"start":2473.571,"end":2475.655,"text":"-Don't \"Hildy\" me. Are you gonna let him out? -No."},{"start":2475.74,"end":2477.282,"text":"-I never stole ̶ -Bruce, please."},{"start":2477.366,"end":2479.951,"text":"All right, you're not. Well, perhaps you'd better read the Post in the morning."},{"start":2480.036,"end":2482.62,"text":"I can't imagine who'd do a thing like that to me."},{"start":2482.705,"end":2485.832,"text":"-I can't think of any enemies I have. -I'm sure you haven't any, Br ̶"},{"start":2485.916,"end":2489.044,"text":"-Have you got the check? -Oh, yes. I have it right here."},{"start":2489.128,"end":2492.172,"text":"That's a funny superstition you newspaper people have."},{"start":2492.256,"end":2494.09,"text":"Yes, isn't it?"},{"start":2494.175,"end":2498.47,"text":"About being arrested, at first I thought Walter Burns might have something to do with it."},{"start":2498.554,"end":2501.514,"text":"But then, of course, I realized he couldn't have."},{"start":2501.599,"end":2503.725,"text":"-Why? -Well, he's a very nice fellow, Hildy."},{"start":2503.809,"end":2506.102,"text":"-Oh! -Oh, yes. I found that out."},{"start":2506.187,"end":2509.105,"text":"-What's the matter? -I've lost my wallet!"},{"start":2509.19,"end":2513.693,"text":"Yes, well, Bruce, never mind. I have the money. You'd better give me the check too."},{"start":2513.778,"end":2516.404,"text":"-And that picture of us in Bermuda ̶ -Don't bother, Bruce."},{"start":2516.489,"end":2518.823,"text":"You'll find lots of things missing."},{"start":2521.452,"end":2524.287,"text":"No, Bruce dear, you wait here. I'm not taking any more chances."},{"start":2524.371,"end":2526.539,"text":"I'll be down in three minutes. We're taking the next train."},{"start":2526.624,"end":2528.041,"text":"Oh, sorry."},{"start":2529.168,"end":2531.586,"text":"\"And so into this little tortured mind"},{"start":2531.67,"end":2534.839,"text":"came the idea that that gun had been produced for use."},{"start":2534.924,"end":2536.716,"text":"And use it he did."},{"start":2536.801,"end":2541.054,"text":"But the state has a production-for-use plan too. It has a gallows."},{"start":2541.138,"end":2543.223,"text":"And at 7:00 AM, unless a miracle occurs,"},{"start":2543.307,"end":2547.685,"text":"that gallows will be used to separate the soul of Earl Williams from his body."},{"start":2547.77,"end":2552.148,"text":"And out of Mollie Malloy's life will go the one kindly soul she ever knew.\""},{"start":2553.234,"end":2555.902,"text":"-That's as far as she got. -(soft whistle)"},{"start":2555.986,"end":2559.739,"text":"-I ask you guys, can that girl write an interview? -She'll do till somebody else comes along."},{"start":2559.824,"end":2562.283,"text":"I don't think it's very ethical, reading other people's stuff."},{"start":2562.368,"end":2566.204,"text":"Where do you get that ethics stuff? You're the only one who'll swipe any of it."},{"start":2566.288,"end":2569.457,"text":"I still say that anybody that can write like that ain't gonna give it up permanently"},{"start":2569.542,"end":2572.377,"text":"to sew socks for a guy in the insurance business."},{"start":2572.461,"end":2575.588,"text":"Now I give that marriage three months, and I'm laying 3-to-1. Any takers?"},{"start":2575.673,"end":2576.923,"text":"HILDY: I'll take that bet."},{"start":2577.007,"end":2580.677,"text":"It's getting so a girl can't leave the room without being discussed by a bunch of old ladies."},{"start":2580.761,"end":2583.513,"text":"Hello, Post, get me Walter Burns, will you, please?"},{"start":2583.597,"end":2587.976,"text":"Don't get sore, Hildy. We were only saying a swell reporter like you wouldn't quit so easy."},{"start":2588.06,"end":2589.644,"text":"This is Hildy Johnson."},{"start":2589.728,"end":2592.147,"text":"I can quit, all right, without a single quiver."},{"start":2592.231,"end":2594.858,"text":"I'm gonna live like a human being, not like you chumps."},{"start":2594.942,"end":2597.402,"text":"Is that you, Walter? Oh, I've got some news for you."},{"start":2597.486,"end":2600.822,"text":"Yes, I got the interview, all right, but I've got some more important news."},{"start":2600.906,"end":2604.742,"text":"Perhaps you'd better get a pencil and take it down. All ready?"},{"start":2604.827,"end":2607.162,"text":"Now get this, you double-crossing chimpanzee."},{"start":2607.246,"end":2609.497,"text":"There ain't gonna be any interview, and there ain't gonna be any story."},{"start":2609.582,"end":2611.833,"text":"And that certified check of yours is leaving with me in 20 minutes."},{"start":2611.917,"end":2614.669,"text":"I wouldn't cover the burning of Rome for you if they were just lighting it up."},{"start":2614.753,"end":2617.088,"text":"If I ever lay my two eyes on you again, I'm gonna walk right up to you"},{"start":2617.173,"end":2620.341,"text":"and hammer on that monkey skull of yours till it rings like a Chinese gong."},{"start":2620.426,"end":2622.385,"text":"Oh, so you don't know why I'm angry with you?"},{"start":2622.469,"end":2625.18,"text":"Perhaps you'd better get Louie to tell you the story of his watch."},{"start":2625.264,"end":2627.473,"text":"There's just one other thing I want you to listen to."},{"start":2629.935,"end":2632.729,"text":"Hear that? That's the story I just wrote."},{"start":2632.813,"end":2636.941,"text":"Yes, I know we had a bargain. I said I'd write it. I didn't say I wouldn't tear it up."},{"start":2637.026,"end":2640.82,"text":"It's all in little pieces now, Walter, and I hope to do the same for you someday."},{"start":2640.905,"end":2643.114,"text":"And that, my friends, is my farewell to the newspaper game."},{"start":2643.199,"end":2645.241,"text":"I'm gonna be a woman, not a news-getting machine."},{"start":2645.326,"end":2647.702,"text":"I'm gonna have babies, take care of 'em, give 'em cod-liver oil"},{"start":2647.786,"end":2649.329,"text":"and watch their teeth grow and... and..."},{"start":2649.455,"end":2652.54,"text":"-If I ever see one of 'em look at a newspaper, I'm gonna brain 'em. -(ringing)"},{"start":2652.625,"end":2655.251,"text":"-Where's my hat? -Hello? Hello?"},{"start":2655.336,"end":2657.921,"text":"-Oh, Mr. Burns? Yes, she's still here. -Give me that!"},{"start":2660.341,"end":2662.008,"text":"And another thing I wanna ̶ Oh!"},{"start":2662.092,"end":2663.426,"text":"Ooh, you ̶"},{"start":2663.51,"end":2665.803,"text":"Where is my ̶ Oh, there it is."},{"start":2665.888,"end":2668.556,"text":"-Hello, Doctor. Sorry to be late. -That's quite all right."},{"start":2668.641,"end":2671.059,"text":"These boys from the newspapers, they take up so much of my time."},{"start":2671.143,"end":2673.811,"text":"They wanted me to hang Williams at their convenience."},{"start":2673.896,"end":2675.855,"text":"-Oh, hello, Earl. -Hello."},{"start":2675.94,"end":2678.274,"text":"These newspapers, what they did to me in Chicago."},{"start":2678.359,"end":2680.276,"text":"-Always after me for interviews. -Yes, me too."},{"start":2680.361,"end":2683.529,"text":"Of course, I did rather promise to make them some sort of statement when I finished here."},{"start":2683.614,"end":2685.949,"text":"-You don't mind, do you? -Well, that's hardly ethical, Doctor."},{"start":2686.033,"end":2688.243,"text":"-Oh? -All statements are supposed to come from me."},{"start":2688.327,"end":2691.621,"text":"Well, what do you say to giving them some sort of joint interview?"},{"start":2691.705,"end":2694.624,"text":"I can discuss some of the psychological aspects of the case and you ̶"},{"start":2694.708,"end":2698.211,"text":"-We'd have our pictures taken together? -Yes, yes, shaking hands."},{"start":2698.295,"end":2700.213,"text":"Of course, I don't take a very good picture."},{"start":2700.297,"end":2702.632,"text":"That doesn't matter, Doctor. The publicity is the main thing."},{"start":2702.716,"end":2706.886,"text":"Doctor, I'm getting awful tired. Can't I go back to jail again?"},{"start":2706.971,"end":2710.932,"text":"I'm sorry. I forgot you were there. No, we've some further questions for you."},{"start":2711.016,"end":2713.184,"text":"-Sheriff, do you mind extinguishing the lights? -Of course, Doctor."},{"start":2713.269,"end":2715.687,"text":"That'll help us with what we have to do over here."},{"start":2715.771,"end":2717.438,"text":"Now, let me see."},{"start":2718.816,"end":2722.277,"text":"Mr. Williams, you know, of course, that you're going to be executed."},{"start":2722.361,"end":2725.238,"text":"Now, who do you feel is responsible for that?"},{"start":2725.322,"end":2728.074,"text":"I'm innocent. It wasn't my fault."},{"start":2728.158,"end":2729.867,"text":"-Well, Murph. -Send us a postcard."},{"start":2729.952,"end":2731.619,"text":"-That I'll do. -So long, \"Yonson.\""},{"start":2731.704,"end":2733.121,"text":"When'll we see ya again, \"Yonson\"?"},{"start":2733.205,"end":2736.916,"text":"Next time you see me, I shall be riding in a Rolls-Royce, giving interviews on success."},{"start":2737.001,"end":2739.002,"text":"-Good-bye! -So long, you wage-slaves."},{"start":2739.086,"end":2742.547,"text":"When you're crawling up fire escapes and getting kicked out of front doors"},{"start":2742.631,"end":2746.592,"text":"and eating Christmas dinners in one-arm joints, don't forget your pal, Hildy Johnson."},{"start":2746.677,"end":2749.304,"text":"-We won't. -When the road beyond unfolds ̶"},{"start":2749.388,"end":2753.016,"text":"(gunfire)"},{"start":2753.1,"end":2755.143,"text":"(alarm ringing)"},{"start":2755.227,"end":2758.396,"text":"-(gunfire continues) -Look out! It's a jailbreak!"},{"start":2761.817,"end":2765.111,"text":"-What's the matter? What happened? -(gunfire)"},{"start":2765.195,"end":2767.53,"text":"Hey, watch where you're aimin', will ya?"},{"start":2767.614,"end":2769.449,"text":"MAN: Block the gate! He'll try the gate!"},{"start":2769.533,"end":2771.826,"text":"-Who got away? Who was it? -Earl Williams!"},{"start":2771.91,"end":2774.12,"text":"(excited chattering)"},{"start":2775.164,"end":2777.874,"text":"-Hello. Hurry up. This is important. -Give me the desk."},{"start":2778,"end":2780.084,"text":"-Flash. Earl Williams just escaped. -Jailbreak. -Don't know yet."},{"start":2780.169,"end":2781.878,"text":"-Call you back. -Williams took a powder. -Went over the wall."},{"start":2781.962,"end":2783.713,"text":"-I don't know anything yet! -Call ya back."},{"start":2783.797,"end":2785.757,"text":"-(gunfire continues) -(siren wailing)"},{"start":2789.303,"end":2792.638,"text":"Hello, Post, get me Walter Burns quick. It's Hildy Johnson."},{"start":2793.64,"end":2796.851,"text":"Walter? Walter, Hildy. Earl Williams just escaped from the county jail."},{"start":2796.935,"end":2799.937,"text":"Yeah, yeah. Yeah! Don't worry. I'm on the job."},{"start":2803.484,"end":2805.109,"text":"(sirens continue wailing)"},{"start":2815.204,"end":2818.581,"text":"Hey, Cooley! Wait!"},{"start":2820.542,"end":2822.043,"text":"Hey ̶"},{"start":2822.127,"end":2824.587,"text":"Hey! Wait a minute!"},{"start":2843.023,"end":2844.982,"text":"Cooley! I wanna talk to you."},{"start":2845.067,"end":2845.566,"text":"(phone ringing)"},{"start":2845.567,"end":2847.86,"text":"(phone ringing)"},{"start":2851.323,"end":2854.617,"text":"(phones ringing)"},{"start":2854.701,"end":2857.161,"text":"-This is Endicott. Give me rewrite. -(ringing)"},{"start":2857.246,"end":2861.833,"text":"He ain't here. Hello, Gil? Here's the situation now. You ready?"},{"start":2861.917,"end":2863.876,"text":"Williams was taken over to the sheriff's private office"},{"start":2863.961,"end":2865.962,"text":"to be examined by this Professor Egelhoffer."},{"start":2866.046,"end":2869.507,"text":"In a few minutes he shot his way out. Nobody knows where he got the gun."},{"start":2869.591,"end":2872.051,"text":"He went upstairs to the infirmary and got out through the skylight."},{"start":2872.136,"end":2875.471,"text":"He must have slid down the rain pipe to the street. Nobody knows where he got it."},{"start":2875.556,"end":2877.64,"text":"-If they do, they won't talk. -Hello, sweetheart. Give me the desk."},{"start":2877.724,"end":2879.892,"text":"Crime commission offers $10,000 reward for Williams' capture."},{"start":2879.977,"end":2882.562,"text":"No clue yet as to Williams' whereabouts. No, no."},{"start":2882.646,"end":2885.314,"text":"Here's a little feature though. There's been an accident about a tear bomb."},{"start":2885.399,"end":2887.65,"text":"Yeah, tear bomb, tear bomb. Criminals cry for it."},{"start":2887.734,"end":2889.318,"text":"I don't know."},{"start":2889.403,"end":2892.447,"text":"This tear bomb went off unexpectedly in the hands of Sheriff Hartwell's bombing squad."},{"start":2892.531,"end":2893.614,"text":"What went off?"},{"start":2893.699,"end":2895.324,"text":"The following deputies were rushed to the hospital."},{"start":2895.409,"end":2896.826,"text":"Fine friend you are."},{"start":2896.91,"end":2899.245,"text":"Their names are Merwyn D. Wilkerson, the mayor's brother-in-law."},{"start":2899.329,"end":2901.998,"text":"-After all I've done for you. -Howard Schuster, the sheriff's uncle."},{"start":2902.082,"end":2903.833,"text":"-On his mother's side. -WILSON: Hello, Jim?"},{"start":2903.917,"end":2905.835,"text":"Sidelights on Sheriff Hartwell's manhunt."},{"start":2905.919,"end":2908.379,"text":"William Mansfield, the sheriff's landlord, and Lester Winthrop,"},{"start":2908.464,"end":2910.006,"text":"who married the sheriff's niece."},{"start":2910.09,"end":2912.049,"text":"You remember, the very homely dame. Call ya back."},{"start":2912.134,"end":2915.303,"text":"Mrs. William Rice, age 55, scrub lady, while scrubbing the eighth floor,"},{"start":2915.387,"end":2917.555,"text":"was shot in the left leg by one of Sheriff Hartwell's deputies."},{"start":2917.639,"end":2919.432,"text":"-Look, I'm not ̶ -(gunfire)"},{"start":2919.516,"end":2922.268,"text":"-There goes another scrub lady! -It was only a flesh wound."},{"start":2922.352,"end":2925.146,"text":"-They took her to the hospital. -McCue speaking. Give me the desk."},{"start":2925.23,"end":2926.898,"text":"Mac, any dope on how he escaped?"},{"start":2926.982,"end":2929.192,"text":"Maybe the sheriff let him out so Williams could vote for him."},{"start":2929.276,"end":2931.819,"text":"A man answering the description of Earl Williams was seen boarding ̶"},{"start":2931.904,"end":2934.489,"text":"-(gunfire) -Call ya back!"},{"start":2934.573,"end":2937.241,"text":"-Thought you'd gone. -I thought so too."},{"start":2937.326,"end":2939.368,"text":"Get me Walter Burns, quick."},{"start":2941.872,"end":2944.081,"text":"Walter, Walter, listen."},{"start":2944.166,"end":2946.792,"text":"I've got the whole story on how Williams got that gun and escaped."},{"start":2946.877,"end":2950.546,"text":"And I got it exclusive. Yeah. That's right, and it's a pip."},{"start":2950.631,"end":2953.174,"text":"It cost me 450 bucks to tear it out of Cooley."},{"start":2953.258,"end":2954.634,"text":"Never mind that. What's the story?"},{"start":2954.718,"end":2956.344,"text":"Just a minute, and I'll give you the story."},{"start":2956.428,"end":2959.847,"text":"I had to give him all the money I had, and it wasn't exactly mine."},{"start":2959.932,"end":2961.766,"text":"It's Bruce's money, and I want it back."},{"start":2962.684,"end":2966.562,"text":"Bruce's money? Sure, sure, sure, you'll get it. Now, what's the story?"},{"start":2966.647,"end":2969.732,"text":"I'll send the money right down to you. I swear it on my mother's grave."},{"start":2969.816,"end":2972.985,"text":"All right, here's the ̶ Wait a minute. Your mother's alive."},{"start":2973.07,"end":2975.655,"text":"My grandmother's grave. Don't be technical. What's the story?"},{"start":2975.739,"end":2979.909,"text":"You get that money down here. All right, here's your story."},{"start":2979.993,"end":2981.41,"text":"The jailbreak of your dreams."},{"start":2981.495,"end":2984.372,"text":"It seems this expert Dr. Egelhoffer, the profound thinker from New York,"},{"start":2984.456,"end":2986.958,"text":"was giving Williams a final sanity test in the sheriff's office."},{"start":2987.042,"end":2990.545,"text":"You know, sticking a lot of pins in him so he could get his reflexes."},{"start":2990.629,"end":2993.673,"text":"He decided to reenact the crime exactly as it had taken place"},{"start":2993.757,"end":2996.509,"text":"in order to study Williams's powers of coordination."},{"start":2996.593,"end":3000.054,"text":"I'm coming to it. Of course, he had to have a gun to reenact the crime with."},{"start":3000.138,"end":3004.225,"text":"Who do you suppose supplied it? Peter B. Hartwell ̶ \"B\" for brains."},{"start":3004.309,"end":3007.144,"text":"(snorts, laughing) No kidding!"},{"start":3008.48,"end":3011.315,"text":"I tell you, I'm not kidding. I'm not good enough to make this one up."},{"start":3011.4,"end":3013.985,"text":"The sheriff gave his gun to the professor. The professor gave it to Earl."},{"start":3014.069,"end":3016.112,"text":"Earl shot the professor right in the classified ads."},{"start":3016.196,"end":3019.407,"text":"No, ads. Ain't it perfect?"},{"start":3019.491,"end":3022.66,"text":"If the sheriff had unrolled a red carpet and loaned Williams an umbrella,"},{"start":3022.744,"end":3024.203,"text":"it couldn't have been more ideal."},{"start":3024.288,"end":3026.622,"text":"Who? Oh, no, no. Egelhoffer wasn't badly hurt."},{"start":3026.707,"end":3029.458,"text":"They took him to the county hospital where they're awfully afraid he'll recover."},{"start":3029.543,"end":3031.586,"text":"Oh, that's great work, Hildy. Huh?"},{"start":3031.67,"end":3034.463,"text":"Stop worrying about the money. I'll see you get it in 15 minutes."},{"start":3034.548,"end":3037.842,"text":"I'd better get it in 15 minutes. Bruce is waiting in a taxicab for me."},{"start":3037.926,"end":3041.262,"text":"-We're in a hurry. -Hold on a minute. Hey, come here."},{"start":3041.346,"end":3044.39,"text":"There's a guy waiting in a taxi in front of the criminal courts building."},{"start":3044.474,"end":3046.392,"text":"-His name is Bruce Baldwin. -What does he look like?"},{"start":3046.476,"end":3049.228,"text":"He looks like that fellow in the movies. You know, Ralph Bellamy."},{"start":3049.313,"end":3050.855,"text":"-Oh, him? -Can you handle it?"},{"start":3050.939,"end":3052.94,"text":"I've never flopped on ya yet, have I?"},{"start":3053.025,"end":3055.985,"text":"Come on. Get going. You only got about two minutes. Hurry."},{"start":3056.069,"end":3058.779,"text":"Yes, dear. Sorry to keep you waiting. How much was it again?"},{"start":3058.864,"end":3061.616,"text":"$450? Just a second."},{"start":3061.7,"end":3065.286,"text":"Louie, I need $450 worth of counterfeit money."},{"start":3065.37,"end":3066.787,"text":"Can't carry that much."},{"start":3066.872,"end":3068.956,"text":"Just the 450 counterfeit. Where can I get it?"},{"start":3069.041,"end":3072.251,"text":"-Oh, I got that on me. -Quite a coincidence. Take it over to Hildy."},{"start":3072.336,"end":3074.754,"text":"Hello. It's coming right over. I'm sending it over with Louie."},{"start":3074.838,"end":3077.256,"text":"Thanks for your story, dear, and good luck on your honeymoon."},{"start":3077.341,"end":3080.76,"text":"No, no, never mind the thanks. Just see that money gets here."},{"start":3083.889,"end":3086.641,"text":"-Hello, Hildy. You still here? -No, I'm in Niagara Falls."},{"start":3086.725,"end":3090.603,"text":"McCue speaking. Emil, I got a good feature for you on the manhunt."},{"start":3090.687,"end":3094.065,"text":"Ready? Mrs. Phoebe DeWolfe, 861 1/2 South State Street, colored,"},{"start":3094.149,"end":3096.067,"text":"gave birth to a pickaninny in a patrol wagon"},{"start":3096.151,"end":3098.944,"text":"with Sheriff Hartwell's special rifle squad acting as nurses."},{"start":3099.029,"end":3102.615,"text":"Phoebe was walking along the street when ̶ That's right. Yeah."},{"start":3102.699,"end":3105.743,"text":"So they coaxed her into the patrol wagon and started a race with the stork."},{"start":3105.827,"end":3109.705,"text":"When the pickaninny was born, the rifle squad examined him to see if it was Earl Williams."},{"start":3109.79,"end":3111.415,"text":"Well, they knew he was hiding somewhere."},{"start":3111.5,"end":3113.459,"text":"-(phone rings) -Here's the payoff."},{"start":3113.543,"end":3117.38,"text":"-They named the kid Peter Hartwell DeWolfe. -Press room."},{"start":3117.464,"end":3120.383,"text":"Bruce! I thought you were downstairs in the ̶"},{"start":3120.467,"end":3124.22,"text":"What? Arrested again? What for this time?"},{"start":3124.304,"end":3128.182,"text":"Oh, well, they called it mashing."},{"start":3129.351,"end":3131.894,"text":"No! I didn't, Hildy."},{"start":3131.978,"end":3134.563,"text":"I was sitting right in the taxi where you left me."},{"start":3134.648,"end":3139.11,"text":"The young lady seemed to have a dizzy spell and I just ̶"},{"start":3139.194,"end":3140.945,"text":"Huh?"},{"start":3141.029,"end":3144.448,"text":"Well, uh, she's kind of, uh ̶"},{"start":3144.533,"end":3146.45,"text":"Huh?"},{"start":3146.535,"end":3150.037,"text":"Yes, she's a blonde. Yes, very blonde."},{"start":3150.122,"end":3153.082,"text":"Never mind. I know how it happened. Just a minute."},{"start":3153.166,"end":3156.127,"text":"Get me Walter Burns. Hildy Johnson."},{"start":3156.211,"end":3159.672,"text":"Bruce, where are ya? 27th Precinct? Hold on a minute, will ya?"},{"start":3159.756,"end":3163.426,"text":"Walter, you ̶ Well, he was there a minute ago."},{"start":3163.51,"end":3167.054,"text":"But, I ̶ (mimicking) Sorry, I can't locate him, Miss Johnson."},{"start":3167.139,"end":3169.598,"text":"Why, that double-crossing ̶ Hello ̶ No, not you."},{"start":3169.683,"end":3173.06,"text":"Bruce, I can't get there right away. How about 20 minutes?"},{"start":3173.145,"end":3177.022,"text":"You see, I have to wait here for the ̶ Uh, I'll tell you when I see you."},{"start":3177.107,"end":3179.442,"text":"If I ever get my two hands again on that Walter Burns ̶"},{"start":3179.526,"end":3182.319,"text":"-Hold on a minute. Anything I can do to help? -How much money you got?"},{"start":3182.404,"end":3183.612,"text":"-$1.80. -Sixty-four cents."},{"start":3183.697,"end":3186.449,"text":"-Welcome to it. -Thanks. You'd better buy an annuity."},{"start":3186.533,"end":3189.952,"text":"What's that, Emil? No, I can't give you an official statement."},{"start":3190.036,"end":3192.705,"text":"No. Wait a minute. Here's the mayor. Maybe he'll give us one."},{"start":3192.789,"end":3194.665,"text":"-How 'bout a statement, Mayor? -Don't pester me now."},{"start":3194.75,"end":3197.084,"text":"-I've got a lot on my mind. -His Honor won't say anything."},{"start":3197.169,"end":3199.17,"text":"-Have you seen Sheriff Hartwell? -It's hard to tell."},{"start":3199.254,"end":3201.088,"text":"There's so many cockroaches around here ̶"},{"start":3201.173,"end":3203.132,"text":"Wait a minute. How about a statement, Your Honor?"},{"start":3203.216,"end":3206.886,"text":"-Sure, we go to press in 20 minutes. -I have nothing to say. Not at this time."},{"start":3206.97,"end":3209.096,"text":"Just a moment, please. What do you know about the escape?"},{"start":3209.181,"end":3210.806,"text":"How'd he get out? Where'd he get the gun?"},{"start":3210.891,"end":3213.476,"text":"-Wait a minute, boys. Not so fast. -Give us a statement on the election then."},{"start":3213.56,"end":3216.061,"text":"-What effect will this have on the voters? -None whatsoever."},{"start":3216.146,"end":3219.607,"text":"How can an unavoidable misfortune like this have any influence"},{"start":3219.691,"end":3221.859,"text":"on the upright citizens of our fair city?"},{"start":3221.943,"end":3223.611,"text":"-Baloney. -Look, Mr. Mayor, please."},{"start":3223.695,"end":3225.613,"text":"Is there a red menace or ain't there?"},{"start":3225.697,"end":3227.656,"text":"How did Williams get out of that rubber jail?"},{"start":3227.741,"end":3230.326,"text":"Have you learned to stand the gaff, or have you picked somebody to be responsible?"},{"start":3230.41,"end":3233.037,"text":"Is there any truth in the report you're on Stalin's payroll?"},{"start":3233.121,"end":3235.79,"text":"Yeah, the senator claims you sleep in red underwear."},{"start":3235.874,"end":3240.336,"text":"Never mind the jokes. Don't forget I'm the mayor. Hartwell, I wanna see you!"},{"start":3240.42,"end":3243.005,"text":"How'd he get away? Where'd he get the gun?"},{"start":3243.089,"end":3245.716,"text":"Hi, Your Honor. Any statement on the red uprising tomorrow?"},{"start":3245.801,"end":3248.052,"text":"-What red uprising? -There'll be no red uprising."},{"start":3248.136,"end":3250.554,"text":"The governor says the situation calls for the militia."},{"start":3250.639,"end":3252.515,"text":"-Get me rewrite. -You can quote me."},{"start":3252.599,"end":3254.934,"text":"Anything the governor says is a tissue of lies."},{"start":3255.018,"end":3257.77,"text":"Hello, Jake. Here's a red-hot statement from the governor."},{"start":3257.854,"end":3260.272,"text":"He claims the mayor and sheriff have shown themselves"},{"start":3260.357,"end":3263.901,"text":"to be a couple of eight-year-olds playing with fire, yeah."},{"start":3264.694,"end":3266.57,"text":"You can quote him as follows ̶"},{"start":3266.655,"end":3269.99,"text":"\"It is a lucky thing for the city that next Tuesday is election day,"},{"start":3270.075,"end":3274.286,"text":"as the citizens will thus be saved the expense of impeaching the mayor and the sheriff.\""},{"start":3274.371,"end":3277.832,"text":"That's all. Call ya back. Nice to have seen ya, Mayor."},{"start":3277.916,"end":3280.459,"text":"-Excuse me, boys, I've got so much to do. -Quit stalling, Pinky!"},{"start":3280.544,"end":3282.086,"text":"-Who engineered this? -Was it the Reds?"},{"start":3282.17,"end":3283.462,"text":"-No! -Who was it? You?"},{"start":3283.547,"end":3286.09,"text":"-Me? No! I've got him located. -Williams?"},{"start":3286.174,"end":3289.093,"text":"-Where? -Where he used to live. I just got a tip."},{"start":3289.177,"end":3291.804,"text":"-Why didn't you say so? -The rifle squad is just going out."},{"start":3291.888,"end":3294.181,"text":"-Get me outta here! -Catch them if you hurry. Please."},{"start":3294.266,"end":3297.184,"text":"-Pete, I wanna talk to you. -I have got so much to do."},{"start":3297.269,"end":3299.311,"text":"-Now, see here, Fred. -Pete, you're through."},{"start":3299.396,"end":3303.023,"text":"-You mean I'm through? -I'm scratching your name off the ticket."},{"start":3303.108,"end":3305.192,"text":"I'm running Sherman in your place."},{"start":3305.277,"end":3308.529,"text":"\"Reform the Reds with a rope.\" Williams isn't a Red, and you know it."},{"start":3308.613,"end":3310.656,"text":"There are a lot of communistic sympathizers around."},{"start":3310.74,"end":3312.825,"text":"I thought if I got a slogan like that, I could ̶"},{"start":3312.909,"end":3315.578,"text":"I know it, but that's got nothing to do with this case."},{"start":3315.662,"end":3317.913,"text":"-(knocking) -There are 200,000 votes at stake."},{"start":3317.998,"end":3319.748,"text":"If Earl Williams don't hang, we're gonna lose 'em."},{"start":3319.833,"end":3322.459,"text":"We're going to hang him. Come in! He can't get away."},{"start":3322.544,"end":3324.962,"text":"What do you mean? He did get away!"},{"start":3325.046,"end":3326.922,"text":"-What do you want? -I ̶ Uh ̶"},{"start":3327.007,"end":3329.216,"text":"-What do you want? -Are you Sheriff Hartwell?"},{"start":3329.301,"end":3330.926,"text":"I'm he. What is it?"},{"start":3331.011,"end":3334.597,"text":"You're a hard man to find, Sheriff. I have a message here from the governor."},{"start":3334.681,"end":3337.433,"text":"-What's from the governor? -It was a reprieve for Earl Williams."},{"start":3337.517,"end":3339.351,"text":"-For who? -Earl Williams' reprieve."},{"start":3339.436,"end":3341.854,"text":"-You said there wasn't gonna be a reprieve. -I didn't know about this."},{"start":3341.938,"end":3344.398,"text":"It frightens me to think of what I'd like to do to you."},{"start":3344.482,"end":3346.901,"text":"-Who else was there when he gave you this? -Nobody. He was out fishing."},{"start":3346.985,"end":3350.195,"text":"-Get the governor on the phone. -He's not there. He's out duck shooting."},{"start":3350.28,"end":3352.615,"text":"-Bought a red hat. -Duck shooting."},{"start":3352.699,"end":3355.367,"text":"A guy who's done nothing for the last 40 years but play pinochle"},{"start":3355.452,"end":3357.786,"text":"gets elected governor and thinks he's a Tarzan."},{"start":3357.871,"end":3361.332,"text":"Read that! \"Insane,\" he says! He knows Williams isn't insane."},{"start":3361.416,"end":3363.751,"text":"-I never met the man. -Ah! Pure politics."},{"start":3363.835,"end":3366.503,"text":"It's an attempt to ruin us. We gotta think fast."},{"start":3366.588,"end":3369.715,"text":"-What are we gonna tell the reporters? -The party's through on account of you."},{"start":3369.799,"end":3373.01,"text":"-Oh, Fred! -Tell 'em I want your resignation now."},{"start":3373.094,"end":3375.554,"text":"Hello? Yes. Yes, this is Hartwell."},{"start":3375.639,"end":3377.139,"text":"What? Where? Where?"},{"start":3378.099,"end":3379.892,"text":"-Holy Moses! Hold the wire! -What is it?"},{"start":3379.976,"end":3383.354,"text":"They've got him. They've got Williams surrounded at his house!"},{"start":3383.438,"end":3385.94,"text":"-Tell them to hold the phone. -I did. Hold the wire!"},{"start":3386.024,"end":3388.233,"text":"-Cover up that transmitter! -Cover up ̶"},{"start":3388.318,"end":3391.904,"text":"-Listen. You never arrived with this. -Yes, I did. Remember?"},{"start":3391.988,"end":3394.99,"text":"-I came through that door. -How much money do you make?"},{"start":3395.075,"end":3396.2,"text":"-Huh? -What's your salary?"},{"start":3396.284,"end":3399.119,"text":"-Forty dollars a week. -How'd you like to make $350 a month?"},{"start":3399.204,"end":3402.623,"text":"-Almost $100 a week. -No, I couldn't afford ̶ Who, me?"},{"start":3402.707,"end":3406.043,"text":"Who do you think? They need a fellow like you in the city sealer's office."},{"start":3406.127,"end":3407.628,"text":"-In the what? -City sealer's."},{"start":3407.712,"end":3409.755,"text":"-I should work ̶ -Wait a minute! I'm in conference!"},{"start":3409.839,"end":3411.924,"text":"-My wife wouldn't want me to do that. -Why not?"},{"start":3412.008,"end":3414.718,"text":"-My wife lives in the country with my family. -That's all right."},{"start":3414.803,"end":3417.137,"text":"Bring her in here. We'll pay all the expenses."},{"start":3417.222,"end":3420.015,"text":"-No, I don't think so. -For heaven's sakes, why not?"},{"start":3420.1,"end":3423.519,"text":"I got two kids going to school. If they change towns, they lose a grade."},{"start":3423.603,"end":3425.479,"text":"No, they won't. They'll skip a grade."},{"start":3425.563,"end":3428.065,"text":"I'll guarantee ya they'll graduate with highest honors."},{"start":3428.149,"end":3429.984,"text":"Hold your horses! Hurry up, Fred."},{"start":3430.068,"end":3431.694,"text":"What do you say?"},{"start":3431.778,"end":3434.279,"text":"-Puts me in a kind of peculiar hole. -No, it doesn't."},{"start":3434.364,"end":3436.24,"text":"-Remember, you never delivered this. -Yes, I did."},{"start":3436.324,"end":3438.826,"text":"-No, you got caught in the traffic. -No, I came ̶"},{"start":3438.91,"end":3441.704,"text":"Pretend you did. Get out. Don't let anybody see ya."},{"start":3441.788,"end":3443.747,"text":"-Wait a minute. -But how do I know ̶"},{"start":3443.832,"end":3446.083,"text":"Come in and see me tomorrow. What's your name?"},{"start":3446.167,"end":3447.793,"text":"-Pettibone. What's yours? -Pettibone?"},{"start":3447.877,"end":3448.919,"text":"-Really? -No."},{"start":3449.004,"end":3451.38,"text":"All you've got to do is lay low and keep your mouth shut."},{"start":3451.464,"end":3453.048,"text":"-I'm tired anyhow. -Go to this address."},{"start":3453.133,"end":3456.468,"text":"Homey place. They'll take good care of ya. Tell 'em Fred sent ya."},{"start":3456.553,"end":3459.888,"text":"-Here's $50 on account. -Will ya wait, Olsen? I'll tell ya in one minute."},{"start":3459.973,"end":3462.641,"text":"-You forgot to tell me what a city sealer does. -I'll explain tomorrow."},{"start":3462.726,"end":3464.56,"text":"-Is it hard? -No, no, easy. Very easy."},{"start":3464.644,"end":3466.854,"text":"That's good, because my health isn't ̶ My wife ̶"},{"start":3466.938,"end":3468.564,"text":"-We'll fix that too. -My wife?"},{"start":3468.648,"end":3472.109,"text":"-Yeah, fix anything. Go ahead. -Fred, they're still on the phone."},{"start":3472.193,"end":3474.361,"text":"-All right, tell 'em to shoot to kill. -What?"},{"start":3474.446,"end":3476.405,"text":"-You heard what I said. -But the reprieve, Fred."},{"start":3476.489,"end":3479.742,"text":"-Do as I tell ya. -Hello, Olsen? Shoot to kill."},{"start":3479.826,"end":3482.536,"text":"-That's the orders. Pass the word along. -$500 reward."},{"start":3482.62,"end":3485.956,"text":"$500 to the man who does it. I'll be right over."},{"start":3487.792,"end":3489.293,"text":"Hi, Hildy."},{"start":3489.377,"end":3491.67,"text":"-You double-crossing hyena, I'd like to ̶ -What's the matter?"},{"start":3491.755,"end":3494.339,"text":"Don't give me that innocent stuff. What did you pull on Mr. Baldwin this time?"},{"start":3494.424,"end":3495.966,"text":"-Who, me? -You and that albino of yours."},{"start":3496.051,"end":3497.551,"text":"-You talkin' about Evangeline? -None other."},{"start":3497.635,"end":3500.679,"text":"She ain't no albino. She was born right here in this country."},{"start":3500.764,"end":3502.931,"text":"She tries anything else, she'll have to stay here in this country."},{"start":3503.016,"end":3505.142,"text":"And you, too, and it won't be on a phony charge either."},{"start":3505.226,"end":3506.852,"text":"-Did you bring that money? -Oh, yeah."},{"start":3506.936,"end":3509.813,"text":"-400 bucks. -450."},{"start":3510.398,"end":3513.358,"text":"All right. You can't blame a guy for tryin'."},{"start":3513.443,"end":3515.611,"text":"-Better give me a receipt. -I'll give you a scar."},{"start":3515.695,"end":3518.489,"text":"-I got plenty of them. -Oh, and I'll take Mr. Baldwin's wallet too."},{"start":3518.573,"end":3521.408,"text":"-Mr. Baldwin's what? -His purse. Come on. Come on, Louie."},{"start":3521.493,"end":3524.787,"text":"All right, Hildy. I'll do it for you because I like you."},{"start":3524.871,"end":3527.915,"text":"But you better tell that financier to be more careful in these hard times."},{"start":3527.999,"end":3530.751,"text":"Sure, sure. Want him to carry your brass knuckles too?"},{"start":3530.835,"end":3533.962,"text":"Don't talk that way. Here, I'll take that. I'll take it to the station."},{"start":3534.047,"end":3536.465,"text":"Wait a minute. You'll take it over to the station, all right."},{"start":3536.549,"end":3539.301,"text":"You'll take it to the 27th Precinct and tell the cops how this all happened."},{"start":3539.385,"end":3541.22,"text":"Burns would have me in Alcatraz in an hour."},{"start":3541.304,"end":3542.888,"text":"-That's not a bad idea. -Here, catch."},{"start":3542.972,"end":3544.473,"text":"Louie!"},{"start":3552.982,"end":3555.818,"text":"Hello, Operator. Hildy Johnson. Will you get me ̶"},{"start":3555.902,"end":3557.694,"text":"Drop that phone."},{"start":3557.779,"end":3559.905,"text":"Never mind."},{"start":3559.989,"end":3561.949,"text":"You're not gonna tell anybody where I am."},{"start":3565.912,"end":3567.871,"text":"Put that gun down, Earl."},{"start":3570.125,"end":3572.751,"text":"You don't want to shoot me, Earl. I'm your friend, remember?"},{"start":3572.836,"end":3575.17,"text":"I'm gonna write the story on you and production for use."},{"start":3575.255,"end":3578.423,"text":"Oh, yes. That's right. Production for use."},{"start":3578.508,"end":3580.592,"text":"-You don't want to hurt your friend ̶ -Don't move!"},{"start":3580.677,"end":3583.887,"text":"Maybe you're my friend and maybe you're not, but don't come any nearer."},{"start":3583.972,"end":3587.015,"text":"-You can't trust anybody in this crazy world. -(phone ringing)"},{"start":3587.1,"end":3590.144,"text":"I don't blame you, Earl. If I were you, I wouldn't trust anybody either."},{"start":3590.228,"end":3592.813,"text":"Don't do that. Put it back! Put it back!"},{"start":3592.897,"end":3597.025,"text":"If you try any tricks, I'll shoot you. I can do it right from here."},{"start":3597.11,"end":3599.278,"text":"S-Sure you could, Earl."},{"start":3599.362,"end":3602.489,"text":"But you don't want to do that. You don't want to kill anybody."},{"start":3602.574,"end":3605.951,"text":"No, you're right. I don't want to kill anybody."},{"start":3606.035,"end":3609.079,"text":"-That's what I thought. -Wait a minute. Where are you going?"},{"start":3609.164,"end":3611.707,"text":"I was just going to close the door so nobody'd see you."},{"start":3611.791,"end":3613.959,"text":"No, you weren't. You were gonna get somebody."},{"start":3614.043,"end":3616.545,"text":"But I don't want that. All I want is to be left alone."},{"start":3616.629,"end":3619.339,"text":"-I won't get anybody. -Yes, you will. You'll get 'em after me again."},{"start":3619.424,"end":3621.758,"text":"-I won't let you do that! -(shade rattling)"},{"start":3622.802,"end":3624.511,"text":"-(gun clicking) -Give me that."},{"start":3624.596,"end":3628.182,"text":"I guess I fired all the shells. Oh, I'm awful tired."},{"start":3628.266,"end":3630.767,"text":"-I couldn't go through ̶ -That shot. They'll know you're here!"},{"start":3630.852,"end":3634.188,"text":"-I don't care. I'm not afraid to die. -Stop it."},{"start":3634.272,"end":3636.648,"text":"I was telling the fella that when he handed me the gun."},{"start":3636.733,"end":3638.65,"text":"-Be quiet. -Waking me up in the middle of the night."},{"start":3638.735,"end":3640.819,"text":"Talking to me about things they don't understand."},{"start":3640.904,"end":3644.323,"text":"-Shut up. -I wish they'd take me back and hang me."},{"start":3644.407,"end":3646.241,"text":"They will if you don't keep quiet."},{"start":3646.326,"end":3649.62,"text":"-I couldn't go through another day like this. -Maybe you think I could."},{"start":3650.496,"end":3652.497,"text":"-Get me Walter Burns, quick! -(phone ringing)"},{"start":3652.582,"end":3654.708,"text":"Tell him I need him."},{"start":3655.21,"end":3656.793,"text":"Hello, hello."},{"start":3656.878,"end":3660.672,"text":"Bruce, I know I said I'd be down in 20 minutes, but something terrific has happened. Hold on."},{"start":3660.757,"end":3663.634,"text":"Walter, come over here! Bruce, just a second. I'll explain everything."},{"start":3663.718,"end":3667.763,"text":"Walter, I got Earl Williams right in the press room. Hurry! I need you. Right."},{"start":3667.847,"end":3670.098,"text":"I've captured Earl Williams. You know, the murderer!"},{"start":3670.183,"end":3672.601,"text":"-(knocking) -Stay down, Earl. Wait a minute!"},{"start":3672.685,"end":3675.979,"text":"Bruce, as soon as I hand him over to the paper, I'll be right down."},{"start":3676.064,"end":3678.023,"text":"-Bruce, I can't! Don't you realize ̶ -(pounding on door)"},{"start":3678.107,"end":3680.317,"text":"-Come on! Let me in! -Who is it?"},{"start":3680.401,"end":3683.237,"text":"It's me, Mollie Malloy. Open the door!"},{"start":3684.239,"end":3686.49,"text":"-What do you want, Mollie? -I gotta find ̶"},{"start":3686.574,"end":3688.575,"text":"-Where is everybody? -They're not here. They've all gone."},{"start":3688.66,"end":3691.578,"text":"-Please tell me where they've gone. -I don't know. I'm busy."},{"start":3691.663,"end":3693.664,"text":"-Do you mind running along? -They got him surrounded."},{"start":3693.748,"end":3696.75,"text":"-They're gonna shoot him down like a dog. -They're lookin' for you too. Get out."},{"start":3696.834,"end":3699.628,"text":"I don't care! You gotta tell me. I ain't afraid ̶"},{"start":3699.712,"end":3702.547,"text":"All right, I'll tell ya. They're down at Center and Fourth."},{"start":3702.632,"end":3705.425,"text":"-Oh, that's where he used to ̶ -EARL: Mollie. Mollie, don't go."},{"start":3705.51,"end":3707.97,"text":"Oh, come in, Mollie. Draw up a chair."},{"start":3710.598,"end":3712.724,"text":"-Hello, Mollie. -How did you get in here?"},{"start":3712.809,"end":3716.186,"text":"Down the pipe. I didn't mean to shoot him. Really I didn't."},{"start":3716.271,"end":3718.397,"text":"-I know. -HILDY (whispering): Shh. Be quiet."},{"start":3718.481,"end":3721.024,"text":"-You believe me, don't you, Mollie? -Sure, I believe you."},{"start":3721.109,"end":3723.944,"text":"Thanks for the roses. They were beautiful."},{"start":3724.028,"end":3726.405,"text":"That's all right, Mr. Williams."},{"start":3728.241,"end":3730.784,"text":"Oh, for heaven's sake. Don't you even dare. Be quiet."},{"start":3730.868,"end":3732.953,"text":"-I want to get him out of here. -Are you crazy?"},{"start":3733.037,"end":3735.163,"text":"You wouldn't get halfway down that hall without being seen."},{"start":3735.248,"end":3736.748,"text":"-But they'll find him. -I know it."},{"start":3736.833,"end":3738.583,"text":"I'm trying to think before those reporters come back."},{"start":3738.668,"end":3740.544,"text":"Let 'em take me. What difference does it make?"},{"start":3740.628,"end":3742.796,"text":"-No, I'll never let 'em. -(doorknob rattling)"},{"start":3742.88,"end":3744.464,"text":"Hey, who locked the door?"},{"start":3744.549,"end":3746.591,"text":"-(pounding) -It's too late."},{"start":3746.676,"end":3749.011,"text":"-No, it isn't. Earl, get in this desk. -What's the use?"},{"start":3749.095,"end":3751.096,"text":"Come on. Get in."},{"start":3755.852,"end":3758.603,"text":"-Open up! -Pull yourself together. All right."},{"start":3758.688,"end":3760.105,"text":"-(crying) -Sit down."},{"start":3760.189,"end":3763.191,"text":"-(pounding continues) -All right, all right. I'm coming."},{"start":3765.57,"end":3769.364,"text":"-Are you tryin' to kick the building down? -Gettin' exclusive. We got phone calls to ̶"},{"start":3769.449,"end":3771.491,"text":"-What's she doin' up here? -Get some smelling salts."},{"start":3771.576,"end":3773.994,"text":"-What's the matter? -Came up here and had hysterics."},{"start":3774.078,"end":3775.912,"text":"-Looks pretty sick. -How you feel, kid?"},{"start":3775.997,"end":3777.956,"text":"-I don't feel so good. -Get you some water?"},{"start":3778.041,"end":3779.541,"text":"-I'll get it. -Do anything for you?"},{"start":3779.625,"end":3781.209,"text":"-No. -You don't look sick to me."},{"start":3781.294,"end":3783.462,"text":"-You didn't bump into Williams, did you? -Ain't you funny."},{"start":3783.546,"end":3785.464,"text":"-Yeah? Where is he? -Let me alone, will ya?"},{"start":3785.548,"end":3787.883,"text":"-Okay. Give me the desk. -No harm in askin'."},{"start":3787.967,"end":3789.968,"text":"Hello, Jim? False alarm."},{"start":3790.053,"end":3793.68,"text":"They surrounded the house, but they forgot to tell Williams, and he wasn't there."},{"start":3793.765,"end":3796.516,"text":"Some Halloween going on outside. The whole police force standing on its ear."},{"start":3796.601,"end":3799.186,"text":"-Hildy, I thought you were gone. -Been waitin' for money from Walter."},{"start":3799.27,"end":3801.396,"text":"What a chase. Give me Emil."},{"start":3801.481,"end":3803.398,"text":"-(chattering) -Any news, boys?"},{"start":3803.483,"end":3805.942,"text":"Yeah, I've never been so tired in my life."},{"start":3806.027,"end":3809.78,"text":"Where? Melrose Station? All right, connect me. Hello, Mollie, how are ya?"},{"start":3809.864,"end":3812.115,"text":"-Hey, fellas, this looks good. -Call you back."},{"start":3812.2,"end":3815.41,"text":"An old lady just called the detective bureau, claims Williams is hiding under her piazza."},{"start":3815.495,"end":3817.496,"text":"-Tell her to stand up. -We looked every other place."},{"start":3817.58,"end":3820.665,"text":"-Don't you want to go out on it? -I have to stick around. I'll cover this end."},{"start":3820.75,"end":3823.543,"text":"-I spent $1.40 on taxicabs already. -Let's not do any more goin' out."},{"start":3823.628,"end":3825.962,"text":"-Never mind, Sarge. Tear it up. -Who pulled the shades down?"},{"start":3826.047,"end":3827.881,"text":"I did. They were throwing those lights around."},{"start":3832.303,"end":3834.596,"text":"♪♪ (whistling)"},{"start":3834.68,"end":3838.892,"text":"You know, I got a hunch Williams ain't anywhere they been lookin' for him."},{"start":3838.976,"end":3841.144,"text":"He might be right here in this building somewhere."},{"start":3841.229,"end":3844.314,"text":"HILDY: Sure, hanging around like a duck in a shooting gallery."},{"start":3844.399,"end":3847.317,"text":"There's that skylight to get out of. But how did he reach the ground?"},{"start":3847.402,"end":3850.362,"text":"-I'm pretending there ain't any Earl Williams. -He could jump over to this roof."},{"start":3850.446,"end":3851.655,"text":"It's only about four feet."},{"start":3851.739,"end":3853.99,"text":"Once he got to the roof, he could slide down a drainpipe."},{"start":3854.075,"end":3856.034,"text":"And come in any one of these windows on this side."},{"start":3856.119,"end":3858.12,"text":"The story's gonna walk right in the window ̶"},{"start":3858.204,"end":3861.373,"text":"Masterminds at work. You boys go home. Maybe Williams will call on you."},{"start":3861.457,"end":3863.625,"text":"Wouldn't it be funny if he's in this building?"},{"start":3863.709,"end":3866.002,"text":"Why not search the building? Everybody take a floor."},{"start":3866.087,"end":3869.339,"text":"-I'm not gonna wander all over. -A great bunch of reporters you are."},{"start":3869.424,"end":3872.134,"text":"The biggest story in two years, and you're too lazy to go out."},{"start":3872.218,"end":3875.971,"text":"If I know you, you seem pretty anxious to get rid of us. You trying to scoop us?"},{"start":3876.055,"end":3877.597,"text":"Are you crazy? On my own time?"},{"start":3877.682,"end":3879.891,"text":"Maybe Mollie's given her the story on how Williams got the gun."},{"start":3879.976,"end":3882.352,"text":"-Did you smuggle that gun in to Williams? -I didn't do nothin'."},{"start":3882.437,"end":3884.771,"text":"-Come clean, Mollie. -HILDY: Let the girl alone."},{"start":3884.856,"end":3886.273,"text":"Well?"},{"start":3886.357,"end":3889.234,"text":"-Mrs. Baldwin. Mother ̶ -Don't you \"Mother\" me."},{"start":3889.318,"end":3891.945,"text":"Playing cat-and-mouse with my poor boy, keeping him locked up."},{"start":3892.029,"end":3894.739,"text":"Making us miss two trains, and you supposed to be married tomorrow."},{"start":3894.824,"end":3897.784,"text":"-I'll be with you in five minutes. -You don't have to go at all."},{"start":3897.869,"end":3900.787,"text":"Give me Bruce's money. You can stay here forever, as far as I'm concerned."},{"start":3900.872,"end":3903.623,"text":"-You and that murderer you caught. -What's that? What murderer?"},{"start":3903.708,"end":3906.501,"text":"Which one of these men is it? They all look like murderers."},{"start":3906.586,"end":3908.879,"text":"-What murderer did you catch? -I don't know what she's talking about."},{"start":3908.963,"end":3911.339,"text":"-I never said any such thing. -I'm quoting my son."},{"start":3911.424,"end":3914.009,"text":"-And he has never lied to me. -That's ridiculous."},{"start":3914.093,"end":3916.344,"text":"-I never said anything like that! -Yes, you did."},{"start":3916.429,"end":3921.183,"text":"No, I said I was trying to find the murderer. She's got it all balled up."},{"start":3921.267,"end":3924.019,"text":"-Who you holdin' out on? -Nobody. Let me go."},{"start":3924.103,"end":3926.855,"text":"-I don't know where he is. -Stop it. Stop it!"},{"start":3926.939,"end":3929.649,"text":"What are you askin' her for? She don't know where he is."},{"start":3929.734,"end":3931.359,"text":"I'm the only one that knows."},{"start":3931.444,"end":3933.069,"text":"-Where is Williams? -Try and find out."},{"start":3933.154,"end":3935.739,"text":"-Come on, Mollie. Talk. -Talk? Now you want me to talk?"},{"start":3935.823,"end":3937.657,"text":"-Sure. -Ain't that funny."},{"start":3937.742,"end":3941.328,"text":"You wouldn't listen before, not for a minute, and now you want me to talk."},{"start":3941.412,"end":3943.622,"text":"-HILDY: Don't tell 'em anything, Mollie. -I know what I'm doing."},{"start":3943.706,"end":3946.166,"text":"-Stay out of this, Hildy. -Why didn't you listen to me?"},{"start":3946.25,"end":3948.585,"text":"-Cut that out! -Keep your hands off me."},{"start":3948.669,"end":3951.171,"text":"What do you want to know for? So you can write more lies."},{"start":3951.255,"end":3953.465,"text":"-So you can sell more papers. -Never mind that."},{"start":3953.549,"end":3957.427,"text":"All right, I'll give you a story, a wonderful story!"},{"start":3957.512,"end":3960.43,"text":"Only this time it'll be true! You'll never find him now!"},{"start":3960.515,"end":3961.932,"text":"-(shouting) -(screaming)"},{"start":3962.016,"end":3964.809,"text":"Get the ambulance, somebody. Get an ambulance, somebody."},{"start":3969.023,"end":3972.692,"text":"-She's dead. -No, she isn't killed. She's moving!"},{"start":3976.155,"end":3977.864,"text":"-Darling, did you see that? -Where is he?"},{"start":3977.949,"end":3979.616,"text":"-She jumped out the window. -Where is he?"},{"start":3979.7,"end":3982.077,"text":"-She isn't dead. -Hildy, where have you got Williams?"},{"start":3982.161,"end":3984.955,"text":"He's in the desk. Can't believe she didn't kill herself."},{"start":3985.039,"end":3987.207,"text":"-How you doin'? -Get me out. I can't stand it."},{"start":3987.291,"end":3989.376,"text":"-Keep quiet. You're sitting pretty. -What's in there?"},{"start":3989.46,"end":3992.379,"text":"-Who are you? Who is she? -This is Mrs. Baldwin, Bruce's mother."},{"start":3992.463,"end":3993.838,"text":"-What are you doing? -Shut up!"},{"start":3993.923,"end":3996.883,"text":"-I won't! You're doing something wrong. -Take her out of here."},{"start":3996.968,"end":3999.344,"text":"Fine. Louie, take the lady over to Polack Mike's."},{"start":3999.428,"end":4002.389,"text":"-My name's Louie Poluso. -(screaming)"},{"start":4002.473,"end":4004.599,"text":"Knock her out. See that she doesn't talk to anyone."},{"start":4004.684,"end":4006.518,"text":"-You can't do this. -What do I tell 'em?"},{"start":4006.602,"end":4009.396,"text":"-Tell 'em it's a case of dt's. -Don't worry, Mother. This is only temporary!"},{"start":4010.147,"end":4013.066,"text":"-Walter, let go of me. -Where do you think you're going?"},{"start":4013.15,"end":4015.902,"text":"I'm going after Mother, and I'm going to get Bruce out of jail."},{"start":4015.987,"end":4018.989,"text":"-Why did you have to do this to me? -Get Bruce out of jail?"},{"start":4019.073,"end":4022.576,"text":"How can you worry about a man who's resting in a nice, quiet police station?"},{"start":4022.66,"end":4025.787,"text":"-This is war. You can't desert me now. -Get off that trapeze."},{"start":4025.871,"end":4028.707,"text":"You've got your story in the desk. Smear it all over the front page."},{"start":4028.791,"end":4030.625,"text":"\"Earl Williams captured by the Morning Post.\""},{"start":4030.71,"end":4033.461,"text":"I covered your story and got in a mess. Now I'm gettin' out."},{"start":4033.546,"end":4035.839,"text":"-You drooling idiot. What do you mean? -Just what I said."},{"start":4035.923,"end":4038.216,"text":"There are 365 days in a year one can get married."},{"start":4038.301,"end":4041.386,"text":"How many times you got a murderer locked up in a desk? Once in a lifetime."},{"start":4041.47,"end":4044.681,"text":"-You got the city by the seat of the pants. -Sure, I know."},{"start":4044.765,"end":4047.601,"text":"You've got the brain of a pancake. This isn't just a story you're covering."},{"start":4047.685,"end":4048.893,"text":"It's a revolution."},{"start":4048.978,"end":4051.813,"text":"This is the greatest yarn in journalism since Livingston discovered Stanley."},{"start":4051.897,"end":4055.442,"text":"-It's the other way around. -Don't get technical at a time like this."},{"start":4055.526,"end":4059.029,"text":"You've taken a city that's been graft-ridden for 40 years under the same old gang."},{"start":4059.113,"end":4061.364,"text":"With this yarn, you're kicking 'em out, giving us a chance"},{"start":4061.449,"end":4064.492,"text":"to have the kind of government New York's having under La Guardia."},{"start":4064.577,"end":4067.996,"text":"If I didn't have your best interest at heart, you think I'd waste time arguing?"},{"start":4068.08,"end":4070.832,"text":"You done something big. You stepped up into a new class."},{"start":4070.916,"end":4072.042,"text":"Huh?"},{"start":4072.126,"end":4076.171,"text":"We'll make monkeys out of those ward heelers. Nobody'll vote for them, not even their wives."},{"start":4076.255,"end":4078.256,"text":"-Expose 'em, eh? -We'll crucify that mob."},{"start":4078.341,"end":4081.343,"text":"We'll keep Williams undercover until morning so the Post can break the story exclusive."},{"start":4081.427,"end":4084.429,"text":"-We'll let the governor in on the capture. -I get it."},{"start":4084.513,"end":4086.556,"text":"You've kicked over City Hall like an apple cart."},{"start":4086.641,"end":4088.725,"text":"You got the mayor and Hartwell backed up against a wall."},{"start":4088.809,"end":4090.685,"text":"You've put one administration out and another one in."},{"start":4090.77,"end":4093.313,"text":"This isn't just a newspaper story, it's a career."},{"start":4093.397,"end":4096.941,"text":"And you stand there bellyaching about whether you catch an 8:00 or 9:00 train."},{"start":4097.026,"end":4099.736,"text":"-Walter, I never figured it that way. -You're still a doll-faced hick, that's why."},{"start":4099.82,"end":4102.447,"text":"-We'd be the white-haired boys. -They'd be naming streets after you."},{"start":4102.531,"end":4105.909,"text":"There'll be statues of you in the park. The movies'll be after you, the radio."},{"start":4105.993,"end":4108.953,"text":"By tomorrow morning a Hildy Johnson cigar. I can see the billboards."},{"start":4109.038,"end":4111.956,"text":"-\"Light up with Hildy Johnson.\" -Stop that acting. We've got a lot to do."},{"start":4112.041,"end":4114.417,"text":"-Now you're talking. -We can't leave Williams in here."},{"start":4114.502,"end":4116.628,"text":"We'll take him to my private office. Which is our phone?"},{"start":4116.712,"end":4120.59,"text":"-On the end. How you gonna take him? -We'll carry the desk over."},{"start":4120.675,"end":4122.926,"text":"You can't move that desk. It's crawling with cops outside."},{"start":4123.01,"end":4126.805,"text":"We'll lower it out the window with pulleys. Get the typewriter. Start pounding out a lead."},{"start":4126.889,"end":4130.183,"text":"-How much do you want? -All the words you got. Hello! Give me Duffy."},{"start":4130.267,"end":4133.103,"text":"-Can I call the mayor a bird of prey? -Call him anything you like."},{"start":4133.187,"end":4135.563,"text":"How about the time he had his house painted by the fire department?"},{"start":4135.648,"end":4138.942,"text":"The works. Hello, Duffy? Get set. We got the biggest story in years."},{"start":4139.026,"end":4141.82,"text":"\"Earl Williams captured by The Morning Post, exclusive!"},{"start":4141.904,"end":4144.322,"text":"Yeah! And I want you to tear out the whole front page."},{"start":4144.407,"end":4146.408,"text":"I said the whole front page out."},{"start":4146.492,"end":4149.244,"text":"Never mind the European war. We got something bigger than that."},{"start":4149.328,"end":4152.372,"text":"Hildy Johnson's writing the lead. I'll give it to you as soon as she's finished."},{"start":4152.456,"end":4156,"text":"Get hold of Butch O'Connor. Tell him to come up with half a dozen of his wrestlers."},{"start":4156.085,"end":4158.753,"text":"Butch O'Connor. I've got a desk I want moved."},{"start":4158.838,"end":4160.213,"text":"-Never mind what ̶ -Hildy!"},{"start":4160.297,"end":4162.424,"text":"-What the deuce do you want? -Hello, Bruce."},{"start":4162.508,"end":4164.884,"text":"Never mind the Chinese earthquake."},{"start":4164.969,"end":4167.804,"text":"-I want to ask one question. -How did you get out of jail?"},{"start":4167.888,"end":4170.473,"text":"-Not through any help of yours. -You can't come in here. We're busy."},{"start":4170.558,"end":4174.686,"text":"I'm not talking to you. I had to wire Albany for $100 so I could get out on bail."},{"start":4174.77,"end":4177.48,"text":"-I don't care if there's a million dead. -I don't know what they're gonna think."},{"start":4177.565,"end":4180.108,"text":"They had to send the money to the police station."},{"start":4180.192,"end":4182.861,"text":"-We're waiting for that story. -We'll explain everything to them, Bruce."},{"start":4182.945,"end":4184.988,"text":"-Where's Mother? She was coming here. -She left."},{"start":4185.072,"end":4186.781,"text":"-I can't hear you, Duffy. -Where'd she go?"},{"start":4186.866,"end":4189.2,"text":"-Out someplace. -No, no, junk the Polish corridor."},{"start":4189.285,"end":4192.162,"text":"-Tell me where my mother was going. -She couldn't say."},{"start":4192.246,"end":4194.664,"text":"-This is more important. -Did she get the money from you?"},{"start":4194.749,"end":4197.292,"text":"-No, she left in a hurry. -I'll take that money."},{"start":4197.376,"end":4200.003,"text":"-It's right there in my purse. -I can handle things around here."},{"start":4200.087,"end":4203.173,"text":"-I'll take that certified check too. -I'll give it to you. Here are the tickets."},{"start":4203.257,"end":4206.676,"text":"-You'll find your money in the wallet. -My wallet? This is my wallet!"},{"start":4206.761,"end":4210.263,"text":"Say, there's something funny going on. What are you doing?"},{"start":4210.347,"end":4212.432,"text":"Just wanted to look at it."},{"start":4212.516,"end":4214.851,"text":"-Hildy, I'm taking ̶ -WALTER: What'd you say?"},{"start":4214.935,"end":4217.937,"text":"-Hildy, I'm taking the 9:00 train. -Sure, sure."},{"start":4218.022,"end":4220.648,"text":"Did you hear what I said? I'm taking the 9:00 train."},{"start":4220.733,"end":4223.318,"text":"The 9:00 train. Oh, Bruce, I put it in here."},{"start":4224.653,"end":4227.322,"text":"Hey, let her alone, will you, buddy?"},{"start":4227.406,"end":4229.866,"text":"-Do me a favor, Bruce? -Just answer me one question."},{"start":4229.95,"end":4232.535,"text":"-You don't want to come with me, do you? -I need that!"},{"start":4232.62,"end":4234.746,"text":"-You don't, do you? -No!"},{"start":4234.83,"end":4237.248,"text":"Take those Miss America pictures off page six."},{"start":4237.333,"end":4238.75,"text":"Hildy, tell me the truth."},{"start":4238.834,"end":4241.878,"text":"-Did you ever love me, Hildy? -Now look here, my good man!"},{"start":4241.962,"end":4244.464,"text":"-You shut up, Burns! -How can I do anything with this racket?"},{"start":4244.548,"end":4245.965,"text":"You're doin' this to her."},{"start":4246.05,"end":4248.343,"text":"She wanted to get away from you and everything you stand for,"},{"start":4248.427,"end":4249.928,"text":"but you caught her and changed her mind."},{"start":4250.012,"end":4252.931,"text":"Take Hitler and stick him on the funny page. Let me ask you ̶"},{"start":4253.015,"end":4255.433,"text":"Are you giving up everything for a man like him?"},{"start":4255.518,"end":4258.269,"text":"No, I am not, but something's happened. I'll tell you everything ̶"},{"start":4258.354,"end":4260.438,"text":"You'll tell him nothing! He's a spy!"},{"start":4260.523,"end":4263.65,"text":"I am not a spy. Hildy, you're coming with me now!"},{"start":4263.734,"end":4266.486,"text":"Give me a second. This is the biggest thing in my life!"},{"start":4266.57,"end":4269.614,"text":"I see. I'll keep. I'm like something in the icebox."},{"start":4269.698,"end":4271.407,"text":"-Yeah. -You don't love me."},{"start":4271.492,"end":4274.244,"text":"That isn't true. Just because you won't listen, you say I don't love you."},{"start":4274.328,"end":4275.912,"text":"That isn't the point at all."},{"start":4275.996,"end":4278.706,"text":"The point is you never intended to live like a human being."},{"start":4278.791,"end":4281.251,"text":"-All right! -Sebastian jumping!"},{"start":4281.335,"end":4283.461,"text":"-I'm trying to concentrate! -I see what's going on now."},{"start":4283.546,"end":4286.673,"text":"-You're just like him and all the rest. -HILDY: Sure, sure. That's what I am."},{"start":4286.757,"end":4290.093,"text":"What? No, leave the rooster story alone. That's human interest."},{"start":4290.177,"end":4293.054,"text":"-You get hold of Butch O'Connor? -If you had any sympathy or understanding ̶"},{"start":4293.138,"end":4295.098,"text":"-I understand, all right. -Wait."},{"start":4295.182,"end":4297.058,"text":"There's only one question I want to know."},{"start":4297.142,"end":4299.143,"text":"Walter, the mayor's first wife ̶ What was her name?"},{"start":4299.228,"end":4301.896,"text":"The one with the wart on her? Fanny. What, Duffy?"},{"start":4301.981,"end":4304.774,"text":"-I don't think you ever loved me at all. -Never mind that!"},{"start":4304.859,"end":4306.86,"text":"You're not working for the advertising department."},{"start":4306.944,"end":4309.445,"text":"If you change your mind, I'm leaving on the 9:00 train."},{"start":4309.53,"end":4312.198,"text":"If you want me, Bruce, you gotta take me as I am."},{"start":4312.283,"end":4315.034,"text":"I'm no suburban bridge player. I'm a newspaperman."},{"start":4315.119,"end":4319.956,"text":"That's the stuff, Hildy. Keep it coming. Get back in there, you mock turtle."},{"start":4321.5,"end":4325.545,"text":"Duffy, did you tell Butch and his gang to take a taxi as a matter of life and death?"},{"start":4325.629,"end":4329.132,"text":"Stay on this wire. Butch is on his way. We gotta hold out for 15 minutes."},{"start":4329.216,"end":4332.218,"text":"-The boys'll be coming in here to phone. -I'll handle 'em."},{"start":4333.178,"end":4335.722,"text":"Ah, now the moon's out."},{"start":4338.392,"end":4339.893,"text":"(three knocks)"},{"start":4339.977,"end":4342.729,"text":"Fine, three taps is me. Don't forget. Got enough air?"},{"start":4342.813,"end":4345.982,"text":"-Not very much. -That better? You're sitting pretty."},{"start":4346.066,"end":4349.152,"text":"-How's it coming, honey? -All right, I guess. Where's Bruce?"},{"start":4349.236,"end":4350.987,"text":"-Oh, he went out. -Is he coming back?"},{"start":4351.071,"end":4353.948,"text":"Certainly. Didn't you hear him? What have you got so far?"},{"start":4354.033,"end":4356.659,"text":"\"While hundreds of Sheriff Hartwell's paid gunmen stalked through the city,"},{"start":4356.744,"end":4359.037,"text":"shooting innocent bystanders, spreading their reign of terror,"},{"start":4359.121,"end":4362.165,"text":"-Earl Williams was lurking less than 20 yards ̶ \" -Aren't you gonna mention the Post?"},{"start":4362.249,"end":4365.001,"text":"-Doesn't the paper get credit? -I did that in the second paragraph."},{"start":4365.085,"end":4366.377,"text":"Who's gonna read the second paragraph?"},{"start":4366.462,"end":4369.464,"text":"For ten years I've been tellin' you how to write a story, and that's what I get?"},{"start":4373.427,"end":4375.72,"text":"What's the idea of locking this door?"},{"start":4375.804,"end":4378.056,"text":"-Who's that? -Bensinger. That's his desk."},{"start":4378.14,"end":4380.683,"text":"-Open the door, will ya? -(pounding)"},{"start":4380.768,"end":4383.186,"text":"-What'd you say his name was? -Bensinger, of The Tribune."},{"start":4383.27,"end":4386.773,"text":"-Tribune, huh? -Who's in there?"},{"start":4386.857,"end":4390.568,"text":"Haven't you any better sense ̶ Uh, hello. Hello, Mr. Burns."},{"start":4390.653,"end":4392.654,"text":"Well, quite an honor having you come over here."},{"start":4392.738,"end":4394.697,"text":"-Hello, Bensinger. -Oh, you know my ̶"},{"start":4394.782,"end":4397.075,"text":"-(chuckling) -Excuse me, I just want to get my ̶"},{"start":4397.159,"end":4399.994,"text":"It's quite a coincidence seeing you tonight. Isn't it, Hildy?"},{"start":4400.079,"end":4401.788,"text":"-Yes. -How do you mean?"},{"start":4401.872,"end":4404.29,"text":"I was talking to our Mr. Duffy about you this afternoon."},{"start":4404.375,"end":4408.127,"text":"-Really. Nothing detrimental, I hope. -On the contrary."},{"start":4408.212,"end":4410.88,"text":"That was one swell story you had in the paper this morning."},{"start":4410.965,"end":4414.509,"text":"-Did you care for the poem, Mr. Burns? -Uh, the poem?"},{"start":4414.593,"end":4417.428,"text":"-The poem was great. -I like the ending especially."},{"start":4417.513,"end":4419.472,"text":"\"And all is well outside his cell,"},{"start":4419.556,"end":4423.017,"text":"but in his heart, he hears the hangman calling and the gallows falling"},{"start":4423.102,"end":4425.728,"text":"and his white-haired mother's tears.\""},{"start":4425.813,"end":4427.313,"text":"-Heartbreaking? -Uh-huh."},{"start":4427.398,"end":4429.691,"text":"-That's fine. How'd you like to work for me? -What?"},{"start":4429.775,"end":4433.569,"text":"We can use a man like you. We got a lot of lowbrows like Johnson here."},{"start":4433.654,"end":4436.322,"text":"-Are you serious, Mr. Burns? -Serious? Wait a minute."},{"start":4436.407,"end":4439.117,"text":"Duffy, I'm sending a Mr. Bunsinger over to see you."},{"start":4439.201,"end":4440.952,"text":"-Bensinger. -Mervyn, isn't it?"},{"start":4441.036,"end":4443.413,"text":"-Yeah. No, Roy. Roy V. -Certainly."},{"start":4443.497,"end":4445.623,"text":"Roy V. Bensinger, the poet."},{"start":4445.708,"end":4450.044,"text":"Of course you wouldn't know. You probably never heard of Shakespeare either."},{"start":4450.129,"end":4451.254,"text":"(slaps back)"},{"start":4451.338,"end":4453.756,"text":"I want you to put Mr. Bensinger on the staff right away."},{"start":4453.841,"end":4455.8,"text":"-How much you getting on The Tribune? -Ah, 75."},{"start":4455.884,"end":4459.095,"text":"I'll give you 100 and a byline. You give him everything he wants, understand?"},{"start":4459.179,"end":4460.722,"text":"Okay. Look."},{"start":4460.806,"end":4464.267,"text":"I want you to write me a story from the point of view of the escaped man."},{"start":4464.351,"end":4466.811,"text":"He hides, cowering, afraid of every sound, of every light."},{"start":4466.895,"end":4469.647,"text":"He hears footsteps. His heart is going like that. They're closing in."},{"start":4469.732,"end":4472.692,"text":"-Get the sense of the animal at bay. -Sort of a Jack London style?"},{"start":4472.776,"end":4474.61,"text":"-Exactly. -I'll get my rhyming dictionary."},{"start":4474.695,"end":4476.612,"text":"It doesn't have to rhyme."},{"start":4476.697,"end":4479.032,"text":"-Well, I'm deeply grateful, Mr. Burns. -Good."},{"start":4479.116,"end":4482.744,"text":"Oh! If you should have an opening for a war correspondent,"},{"start":4482.828,"end":4484.746,"text":"I parler a little French."},{"start":4484.83,"end":4487.331,"text":"-I'll keep you in mind. -Au revoir, mon capitaine."},{"start":4487.416,"end":4488.916,"text":"Bonjour."},{"start":4491.712,"end":4493.755,"text":"(laughs) \"His white-haired mother's tears.\""},{"start":4493.839,"end":4495.465,"text":"That's the stuff, isn't it?"},{"start":4495.549,"end":4499.093,"text":"Listen, Bensinger is on his way to see you. Handle him with kid gloves."},{"start":4499.178,"end":4500.803,"text":"Put him to work writing poetry."},{"start":4500.888,"end":4503.514,"text":"No, we don't want him. Just stall him until the extra's out."},{"start":4503.599,"end":4505.933,"text":"Then tell him his poetry smells and kick him downstairs."},{"start":4506.018,"end":4507.643,"text":"Double-crossing swine."},{"start":4507.728,"end":4510.521,"text":"You said it. He won't quit his paper without giving notice after this."},{"start":4510.606,"end":4512.607,"text":"I mean you. You'd double-cross anybody."},{"start":4512.691,"end":4514.734,"text":"Wait a minute. I just remembered."},{"start":4514.818,"end":4517.32,"text":"Bruce isn't coming back here. He's taking the 9:00 train."},{"start":4517.404,"end":4519.363,"text":"In that case, he's gone."},{"start":4519.448,"end":4522.116,"text":"Don't sit there like a frozen robin. Get on with the story."},{"start":4522.201,"end":4524.994,"text":"We ought to have our plans finished by the time Butch gets here."},{"start":4525.079,"end":4528.581,"text":"How you have messed up my life. What am I going to do?"},{"start":4528.665,"end":4531,"text":"The window's too small. We'll have to carry the desk out."},{"start":4531.085,"end":4534.504,"text":"I oughta be on that train right now. What a sap I am, falling for your line."},{"start":4534.588,"end":4537.09,"text":"They're gonna name streets after me. Johnson Street."},{"start":4537.174,"end":4539.217,"text":"-Get back to work. -I'm not going back to work."},{"start":4539.301,"end":4541.219,"text":"(doorknob rattling)"},{"start":4541.303,"end":4543.429,"text":"-Who is it? -It's me, boss. It's Louie."},{"start":4543.514,"end":4545.556,"text":"Louie."},{"start":4546.475,"end":4548.643,"text":"-Holy smokes! What's the matter with you? -Where's Mrs. Baldwin?"},{"start":4548.727,"end":4550.144,"text":"-What happened? -You been in a fight?"},{"start":4550.229,"end":4552.814,"text":"Down Western Avenue, we was going 65 miles an hour."},{"start":4552.898,"end":4555.483,"text":"-Take that mush out of your mouth. -Where's the old lady?"},{"start":4555.567,"end":4558.277,"text":"We run smack into a police patrol, busted it in half."},{"start":4558.362,"end":4560.113,"text":"-Was she hurt? -Where is she?"},{"start":4560.197,"end":4563.116,"text":"Imagine bumping into a load of cops. They come rolling out like oranges."},{"start":4563.2,"end":4564.826,"text":"-What did you do with her? -Search me."},{"start":4564.91,"end":4566.911,"text":"When I come to, I was running down 34th Street."},{"start":4566.995,"end":4568.204,"text":"-You were with her? -Was I?"},{"start":4568.288,"end":4570.373,"text":"-You were in the taxicab. -The driver got knocked cold."},{"start":4570.457,"end":4574.127,"text":"Butterfingers! I give you an old dame to take somewhere and you hand her over to the cops."},{"start":4574.211,"end":4577.755,"text":"What do you mean, I handed her? The cops was on the wrong side of the street."},{"start":4577.84,"end":4579.966,"text":"She's probably squawking her head off in a police station."},{"start":4580.05,"end":4582.718,"text":"I don't think she's squawking much. You know what I mean?"},{"start":4582.803,"end":4585.304,"text":"-Was she killed? -Was she? Did you notice?"},{"start":4585.389,"end":4588.432,"text":"Me with a gun on the hip and a kidnapped old lady on my hands."},{"start":4588.517,"end":4591.519,"text":"I'm gonna stick around asking questions from cops? You know what I mean?"},{"start":4591.603,"end":4594.48,"text":"Dead. Oh, this is the end."},{"start":4594.565,"end":4597.191,"text":"It's fate, Hildy. What will be will be."},{"start":4597.276,"end":4600.069,"text":"What am I gonna say to Bruce? What can I tell him?"},{"start":4600.154,"end":4602.989,"text":"If he really loves you, you won't have to tell him anything."},{"start":4603.073,"end":4606.492,"text":"Would you rather have had the old dame dragging the whole police force in here?"},{"start":4606.577,"end":4608.703,"text":"I killed her. I'm responsible."},{"start":4608.787,"end":4611.122,"text":"How can I ever face Bruce again?"},{"start":4611.206,"end":4612.623,"text":"Look at me, Hildy."},{"start":4612.708,"end":4614.792,"text":"I am looking at you, you murderer."},{"start":4614.877,"end":4618.087,"text":"If it was my own grandmother, I'd carry on for the paper."},{"start":4618.172,"end":4619.755,"text":"Louie, where did it happen?"},{"start":4619.84,"end":4622.55,"text":"-Western and 34th. -I gotta get out of here."},{"start":4622.634,"end":4625.052,"text":"We can do more here. Now be calm."},{"start":4625.137,"end":4628.014,"text":"-Listen ̶ -(phone ringing)"},{"start":4628.098,"end":4631.058,"text":"-Hello? Hello? -Maine 4557."},{"start":4631.143,"end":4633.436,"text":"Who? Well, Butch, where are you?"},{"start":4633.52,"end":4636.397,"text":"-Mission Hospital? Receiving room, please. -What are you doing there?"},{"start":4636.481,"end":4637.773,"text":"Haven't you even started?"},{"start":4637.858,"end":4640.109,"text":"Was there an old lady brought in from an auto smashup?"},{"start":4640.194,"end":4642.528,"text":"Oh, for H. Sebastian! It's a matter of life and death."},{"start":4642.613,"end":4644.655,"text":"-Nobody? -I can't hear."},{"start":4644.74,"end":4648.284,"text":"-Morningside 2469. -They got who? Speak up. A what?"},{"start":4648.368,"end":4651.495,"text":"-You can't stop for a dame now. -Community hospital. Receiving room, please."},{"start":4651.58,"end":4654.874,"text":"I don't care if you've been after her for six years. Our lives are at stake!"},{"start":4654.958,"end":4657.793,"text":"Are you gonna let a woman come between us after all we've been through?"},{"start":4657.878,"end":4660.129,"text":"-Was an old lady brought in there? -Butch."},{"start":4660.214,"end":4664.008,"text":"I'd put my arm in fire for you up to here. You can't double-cross me!"},{"start":4664.092,"end":4667.678,"text":"-Look around, will you? -Put her on. I'll talk to her."},{"start":4667.763,"end":4670.973,"text":"Good evening, madam. Listen, you ten-cent glamour girl."},{"start":4671.058,"end":4673.893,"text":"You can't keep Butch away from his duty. What's that?"},{"start":4673.977,"end":4677.021,"text":"You say that again, I'll come over and kick you in the teeth!"},{"start":4677.105,"end":4680.358,"text":"Say, what kind of language is that? Now, look here ̶"},{"start":4680.442,"end":4683.277,"text":"(whimpers) She hung up. What did I say?"},{"start":4684.655,"end":4687.406,"text":"Duffy. How do you like that, mousing around with some big ̶"},{"start":4687.491,"end":4689.825,"text":"-Duffy! -Will you shut up? I'm tryin' to hear!"},{"start":4689.91,"end":4692.703,"text":"-That's cooperation. Duffy! -Nobody?"},{"start":4692.788,"end":4695.665,"text":"Well, where is Duffy? (whines)"},{"start":4695.749,"end":4699.126,"text":"Diabetes. I ought to know better than to hire anybody with a disease."},{"start":4699.211,"end":4701.504,"text":"-Give me Olympia 218. -Louie."},{"start":4701.588,"end":4703.547,"text":"-Yes, boss. -Louie, it's up to you."},{"start":4703.632,"end":4706.133,"text":"-Anything you say, boss. -Beat it out. Get ahold of some guys."},{"start":4706.218,"end":4708.386,"text":"-Who do you want? -Anybody with hair on his chest."},{"start":4708.47,"end":4711.639,"text":"Get 'em anywhere. Offer 'em anything. We got to get that desk out of here."},{"start":4711.723,"end":4714.016,"text":"-Is it important? -Louie, you're the best friend I got."},{"start":4714.101,"end":4715.518,"text":"I like you too."},{"start":4715.602,"end":4718.354,"text":"Then don't fail me. Get enough people to move that desk."},{"start":4718.438,"end":4722.358,"text":"-You know me, boss. The shirt off my back. -Okay, don't bump into anything."},{"start":4722.442,"end":4725.194,"text":"That dumb immigrant will flop on me as sure as you're born."},{"start":4725.279,"end":4726.696,"text":"Try again at the hospital."},{"start":4726.78,"end":4729.282,"text":"If he's not back in five minutes, we'll carry it out alone."},{"start":4729.366,"end":4731.492,"text":"-Do anything you want. -We can start a fire."},{"start":4731.576,"end":4734.578,"text":"-Have the firemen take it out. -I don't give a darn what you do."},{"start":4734.663,"end":4737.999,"text":"-See if we can lift it. -What? Nobody? Oh, never mind!"},{"start":4738.083,"end":4739.709,"text":"-Are you gonna help me? -No, I'm not."},{"start":4739.793,"end":4742.545,"text":"-You want me to strain my back? -I'm going to find Mrs. Baldwin."},{"start":4742.629,"end":4744.922,"text":"I'm going down to the morgue and find her."},{"start":4745.007,"end":4748.05,"text":"-We wanna talk a minute. -What is this?"},{"start":4748.135,"end":4750.678,"text":"-Get your hands off me! -Now look here, Johnson."},{"start":4750.762,"end":4752.555,"text":"-Hey, you! -You mean me?"},{"start":4752.639,"end":4756.767,"text":"Yes, you. What do you mean by breaking in here like this, hmm?"},{"start":4756.852,"end":4760.313,"text":"You can't bluff me, Burns. I don't care who you are or what paper you're editor of."},{"start":4760.397,"end":4762.44,"text":"-Let go of me, will you? -Hang onto her."},{"start":4762.524,"end":4765.526,"text":"-Something's happened to my mother-in-law. -May be going out to get Williams."},{"start":4765.61,"end":4767.987,"text":"-She had the door locked. -She and Mollie were in here talking."},{"start":4768.071,"end":4770.698,"text":"I don't know anything, and there's been an accident."},{"start":4770.782,"end":4773.075,"text":"Johnson, there's something very peculiar going on here."},{"start":4773.16,"end":4775.619,"text":"-Now, see here, Johnson. -Just a moment, Hartwell."},{"start":4775.704,"end":4778.664,"text":"If you have any accusations to make, make them in the proper manner."},{"start":4778.749,"end":4781.751,"text":"-Otherwise I'll have to ask you to get out. -You'll ask me to what?"},{"start":4781.835,"end":4783.669,"text":"Get out."},{"start":4783.754,"end":4786.922,"text":"Oh, you will? Keep that door closed and don't let anybody in or out."},{"start":4787.007,"end":4789.425,"text":"-We'll see about this. -Pinky, give him the third degree."},{"start":4789.509,"end":4793.054,"text":"-Get 'em talkin', you got Williams, -I'm going to get to the bottom of this."},{"start":4793.138,"end":4795.723,"text":"-Are you going to talk? -What do you want me to say?"},{"start":4795.807,"end":4798.225,"text":"-What do you know about Williams? -What do you know about Williams?"},{"start":4798.31,"end":4800.936,"text":"Now we're getting somewh ̶ Take her out of here."},{"start":4801.021,"end":4804.273,"text":"-I've got ways of making her talk. -Don't you dare touch me or ̶"},{"start":4804.358,"end":4806.067,"text":"-She's got a gun! -Grab it!"},{"start":4806.151,"end":4809.779,"text":"-No, you don't! Walter! -All right, Burns. I'll take that gun."},{"start":4811.156,"end":4814.033,"text":"-Where did you get this gun? -I've got a right to carry a gun."},{"start":4814.117,"end":4816.077,"text":"-Not this gun. -I can explain that."},{"start":4816.161,"end":4820.039,"text":"When Hildy told me she was going to interview Williams, I gave her a gun."},{"start":4820.123,"end":4821.749,"text":"That's very interesting."},{"start":4821.833,"end":4825.002,"text":"This happens to be the gun that Williams used to shoot his way out with!"},{"start":4825.087,"end":4828.839,"text":"-Are you trying to make me out a liar? -I ought to know my own gun ̶"},{"start":4828.924,"end":4832.051,"text":"-Oh! So that's where Williams got the gun. -Hildy got it from Williams."},{"start":4832.135,"end":4835.388,"text":"-Where is Earl Williams? -You're barking up the wrong tree, Hartwell."},{"start":4835.472,"end":4837.89,"text":"I'll give you three minutes to tell me where he is!"},{"start":4837.974,"end":4841.06,"text":"He went to the hospital to call on Egelhoffer with a bag of marshmallows."},{"start":4841.144,"end":4844.188,"text":"Where is he? Ask the mastermind what he's doing here."},{"start":4844.272,"end":4846.357,"text":"Speak up. What do you know about this?"},{"start":4846.441,"end":4850.82,"text":"My dear fellow, the Morning Post does not obstruct justice or hide criminals."},{"start":4850.904,"end":4853.322,"text":"-You oughta know that. -You're under arrest."},{"start":4853.407,"end":4855.408,"text":"-And you too! -Who's under arrest?"},{"start":4855.492,"end":4858.994,"text":"Listen, you insignificant, square-toed, pimple-headed spy!"},{"start":4859.079,"end":4861.539,"text":"-You realize what you're doing? -I'll show you what I'm doing!"},{"start":4861.623,"end":4863.916,"text":"You're obstructing justice, and so is the Morning Post!"},{"start":4864,"end":4867.294,"text":"-I'm going to see that you're fined $10,000! -You'll see nothing of the kind."},{"start":4867.379,"end":4869.797,"text":"I'm going to begin by impounding the Post's property."},{"start":4869.881,"end":4871.507,"text":"-Is this your desk? -No!"},{"start":4871.591,"end":4874.635,"text":"Yes! What are you afraid of, Hildy? I dare you to move this desk out!"},{"start":4874.719,"end":4876.262,"text":"-Try it. -I will!"},{"start":4876.346,"end":4879.515,"text":"You move this desk out, I'll put you behind bars!"},{"start":4879.599,"end":4881.225,"text":"-He can do it too. -Is that so?"},{"start":4881.309,"end":4884.311,"text":"-I'll see that Roosevelt hears about it. -Tell him. Come on, boys!"},{"start":4884.396,"end":4886.272,"text":"-Confiscate this desk. -This is your last chance."},{"start":4886.356,"end":4888.566,"text":"This is a federal offense, and you fellas will be accessories."},{"start":4888.65,"end":4891.277,"text":"-We'll take a chance. Go ahead, boys! -All right."},{"start":4891.361,"end":4893.362,"text":"-(pounding on door) -Open up this door!"},{"start":4894.614,"end":4897.032,"text":"Mother, I am glad to see you. Are you all right?"},{"start":4897.117,"end":4899.785,"text":"That's the man that did it, right there."},{"start":4901.746,"end":4905.082,"text":"-What's the idea here? -This lady claims she's been kidnapped."},{"start":4905.167,"end":4908.043,"text":"-They dragged me down the stairs. -Just a minute."},{"start":4908.128,"end":4911.13,"text":"-Did this man have anything to do with it? -He was in charge of the whole thing!"},{"start":4911.214,"end":4913.591,"text":"-He told them to kidnap me. -Excuse me, madam."},{"start":4913.675,"end":4916.427,"text":"-Are you referring to me? -You know you did."},{"start":4916.511,"end":4919.722,"text":"-What about this, Burns? Kidnapping, huh? -Trying to frame me, huh?"},{"start":4919.806,"end":4922.183,"text":"I never saw this woman before in my life."},{"start":4922.267,"end":4926.145,"text":"What a thing to say. I was standing here when that girl jumped out the window."},{"start":4926.229,"end":4929.273,"text":"-Call the mayor! Get him here. -Look here, madam. Be honest."},{"start":4929.357,"end":4932.485,"text":"If you were joyriding, plastered, or got into some scrape,"},{"start":4932.569,"end":4935.321,"text":"why don't you admit it instead of accusing innocent people?"},{"start":4935.405,"end":4938.324,"text":"You ruffian! How dare you talk like that to me!"},{"start":4938.408,"end":4940.868,"text":"-He's just crazy, Mother. -I can tell you something more."},{"start":4940.952,"end":4942.912,"text":"I can tell you why they did it."},{"start":4942.996,"end":4946.582,"text":"They had a murderer in here, and they were hiding him!"},{"start":4946.666,"end":4951.378,"text":"-In here? -You're a cockeyed liar, and you know it!"},{"start":4951.463,"end":4953.672,"text":"-(knocks three times) -What was that?"},{"start":4953.757,"end":4955.174,"text":"-He's in there. -Give me the desk."},{"start":4955.258,"end":4958.761,"text":"-Give me the phone. What a break. -Stand back, everybody. Get your guns out."},{"start":4958.845,"end":4961.096,"text":"-He's harmless. -Shoot right through the desk."},{"start":4961.181,"end":4962.806,"text":"He can't hurt anybody. You've got his gun."},{"start":4962.891,"end":4964.85,"text":"-Oh, dear! -Go on, you gray-haired old weasel!"},{"start":4964.935,"end":4966.602,"text":"Let me out of here!"},{"start":4966.686,"end":4969.188,"text":"Mother! I've been looking all over for you."},{"start":4969.272,"end":4970.981,"text":"-What's happened? -Hello, Jake? Hang on."},{"start":4971.066,"end":4972.9,"text":"-Hildy, call Duffy! -No, you don't!"},{"start":4972.984,"end":4975.861,"text":"-You want to see us scooped? -Everybody, aim right at the center."},{"start":4975.946,"end":4979.114,"text":"-That's murder. -One of you get on each end of the desk."},{"start":4979.199,"end":4980.616,"text":"-Comin' up. -We got you covered, Williams!"},{"start":4980.7,"end":4982.743,"text":"-Have it in a minute. -Don't try to move. -Anytime now."},{"start":4982.827,"end":4984.537,"text":"-I'll count three. -It's hot!"},{"start":4984.621,"end":4986.08,"text":"-Ready for an emergency. -One. Two."},{"start":4986.164,"end":4987.414,"text":"-Any second now. -Three! Up with it!"},{"start":4988.041,"end":4991.043,"text":"-I got you, Williams! -Go ahead, shoot me."},{"start":4991.127,"end":4994.421,"text":"Earl Williams just captured in the press room in the criminal courts building hiding in a desk."},{"start":4994.506,"end":4997.424,"text":"-On your feet. -Don't try any funny stuff."},{"start":4997.509,"end":4998.968,"text":"Williams was unconscious when they opened the desk."},{"start":4999.052,"end":5001.512,"text":"Williams put up a struggle, but the police overpowered him."},{"start":5001.596,"end":5003.514,"text":"He tried to shoot it out, but his gun wouldn't work."},{"start":5003.598,"end":5004.974,"text":"Tried to break through a cordon of police."},{"start":5005.058,"end":5007.351,"text":"Duffy, the Post just turned Williams over to the sheriff!"},{"start":5007.435,"end":5008.978,"text":"-Put the cuffs on these people. -More later."},{"start":5009.062,"end":5012.523,"text":"An anonymous note led to Williams' capture. Hold on!"},{"start":5013.358,"end":5016.443,"text":"The sheriff was tracing a telephone call which gave away Williams' hiding place."},{"start":5016.528,"end":5018.153,"text":"-Where's the old lady? -She went out!"},{"start":5018.238,"end":5020.531,"text":"-Out? -Call me back. I'll call you back!"},{"start":5025.662,"end":5028.497,"text":"♪♪ (humming)"},{"start":5029.499,"end":5031.208,"text":"Give me the warden's office, quick."},{"start":5031.293,"end":5033.21,"text":"Hartwell, you're gonna wish you'd never been born!"},{"start":5033.295,"end":5034.545,"text":"Oh, am I?"},{"start":5034.629,"end":5037.006,"text":"-Hello, Fred. -Well, fine work, Pete."},{"start":5037.09,"end":5039.133,"text":"You certainly delivered the goods. I'm proud of you."},{"start":5039.217,"end":5040.884,"text":"-Look natural, don't they? -A sight for sore eyes."},{"start":5040.969,"end":5043.387,"text":"Aiding an escaped criminal and a little charge of kidnapping."},{"start":5043.471,"end":5046.181,"text":"What's that? That's the jail. There must be somebody there."},{"start":5046.266,"end":5048.726,"text":"Looks like about 10 years apiece for you two birds."},{"start":5048.81,"end":5049.81,"text":"Does it?"},{"start":5049.894,"end":5051.77,"text":"Whenever you think you've got the Morning Post licked,"},{"start":5051.855,"end":5053.522,"text":"it's time for you to get out of town."},{"start":5053.607,"end":5055.983,"text":"Whistling in the dark. That ain't gonna help you this time. You're through."},{"start":5056.067,"end":5059.528,"text":"The last man who said that was Archie Leach, just a week before he cut his throat."},{"start":5059.613,"end":5060.613,"text":"Is that so?"},{"start":5060.697,"end":5062.573,"text":"We've been in worse jams than this, haven't we, Hildy?"},{"start":5062.657,"end":5063.782,"text":"No."},{"start":5063.867,"end":5066.66,"text":"You forget the power that always watches over the Morning Post."},{"start":5066.745,"end":5069.038,"text":"-Your luck's not with you now. -This is Hartwell."},{"start":5069.122,"end":5071.332,"text":"I've caught him. Yes, Williams."},{"start":5071.416,"end":5074.001,"text":"Single-handed. We'll proceed with the hanging per schedule."},{"start":5074.085,"end":5076.17,"text":"You're gonna be in office exactly two days more."},{"start":5076.254,"end":5078.547,"text":"Then we're gonna pull your nose out of that feed bag."},{"start":5078.632,"end":5080.466,"text":"-I'll tell you what you'll be doing. -What?"},{"start":5080.55,"end":5083.01,"text":"-Well, go on. -Making brooms in the state penitentiary!"},{"start":5083.094,"end":5086.18,"text":"Joe, this is Hartwell. Come over to my office right away."},{"start":5086.264,"end":5089.35,"text":"I captured a couple of important birds. I want you to take their confessions."},{"start":5089.434,"end":5090.851,"text":"Duffy, get Liebowitz!"},{"start":5090.935,"end":5093.187,"text":"All the lawyers in the world aren't gonna help you now."},{"start":5093.271,"end":5095.105,"text":"You're talking to the Morning Post!"},{"start":5095.19,"end":5097.566,"text":"MAYOR: Oh, power of the press. (laughing)"},{"start":5097.651,"end":5100.861,"text":"WALTER: Bigger men than you have found out what the power of the press is!"},{"start":5100.945,"end":5103.197,"text":"-Presidents. Kings! -Here's the reprieve."},{"start":5103.281,"end":5106.283,"text":"-Say, you ̶ Get out of here. -You can't bribe me. My wife ̶"},{"start":5106.368,"end":5109.787,"text":"-Get out of here! -Oh, no, I won't! Here's the reprieve."},{"start":5109.871,"end":5112.206,"text":"-What? -I don't want to be a city sealer."},{"start":5112.29,"end":5114.041,"text":"-Who is this man? -Throw him out."},{"start":5114.125,"end":5116.585,"text":"Just a minute. Who's trying to bribe you?"},{"start":5116.67,"end":5118.504,"text":"-They wouldn't take this. -He's insane."},{"start":5118.588,"end":5120.506,"text":"What did I tell ya? An unseen power!"},{"start":5120.59,"end":5123.175,"text":"What do you mean by coming here with a cock-and-bull story like that?"},{"start":5123.259,"end":5125.302,"text":"-SHERIFF: He's an impostor! -Arrest him."},{"start":5125.387,"end":5127.805,"text":"Trying to hang an innocent man to win an election."},{"start":5127.889,"end":5129.682,"text":"-That's murder. -Never saw him before."},{"start":5129.766,"end":5132.017,"text":"-If I was to tell my wife ̶ -What's your name?"},{"start":5132.102,"end":5134.687,"text":"-Joe Pettibone. -When did you deliver this first?"},{"start":5134.771,"end":5136.772,"text":"-Who'd you talk to? -They started right in bribing me."},{"start":5136.856,"end":5138.607,"text":"-Who's they? -Those. Them."},{"start":5138.692,"end":5141.36,"text":"That's absurd! He's talking like a child."},{"start":5141.444,"end":5143.737,"text":"-Out of the mouths of babes! -Hi, babe."},{"start":5143.822,"end":5145.572,"text":"He's insane. Drunk."},{"start":5145.657,"end":5149.243,"text":"If this unfortunate man has really been reprieved, I'm tickled to death."},{"start":5149.327,"end":5152.037,"text":"-Aren't you, Pete? -You'd hang your own mother to be reelected."},{"start":5152.122,"end":5155.165,"text":"-That's a horrible thing to say about anybody. -Oh, you're marvelous."},{"start":5155.25,"end":5159.128,"text":"-Look here, Walter. You're an intelligent man. -Never mind that."},{"start":5159.212,"end":5161.38,"text":"Now let's have your story, Mr. Pettibone."},{"start":5161.464,"end":5164.174,"text":"-Nineteen years ago, I married Mrs. Pettibone. -Skip all that."},{"start":5164.259,"end":5167.261,"text":"-Only she wasn't Mrs. Pettibone then. -I mean ̶"},{"start":5167.345,"end":5171.014,"text":"Sheriff, this document is authentic. Earl Williams has been reprieved."},{"start":5171.099,"end":5174.768,"text":"And our commonwealth has been saved the painful necessity of shedding blood."},{"start":5174.853,"end":5177.813,"text":"You said it. Get off the soapbox. Save that for the Tribune."},{"start":5177.897,"end":5180.107,"text":"Pete, take those handcuffs off my friends."},{"start":5180.191,"end":5183.026,"text":"-I'm amazed at you, doing a thing like that. -Isn't he awful?"},{"start":5183.111,"end":5184.945,"text":"-You don't know how badly I feel. -No."},{"start":5185.029,"end":5188.574,"text":"-No excuse for Pete to fly off the handle. -I was only doing my duty. Nothing personal."},{"start":5188.658,"end":5190.576,"text":"-That's all right. -What'd you say your name was?"},{"start":5190.66,"end":5193.537,"text":"Pettibone. Here's a picture of my wife."},{"start":5193.621,"end":5195.748,"text":"-A fine-looking woman. -You haven't seen her yet."},{"start":5195.832,"end":5197.458,"text":"She's all right."},{"start":5197.542,"end":5200.544,"text":"She's good enough for me! If I was to tell my wife ̶ Ooh-hoo-hoo-hoo!"},{"start":5200.628,"end":5203.213,"text":"I understand perfectly, Mr. Pettibone. As long as I'm mayor ̶"},{"start":5203.298,"end":5205.299,"text":"Which ought to be about three more hours."},{"start":5205.383,"end":5208.469,"text":"Just long enough for us to get our special edition, asking for your recall."},{"start":5208.553,"end":5212.014,"text":"And your arrest. You boys ought to get about 10 years apiece."},{"start":5212.098,"end":5214.433,"text":"Don't make any hasty decisions, Mr. Burns."},{"start":5214.517,"end":5216.477,"text":"You might run into a big libel suit!"},{"start":5216.561,"end":5218.395,"text":"You're going to run into the governor."},{"start":5218.48,"end":5221.398,"text":"My old friend, the governor, and I understand each other perfectly."},{"start":5221.483,"end":5224.443,"text":"-Yes, and so do I. -So do you what, you hoodoo?"},{"start":5224.527,"end":5227.821,"text":"Mr. Pettibone, if you'll come with us, we'll take you to the warden's office"},{"start":5227.906,"end":5229.198,"text":"and deliver this reprieve."},{"start":5229.282,"end":5231.366,"text":"-Come along, Pete. -If I was to tell my wife ̶"},{"start":5231.451,"end":5234.536,"text":"-You won't have to. -PETTIBONE: Whoo-hoo-hoo-hoo!"},{"start":5234.621,"end":5236.872,"text":"Wait till those two future jailbirds read the Morning Post tomorrow."},{"start":5236.956,"end":5238.749,"text":"-A tight squeeze though. -Give me Duffy."},{"start":5238.833,"end":5241.168,"text":"That's the worst jam we've been in in a long time."},{"start":5241.252,"end":5242.377,"text":"Where is he? Get him."},{"start":5242.462,"end":5246.298,"text":"Remember the time we stole old lady Haggerty's stomach off the coroner's physician?"},{"start":5246.382,"end":5250.636,"text":"-Anytime you need this guy, he's never there. -We proved she'd been poisoned."},{"start":5250.72,"end":5253.931,"text":"We had to hide out for a week. Remember that?"},{"start":5254.015,"end":5257.226,"text":"The Shoreland Hotel. That's where ̶ I mean, how we ̶"},{"start":5257.31,"end":5260.062,"text":"We could've gone to jail for that too. You know that."},{"start":5260.146,"end":5262.731,"text":"Yes, you're right, Hildy. It's a bad business."},{"start":5262.816,"end":5265.901,"text":"You're gonna be better off. You'd better get going."},{"start":5265.985,"end":5268.695,"text":"-Where would I go? -To Bruce, of course."},{"start":5268.78,"end":5271.156,"text":"But you know he's gone. He took the 9:00 train."},{"start":5271.241,"end":5274.535,"text":"Send him a wire. He'll be waiting in the station when you get into Albany."},{"start":5274.619,"end":5278.539,"text":"-Why doesn't that guy have a phone in there? -I got it so messed up."},{"start":5278.623,"end":5282.167,"text":"-Get going, Hildy. -\"Get going\"? What is that with you?"},{"start":5282.252,"end":5285.128,"text":"Wait a minute. Can't you understand?"},{"start":5285.213,"end":5289.049,"text":"I'm trying to do something noble for once in my life. Get out of here."},{"start":5289.133,"end":5291.26,"text":"Walter, just a minute."},{"start":5291.344,"end":5294.346,"text":"-Send the fellow a wire. He'll be waiting. -Who'll write the story?"},{"start":5294.43,"end":5297.307,"text":"I'll do it myself. Won't be half as good as you can do it."},{"start":5297.392,"end":5299.351,"text":"It's my story. I'd like to think ̶"},{"start":5299.435,"end":5302.479,"text":"-Oh, at last! -I get it, Walter. The same old act."},{"start":5302.564,"end":5305.649,"text":"Trying to push me out, thinking I'll be stupid enough to want to stay."},{"start":5305.733,"end":5308.151,"text":"I know I deserved that. Wait a minute, Duffy."},{"start":5308.236,"end":5309.862,"text":"But this is one time you're wrong."},{"start":5309.946,"end":5313.407,"text":"Honey, when you walk out that door, part of me will go with you."},{"start":5313.491,"end":5315.826,"text":"But a whole new world's gonna open up for you."},{"start":5315.91,"end":5319.079,"text":"-I made fun of Bruce. You know why? -Why?"},{"start":5319.163,"end":5320.581,"text":"I was jealous."},{"start":5320.665,"end":5324.418,"text":"I was sore because he could offer you the kind of life I can't give you."},{"start":5324.502,"end":5326.003,"text":"That's what you want, honey."},{"start":5326.087,"end":5328.922,"text":"I could stay and do the story and take the train in the morning."},{"start":5329.007,"end":5330.841,"text":"No, forget it. Come on, come on."},{"start":5330.925,"end":5332.926,"text":"Good-bye, dear, and good luck."},{"start":5336.848,"end":5339.182,"text":"Duffy. This is how it goes so far."},{"start":5339.267,"end":5342.102,"text":"-(phone ringing) -Oh, just a minute."},{"start":5342.896,"end":5345.355,"text":"Hello. Who? Hildy Johnson?"},{"start":5345.44,"end":5348.233,"text":"-No, she just left. -I'm still here. I can take it."},{"start":5348.318,"end":5350.193,"text":"Hang on a minute."},{"start":5351.779,"end":5354.323,"text":"Hildy Johnson speaking."},{"start":5354.407,"end":5356.95,"text":"The Fourth Precinct Police Station?"},{"start":5357.035,"end":5359.036,"text":"Well, put him on."},{"start":5359.12,"end":5361.705,"text":"Bruce, I thought you were on your way to Albany."},{"start":5361.789,"end":5365.042,"text":"-What for? -For having counterfeit money."},{"start":5365.126,"end":5368.295,"text":"-Counterfeit money? -(clears throat) Hold on a minute, Duffy."},{"start":5368.379,"end":5370.172,"text":"Where did you get it?"},{"start":5370.256,"end":5372.257,"text":"I gave it to you?"},{"start":5372.342,"end":5376.094,"text":"Oh, all right. I'll try and do something about it."},{"start":5377.138,"end":5378.639,"text":"(crying)"},{"start":5382.56,"end":5384.561,"text":"(sobbing)"},{"start":5387.106,"end":5389.024,"text":"Oh, honey."},{"start":5389.108,"end":5391.151,"text":"Honey, don't ̶ don't cry, please."},{"start":5391.235,"end":5394.071,"text":"Come on. I didn't mean to make you cry. What's the matter with you?"},{"start":5394.155,"end":5396.615,"text":"You never cried before. Hildy."},{"start":5396.699,"end":5400.202,"text":"I thought you were really sending me away with Bruce."},{"start":5402.205,"end":5405.04,"text":"I didn't know you had him locked up."},{"start":5405.124,"end":5408.543,"text":"I thought... you were on the level for once,"},{"start":5408.628,"end":5412.172,"text":"that you were just standing by and letting me go off with him"},{"start":5412.256,"end":5414.591,"text":"and not doing a thing about it."},{"start":5414.676,"end":5417.386,"text":"Aw, come on, honey. What do you think I was, a chump?"},{"start":5417.47,"end":5419.888,"text":"And I thought you didn't love me."},{"start":5419.973,"end":5423.058,"text":"-What were you thinking with? -I don't know."},{"start":5423.935,"end":5426.52,"text":"Well, what are you standing there gawking for?"},{"start":5426.604,"end":5429.064,"text":"We have to get him out of jail."},{"start":5429.148,"end":5431.692,"text":"Send Louie down with some honest money"},{"start":5431.776,"end":5433.86,"text":"and send him back to Albany where he belongs."},{"start":5433.945,"end":5435.654,"text":"Sure, sure."},{"start":5435.738,"end":5439.199,"text":"Duffy, everything's changed. Tell Louie to stand by. We're coming to the office."},{"start":5439.283,"end":5441.868,"text":"Don't worry about the story. Hildy's gonna write it."},{"start":5441.953,"end":5444.746,"text":"Of course she's not quitting. We're gonna get married."},{"start":5444.831,"end":5448.208,"text":"-Oh! Can we go on a honeymoon this time? -Sure."},{"start":5448.292,"end":5452.337,"text":"Duffy, you can be managing editor. No, no, not permanently."},{"start":5452.422,"end":5454.715,"text":"Just for the two weeks we're away on our honeymoon."},{"start":5454.799,"end":5457.092,"text":"-What? -I don't know where. Where are we going?"},{"start":5457.176,"end":5459.636,"text":"-Niagara Falls. -Niagara Falls, Duffy!"},{"start":5459.721,"end":5462.305,"text":"-Two whole weeks, Walter? -Sure. You've earned it!"},{"start":5462.39,"end":5464.516,"text":"What? What?"},{"start":5464.6,"end":5467.102,"text":"Strike? What strike?"},{"start":5467.186,"end":5469.646,"text":"Where? Albany?"},{"start":5469.731,"end":5473.358,"text":"-I know it's on the way, but I can't ask Hildy ̶ -We'll honeymoon in Albany."},{"start":5473.443,"end":5475.444,"text":"Okay, Duffy. (weak laugh)"},{"start":5475.528,"end":5479.031,"text":"Isn't that a coincidence? We're going to Albany. I wonder if Bruce can put us up."},{"start":5479.115,"end":5481.491,"text":"Say, why don't you carry that in your hand?"}]},{"id":"nasa-spaceship-earth","type":"video","title":"Spaceship Earth: Science, Models and Our Future","creator":"NASA · Dr. Piers Sellers","year":2014,"level":"C2","category":"real","genre":"documentary","durationSeconds":651,"summaryTr":"Eski bir astronot, Dünya’yı uzaydan görmenin anlamını mizah ve bilimle birleştirir. İklim modelleri, toplumsal kararlar ve gezegenimizin geleceği üzerine bir konuşma.","levelNoteTr":"Seviye, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî CEFR derecesi değildir. C2 için zorlayıcı bir dinleme seçkisidir: bilimsel ve siyasi dil arasında geçiş, deyimler, kültürel göndermeler, ironi ve konuşma dilindeki eksiltiler vardır. 2014 tarihli konuşmada sayılar ve görev planları o dönemi yansıtır.","videoUrl":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Piers_Sellers.2014_ipod_lg.m4v","qualities":[{"label":"240p","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Piers_Sellers.2014_ipod_sm.mp4","sizeMB":51},{"label":"360p","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Piers_Sellers.2014_ipod_lg.m4v","sizeMB":112},{"label":"540p","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Piers_Sellers.2014_appletv.m4v","sizeMB":274}],"downloadable":false,"source":{"name":"NASA Goddard — Spaceship Earth: Science, Models and Our Future","url":"https://svs.gsfc.nasa.gov/11668/#media_group_344478","watchUrl":"https://svs.gsfc.nasa.gov/11668/#media_group_344478","license":"NASA medya kullanım koşulları · Eğitim amaçlı kullanım","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","credit":"NASA's Goddard Space Flight Center · NASA · Dr. Piers Sellers","creditNoteTr":"Özgün video ve jenerik değiştirilmeden oynatılır."},"subtitleSource":{"name":"NASA — resmî İngilizce WebVTT altyazısı","url":"https://svs.gsfc.nasa.gov/vis/a010000/a011600/a011668/NASM-Dr.Piers_Sellers.en_US.vtt","license":"NASA medya kullanım koşulları","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","changeNoteTr":"Sözler ve kaynak zamanları korunmuştur; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür. Kaynak altyazıda yazım veya aktarım hataları bulunabilir."},"glossary":{"salinity":"tuzluluk","circulation":"dolaşım","biosphere":"biyosfer; canlıların yaşadığı katman","carbon":"karbon","fossil":"fosil","grizzled":"kırlaşmış; deneyimli","bureaucrat":"bürokrat","dazzled":"etkiledi; göz kamaştırdı","timescales":"zaman ölçekleri","plankton":"plankton; suda sürüklenen küçük canlılar","ingenuity":"yaratıcılık; çözüm bulma becerisi","resourcefulness":"beceriklilik","grit":"azim; yılmama","sobering":"insanı düşündüren; ayıltıcı","depletion":"tükenme; azalım","refrigerants":"soğutucu maddeler","assessment":"değerlendirme","gigatonne":"milyar ton","gigatonnes":"milyarlarca ton"},"captions":[{"start":0.01,"end":4.05,"text":"[Applause]"},{"start":4.05,"end":8.09,"text":"Thanks. So I have to treat Thorsten with a lot of"},{"start":8.09,"end":12.13,"text":"respect because he reminds me of Arnnie Schwarzenegger with a PhD,"},{"start":12.13,"end":16.16,"text":"I don't want to get on wrong side of him. So,"},{"start":16.16,"end":20.19,"text":"okay, the view from orbit really does put things"},{"start":20.19,"end":24.3,"text":"in perspective and as Senator Nelson has seen this with his own eyes,"},{"start":24.3,"end":28.34,"text":"so he knows what I am talking about, I have enjoyed seeing the earth too"},{"start":28.34,"end":32.41,"text":"with my own eyes through a space supervisor, and I am absolutely fascinated"},{"start":32.41,"end":36.52,"text":"by what a satellite instruments can tell us. We, that's"},{"start":36.52,"end":40.53,"text":"NASA and all our friends at NASA, are quite literally conducting a health check"},{"start":40.53,"end":44.56,"text":"of the planet. Okay, so these hands on working scientists"},{"start":44.56,"end":48.59,"text":"have dazzled with facts and data. It's my job, as a grizzled"},{"start":48.59,"end":52.61,"text":"bureaucrat to drag this event over the finish line and let you find your cars."},{"start":52.61,"end":56.64,"text":"So I will try and be quick. So here are a few"},{"start":56.64,"end":60.69,"text":"closing thoughts. What all of this means for science, for policy makers"},{"start":60.69,"end":64.7,"text":"and for the crew spaceship Earth, that's all of us."},{"start":64.7,"end":68.77,"text":"Okay, this movie shows"},{"start":68.77,"end":72.89,"text":"you what happens when we combine the satellite data with computer models"},{"start":72.89,"end":76.92,"text":"and use a lot of physics to fill in the gaps between observations."},{"start":76.92,"end":80.97,"text":"Here we are on the space, this is not a snow storm, these are solar particles blasting"},{"start":80.97,"end":85.02,"text":"by the earth but we are protected by magnetic field. So the particles are diverted."},{"start":85.02,"end":89.02,"text":"As we come down deeper, and by the way this is a model"},{"start":89.02,"end":93.06,"text":"based on physics and observations so there is fact and mathematics,"},{"start":93.06,"end":97.14,"text":"Isaac Newton is hard at work here, here is the atmospheric flows, again"},{"start":97.14,"end":101.18,"text":"produced by a model, circulation timescales here"},{"start":101.18,"end":105.25999999999999,"text":"are on hours to days, so we come a little bit deeper in to the world,"},{"start":105.25999999999999,"end":109.42,"text":"We see the surface winds. Now we are looking at the"},{"start":109.42,"end":113.47,"text":"surface, ocean circulation. Ms. Gail said that's forced by heat,"},{"start":113.47,"end":117.56,"text":"wind and salinity, timescales of days and months and years."},{"start":117.56,"end":121.7,"text":"Deep yet, and now I will talk with the French accent like Jacques Cousteau,"},{"start":121.7,"end":125.74,"text":"the sub surface flows down to the deep ocean circulation,"},{"start":125.74,"end":129.76,"text":"timescales of a thousand years or more."},{"start":129.76,"end":133.79,"text":"It's beautiful and we get all of this for combining the satellite"},{"start":133.79,"end":137.82999999999998,"text":"data with what we understand about nature and putting it in to a computer."},{"start":137.82999999999998,"end":141.85,"text":"This stuff is based on actual reality. Not"},{"start":141.85,"end":145.9,"text":"the Kardashian kind, but let's get back to think about climate."},{"start":145.9,"end":149.94,"text":"So here is a computer model simulation of the earth's climate system, this is not"},{"start":149.94,"end":154.02,"text":"a picture, this is a simulation. It's a toy world"},{"start":154.02,"end":158.05,"text":"based on physics and propelled by satellite data. I guess when you look at"},{"start":158.05,"end":162.12,"text":"the detail here, the popcorn clouds, the winds,"},{"start":162.12,"end":166.25,"text":"or the planetary scale waves in the atmosphere. The snow,"},{"start":166.25,"end":170.28,"text":"the ice, the biosphere, it's all"},{"start":170.28,"end":174.37,"text":"right there. It's all being calculated and it's all being faithfully reproduced."},{"start":174.37,"end":178.39,"text":"Now what is this all good for? Well, models"},{"start":178.39,"end":182.45,"text":"have got to the point of providing weather prediction up to 72 hours"},{"start":182.45,"end":186.54,"text":"reliably. You can quite literally bank on it, most days."},{"start":186.54,"end":190.56,"text":"This is going to be Hurricane Sandy, this is actually a model prediction"},{"start":190.56,"end":194.66,"text":"of Sandy and as you could see the Hurricane wandered around the Atlantic"},{"start":194.66,"end":198.67000000000002,"text":"before turning sharply left and whacking New Jersey and New York."},{"start":198.67000000000002,"end":202.72,"text":"But accurate warnings were given out 72 hours ahead of time"},{"start":202.72,"end":206.82999999999998,"text":"and many lives and a lot of money was saved as a result of these"},{"start":206.82999999999998,"end":210.86,"text":"warnings. By the way, speaking for us, that's not counting"},{"start":210.86,"end":214.89,"text":"all the people up and down the East Coast who did not have to evacuate,"},{"start":214.89,"end":218.91,"text":"because they knew the Hurricane was going to miss them all together, and hat counts for"},{"start":218.91,"end":222.95,"text":"something. Now the exact same physics and many of the same observations that we use"},{"start":222.95,"end":226.97,"text":"for weather are helping us to understand climate better."},{"start":226.97,"end":231.01,"text":"And these climate models allow us to peer in to the future and will help us make"},{"start":231.01,"end":235.05,"text":"decisions about energy, water and food resources."},{"start":235.05,"end":239.07999999999998,"text":"Okay, this is a simulation of what we think the earth will look like"},{"start":239.07999999999998,"end":243.12,"text":"in 20 to 30 years. Actually it's not."},{"start":243.12,"end":247.21,"text":"It's the picture of the sun, it's being taken by our heliophysical"},{"start":247.21,"end":251.35,"text":"friends using their satellites. Besides being a really cool image,"},{"start":251.35,"end":255.4,"text":"it shows that we are keeping a close eye on the sun, again using satellites and guess what,"},{"start":255.4,"end":259.44,"text":"we have found the sun to be not guilty for the recent warming trend."},{"start":259.44,"end":263.56,"text":"Now as I said we use the same exact physics and many of the same satellite"},{"start":263.56,"end":267.57,"text":"data to be used in weather models to build and test our climate models."},{"start":267.57,"end":271.59,"text":"Now what these models do tell us is"},{"start":271.59,"end":275.62,"text":"the rate of warming depends very largely on how much fossil fuel we use"},{"start":275.62,"end":279.64,"text":"and how much carbon dioxide we put in the atmosphere."},{"start":279.64,"end":283.65999999999997,"text":"I am now going to show you a graph and it is very bad"},{"start":283.65999999999997,"end":287.67,"text":"form for even like this but in compensation it may be the"},{"start":287.67,"end":291.69,"text":"most expensive graph ever made and thats not because of the colors."},{"start":291.69,"end":295.71,"text":"This cost several years of effort by thousands of scientists"},{"start":295.71,"end":299.74,"text":"worldwide to put it together and it tell us something, we didn't know"},{"start":299.74,"end":303.75,"text":"until only recently. It's something new and something very,"},{"start":303.75,"end":307.78,"text":"very simple. What it says is that the expected rise in"},{"start":307.78,"end":311.79,"text":"temperature is directly, linearly related to the amount"},{"start":311.79,"end":315.83,"text":"of fossil fuel we burn. The X axis of the bottom"},{"start":315.83,"end":319.86,"text":"shows how much fossil fuel we burn which makes the carbon dioxide"},{"start":319.86,"end":323.89,"text":"and the y-axis shows the temperature increase that results"},{"start":323.89,"end":327.91,"text":"from this extra Co2. The zero point is"},{"start":327.91,"end":331.94,"text":"roughly or a bit left to the zero point is roughly when fellow in England"},{"start":331.94,"end":335.95,"text":"in 1700 decided it was time to start an industrial revolution"},{"start":335.95,"end":339.98,"text":"and dug up the first pit of coal. Now, if you look at the black line"},{"start":339.98,"end":344.01,"text":"that ends at 2010, you'll see that we burned about 500"},{"start":344.01,"end":348.02,"text":"gigatonnes of carbon since then and a gigatonne of carbon is a brick of"},{"start":348.02,"end":352.05,"text":"coal about a kilometer on the side so it is a big piece of coal"},{"start":352.05,"end":356.08,"text":"and that's give us about 1° C rise in global temperature"},{"start":356.08,"end":360.1,"text":"which is what we have seen and that's led to some changes in the world"},{"start":360.1,"end":364.12,"text":"that my good friend I've just shown you. Now we'll"},{"start":364.12,"end":368.16,"text":"likely to burn 1000 gigatonnes, that's halfway up the graph,"},{"start":368.16,"end":372.18,"text":"that will give us two degree centigrade to two and half centigrade increase"},{"start":372.18,"end":376.21,"text":"in global temperature. We definitely don't want"},{"start":376.21,"end":380.24,"text":"to be up in the top right-hand corner, four degree centigrade."},{"start":380.24,"end":384.26,"text":"This look like a very different planet than the current Earth that we inhabit"},{"start":384.26,"end":388.28,"text":"and we don't really know what that planet would look like, how it would work,"},{"start":388.28,"end":392.32,"text":"so this is sobering, right? but"},{"start":392.32,"end":396.33,"text":"is it necessary going to be grim and nasty to the maximum?"},{"start":396.33,"end":400.36,"text":"Is this evening going to be a total down of few you all if we don't count the"},{"start":400.36,"end":404.4,"text":"refreshments? I think not and there is some basis for my"},{"start":404.4,"end":408.40999999999997,"text":"optimism. Here is a picture of the ozone hole that was"},{"start":408.40999999999997,"end":412.46,"text":"discovered in 1979. The blue color shows that ozone is being"},{"start":412.46,"end":416.48,"text":"eaten up by manmade chemicals, many refrigerants. We saw"},{"start":416.48,"end":420.51,"text":"the hole growing rapidly in the 80s and 90s"},{"start":420.51,"end":424.56,"text":"and this was bad news because ozone protects most of life on Earth"},{"start":424.56,"end":428.57,"text":"from strong ultraviolet radiation from the sun and that's bad for you."},{"start":428.57,"end":432.62,"text":"But here is the good part of the story. Governments"},{"start":432.62,"end":436.66,"text":"all around the world took information seriously. Here is a UN meeting"},{"start":436.66,"end":440.67,"text":"where they are discussing the problem on what to do about it. It modeled"},{"start":440.67,"end":444.69,"text":"on Goddard seminar. Here are all the agreements that they"},{"start":444.69,"end":448.73,"text":"cranked out to reduce the chemicals that cause the problem"},{"start":448.73,"end":452.74,"text":"and here is two of Goddard's finest scientists in the back"},{"start":452.74,"end":456.79,"text":"row providing solid science advice"},{"start":456.79,"end":460.81,"text":"and eating chips, there they are."},{"start":460.81,"end":464.84000000000003,"text":"Alright, and what happen"},{"start":464.84000000000003,"end":468.9,"text":"Here is a picture of two worlds; on the left is world that we are"},{"start":468.9,"end":472.92,"text":"likely to see with the ozone depletion leveling off and then slowly"},{"start":472.92,"end":476.96,"text":"reversing and on the right is what would have happened if we didn't have"},{"start":476.96,"end":481.02,"text":"all those controls and agreements and blue here means no ozone which is"},{"start":481.02,"end":485.04,"text":"bad news. On right-hand side is the world we avoided."},{"start":485.04,"end":489.08,"text":"hat's the world with thinning ozone, a world with damage"},{"start":489.08,"end":493.14,"text":"to all living things exposed to sunlight and that includes the crops that provide our"},{"start":493.14,"end":497.17,"text":"food, the ocean plankton that makes our oxygen and damage"},{"start":497.17,"end":501.21,"text":"to us, people. And now a news flash"},{"start":501.21,"end":505.22,"text":"today at four o'clock United Nations"},{"start":505.22,"end":509.26,"text":"released a statement. It reads, the Earth's protective"},{"start":509.26,"end":513.28,"text":"ozone layer is well on track to recovery in the next few decades"},{"start":513.28,"end":517.32,"text":"thanks concerted international action against ozone depleting"},{"start":517.32,"end":521.32,"text":"substances according to a new assessment by 300"},{"start":521.32,"end":525.35,"text":"scientists. So it can be done,"},{"start":525.35,"end":529.38,"text":"this is proof that people and that's all of us and our"},{"start":529.38,"end":533.39,"text":"political representatives can use solid information, facts,"},{"start":533.39,"end":537.42,"text":"models, like every thing we have seen tonight"},{"start":537.42,"end":541.45,"text":"to make the right decisions. Now sometimes it happens a bit later,"},{"start":541.45,"end":545.47,"text":"and it takes bit longer than we would like but generally"},{"start":545.47,"end":549.48,"text":"the right decisions get made. Now"},{"start":549.48,"end":553.51,"text":"there's are a lot of people on this planet."},{"start":553.51,"end":557.53,"text":"This is Christmas 1968"},{"start":557.53,"end":561.57,"text":"3 billion people on Earth and there"},{"start":561.57,"end":565.62,"text":"they all are, actually we or some of us are,"},{"start":565.62,"end":569.64,"text":"minus three because somebody has to take the photo."},{"start":569.64,"end":573.68,"text":"Now here is a picture 2013"},{"start":573.68,"end":577.7,"text":"put together from satellite data. Now there are 7 billion of us"},{"start":577.7,"end":581.72,"text":"plus six on"},{"start":581.72,"end":585.75,"text":"space station and we will top out at about 9 billion this century"},{"start":585.75,"end":589.8,"text":"But again I think there is reason for optimism here because people are actually"},{"start":589.8,"end":593.88,"text":"part of the solution. Every new human born"},{"start":593.88,"end":597.9,"text":"is not just an extra stress on the world but brings with"},{"start":597.9,"end":601.93,"text":"himself or herself resources and answers."},{"start":601.93,"end":605.98,"text":"This is an early picture of Len Fisk. [Laughter]"},{"start":605.98,"end":610.02,"text":"So I think, I hope that with the ingenuity,"},{"start":610.02,"end":614.04,"text":"the resourcefulness, the grit that has got the human race so far"},{"start":614.04,"end":618.06,"text":"we can use these vital signs about the health of our planet"},{"start":618.06,"end":622.1,"text":"to figure out how to live long and prosper on this Earth."},{"start":622.1,"end":626.12,"text":"Now before I close up I'd like to recognize the great work done by the"},{"start":626.12,"end":630.16,"text":"visualization team, Ali Ogden, Wade Sisler, Rani Gran,Horace Mitchell and friends who put"},{"start":630.16,"end":634.2,"text":"all these beautiful pictures together and of course a huge thank you for all speakers"},{"start":634.2,"end":638.21,"text":"and sponsors so put your hand together please. [Applause]"},{"start":638.21,"end":642.28,"text":"[Applause] [Music]"},{"start":642.28,"end":650.631,"text":"[Music] end"}]}];
